#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SENSITIVITY 0.100 // 100mV/A
#define VREF 4.096       // V

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_ads1115();
int16_t read_ads1115();
float convert_to_amperes(int16_t raw_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the ADS1115
int init_ads1115() {
    // Configuration register value: Single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint16_t config = 0x4003; // 0b0100000000000011
    uint8_t buf[3];

    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;       // LSB

    int result = i2cWriteDevice(i2c_handle, (char *)buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the ADS1115
int16_t read_ads1115() {
    uint8_t buf[2];
    int16_t raw_value;

    // Read two bytes from the conversion register
    int result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from conversion register: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }

    // Combine the bytes to form the 16-bit raw value
    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

// Function to convert raw value to amperes
float convert_to_amperes(int16_t raw_value) {
    return (float)raw_value * SENSITIVITY / VREF;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int16_t raw_value = read_ads1115();

        // Convert to amperes
        float current = convert_to_amperes(raw_value);

        // Print the current value
        printf("Current: %.3f A\n", current);

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

