#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define FLAME_SENSOR_GPIO 4
#define MCP3008_CE_GPIO 8
#define CSV_FILENAME "flame_data.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
int log_data(time_t timestamp, int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int flame_sensor_gpio;
    int mcp3008_ce_gpio;
    char csv_filename[64];
    int sample_interval_sec;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_BAUD,
    FLAME_SENSOR_GPIO,
    MCP3008_CE_GPIO,
    CSV_FILENAME,
    SAMPLE_INTERVAL_SEC
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(config.csv_filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        time_t now = time(NULL);
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(0);
        float temperature = calculate_temperature(adc_value);

        if (log_data(now, flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        gpioDelay(config.sample_interval_sec * 1000000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read flame sensor
int read_flame_sensor() {
    return gpioRead(config.flame_sensor_gpio);
}

// Read MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(config.mcp3008_ce_gpio, 0); // Select the MCP3008
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(config.mcp3008_ce_gpio, 1); // Deselect the MCP3008

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate temperature (linear approximation)
float calculate_temperature(int adc_value) {
    // Assuming 0 ADC value corresponds to 20°C and 1023 ADC value corresponds to 50°C
    float temperature = 20.0 + (float)adc_value / 1023.0 * 30.0;
    return temperature;
}

// Log data to CSV file
int log_data(time_t timestamp, int flame_detected, float temperature) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp_str, flame_detected, temperature);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

