#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27

// Define ADS1115 I2C address
#define ADS1115_ADDR 0x48

// Define ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Define ADS1115 configuration values
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060 // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_ACTV_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Define temperature threshold
#define TEMPERATURE_THRESHOLD 60.0

// Define debounce delay
#define DEBOUNCE_DELAY 50

// Global variables
static volatile bool running = true;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int init_log(void);
int read_flame_sensor(void);
int read_temperature(int *raw_value);
float convert_to_celsius(int raw_value);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup(void);

// Function to initialize GPIO
int init_gpio(void) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(FLAME_SENSOR_PIN, INPUT);
    pinMode(BUZZER_PIN, OUTPUT);
    digitalWrite(BUZZER_PIN, LOW); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int init_i2c(void) {
