    int config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_ACTV_LOW | ADS1115_CONFIG_COMP_LAT_NON_LATCH | ADS1115_CONFIG_COMP_QUE_DISABLE;
