        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    if (adc_value == 0) {
        fprintf(stderr, "Error: ADC value is zero, sensor absent.\n");
        return -1.0; // Indicate sensor error
    }
    if (adc_value == 1023) {
        fprintf(stderr, "Error: ADC value is all ones, sensor error.\n");
        return -2.0; // Indicate sensor error
    }

    float voltage = (float)adc_value * VREF / 1024.0;
    float current = (voltage - SENSOR_OFFSET) / SENSOR_SENSITIVITY;
    return current;
}

// Log current function
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f mA\n", timestamp, current);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Control fan function
int control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Ensure fan is OFF
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting measurement loop...\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);
        if (current < 0) {
            fprintf(stderr, "Error converting ADC to current, skipping...\n");
            sleep(1);
            continue;
        }

        // Log current
        if (log_current(current) != 0) {
            fprintf(stderr, "Error logging current.\n");
        }

        // Control fan
        control_fan(current);

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

