#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define temperature conversion parameters
#define ADC_MAX 1023.0
#define TEMP_MIN 20.0
#define TEMP_MAX 50.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
int log_data(int flame_presence, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int flame_presence = gpioRead(FLAME_SENSOR_PIN);
    if (flame_presence < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", flame_presence);
        return -1; // Indicate an error
    }
    return flame_presence;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS_PIN, 0); // Select the MCP3008
    int spi_result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect the MCP3008

    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", spi_result);
        return -1; // Indicate an error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature
float convert_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate an error
    }

    float temperature = TEMP_MIN + (adc_value / ADC_MAX) * (TEMP_MAX - TEMP_MIN);
    return temperature;
}

// Function to log data to CSV file
int log_data(int flame_presence, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_presence, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int flame_presence = read_flame_sensor();
        if (flame_presence < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping logging.\n");
        } else {
            int adc_value = read_mcp3008(0);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading MCP3008, skipping logging.\n");
            } else {
                float temperature = convert_to_temperature(adc_value);
                if (temperature < 0) {
                    fprintf(stderr, "Error converting temperature, skipping logging.\n");
                } else {
                    if (log_data(flame_presence, temperature) != 0) {
                        fprintf(stderr, "Error logging data.\n");
                    }
                }
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

