    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int flame_presence = read_flame_sensor();
        if (flame_presence < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping logging.\n");
