        // Convert CO ADC to ppm
        float co_ppm = convert_to_co_ppm(sensor_data.co_adc);

        // Log CO value
        log_co_value(co_ppm);

        // Check alert threshold
        check_alert_threshold(co_ppm);

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

