#include <string.h>

// Define GPIO pins for I2C
#define I2C_SDA 2
#define I2C_SCL 3

// Define I2C address of the IMP23ABSU sensor
#define IMP23ABSU_ADDR 0x41

// Define register address for reading the sound pressure level
#define SPL_REG 0x00

// Define the sampling interval in milliseconds
#define SAMPLE_INTERVAL_MS 100

// Define the log file name
#define LOG_FILE "audio_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float sensor1_spl;
    float sensor2_spl;
} SensorData;

// Function prototypes
int init_i2c();
float read_spl(int handle, int sensor_id);
float average_spl(float spl1, float spl2);
void log_data(float avg_spl);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, IMP23ABSU_ADDR, 0); // Bus 1, address 0x41, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sound pressure level from a single sensor
float read_spl(int handle, int sensor_id) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, SPL_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading SPL from sensor %d: %d\n", sensor_id, result);
        return -999.0; // Indicate error
    }

    // Convert the two bytes to a float (example conversion, adjust as needed)
    int16_t raw_value = (buf[0] << 8) | buf[1];
    float spl = (float)raw_value / 10.0; // Example scaling

    return spl;
}

// Calculate the average sound pressure level
float average_spl(float spl1, float spl2) {
    return (spl1 + spl2) / 2.0;
}

// Log the data to a file
void log_data(float avg_spl) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, avg_spl);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        float spl1 = read_spl(i2c_handle, 1);
        float spl2 = read_spl(i2c_handle, 2);

        if (spl1 == -999.0 || spl2 == -999.0) {
            fprintf(stderr, "Error reading from one or more sensors, using -999.0 for average.\n");
        }

        float avg_spl = average_spl(spl1, spl2);

        log_data(avg_spl);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for the sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

