#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_SAMPLES 100
#define SAMPLE_PERIOD_MS 1
#define WINDOW_DURATION_MS (NUM_SAMPLES * SAMPLE_PERIOD_MS)
#define RMS_THRESHOLD 0.1
#define LED_GPIO 27
#define CS_GPIO_1 8
#define CS_GPIO_2 9

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double timestamp, double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_GPIO_1, 0); // Select chip
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_GPIO_1, 1); // Deselect chip

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
void log_data(double timestamp, double mic1_rms, double mic2_rms) {
    fprintf(log_file, "%.6f,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Turn LED off initially

    // Configure CS GPIOs
    gpioSetMode(CS_GPIO_1, PI_OUTPUT);
    gpioSetMode(CS_GPIO_2, PI_OUTPUT);
    gpioWrite(CS_GPIO_1, 1); // Deselect chip initially
    gpioWrite(CS_GPIO_2, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    int sample_index = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (!terminate) {
        // Read audio samples
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            mic1_samples[sample_index] = adc_value;
        } else {
            fprintf(stderr, "Error reading mic1, skipping sample\n");
            continue;
        }

        adc_value = read_mcp3008(1);
        if (adc_value >= 0) {
            mic2_samples[sample_index] = adc_value;
        } else {
            fprintf(stderr, "Error reading mic2, skipping sample\n");
            continue;
        }

        sample_index++;

        // Check if window is complete
        if (sample_index == NUM_SAMPLES) {
            // Calculate RMS values
            double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
            double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &current_time);
            double timestamp = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

            // Log data
            log_data(timestamp, mic1_rms, mic2_rms);

            // Check RMS thresholds and control LED
