#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0
#define SENSITIVITY 0.1 // 100mV/A
#define VREF 4.096 // 4.096V

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int16_t read_ads1115();
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float calculate_average();
void control_led(int state);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    float current_threshold;
    float sensitivity;
    float vref;
} config_t;

config_t config = {
    I2C_BUS,
    ADS1115_ADDR,
    LED_GPIO,
    CURRENT_THRESHOLD,
    SENSITIVITY,
    VREF
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int16_t raw_value = read_ads1115();

        // Convert raw value to current
        float current = convert_to_current(raw_value);

        // Add current to circular buffer
        add_to_buffer(current);

        // Calculate average current
        float average_current = calculate_average();

        // Control LED based on average current
        if (average_current > config.current_threshold) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(config.led_gpio, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended channel A0, 4.096V range, 128 SPS
    // Configuration register value: OS = 0 (Start single conversion), MUX = 001 (AIN0, GND), PGA = 010 (+/-4.096V), MODE = 1 (Single-shot mode), DR = 100 (128 SPS), COMP_MODE = 0 (Traditional comparator), COMP_POL = 0 (Active low), COMP_LAT = 0 (Non-latching), COMP_QUE = 0 (Disable comparator)
    uint16_t config_value = 0x4083; //0b0100000010000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;       // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return 1;
    }

    return 0;
}

// Read raw value from ADS1115
int16_t read_ads1115() {
    char buf[1];
    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for conversion\n");
        return 0; // Return 0 on error
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return 0; // Return 0 on error
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Convert raw value to current
float convert_to_current(int16_t raw_value) {
    float current = (raw_value * config.vref / 32768.0) / config.sensitivity;
    return current;
}

// Add current to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED
void control_led(int state) {
    gpioWrite(config.led_gpio, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

