#define TCS34725_ATIME 0x81
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int tcs34725_init();
int tcs34725_read_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
char* format_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
int write_to_log(const char *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, exiting gracefully.\n", signal);
        program_running = 0;
    }
}

// Initialize the TCS34725 sensor
int tcs34725_init() {
    uint8_t enable_value = 0x03; // Power on and enable RGBC
    uint8_t atime_value = 0xD5; // Integration time

    // Enable the sensor
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ENABLE, enable_value) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ATIME, atime_value) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ATIME: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read color data from the TCS34725 sensor
int tcs34725_read_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        *clear = i2c_smbus_read_word_data(i2c_fd, TCS34725_CDATA);
        *red = i2c_smbus_read_word_data(i2c_fd, TCS34725_RDATA);
        *green = i2c_smbus_read_word_data(i2c_fd, TCS34725_GDATA);
        *blue = i2c_smbus_read_word_data(i2c_fd, TCS34725_BDATA);

        if (i2c_smbus_read_word_data(i2c_fd, TCS34725_CDATA) >= 0 &&
            i2c_smbus_read_word_data(i2c_fd, TCS34725_RDATA) >= 0 &&
            i2c_smbus_read_word_data(i2c_fd, TCS34725_GDATA) >= 0 &&
            i2c_smbus_read_word_data(i2c_fd, TCS34725_BDATA) >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retrying in %d ms...\n", delay_ms);
            usleep(delay_ms * 1000); // Sleep for delay_ms milliseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Failed to read color data after multiple retries.\n");
    return -1; // Failure
}

// Format the color data into a comma-separated string
char* format_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char data_string[100]; // Static to preserve value between calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(data_string, sizeof(data_string), "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    return data_string;
}

// Write the formatted data to the log file
int write_to_log(const char *data) {
    if (fputs(data, log_file) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

int main() {
    uint16_t clear, red, green, blue;
    char *data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (program_running) {
        // Read color data
        if (tcs34725_read_data(&clear, &red, &green, &blue) == 0) {
            // Format the data
            data = format_data(clear, red, green, blue);

            // Write the data to the log file
            if (write_to_log(data) != 0) {
                fprintf(stderr, "Failed to write data to log.\n");
            }
        } else {
            fprintf(stderr, "Failed to read color data.\n");
        }

        // Wait for 1 second
        struct timespec req = {1, 0}; // 1 second
        nanosleep(&req, NULL);
    }

    // Close the I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program finished.\n");
    return 0;
}

