    return 0;
}

// Over-current protection function
void over_current_protection(float current) {
    if (current > OVER_CURRENT_THRESHOLD) {
        printf("Over-current detected: %.3f A\n", current);
        gpioWrite(MOTOR_CONTROL_GPIO, 0); // Disable motor
        log_current(current); // Log the over-current event
        sleep(1); // Wait for 1 second
        gpioWrite(MOTOR_CONTROL_GPIO, 1); // Re-enable motor
    }
}

// Signal handler function
