#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define TMP36_SENSITIVITY 0.010 // 10mV/°C
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define LOG_FILE "temperature_log.csv"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_ioctl(int fd, int request, unsigned long arg);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int spi_close(int fd);
int read_mcp3208(int channel);
float convert_to_celsius(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);
int check_temperature_range(float temperature);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return fd;
}

// SPI ioctl function
int spi_ioctl(int fd, int request, unsigned long arg) {
    if (ioctl(fd, request, arg) < 0) {
        perror("Error performing SPI ioctl");
        return -1;
    }
    return 0;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error performing SPI transfer");
        return -1;
    }
    return 0;
}

// SPI close function
int spi_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing SPI device");
        return -1;
    }
    return 0;
}

// Read MCP3208 function
int read_mcp3208(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading MCP3208 channel %d\n", channel);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert to Celsius function
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature_celsius = (voltage - 0.5) / TMP36_SENSITIVITY;
    return temperature_celsius;
}

// Log temperature function
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Check temperature range function
int check_temperature_range(float temperature) {
    if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
        fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure SPI
    if (spi_ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (spi_ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD) < 0) {
        spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (spi_ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Check temperature range
        if (check_temperature_range(temperature) < 0) {
            fprintf(stderr, "Temperature out of range, skipping logging.\n");
        } else {
            // Log temperature
            if (log_temperature(temperature) < 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        spi_close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

