#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define FULL_SCALE_VOLTAGE 5.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 5.0
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel(int channel, int speed);
int read_mcp3008(int channel);
float convert_to_flow_rate(int adc_value);
int validate_flow_rate(float flow_rate);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float full_scale_voltage;
    float min_flow_rate;
    float max_flow_rate;
    char *log_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    FULL_SCALE_VOLTAGE,
    MIN_FLOW_RATE,
    MAX_FLOW_RATE,
    LOG_FILE
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = open_spi_channel(config.spi_channel, config.spi_speed);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Continuing.\n");
            continue;
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Validate flow rate
        if (validate_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Flow rate out of range: %.2f L/min\n", flow_rate);
        }

        // Log data
        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to flow rate
float convert_to_flow_rate(int adc_value) {
    if (adc_value == 0) {
        return 0.0;
    } else if (adc_value == 1023) {
        return config.full_scale_voltage;
    } else {
        return (float)adc_value / 1023.0 * config.full_scale_voltage;
    }
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < config.min_flow_rate || flow_rate > config.max_flow_rate) {
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

