#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICP_10125_ADDR 0x68
#define HIGH_PRECISION_MEASUREMENT_CMD 0x2D
#define DATA_LENGTH 6
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 5
#define CSV_FILENAME "environmental_data.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients (example values, replace with actual values from datasheet)
float T_sensitivity = 0.01;  // Example sensitivity
float P_sensitivity = 0.001; // Example sensitivity
float T_offset = 25.0;       // Example offset
float P_offset = 100000.0;    // Example offset

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int process_sensor_data(uint8_t *data, float *temperature, float *pressure);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP_10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
        if (result == DATA_LENGTH) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_SEC * 1000000); // Delay in microseconds
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Process sensor data
int process_sensor_data(uint8_t *data, float *temperature, float *pressure) {
    // Extract raw values
    int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    // Apply calibration formulas
    *temperature = (float)raw_temperature * T_sensitivity + T_offset;
    *pressure = (float)raw_pressure * P_sensitivity + P_offset;

    return 0;
}

// Log data to CSV file
int log_data(float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        return -1;
    }

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fclose(csv_file);

    return 0;
}

// Display data on console
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t data[DATA_LENGTH];
    float temperature, pressure;

    while (!terminate) {
        // Send high-precision measurement command
        if (i2cWriteByteData(i2c_handle, 0x00, HIGH_PRECISION_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Error writing to I2C.\n");
            gpioDelay(RETRY_DELAY_SEC * 1000000);
            continue;
        }

        gpioDelay(10000); // Wait for conversion (adjust as needed)

        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Process sensor data
            if (process_sensor_data(data, &temperature, &pressure) == 0) {
                // Log data
                if (log_data(temperature, pressure) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }

                // Display data
                display_data(temperature, pressure);
            } else {
                fprintf(stderr, "Error processing sensor data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(5000000); // Sample every 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

