#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define NOISE_CANCELLATION_THRESHOLD 100
#define DEFAULT_GAIN 1.0
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold program configuration
typedef struct {
    double gain;
} ProgramConfig;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
int noise_cancellation(int sample1, int sample2);
void print_csv(int sample1, int sample2);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], ProgramConfig *config);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Noise cancellation algorithm
int noise_cancellation(int sample1, int sample2) {
    int difference = abs(sample1 - sample2);
    if (difference > NOISE_CANCELLATION_THRESHOLD) {
        return (sample1 + sample2) / 2; // Average the samples
    } else {
        return sample1; // Return the first sample
    }
}

// Print CSV data
void print_csv(int sample1, int sample2) {
    printf("%d,%d\n", sample1, sample2);
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[], ProgramConfig *config) {
    if (argc > 1) {
        char *endptr;
        config->gain = strtod(argv[1], &endptr);
        if (*endptr != '\0' || config->gain <= 0) {
            fprintf(stderr, "Invalid gain value: %s\n", argv[1]);
            return -1;
        }
    } else {
        config->gain = DEFAULT_GAIN;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    ProgramConfig config;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &config) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sampling audio... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sample1 = read_mcp3008(MCP3008_CHANNEL_0);
        int sample2 = read_mcp3008(MCP3008_CHANNEL_1);

        if (sample1 < 0 || sample2 < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Apply gain
        sample1 = (int)(sample1 * config.gain);
        sample2 = (int)(sample2 * config.gain);

        // Noise cancellation
        int cancelled_sample1 = noise_cancellation(sample1, sample2);
        int cancelled_sample2 = noise_cancellation(sample2, sample1);

        // Print CSV data
        print_csv(cancelled_sample1, cancelled_sample2);

        gpioDelay(SAMPLE_PERIOD_US); // Delay to achieve desired sample rate
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

