// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float temperature_compensation(int adc_value, float temperature);
void log_data(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);
float read_ambient_temperature();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Dummy byte

    // Perform SPI transfer
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to perform temperature compensation
float temperature_compensation(int adc_value, float temperature) {
    // Simple linear compensation (replace with actual calibration curve)
    return (float)adc_value * 0.003 + temperature;
}

// Function to log data to file
void log_data(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open ambient temperature file %s, using default temperature 25.0\n", AMBIENT_TEMP_FILE);
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Warning: Invalid temperature in file %s, using default temperature 25.0\n", AMBIENT_TEMP_FILE);
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially OFF

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value;
        float temperature = read_ambient_temperature();
        int retry = 0;

        // Retry loop for ADC reading
        while (retry < RETRY_COUNT) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Error: ADC read failed, retrying (%d/%d)\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed after multiple retries\n");
            log_data(-1, -1.0, -1.0, temperature, 0); // Log error
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
            log_data(adc_value, -1.0, -1.0, temperature, 0); // Log error
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value * 3.3 / 1024.0;

        // Perform temperature compensation
        float compensated_voltage = temperature_compensation(adc_value, temperature);

        // Flame detection logic (example: voltage > 0.5V)
        int flame_detected = (compensated_voltage > 0.5) ? 1 : 0;

        // Log data
        log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

