// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define AWM7300V_MIN_VOLTAGE 0.5
#define AWM7300V_MAX_VOLTAGE 4.5
#define AWM7300V_MIN_FLOW 0.0
#define AWM7300V_MAX_FLOW 100.0
#define LOG_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
float convert_to_flow(float voltage);
char* get_iso8601_timestamp();
int log_data(float flow);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 5.0; // Assuming 5V reference
}

// Convert voltage to Liters Per Minute
float convert_to_flow(float voltage) {
    return ((voltage - AWM7300V_MIN_VOLTAGE) / (AWM7300V_MAX_VOLTAGE - AWM7300V_MIN_VOLTAGE)) * (AWM7300V_MAX_FLOW - AWM7300V_MIN_FLOW) + AWM7300V_MIN_FLOW;
}

