#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_calibration;
    int max_calibration;
    int moisture_threshold;
    int logging_interval;
    char email_recipient[256];
    char msmtp_config_path[256];
} Config;

// Global variables
int spi_handle;
FILE *log_file;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, Config *config);
int read_mcp3008(int spi_handle, int channel);
float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration);
int log_data(FILE *log_file, float moisture_percentage);
int send_email(const char *email_recipient, const char *msmtp_config_path, float moisture_percentage);
void signal_handler(int signal);

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s\n", filename);
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(key, "min_calibration") == 0) {
            config->min_calibration = atoi(value);
        } else if (strcmp(key, "max_calibration") == 0) {
            config->max_calibration = atoi(value);
        } else if (strcmp(key, "moisture_threshold") == 0) {
            config->moisture_threshold = atoi(value);
        } else if (strcmp(key, "logging_interval") == 0) {
            config->logging_interval = atoi(value);
        } else if (strcmp(key, "email_recipient") == 0) {
            strncpy(config->email_recipient, value, sizeof(config->email_recipient) - 1);
            config->email_recipient[sizeof(config->email_recipient) - 1] = '\0';
        } else if (strcmp(key, "msmtp_config_path") == 0) {
            strncpy(config->msmtp_config_path, value, sizeof(config->msmtp_config_path) - 1);
            config->msmtp_config_path[sizeof(config->msmtp_config_path) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration) {
    float percentage = 100.0 - ((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration) * 100.0);
    if (percentage < 0.0) percentage = 0.0;
    if (percentage > 100.0) percentage = 100.0;
    return percentage;
}

// Function to log data to file
int log_data(FILE *log_file, float moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to send email alert
int send_email(const char *email_recipient, const char *msmtp_config_path, float moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char email_body[512];
