#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel to read
#define VREF 3.3          // Reference voltage
#define MIN_VOLTAGE 0.5   // Minimum expected voltage (V)
#define MAX_VOLTAGE 4.5   // Maximum expected voltage (V)
#define MIN_PRESSURE 0.0  // Minimum expected pressure (kPa)
#define MAX_PRESSURE 100.0 // Maximum expected pressure (kPa)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (example)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    float min_voltage;
    float max_voltage;
    float min_pressure;
    float max_pressure;
} sensor_config_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert voltage to pressure (linear relationship)
float voltage_to_pressure(float voltage) {
    // Assuming a linear relationship: pressure = (voltage - min_voltage) / (max_voltage - min_voltage) * (max_pressure - min_pressure) + min_pressure
    return (voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
}

// Log data with timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("Timestamp: %s, Pressure: %.2f kPa\n", timestamp, pressure);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Sensor node started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            // Validate ADC value
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            } else {
                // Convert ADC value to voltage
                float voltage = (float)adc_value / 1023.0 * VREF;

                // Convert voltage to pressure
                float pressure = voltage_to_pressure(voltage);

                // Log the data
                log_data(pressure);
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

