#define MIN_ADC_VALUE 10
#define MAX_ADC_VALUE 1010

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the SPI device if it's open
    if (spi_fd != -1)
    {
        spiClose(spi_fd);
        printf("SPI device closed.\n");
    }

    // Terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel)
{
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer the data over SPI
    int result = spiXfer(spi_fd, tx_buffer, rx_buffer, 3);

    if (result != 0)
    {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1; // Indicate an error
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

