{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the SPI interface
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_fd < 0)
    {
        fprintf(stderr, "SPI open failed: %d\n", spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Sensor Data Logger\n");

    // Main loop to read and log sensor data
    while (1)
    {
        // Read the ADC value from the MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        if (adc_value < 0)
        {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds...\n", SAMPLING_INTERVAL);
            gpioDelay(SAMPLING_INTERVAL * 1000000); // Delay for the sampling interval
            continue; // Skip to the next iteration
        }

        // Get the current timestamp
