#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define RELAY_GPIO 17
#define DOOR_SENSOR_GPIO 27
#define THRESHOLD 500 // Calibrated threshold
#define RELAY_DURATION 3 // seconds
#define SAMPLE_INTERVAL 200 // milliseconds
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_INTERVAL 50 // milliseconds
#define LOG_FILE "/var/log/door_events.log"

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, unsigned char reg);
int i2c_write_word(int fd, unsigned char reg, unsigned short value);
int read_adc(int fd, int channel);
int calibrate_threshold(int fd, int samples);
void control_relay(int gpio, int state);
int read_door_sensor(int gpio);
void log_event(const char *event);
void signal_handler(int sig);

// I2C read word function
int i2c_read_word(int fd, unsigned char reg) {
    unsigned char buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write word function
int i2c_write_word(int fd, unsigned char reg, unsigned short value) {
    unsigned char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int fd, int channel) {
    unsigned short config;

    // Configure ADS1115 for single-ended read on specified channel
    config = 0x4000 | (channel << 12); // Single-ended, +/-4.096V, 128 SPS
    config |= 0x0080; // Start single conversion

    if (i2c_write_word(fd, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10);

    int adc_value = i2c_read_word(fd, CONVERSION_REG);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    return adc_value;
}

// Calibrate the threshold value
int calibrate_threshold(int fd, int samples) {
    int sum = 0;
    for (int i = 0; i < samples; i++) {
        int adc_value = read_adc(fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Calibration failed: Could not read ADC value\n");
            return -1;
        }
        sum += adc_value;
        gpioDelay(CALIBRATION_INTERVAL);
    }
    return sum / samples;
}

// Control the relay
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Read the door sensor
int read_door_sensor(int gpio) {
    return gpioRead(gpio);
}

// Log events to file
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Configure door sensor GPIO as input with pull-up resistor
    gpioSetMode(DOOR_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(DOOR_SENSOR_GPIO, PI_PUD_UP);

    // Calibrate the threshold
    int threshold = calibrate_threshold(i2c_fd, CALIBRATION_SAMPLES);
    if (threshold < 0) {
        fprintf(stderr, "Threshold calibration failed. Exiting.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    printf("Calibrated threshold: %d\n", threshold);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(i2c_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying...\n");
            log_event("Sensor failure");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        if (adc_value < threshold) {
            printf("Distance below threshold. Activating relay.\n");
            log_event("Distance below threshold. Activating relay.");
            control_relay(RELAY_GPIO, 1); // Activate relay
            gpioDelay(RELAY_DURATION * 1000); // Wait for relay duration
            control_relay(RELAY_GPIO, 0); // Deactivate relay
            log_event("Relay deactivated.");

            int door_state = read_door_sensor(DOOR_SENSOR_GPIO);
            if (door_state == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(RELAY_GPIO, 0); // Ensure relay is off
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

