#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for chip select lines
#define CS0 8
#define CS1 7
#define CS2 25

// SPI channel
#define SPI_CHANNEL 0

// SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// SPI flags
#define SPI_FLAGS 0

// File name for logging
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int cs_pin, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int cs_pin, int channel) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    gpioWrite(cs_pin, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(cs_pin, 1); // Deselect the chip

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output for chip select lines
    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    // Initialize chip select lines to high (inactive)
    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1 = read_mcp3008(CS0, 0);
        int sensor2 = read_mcp3008(CS1, 0);
        int sensor3 = read_mcp3008(CS2, 0);

        // Open log file in append mode
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            break; // Exit loop on file open error
        }

        // Check if the file is newly created (empty)
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            // Write header if the file is empty
            fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        }
        fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

        // Log data
        if (log_data(log_file, sensor1, sensor2, sensor3) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Close log file
        fclose(log_file);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

