#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 0.3
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Configuration
static float threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
int should_irrigate(float voltage, float threshold);
void activate_pump(int duration_seconds);
void deactivate_pump();
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to determine if irrigation is needed
int should_irrigate(float voltage, float threshold) {
    return (voltage < threshold) ? 1 : 0;
}

// Function to activate the water pump
void activate_pump(int duration_seconds) {
    gpioWrite(PUMP_GPIO, 1); // Set GPIO HIGH
    log_message("Pump activated");
    sleep(duration_seconds);
    gpioWrite(PUMP_GPIO, 0); // Set GPIO LOW
    log_message("Pump deactivated");
}

// Function to deactivate the water pump
void deactivate_pump() {
    gpioWrite(PUMP_GPIO, 0); // Set GPIO LOW
    log_message("Pump deactivated (forced)");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    deactivate_pump();
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Threshold: %.2f, Duration: %d, Sleep Interval: %d\n", threshold, duration, sleep_interval);

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            log_message("Error: Failed to read ADC value");
        } else {
            float voltage = adc_to_voltage(adc_value);
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "ADC Value: %d, Voltage: %.2f", adc_value, voltage);
            log_message(log_buffer);

            if (should_irrigate(voltage, threshold)) {
                activate_pump(duration);
            }
        }

        sleep(sleep_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

