#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "/var/log/sound_events.log"
#define PEAK_THRESHOLD_FACTOR 1.5
#define NUM_SAMPLES_FOR_THRESHOLD 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    int spi_handle;
    FILE *log_file;
    int terminate;
} ProgramState;

ProgramState state;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float calculate_dynamic_threshold(int *samples, int num_samples);
int detect_peak(int sample, float threshold);
int log_event(int sample);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate dynamic threshold
float calculate_dynamic_threshold(int *samples, int num_samples) {
    if (num_samples <= 0) return 0.0;

    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    float average = sum / num_samples;
    return average * PEAK_THRESHOLD_FACTOR;
}

// Detect peak
int detect_peak(int sample, float threshold) {
    return sample > threshold;
}

// Log event
int log_event(int sample) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, sample);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sampling loop
    int samples[NUM_SAMPLES_FOR_THRESHOLD];
    int sample_index = 0;
    float threshold = 0.0;

    while (!terminate) {
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        samples[sample_index] = sample;
        sample_index = (sample_index + 1) % NUM_SAMPLES_FOR_THRESHOLD;

        if (sample_index == 0) {
            // Calculate threshold every NUM_SAMPLES_FOR_THRESHOLD samples
            threshold = calculate_dynamic_threshold(samples, NUM_SAMPLES_FOR_THRESHOLD);
        }

        if (detect_peak(sample, threshold)) {
            log_event(sample);
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

