#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_PIN 27
#define THRESHOLD 500.0f // Gauss
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)

// Global variables
static int i2c_fd;
static volatile sig_atomic_t program_running = 1;

// Circular buffer
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float convert_to_voltage(int16_t adc_value);
float convert_to_gauss(float voltage);
void update_circular_buffer(float gauss);
float calculate_average();
void check_threshold(float average);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to initialize I2C: %s", strerror(errno));
        return -1;
    }

    // Configure ADS1115 for single-ended channel AIN0, 4.096V range, single-shot mode
    int16_t config = 0x4003; // 0b0100000000000011
    if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_REG_CONFIG, __builtin_bswap16(config)) == -1) {
        syslog(LOG_ERR, "Failed to write to ADS1115 config register: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read ADC value
int16_t read_adc() {
    int16_t adc_value;

    // Start a single conversion
    if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_REG_CONFIG, __builtin_bswap16(0x8003)) == -1) {
        syslog(LOG_ERR, "Failed to start conversion: %s", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    delay(10);

    adc_value = wiringPiI2CReadReg16(i2c_fd, ADS1115_REG_CONVERT);
    if (adc_value == -1) {
        syslog(LOG_ERR, "Failed to read ADC value: %s", strerror(errno));
        return -1;
    }

    // Swap bytes (ADS1115 returns big-endian)
    adc_value = __builtin_bswap16(adc_value);

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int16_t adc_value) {
    // ADS1115 is a 16-bit ADC, so the full range is 32768 (2^15)
    // Assuming 4.096V range, each step is 4.096V / 32768
    float voltage = (float)adc_value * 4.096f / 32768.0f;
    return voltage;
}

// Function to convert voltage to magnetic field strength (Gauss)
float convert_to_gauss(float voltage) {
    // Assuming a linear relationship: 0V = 0 Gauss, 3.3V = 1000 Gauss
    // This is a simplified model; a more accurate conversion might require calibration
    float gauss = voltage * 1000.0f / 3.3f;
    return gauss;
}

// Function to update the circular buffer
void update_circular_buffer(float gauss) {
    buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average of the circular buffer
float calculate_average() {
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to check if the threshold is exceeded
void check_threshold(float average) {
    if (average > THRESHOLD) {
        syslog(LOG_INFO, "Threshold exceeded: Average = %.2f Gauss, Threshold = %.2f Gauss", average, THRESHOLD);
        digitalWrite(GPIO_PIN, HIGH); // Activate motor shutdown
    } else {
        digitalWrite(GPIO_PIN, LOW);  // Deactivate motor shutdown
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, stopping program...");
    program_running = 0;
    digitalWrite(GPIO_PIN, LOW); // Deactivate motor shutdown
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("magnetic_field_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        syslog(LOG_ERR, "I2C initialization failed, exiting...");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Program started successfully");

    // Main loop
    while (program_running) {
        int16_t adc_value = read_adc();
        if (adc_value == -1) {
            syslog(LOG_ERR, "Failed to read ADC, skipping sample");
            delay(SAMPLE_PERIOD_MS);
            continue;
        }

        float voltage = convert_to_voltage(adc_value);
        if (voltage < 0.0f || voltage > 3.3f) {
            syslog(LOG_ERR, "Voltage out of range: %.2f V", voltage);
            delay(SAMPLE_PERIOD_MS);
            continue;
        }

        float gauss = convert_to_gauss(voltage);
        update_circular_buffer(gauss);
        float average = calculate_average();
        check_threshold(average);

        delay(SAMPLE_PERIOD_MS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    digitalWrite(GPIO_PIN, LOW);
    closelog();
    return 0;
}

