#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO 18
#define PUMP_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int is_moisture_low(int adc_value, int threshold);
void activate_pump(int gpio_pin);
void deactivate_pump(int gpio_pin);
void log_event(int adc_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to check if moisture level is low
int is_moisture_low(int adc_value, int threshold) {
    return adc_value < threshold;
}

// Function to activate the water pump
void activate_pump(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
    printf("Pump activated\n");
}

// Function to deactivate the water pump
void deactivate_pump(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO low
    printf("Pump deactivated\n");
}

// Function to log watering event
void log_event(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC Value: %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    deactivate_pump(PUMP_GPIO); // Ensure pump is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Check moisture level
        if (is_moisture_low(adc_value, MOISTURE_THRESHOLD)) {
            printf("Moisture level low (ADC: %d)\n", adc_value);

            // Activate pump
            activate_pump(PUMP_GPIO);

            // Log event
            log_event(adc_value);

            // Wait for pump duration
            gpioDelay(PUMP_DURATION * 1000000); // microseconds

            // Deactivate pump
            deactivate_pump(PUMP_GPIO);
        }

        // Wait 60 seconds
        gpioDelay(60 * 1000000); // microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_pump(PUMP_GPIO); // Ensure pump is off
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

