// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define ADC_MAX 1023
#define RAINFALL_INTENSITY_MAX 100.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_rainfall(int adc_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to rainfall intensity
float adc_to_rainfall(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return 0.0;
    }

    float voltage = (float)adc_value * VREF / ADC_MAX;
    float rainfall_intensity = (voltage / VREF) * RAINFALL_INTENSITY_MAX;

    return rainfall_intensity;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI_MODE_0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to rainfall intensity
        float rainfall_intensity = adc_to_rainfall(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to stdout
        printf("%s, ADC: %d, Rainfall: %.2f\n", timestamp, adc_value, rainfall_intensity);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

