#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SLEEP_MS 100

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_adc(int16_t *value);
double convert_to_gauss(int16_t raw_value);
void check_threshold_and_blink(double gauss);
void signal_handler(int signal);
void cleanup();

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    double threshold;
} config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to read ADC value
int read_adc(int16_t *value) {
    char buf[2];
    int result;

    // Configure ADS1115 for single-ended input on AIN0, PGA gain 4.096V
    uint16_t config = 0x4003; // Single-ended AIN0, 4.096V, Start single conversion

    // Write configuration to ADS1115
    buf[0] = (config >> 8) & 0xFF;
    buf[1] = config & 0xFF;

    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 4.096V PGA)
    gpioDelay(10);

    // Read conversion result
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw ADC value to Gauss
double convert_to_gauss(int16_t raw_value) {
    // Assuming 2^15 counts per Gauss (2^15 / 4.096V = 32768)
    return (double)raw_value / 32768.0;
}

// Function to check threshold and blink LED
void check_threshold_and_blink(double gauss) {
    if (gauss > threshold) {
        for (int i = 0; i < 5; ++i) { // Blink for 1 second (5 * 20ms)
            gpioWrite(LED_GPIO, 1);
            gpioDelay(50); // 50ms on
            gpioWrite(LED_GPIO, 0);
            gpioDelay(50); // 50ms off
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Using threshold: %.2f Gauss\n", threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_value;
    double gauss;

    // Main loop
    while (!terminate) {
        if (read_adc(&raw_value) == 0) {
            gauss = convert_to_gauss(raw_value);
            printf("Magnetic Field Strength: %.2f Gauss\n", gauss);
            check_threshold_and_blink(gauss);
        } else {
            fprintf(stderr, "Error reading ADC, retrying...\n");
        }
        gpioDelay(SLEEP_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

