#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define HYSTERESIS_LOW 30
#define HYSTERESIS_HIGH 35
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35

// Global variables
static int spi_handle;
static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int pump_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void pump_on();
void pump_off();
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signum);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "Invalid ADC value: %d", adc_value);
        return -1.0;
    }

    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to turn the pump on
void pump_on() {
    gpioWrite(PUMP_GPIO, 1); // Set GPIO high
    pump_state = 1;
    syslog(LOG_INFO, "Pump turned ON");
}

// Function to turn the pump off
void pump_off() {
    gpioWrite(PUMP_GPIO, 0); // Set GPIO low
    pump_state = 0;
    syslog(LOG_INFO, "Pump turned OFF");
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_ERR, "MQTT disconnected unexpectedly with code %d", rc);
    } else {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    }
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "pump_on") == 0) {
            pump_on();
        } else if (strcmp(payload, "pump_off") == 0) {
            pump_off();
        } else {
            syslog(LOG_WARNING, "Unknown MQTT message: %s", payload);
        }
    }
}

// Signal handler
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    running = 0;

    // Turn off the pump
    pump_off();

    // Disconnect from MQTT
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    syslog(LOG_INFO, "Cleanup complete, exiting.");
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    pump_off(); // Ensure pump is off initially

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

