void set_motor_speed(int gpio, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    gpioPWM(gpio, speed);
}

// Function to log vibration events
void log_vibration_event(int noise_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Vibration detected! Noise level: %d\n", timestamp, noise_level);
