    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        int noise_level = calculate_noise_level(adc_value);

        if (noise_level > NOISE_THRESHOLD) {
            set_motor_speed(MOTOR1_GPIO, PWM_RANGE / 2); // 50% duty cycle
            set_motor_speed(MOTOR2_GPIO, PWM_RANGE / 2); // 50% duty cycle
            log_vibration_event(noise_level);
        } else {
            set_motor_speed(MOTOR1_GPIO, 0);
            set_motor_speed(MOTOR2_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 10ms
    }

    // Cleanup
    printf("Stopping motors...\n");
    set_motor_speed(MOTOR1_GPIO, 0);
    set_motor_speed(MOTOR2_GPIO, 0);

    printf("Closing SPI...\n");
    spiClose(spi_handle);

    printf("Closing log file...\n");
    fclose(log_file);

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

