// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0f
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
float convert_to_moisture(float voltage);
void control_pump(float moisture);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 3) {
            // Extract ADC value
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Error: Max retries reached for SPI transfer.\n");
    return -1; // Indicate failure
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return (float)adc_value * (3.3f / 1024.0f);
}

// Function to convert voltage to moisture percentage
float convert_to_moisture(float voltage) {
    return (voltage / 3.3f) * 100.0f;
}

// Function to control the water pump
void control_pump(float moisture) {
    if (moisture < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        printf("Pump ON (Moisture: %.2f%%)\n", moisture);
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        printf("Pump OFF (Moisture: %.2f%%)\n", moisture);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read moisture sensor\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage and moisture percentage
        float voltage = convert_to_voltage(adc_value);
        float moisture = convert_to_moisture(voltage);

        // Control the water pump
        control_pump(moisture);

        // Log the data with timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Moisture: %.2f%%\n", timestamp, moisture);

        // Wait for 60 seconds
        gpioDelay(60000000); // 60 seconds
    }

    // Cleanup before exiting
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is OFF
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

