    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MQ-135 sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Optionally add retry logic here
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to CO2 concentration
        float co2_ppm = adc_to_ppm(adc_value);

        // Control ventilation fan
        control_fan(co2_ppm);
        int fan_state = gpioRead(FAN_GPIO);

        // Log data
        log_data(co2_ppm, fan_state);

        printf("CO2: %.2f ppm, Fan: %s\n", co2_ppm, fan_state ? "ON" : "OFF");

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

