// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to average sensor readings
float average_samples(int samples[], int num_samples) {
    int sum = 0;
    int valid_count = 0;

    for (int i = 0; i < num_samples; i++) {
        if (samples[i] >= 0) { // Only include valid readings
            sum += samples[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return (float)sum / valid_count;
    } else {
        return -1.0; // Indicate no valid readings
    }
}

// Function to set valve position based on average moisture
void set_valve_position(float average) {
    if (average < 0) {
        fprintf(stderr, "Error: Invalid average moisture value: %f\n", average);
        return;
    }

    // Map average moisture to valve position (0-100)
    int valve_position = (int)(average / 1023.0 * 100.0); // Assuming 10-bit ADC

    // Clamp valve position to 0-100
    if (valve_position < 0) valve_position = 0;
    if (valve_position > 100) valve_position = 100;

    // Set PWM duty cycle
    gpioPWM(VALVE_GPIO, valve_position);
}

