    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Configure PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int samples[3];
    float average;

    // Main loop
    while (!terminate) {
        // Read sensor values
        samples[0] = read_mcp3008(0);
        samples[1] = read_mcp3008(1);
        samples[2] = read_mcp3008(2);

        // Calculate average
        average = average_samples(samples, 3);

        // Set valve position
        if (average >= 0) {
            set_valve_position(average);
        }

        // Log data
        log_data(samples, average, gpioGetPWMdutycycle(VALVE_GPIO));

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    gpioPWM(VALVE_GPIO, 0); // Set valve to 0%
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

