#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration parameters
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 20.0 // cm
#define MIN_VOLUME 0.0
#define MAX_VOLUME 1.0
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz

// Define error values
#define ERROR_DISTANCE -1.0
#define ERROR_VOLUME -1.0
#define ERROR_FREQUENCY -1.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Calibration parameters
double distance_offset = 0.0;
double distance_scale = 1.0;
double volume_offset = 0.0;
double volume_scale = 1.0;
double frequency_offset = 0.0;
double frequency_scale = 1.0;

// Function prototypes
double read_distance();
double read_ldr();
double map_distance_to_frequency(double distance);
double map_ldr_to_volume(double ldr_value);
void generate_tone(double frequency, double volume);
void load_calibration_parameters();
void save_calibration_parameters();
void signal_handler(int signal);

// Function to read distance from HC-SR04 sensor
double read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // 1 us delay
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return ERROR_DISTANCE;
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // 1 us delay
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return ERROR_DISTANCE;
    }

    end_tick = gpioTick();

    double pulse_duration = (double)(end_tick - start_tick) / 1000000.0; // in seconds
    double distance = pulse_duration * 34300.0 / 2.0; // cm

    return distance;
}

// Function to read LDR value from MCP3008
double read_ldr() {
    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3008 configuration: single-ended channel 0
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0 (10000000)
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return ERROR_VOLUME;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return (double)adc_value / 1023.0;
}

// Function to map distance to frequency
double map_distance_to_frequency(double distance) {
    // Clamp distance to calibration range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linear mapping
    double frequency = frequency_offset + (distance - distance_offset) * frequency_scale;

    // Clamp frequency to defined range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to map LDR value to volume
double map_ldr_to_volume(double ldr_value) {
    // Clamp LDR value to calibration range
    if (ldr_value < 0.0) {
        ldr_value = 0.0;
    } else if (ldr_value > 1.0) {
        ldr_value = 1.0;
    }

    // Linear mapping
    double volume = volume_offset + (ldr_value - volume_offset) * volume_scale;

    // Clamp volume to defined range
    if (volume < MIN_VOLUME) {
        volume = MIN_VOLUME;
    } else if (volume > MAX_VOLUME) {
        volume = MAX_VOLUME;
    }

    return volume;
}

// Function to generate tone using PWM
void generate_tone(double frequency, double volume) {
    // Calculate PWM duty cycle (50% for square wave)
    int duty_cycle = (int)(volume * 1000000); // pigpio duty cycle is 0-1000000

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);

    // Set PWM duty cycle
    gpioPWM(PWM_PIN, duty_cycle);
}

// Function to load calibration parameters from file
void load_calibration_parameters() {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file, using default values\n");
        return;
    }

    if (fscanf(fp, "%lf %lf %lf %lf %lf %lf",
               &distance_offset, &distance_scale,
               &volume_offset, &volume_scale,
               &frequency_offset, &frequency_scale) != 6) {
        fprintf(stderr, "Warning: Could not read calibration parameters, using default values\n");
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration parameters loaded successfully\n");
}

// Function to save calibration parameters to file
void save_calibration_parameters() {
    FILE *fp = fopen("theremin_config.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing\n");
        return;
    }

    fprintf(fp, "%lf %lf %lf %lf %lf %lf",
            distance_offset, distance_scale,
            volume_offset, volume_scale,
            frequency_offset, frequency_scale);

    fclose(fp);
    printf("Calibration parameters saved successfully\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Load calibration parameters
    load_calibration_parameters();

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double last_distance = ERROR_DISTANCE;
    double last_volume = ERROR_VOLUME;

    // Main loop
    while (!terminate) {
        double distance = read_distance();
        double ldr_value = read_ldr();

        if (distance != ERROR_DISTANCE && ldr_value != ERROR_VOLUME) {
            last_distance = distance;
            last_volume = ldr_value;

            double frequency = map_distance_to_frequency(distance);
            double volume = map_ldr_to_volume(ldr_value);

            generate_tone(frequency, volume);
        } else {
            // Use last valid values if sensor read fails
            generate_tone(map_distance_to_frequency(last_distance), map_ldr_to_volume(last_volume));
        }

        gpioDelay(50); // 50 ms delay
    }

    // Stop PWM
    gpioPWM(PWM_PIN, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Save calibration parameters
    save_calibration_parameters();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

