#define SAMPLE_INTERVAL 1 // seconds
#define MAX_RETRIES 3
#define ADC_READ_DELAY 100 // milliseconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void classify_alcohol_level(float ppm);
void log_data(float ppm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1; // Initialize to an invalid value
    int retries = 0;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
            gpioDelay(ADC_READ_DELAY * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to convert ADC value to ppm (example linear conversion)
float adc_to_ppm(int adc_value) {
    // Assuming 0 ADC = 0 ppm and 1023 ADC = 1000 ppm
    return (float)adc_value * 1000.0 / 1023.0;
}

// Function to classify alcohol level
void classify_alcohol_level(float ppm) {
    if (ppm > 50.0) {
        printf("Alcohol detected! Limit exceeded.\n");
    } else if (ppm < 20.0) {
        printf("Sobriety confirmed.\n");
    } else {
        printf("Alcohol level within acceptable range.\n");
    }
