    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        if (adc_value >= 0) {
            float ppm = adc_to_ppm(adc_value);
            classify_alcohol_level(ppm);
            log_data(ppm);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 1 second
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

