        gpioDelay(60000000); // 60 seconds in microseconds
    }

    // Cleanup
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Irrigation system terminated.\n");
    return 0;
