// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIRECTION 23
#define MOTOR2_DIRECTION 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 parameters
#define MCP3008_CHANNEL_1 0
#define MCP3008_CHANNEL_2 1

// Define motor direction
#define FORWARD 1
#define BACKWARD 0

// Define PWM range
#define PWM_RANGE 1000

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_potentiometer_to_speed(int potentiometer_value);
void set_motor_speed(int motor_number, int speed, int direction);
void accelerate_decelerate_cycle(int speed1, int speed2);
void reverse_cycle(int speed1, int speed2);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to motor speed
int map_potentiometer_to_speed(int potentiometer_value) {
    // Linear mapping: 0-1023 -> 0-1000
    return (int)(((float)potentiometer_value / 1023.0) * 1000.0);
}

// Function to set motor speed and direction
void set_motor_speed(int motor_number, int speed, int direction) {
    int enable_pin, direction_pin;

    if (motor_number == 1) {
        enable_pin = MOTOR1_ENABLE;
        direction_pin = MOTOR1_DIRECTION;
    } else if (motor_number == 2) {
        enable_pin = MOTOR2_ENABLE;
        direction_pin = MOTOR2_DIRECTION;
