    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Set PWM frequency (optional, default is 1kHz)
    gpioSetPWMfrequency(MOTOR1_ENABLE, 1000); // 1 kHz
    gpioSetPWMfrequency(MOTOR2_ENABLE, 1000); // 1 kHz

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int potentiometer1_value = read_mcp3008(MCP3008_CHANNEL_1);
        int potentiometer2_value = read_mcp3008(MCP3008_CHANNEL_2);

        if (potentiometer1_value == -1 || potentiometer2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            gpioDelay(100000); // Wait before retrying
            continue;
        }

        // Map potentiometer values to motor speeds
        int motor1_speed = map_potentiometer_to_speed(potentiometer1_value);
        int motor2_speed = map_potentiometer_to_speed(potentiometer2_value);

        // Perform accelerate-decelerate cycle
        accelerate_decelerate_cycle(motor1_speed, motor2_speed);

        // Reverse the cycle
        reverse_cycle(motor1_speed, motor2_speed);
    }

    // Stop motors
    set_motor_speed(1, 0, FORWARD);
    set_motor_speed(2, 0, FORWARD);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

