// Define GPIO pins
#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define constants
#define NOISE_CALIBRATION_DURATION 5 // seconds
#define THRESHOLD 500
#define DEBOUNCE_DELAY 10 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calibrate_noise(int *baseline);
int check_threshold(int sample, int baseline, int threshold);
void control_led(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calibrate noise level
int calibrate_noise(int *baseline) {
    int sum = 0;
    int num_samples = 0;

    printf("Calibrating noise level for %d seconds...\n", NOISE_CALIBRATION_DURATION);

    for (int i = 0; i < NOISE_CALIBRATION_DURATION * 10; ++i) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error: Failed to read ADC during calibration\n");
            return -1;
        }
        sum += sample;
        num_samples++;
        gpioDelay(100000); // 100ms delay
    }

    *baseline = sum / num_samples;
    printf("Calibration complete. Baseline: %d\n", *baseline);
    return 0;
}

// Function to check if sound level exceeds threshold
int check_threshold(int sample, int baseline, int threshold) {
    return (sample - baseline) > threshold;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate noise level
    int baseline;
    if (calibrate_noise(&baseline) != 0) {
        fprintf(stderr, "Error: Noise calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int led_state = 0; // 0 = off, 1 = on
    int last_led_state = 0;
    gpioDelay(DEBOUNCE_DELAY * 1000); // Initial debounce delay

    // Main loop
    while (!terminate) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error: Failed to read ADC\n");
            break;
        }

        int threshold_exceeded = check_threshold(sample, baseline, THRESHOLD);

        if (threshold_exceeded && !led_state) {
            led_state = 1;
            control_led(led_state);
            last_led_state = led_state;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else if (!threshold_exceeded && led_state) {
            led_state = 0;
            control_led(led_state);
            last_led_state = led_state;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

