#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 8
#define GPIO_PATH "/sys/class/gpio/gpio"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH GPIO_PATH "/direction"
#define GPIO_VALUE_PATH GPIO_PATH "/value"
#define LOG_FILE "audio_log.txt"
#define SAMPLE_RATE 1000 // Hz
#define DEADLINE_NS (1000000000 / SAMPLE_RATE) // nanoseconds

// Global variables
static int spi_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_adc(void);
int log_data(uint32_t timestamp_ns, uint16_t adc_value);
void signal_handler(int sig);
void cleanup(void);

// Structure for nanosleep arguments
struct timespec deadline = {0, DEADLINE_NS};

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    // Export GPIO pin
    int export_fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (export_fd < 0) {
        perror("Error opening GPIO export file");
        return -1;
    }
    char pin_str[3];
    snprintf(pin_str, sizeof(pin_str), "%d", GPIO_PIN);
    if (write(export_fd, pin_str, strlen(pin_str)) < 0) {
        perror("Error exporting GPIO pin");
        close(export_fd);
        return -1;
    }
    close(export_fd);

    // Set GPIO direction to output
    char direction_path[50];
    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "%d/direction", GPIO_PIN);
    int direction_fd = open(direction_path, O_WRONLY);
    if (direction_fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (write(direction_fd, "out", 3) < 0) {
        perror("Error setting GPIO direction");
        close(direction_fd);
        return -1;
    }
    close(direction_fd);

    // Open GPIO value file for writing
    char value_path[50];
    snprintf(value_path, sizeof(value_path), GPIO_PATH "%d/value", GPIO_PIN);
    gpio_fd = open(value_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(void) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Perform SPI transaction
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transaction");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to file
int log_data(uint32_t timestamp_ns, uint16_t adc_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%u|%u\n", timestamp_ns, adc_value);
    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    fprintf(stderr, "Cleaning up...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close GPIO value file
    if (gpio_fd != -1) {
        close(gpio_fd);
    }

    // Unexport GPIO pin
    int unexport_fd = open(GPIO_UNEXPORT_PATH, O_WRONLY);
    if (unexport_fd >= 0) {
        char pin_str[3];
        snprintf(pin_str, sizeof(pin_str), "%d", GPIO_PIN);
        write(unexport_fd, pin_str, strlen(pin_str));
        close(unexport_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
            perror("Error getting timestamp");
            break;
        }
        uint32_t timestamp_ns = (uint32_t)(ts.tv_sec * 1000000000LL + ts.tv_nsec);

        // Log data
        if (log_data((uint32_t)timestamp_ns, (uint16_t)adc_value) < 0) {
            fprintf(stderr, "Logging failed\n");
            break;
        }

        // Sleep until next deadline
        if (nanosleep(&deadline, NULL) < 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Sleep interrupted by signal\n");
            } else {
                perror("Error sleeping");
                break;
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

