#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2
#define SAMPLE_RATE 10 // Hz
#define KALMAN_Q 0.01
#define KALMAN_R 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    double x;
    double P;
} KalmanState;

KalmanState x_state, y_state, z_state;

// Function prototypes
int initialize_spi();
int read_adc_channel(int channel);
double adc_to_g(int adc_value);
double kalman_filter(double measurement, double process_noise, double measurement_noise, KalmanState *state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC channel
int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to g
double adc_to_g(int adc_value) {
    // Assuming 3.3V reference
    double voltage = (adc_value / 1023.0) * 3.3;
    // ADXL335 sensitivity: 300 mV/g, 10-bit ADC: 3.3V / 1024
    double g = (voltage - 1.65) / 0.03; // 1.65V is 0g
    return g;
}

// Kalman filter
double kalman_filter(double measurement, double process_noise, double measurement_noise, KalmanState *state) {
    // Prediction step
    state->P = state->P + process_noise;

    // Update step
    double K = state->P / (state->P + measurement_noise);
    state->x = state->x + K * (measurement - state->x);
    state->P = (1 - K) * state->P;

    return state->x;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filter states
    x_state.x = 0;
    x_state.P = 1;
    y_state.x = 0;
    y_state.P = 1;
    z_state.x = 0;
    z_state.P = 1;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_adc_channel(X_CHANNEL);
        int y_adc = read_adc_channel(Y_CHANNEL);
        int z_adc = read_adc_channel(Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert to g
        double x_g = adc_to_g(x_adc);
        double y_g = adc_to_g(y_adc);
        double z_g = adc_to_g(z_adc);

        // Apply Kalman filter
        double x_filtered = kalman_filter(x_g, KALMAN_Q, KALMAN_R, &x_state);
        double y_filtered = kalman_filter(y_g, KALMAN_Q, KALMAN_R, &y_state);
        double z_filtered = kalman_filter(z_g, KALMAN_Q, KALMAN_R, &z_state);

        // Print filtered values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        // Delay
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

