#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define magnetic field range
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Define magnetic field sensitivity (mT/V)
#define MAGNETIC_FIELD_SENSITIVITY 0.1

// Define voltage reference (V)
#define VOLTAGE_REFERENCE 3.3

// Global variable for the log file
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
float convert_to_magnetic_field(int sensor_value);
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
    int sensor3_value;
} SensorData;

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to convert the sensor value to a magnetic field strength
float convert_to_magnetic_field(int sensor_value) {
    float voltage = (float)sensor_value * VOLTAGE_REFERENCE;
    float magnetic_field = voltage * MAGNETIC_FIELD_SENSITIVITY;
    return magnetic_field;
}

// Function to log the sensor data to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        SensorData sensor_data;
        float sensor1_mT, sensor2_mT, sensor3_mT;

        // Read sensor values
        sensor_data.sensor1_value = read_sensor(SENSOR1_GPIO);
        sensor_data.sensor2_value = read_sensor(SENSOR2_GPIO);
        sensor_data.sensor3_value = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor_data.sensor1_value == -1 || sensor_data.sensor2_value == -1 || sensor_data.sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
            gpioDelay(100); // Delay for 100ms
            continue;
        }

        // Convert sensor values to magnetic field strengths
        sensor1_mT = convert_to_magnetic_field(sensor_data.sensor1_value);
        sensor2_mT = convert_to_magnetic_field(sensor_data.sensor2_value);
        sensor3_mT = convert_to_magnetic_field(sensor_data.sensor3_value);

        // Check if magnetic field values are within the valid range
        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD ||
            sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD ||
            sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field value(s) out of range. Skipping logging.\n");
        } else {
            // Log the data
            if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop
    fclose(log_file);
    gpioTerminate();
    return 0;
}

