    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    // Configure GPIO for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error: Failed to read ADC value");
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Moisture: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
            log_event(log_message);

            if (moisture_percentage < MOISTURE_THRESHOLD) {
                control_pump(1); // Turn pump ON
            } else {
                control_pump(0); // Turn pump OFF
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

