#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// Bits per word
#define BITS_PER_WORD 8

// Maximum retry count for SPI communication
#define MAX_RETRIES 3

// Global variables
int spi_fd = -1;
FILE *fp = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int spi_read_channel(int channel);
int log_data(int channel0, int channel1, int channel2);
void signal_handler(int signal);
void cleanup(void);

// Structure to hold SPI configuration
typedef struct {
    char device[20];
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed_hz;
} spi_config_t;

// SPI initialization function
int spi_init(void) {
    spi_config_t config = {
        .device = SPI_DEVICE,
        .mode = SPI_MODE,
        .bits_per_word = BITS_PER_WORD,
        .speed_hz = 1000000 // 1 MHz
    };

    int retries = 0;
    while (retries < MAX_RETRIES) {
        spi_fd = open(config.device, O_RDWR);
        if (spi_fd < 0) {
            fprintf(stderr, "Error opening SPI device %s: %s\n", config.device, strerror(errno));
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        // Set SPI mode
        if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
            fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
            close(spi_fd);
            spi_fd = -1;
            retries++;
            sleep(1);
            continue;
        }

        // Set bits per word
        if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
            fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
            close(spi_fd);
            spi_fd = -1;
            retries++;
            sleep(1);
            continue;
        }

        // Set max speed Hz
        if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed_hz) == -1) {
            fprintf(stderr, "Error setting max speed Hz: %s\n", strerror(errno));
            close(spi_fd);
            spi_fd = -1;
            retries++;
            sleep(1);
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize SPI after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read data from a specific MCP3008 channel
int spi_read_channel(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = config.speed_hz;
    transfer[0].bits_per_word = config.bits_per_word;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log the sensor data to a CSV file
int log_data(int channel0, int channel1, int channel2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0, channel1, channel2);
    fflush(fp); // Ensure data is written to the file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Cleanup function to close SPI and file handles
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
}

int main(void) {
    // Register the cleanup function to be called on exit
    atexit(cleanup);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open the CSV file for appending
    fp = fopen("sensor_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening sensor_data.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop to read sensor data and log it to the CSV file
    while (program_running) {
        int channel0_value = spi_read_channel(0);
        int channel1_value = spi_read_channel(1);
        int channel2_value = spi_read_channel(2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (log_data(channel0_value, channel1_value, channel2_value) != 0) {
            fprintf(stderr, "Error logging data. \n");
        }

        sleep(1); // Wait for 1 second
    }

    return 0;
}

