void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void log_message(const char *level, const char *message);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("INFO", "Received signal, shutting down...");
        running = 0;
    }
}

// JSON parsing function
int parse_json(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "JSON parse error: %s", error.text);
        log_message("ERROR", error_message);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        log_message("ERROR", "Missing 'led_state' key in JSON");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        log_message("ERROR", "'led_state' is not a boolean");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);

    json_decref(root);
    return 0;
}

// LED control function
int set_led_state(int led_state) {
    if (gpioWrite(GPIO_PIN, led_state) != 0) {
        log_message("ERROR", "Failed to write to GPIO pin");
        return -1;
    }
    return 0;
}

// MQTT callbacks
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("INFO", "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "MQTT connection error: %s", mosquitto_connack_string(result));
        log_message("ERROR", error_message);
    }
}

void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message("WARNING", "MQTT disconnected unexpectedly");
    }
}

void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json((const char *)message->payload, &led_state) == 0) {
            if (set_led_state(led_state) != 0) {
                log_message("ERROR", "Failed to set LED state");
            }
        }
    }
}

// Logging function
void log_message(const char *level, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "[%s] [%s] %s\n", timestamp, level, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("ERROR", "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn LED off on startup

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("ERROR", "Failed to create MQTT client instance");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "MQTT connection failed: %s", mosquitto_strerror(rc));
            log_message("ERROR", error_message);
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > 60) {
                reconnect_delay = 60;
            }
        } else {
            reconnect_delay = 1; // Reset reconnect delay on successful connection
            mosquitto_loop(mosq, -1, 1); // Blocking call, handle signals in the loop
            mosquitto_disconnect(mosq);
        }
    }

    // Cleanup
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn LED off before exiting
    gpioTerminate();

    log_message("INFO", "Exiting cleanly");
    return 0;
}

