#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(1000);       // Wait for 1 second
    gpioWrite(LED_PIN, 0); // Turn LED off
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            printf("Sound detected!\n");
            trigger_alarm();
        } else {
            printf("No sound detected (%d)\n", sensor_value);
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

