#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/input.h>
#include <sys/types.h>
#include <sys/stat.h>

#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define CONSUMER_LABEL "vibration-monitor"
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

int main() {
    int gpio_fd, input_fd;
    struct gpioevent_request req;
    struct input_event ev;
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char gpio_path[64];
    char input_path[64];
    int ret;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // GPIO path
    snprintf(gpio_path, sizeof(gpio_path), "/dev/%s", GPIO_CHIP);

    // Open GPIO chip
    gpio_fd = open(gpio_path, O_RDONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO line
    req.lineoffset = GPIO_PIN;
    req.handle_flags = GPIOHANDLE_REQUEST_INPUT;
    req.consumer_label = CONSUMER_LABEL;
    req.of_node = NULL;

    ret = ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (ret < 0) {
        perror("Failed to get GPIO line");
        close(gpio_fd);
        return 1;
    }

    // Input path
    snprintf(input_path, sizeof(input_path), "/dev/input/event%d", req.fd);

    // Open input device
    input_fd = open(input_path, O_RDONLY);
    if (input_fd < 0) {
        perror("Failed to open input device");
        close(gpio_fd);
        return 1;
    }

    // Configure for falling-edge detection
    struct input_event ev_setup;
    ev_setup.type = EV_KEY;
    ev_setup.code = KEY_VIBRATION;
    ev_setup.value = 1; // Enable vibration

    ret = write(input_fd, &ev_setup, sizeof(ev_setup));
    if (ret < 0) {
        perror("Failed to configure input device");
        close(input_fd);
        close(gpio_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(input_fd);
        close(gpio_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        ret = read(input_fd, &ev, sizeof(ev));
        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit gracefully
                break;
            }
            perror("Failed to read input event");
            break;
        }

        if (ev.type == EV_KEY && ev.code == KEY_VIBRATION && ev.value == 0) {
            // Vibration detected
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s: Vibration detected!\n", timestamp);
            fflush(log_file);

            printf("%s: Vibration detected!\n", timestamp);

            system("sudo shutdown -h now");
            break; // Exit after one vibration
        }
    }

    // Cleanup
    close(input_fd);
    close(gpio_fd);
    fclose(log_file);

    return 0;
}

