#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x4
#define BMP280_OVERSAMPLING_PRESS 5 // x16
#define BMP280_MODE_NORMAL 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;

// Function prototypes
int bmp280_init();
int bmp280_read_calibration_data();
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
double bmp280_calculate_altitude(double pressure);
char* get_iso8601_timestamp();
int log_altitude(double altitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// BMP280 initialization function
int bmp280_init() {
    // Set oversampling and mode
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL;
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set config register (optional)
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// BMP280 read calibration data function
int bmp280_read_calibration_data() {
    uint8_t buffer[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)buffer, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    dig_T1 = (buffer[1] << 8) | buffer[0];
    dig_T2 = (buffer[3] << 8) | (int8_t)buffer[2];
    dig_T3 = (buffer[5] << 8) | (int8_t)buffer[4];
    dig_P1 = (buffer[7] << 8) | buffer[6];
    dig_P2 = (buffer[9] << 8) | (int8_t)buffer[8];
    dig_P3 = (buffer[11] << 8) | (int8_t)buffer[10];
    dig_P4 = (buffer[13] << 8) | (int8_t)buffer[12];
    dig_P5 = (buffer[15] << 8) | (int8_t)buffer[14];
    dig_P6 = (buffer[17] << 8) | (int8_t)buffer[16];
    dig_P7 = (buffer[19] << 8) | (int8_t)buffer[18];
    dig_P8 = (buffer[21] << 8) | (int8_t)buffer[20];
