#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define LM35_SCALE_FACTOR 0.01
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_fd = -1;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool file_logging_enabled = true;

// Function prototypes
int spi_init();
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
float read_temperature();
void add_to_buffer(float temperature);
void print_buffer();
void write_to_file();
void signal_handler(int signal);

// SPI initialization function
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read temperature from LM35 sensor
float read_temperature() {
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00}; // Start bit, single-ended, channel 0
    uint8_t rx_buf[3];

    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer, retrying...\n");
        return -1.0; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Convert ADC value to temperature (LM35: 10mV/°C)
    float temperature = adc_value * LM35_SCALE_FACTOR;

    return temperature;
}

// Function to add temperature to the circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("Temperature: %.2f °C\n", temperature_buffer[index]);
    }
}

// Function to write the contents of the circular buffer to a file
void write_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening log file");
        file_logging_enabled = false; // Disable file logging if file cannot be opened
        return;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        if (fwrite(&temperature_buffer[index], sizeof(float), 1, fp) != 1) {
            perror("Error writing to log file");
            fclose(fp);
            file_logging_enabled = false; // Disable file logging if write fails
            return;
        }
    }

    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature >= 0) {
            add_to_buffer(temperature);
            print_buffer();

            if (file_logging_enabled) {
                write_to_file();
            }
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        sleep(5);
    }

    return 0;
}

