    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature >= 0) {
            add_to_buffer(temperature);
            print_buffer();

            if (file_logging_enabled) {
                write_to_file();
            }
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        sleep(5);
    }

    return 0;
}

