        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// SPI initialization
int init_spi() {
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode and bits per word
    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Read BH1750 sensor
int read_bh1750() {
    unsigned char buf[2];
    int lux = -1;

    // Send start measurement command
    buf[0] = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux
    lux = (buf[0] << 8 | buf[1]) / 1.2;

    return lux;
}

