#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor state
int read_flame_sensor() {
    int state = gpioRead(GPIO_PIN);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", GPIO_PIN, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log the flame event to a file
void log_flame_event(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, GPIO_PIN, state);
    fclose(fp);
}

// Function to print an alarm message
void print_alarm_message() {
    printf("Flame detected!\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int state = read_flame_sensor();
        if (state == 1) {
            print_alarm_message();
        }
        log_flame_event(state);
        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up GPIO resources
    gpioTerminate();

    return 0;
}

