#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP3008_CHANNEL 0
#define MCP4725_ADDRESS 0x60
#define VREF 3.3
#define TEMP_OFFSET 0.5
#define TEMP_SCALE 0.01
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int spi_fd, int channel);
float adc_to_temperature(int adc_value);
int i2c_init(const char *device, int address);
int write_mcp4725(int i2c_fd, int dac_value);
int log_data(FILE *fp, int adc_value, float temperature, int dac_value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode = 0; // SPI mode 0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits = 8; // 8 bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    uint32_t spi_speed = speed; // 500kHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) == -1) {
        perror("Error setting max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 500000, // 500kHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MCP3008 read function
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading MCP3008 channel %d\n", channel);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to temperature conversion function
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = (voltage - 0.5) / 0.01;
    return temperature;
}

// I2C initialization function
int i2c_init(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MCP4725 write function
int write_mcp4725(int i2c_fd, int dac_value) {
    uint8_t data[3];

    // Construct I2C message
    data[0] = 0x40; // Write DAC command
    data[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    data[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    if (write(i2c_fd, data, 3) != 3) {
        perror("Error writing to MCP4725");
        return -1;
    }

    return 0;
}

// Log data function
int log_data(FILE *fp, int adc_value, float temperature, int dac_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %d, %.2f, %d\n", timestamp, adc_value, temperature, dac_value);
    fflush(fp); // Ensure data is written to file immediately

    printf("%s, %d, %.2f, %d\n", timestamp, adc_value, temperature, dac_value);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT. Cleaning up and exiting...\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, 500000);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, MCP4725_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 0.5 seconds
            continue;
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Calculate DAC value (proportional to temperature)
        int dac_value = (int)((temperature - TEMP_OFFSET) / TEMP_SCALE);
        if (dac_value < 0) dac_value = 0;
        if (dac_value > 4095) dac_value = 4095;

        // Write DAC value
        if (write_mcp4725(i2c_fd, dac_value) < 0) {
            fprintf(stderr, "Failed to write DAC value. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 0.5 seconds
            continue;
        }

        // Log data
        if (log_data(log_file, adc_value, temperature, dac_value) < 0) {
            fprintf(stderr, "Failed to log data. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 0.5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

