#define MOTOR_REVERSE_GPIO 18
#define MOTOR_ENABLE_GPIO 27
#define RAIN_THRESHOLD 5
#define MOTOR_PWM_DUTY 150
#define MOTOR_DURATION 3 // seconds
#define LOG_FILE "rain_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int log_rain_data(int rain_level);
void control_motor(int rain_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log rain data to file
int log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file);

    return 0;
}

// Function to control the motor
void control_motor(int rain_level) {
    if (rain_level > RAIN_THRESHOLD) {
        // Open window
        gpioWrite(MOTOR_FORWARD_GPIO, 1);
        gpioWrite(MOTOR_REVERSE_GPIO, 0);
        gpioPWM(MOTOR_ENABLE_GPIO, MOTOR_PWM_DUTY);
        gpioDelay(MOTOR_DURATION * 1000000); // Delay in microseconds
        gpioPWM(MOTOR_ENABLE_GPIO, 0);
    } else {
        // Close window
        gpioWrite(MOTOR_FORWARD_GPIO, 0);
        gpioWrite(MOTOR_REVERSE_GPIO, 1);
        gpioPWM(MOTOR_ENABLE_GPIO, MOTOR_PWM_DUTY);
        gpioDelay(MOTOR_DURATION * 1000000); // Delay in microseconds
        gpioPWM(MOTOR_ENABLE_GPIO, 0);
    }
}

