    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_REVERSE_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_ENABLE_GPIO, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR_ENABLE_GPIO, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read rain sensor
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            continue; // Skip to the next iteration
        }

        // Log rain data
        if (log_rain_data(rain_level) != 0) {
            fprintf(stderr, "Error: Failed to log rain data\n");
        }

        // Control motor
        control_motor(rain_level);

        // Wait for 1 second
        gpioDelay(1000000); // Delay in microseconds
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

