#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <stdbool.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define clap parameters
#define CLAP_THRESHOLD 500
#define DEBOUNCE_INTERVAL_MS 50

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
bool detect_clap(int adc_value);
void control_led(int on);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int led_state;
    unsigned long last_clap_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc();

        // Detect clap
        if (detect_clap(adc_value)) {
            // Debounce check
            unsigned long current_time = gpioTick();
            if (current_time - state.last_clap_time > DEBOUNCE_INTERVAL_MS * 1000) {
                // Turn on LED
                control_led(1);

                // Print timestamped detection message
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("%s: Clap detected!\n", timestamp);

                // Update last clap time
                state.last_clap_time = current_time;

                // Wait for 500ms
                gpioDelay(500000); // 500ms

                // Turn off LED
                control_led(0);
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1ms
    }

    // Cleanup before exiting
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    printf("Clap detection stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set ADC pin as input
    gpioSetMode(ADC_PIN, PI_INPUT);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;

    // Set ADC pin as output
    gpioSetMode(ADC_PIN, PI_OUTPUT);

    // Drive ADC pin low for 10us
    gpioWrite(ADC_PIN, 0);
    gpioDelay(10); // 10us

    // Set ADC pin as input
    gpioSetMode(ADC_PIN, PI_INPUT);

    // Read ADC value (simulated by counting high time)
    for (int i = 0; i < 10; i++) {
        gpioDelay(1); // Small delay
        if (gpioRead(ADC_PIN) == 1) {
            adc_value++;
        }
    }

    return adc_value;
}

// Detect clap based on ADC value
bool detect_clap(int adc_value) {
    return adc_value > CLAP_THRESHOLD;
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
    state.led_state = on;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

