    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value >= 0) {
            log_data(sensor_value);
            determine_state(sensor_value);
        } else {
            fprintf(stderr, "Failed to read sensor, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
