    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    fprintf(stdout, "Magnetic field logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            delay(SAMPLE_INTERVAL_MS);
            continue;
        }

        // Convert to magnetic field strength
        float magnetic_field = convert_to_gauss(adc_value);

        // Get current timestamp
        time_t timestamp = time(NULL);

        // Log data
        if (log_data(timestamp, magnetic_field) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Print to console
        printf("Timestamp: %ld, Magnetic Field: %.2f Gauss\n", timestamp, magnetic_field);

        // Wait for the next sample
        delay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fprintf(stdout, "Cleaning up...\n");
    close(spi_fd);
    fclose(log_file);

    fprintf(stdout, "Exiting.\n");
    return 0;
}

