#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSOR_SENSITIVITY 0.001 // 1 mV/A for MLX91209
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_fd = -1;
int gpio_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int gpio_init(int pin);
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
int log_data(float current);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd;
    unsigned int mode = 0;
    unsigned int bits = 8;
    unsigned int speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int gpio_init(int pin) {
    int fd;
    char buffer[64];

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO export file");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error exporting GPIO pin");
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (write(fd, "out", 3) < 0) {
        perror("Error setting GPIO direction");
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    gpio_fd = open(buffer, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    return 0;
}

// MCP3008 read function
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float current = voltage / SENSOR_SENSITIVITY;
    return current;
}

// Data logging function
int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.6f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Disable sensor power
    if (gpio_fd != -1) {
        if (write(gpio_fd, "0", 1) < 0) {
            perror("Error writing to GPIO value file");
        }
        close(gpio_fd);
    }

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Unexport GPIO pin
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd >= 0) {
        char buffer[64];
        snprintf(buffer, sizeof(buffer), "%d", GPIO_PIN);
        if (write(fd, buffer, strlen(buffer)) < 0) {
            perror("Error unexporting GPIO pin");
        }
        close(fd);
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Enable sensor power
    if (write(gpio_fd, "1", 1) < 0) {
        perror("Error writing to GPIO value file");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Initialization complete. Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else {
            float current = adc_to_current(adc_value);
            if (log_data(current) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
            printf("Current: %.6f A\n", current);
        }
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

