// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC reading to voltage
double adc_to_voltage(int adc_value, double vref) {
    return ((double)adc_value / 1023.0) * vref;
}

// Function to convert voltage to current
double voltage_to_current(double voltage) {
    return (voltage - MLX91211_OFFSET) / MLX91211_SENSITIVITY;
}

// Function to format log entry
char* format_log_entry(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char log_entry[100]; // Static to preserve value between calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_entry, sizeof(log_entry), "%s %.2f A\n", timestamp, current);

    return log_entry;
}

// Function to write to log file
int write_to_log(const char* log_entry) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    if (fprintf(fp, "%s", log_entry) < 0) {
        fprintf(stderr, "Error: Could not write to log file %s\n", LOG_FILE);
        fclose(fp);
        return -1;
    }

    fflush(fp);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

int main() {
