    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        double voltage = adc_to_voltage(adc_value, VREF);

        // Validate voltage
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
            continue; // Skip to the next iteration
        }

        // Convert voltage to current
        double current = voltage_to_current(voltage);

        // Format log entry
        char* log_entry = format_log_entry(current);

        // Write to log file
        if (write_to_log(log_entry) != 0) {
            fprintf(stderr, "Error: Failed to write to log file\n");
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Current monitoring stopped.\n");

    return 0;
}

