#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio) {
    int high_count = 0;
    int low_count = 0;
    int i;

    for (i = 0; i < 5; i++) {
        if (gpioRead(gpio) == 0) {
            low_count++;
        } else {
            high_count++;
        }
        gpioDelay(DEBOUNCE_TIME * 1000); // Delay in microseconds
    }

    return (high_count > low_count) ? 1 : 0;
}

// Function to log the sensor state
void log_sensor_state(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);
}

// Function to check for simultaneous object detection
void check_simultaneous_detection(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 1 && sensor2_state == 1) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Log the sensor state
        log_sensor_state(sensor1_state, sensor2_state);

        // Check for simultaneous detection
        check_simultaneous_detection(sensor1_state, sensor2_state);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

