#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/wait.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DELAY_S 5
#define CAPTURE_COMMAND "/usr/bin/libcamera-still -n -o /home/pi/security_cam/%Y%m%d_%H%M%S.jpg"
#define MAX_COMMAND_LENGTH 256

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    int pigpio_init_result;
    int gpio_mode_result;
    int gpio_read_result;
    int last_state = -1; // Initialize to an invalid state
    time_t last_change_time = 0;
    char command[MAX_COMMAND_LENGTH];
    int status;

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %d", pigpio_init_result);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully");

    // Configure GPIO pin as input with pull-down resistor
    gpio_mode_result = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_mode_result != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input: %d", GPIO_PIN, gpio_mode_result);
        gpioTerminate();
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "GPIO %d configured as input", GPIO_PIN);

    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Main loop
    while (!terminate) {
        gpio_read_result = gpioRead(GPIO_PIN);
        if (gpio_read_result < 0) {
            syslog(LOG_ERR, "Failed to read GPIO %d: %d", GPIO_PIN, gpio_read_result);
            break; // Exit loop on error
        }

        if (gpio_read_result != last_state) {
            time_t now = time(NULL);
            if (now - last_change_time > DEBOUNCE_DELAY_MS / 1000.0) {
                last_state = gpio_read_result;
                last_change_time = now;

                if (gpio_read_result == 1) {
                    syslog(LOG_INFO, "Motion detected!");

                    // Construct the capture command
                    time_t rawtime;
                    struct tm *timeinfo;
                    char timestamp[80];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);

                    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

                    snprintf(command, MAX_COMMAND_LENGTH, CAPTURE_COMMAND, timestamp);

                    // Execute the capture command
                    pid_t pid = fork();
                    if (pid == 0) {
                        // Child process
                        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
                        // If execl fails, it will return -1
                        syslog(LOG_ERR, "execl failed in child process");
                        exit(1);
                    } else if (pid < 0) {
                        // Fork failed
                        syslog(LOG_ERR, "Fork failed");
                    } else {
                        // Parent process
                        waitpid(pid, &status, 0);
                        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                            syslog(LOG_INFO, "Capture successful");
                        } else {
                            syslog(LOG_ERR, "Capture failed with status %d", WEXITSTATUS(status));
                        }
                    }

                    // Wait for the specified delay
                    sleep(CAPTURE_DELAY_S);
                }
            }
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    syslog(LOG_INFO, "Terminating pigpio...");
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");

    closelog();
    return 0;
}

