#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <stdint.h>

#define DEFAULT_CAMERA_DEVICE "/dev/video0"
#define DEFAULT_IMAGE_WIDTH 640
#define DEFAULT_IMAGE_HEIGHT 480
#define DEFAULT_IMAGE_FORMAT V4L2_PIX_FMT_GREY

// Structure to hold camera configuration
typedef struct {
    char *device_name;
    int image_width;
    int image_height;
    int image_format;
} camera_config_t;

// Global variables
static int camera_fd = -1;
static void *buffer = NULL;
static struct v4l2_buffer buf;
static camera_config_t config;
static int frame_count = 0;
static int running = 1;

// Signal handler for graceful shutdown
static void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize the camera
int init_camera(const char *device_name, int image_width, int image_height, int image_format) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Open the device
    camera_fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (camera_fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }

    // Check device capabilities
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device_name);
        close(camera_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming\n", device_name);
        close(camera_fd);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = image_width;
    fmt.fmt.pix.height = image_height;
    fmt.fmt.pix.pixelformat = image_format;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    // Query buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera_fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    // Map the buffer
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming() {
    if (ioctl(camera_fd, VIDIOC_STREAMON, &buf.type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming() {
    if (ioctl(camera_fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(void **frame_data) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(camera_fd, &fds);

    tv.tv_sec = 2; // 2 seconds timeout
    tv.tv_usec = 0;

    r = select(camera_fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1; // Timeout
    }

    if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *frame_data = buffer;
    return 0;
}

// Function to save a frame as a PGM file
int save_frame(void *frame_data, int width, int height, int frame_number) {
    char filename[50];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_number);

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    fwrite(frame_data, width * height, 1, fp);

    fclose(fp);
    return 0;
}

// Function to enqueue a frame
int enqueue_frame() {
    if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error enqueuing buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (buffer != NULL && munmap(buffer, buf.length) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
    }
    if (camera_fd != -1 && close(camera_fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    config.device_name = DEFAULT_CAMERA_DEVICE;
    config.image_width = DEFAULT_IMAGE_WIDTH;
    config.image_height = DEFAULT_IMAGE_HEIGHT;
    config.image_format = DEFAULT_IMAGE_FORMAT;

    int opt;
    while ((opt = getopt(argc, argv, "d:w:h:f:")) != -1) {
        switch (opt) {
            case 'd':
                config.device_name = optarg;
                break;
            case 'w':
                config.image_width = atoi(optarg);
                break;
            case 'h':
                config.image_height = atoi(optarg);
                break;
            case 'f':
                config.image_format = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d device] [-w width] [-h height] [-f format]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize the camera
    if (init_camera(config.device_name, config.image_width, config.image_height, config.image_format) < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Start streaming
    if (start_streaming() < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Capture and save frames
    void *frame_data;
    while (running) {
        if (capture_frame(&frame_data) == 0) {
            if (save_frame(frame_data, config.image_width, config.image_height, ++frame_count) < 0) {
                fprintf(stderr, "Error saving frame %d\n", frame_count);
            }
            if (enqueue_frame() < 0) {
                fprintf(stderr, "Error enqueuing frame %d\n", frame_count);
            }
        }
    }

    // Stop streaming
    if (stop_streaming() < 0) {
        fprintf(stderr, "Error stopping streaming\n");
    }

    // Cleanup resources
    cleanup();

    printf("Program finished.\n");
    return 0;
}

