#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480

// Structure to hold device information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void **buffers;
    FILE *log_file;
    int running;
} device_t;

// Function prototypes
int open_device(device_t *dev);
int init_device(device_t *dev);
int start_capturing(device_t *dev);
int read_frame(device_t *dev, unsigned char **buffer, size_t *size);
int write_timestamp(device_t *dev);
int stop_capturing(device_t *dev);
int uninit_device(device_t *dev);
int close_device(device_t *dev);
void signal_handler(int signal);

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to open the video device
int open_device(device_t *dev) {
    dev->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (dev->fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the video device
int init_device(device_t *dev) {
    if (ioctl(dev->fd, VIDIOC_QUERYCAP, &dev->cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(dev->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(dev->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    dev->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->fmt.fmt.pix.width = FRAME_WIDTH;
    dev->fmt.fmt.pix.height = FRAME_HEIGHT;
    dev->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // MJPEG format
    dev->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(dev->fd, VIDIOC_S_FMT, &dev->fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    dev->req.count = 1; // Single buffer
    dev->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev->fd, VIDIOC_REQBUFS, &dev->req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    dev->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->buf.memory = V4L2_MEMORY_MMAP;
    dev->buf.index = 0;

    if (ioctl(dev->fd, VIDIOC_QUERYBUF, &dev->buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    dev->buffers = calloc(dev->req.count, sizeof(void *));
    if (!dev->buffers) {
        fprintf(stderr, "Error allocating buffer memory\n");
        return -1;
    }

    for (int i = 0; i < dev->req.count; i++) {
        dev->buf.index = i;
        dev->buffers[i] = mmap(NULL, dev->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, dev->fd, dev->buf.m.offset);
        if (dev->buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to start capturing frames
int start_capturing(device_t *dev) {
    for (int i = 0; i < dev->req.count; i++) {
        dev->buf.index = i;
        if (ioctl(dev->fd, VIDIOC_QBUF, &dev->buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a single frame
int read_frame(device_t *dev, unsigned char **buffer, size_t *size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(dev->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(dev->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(dev->fd, VIDIOC_DQBUF, &dev->buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *buffer = dev->buffers[dev->buf.index];
    *size = dev->buf.length;

    if (ioctl(dev->fd, VIDIOC_QBUF, &dev->buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to write the timestamp to the log file
int write_timestamp(device_t *dev) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    fprintf(dev->log_file, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);
    fflush(dev->log_file);
    return 0;
}

// Function to stop capturing frames
int stop_capturing(device_t *dev) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to uninitialize the device
int uninit_device(device_t *dev) {
    for (int i = 0; i < dev->req.count; i++) {
        if (munmap(dev->buffers[i], dev->buf.length) < 0) {
            fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    free(dev->buffers);
    return 0;
}

// Function to close the device
int close_device(device_t *dev) {
    if (close(dev->fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    device_t device;
    unsigned char *frame_buffer;
    size_t frame_size;

    // Initialize device structure
    memset(&device, 0, sizeof(device_t));
    device.running = 1;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    if (open_device(&device) < 0) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(&device) < 0) {
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Open the log file
    device.log_file = fopen(LOG_FILE, "a");
    if (!device.log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        uninit_device(&device);
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Start capturing frames
    if (start_capturing(&device) < 0) {
        fclose(device.log_file);
        uninit_device(&device);
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        if (read_frame(&device, &frame_buffer, &frame_size) == 0) {
            if (write_timestamp(&device) != 0) {
                fprintf(stderr, "Error writing timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading frame\n");
        }
    }

    // Stop capturing frames
    if (stop_capturing(&device) < 0) {
        fprintf(stderr, "Error stopping capturing\n");
    }

    // Uninitialize the device
    if (uninit_device(&device) < 0) {
        fprintf(stderr, "Error uninitializing device\n");
    }

    // Close the device
    if (close_device(&device) < 0) {
        fprintf(stderr, "Error closing device\n");
    }

    // Close the log file
    if (fclose(device.log_file) != 0) {
        fprintf(stderr, "Error closing log file\n");
    }

    return EXIT_SUCCESS;
}

