#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <linux/videodev2.h>

#define NUM_BUFFERS 4
#define MAX_FRAME_SIZE 65535
#define MAX_FRAGMENTS 10

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Structure to hold frame data
typedef struct {
    unsigned char *data;
    size_t         size;
} frame_data;

// Structure to hold UDP packet data
typedef struct {
    unsigned char *data;
    size_t         size;
    struct sockaddr_in dest_addr;
} udp_packet;

// Global variables
