static buffer              buffers[NUM_BUFFERS];
static int                 frame_index = 0;
static volatile sig_atomic_t running = 1;
static char                *target_ip = NULL;
static int                 target_port = 0;
static int                 socket_fd = -1;
static pthread_t           udp_thread;
static pthread_mutex_t     frame_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t      frame_cond = PTHREAD_COND_INITIALIZER;
static frame_data          frame_queue[MAX_FRAGMENTS];
static int                 queue_head = 0;
static int                 queue_tail = 0;
static int                 queue_count = 0;

// Function prototypes
int  open_device(const char *device_name);
int  init_device(int fd);
int  enumerate_buffers(int fd);
int  map_buffers(int fd);
int  start_capturing(int fd);
int  stop_capturing(int fd);
int  unmap_buffers(int fd);
int  close_device(int fd);
int  capture_frame(int fd, buffer *buf);
int  fragment_frame(frame_data *frame, unsigned char **fragments, int *num_fragments);
int  send_udp_packet(udp_packet *packet);
void *udp_sender_thread(void *arg);
