// Function to enumerate the video buffers
int enumerate_buffers(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Error: Insufficient buffer memory on %s\n", "/dev/video0");
        return -1;
    }

    return 0;
}

// Function to map the video buffers
int map_buffers(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }
    return 0;
}

// Function to start capturing frames
int start_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }
    return 0;
}

// Function to stop capturing frames
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to unmap the video buffers
int unmap_buffers(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to close the video device
int close_device(int fd) {
    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Function to capture a single frame
int capture_frame(int fd, buffer *buf) {
    struct v4l2_buffer v4l2_buf;
    memset(&v4l2_buf, 0, sizeof(v4l2_buf));
    v4l2_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    v4l2_buf.memory = V4L2_MEMORY_MMAP;
    v4l2_buf.index = buf->index;

    if (ioctl(fd, VIDIOC_DQBUF, &v4l2_buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    frame_data frame;
    frame.data = (unsigned char *)buf->start;
    frame.size = v4l2_buf.bytesused;

    pthread_mutex_lock(&frame_mutex);
    frame_queue[queue_tail] = frame;
    queue_tail = (queue_tail + 1) % MAX_FRAGMENTS;
    queue_count++;
    pthread_cond_signal(&frame_cond);
    pthread_mutex_unlock(&frame_mutex);

    if (ioctl(fd, VIDIOC_QBUF, &v4l2_buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to fragment a frame into UDP packets
int fragment_frame(frame_data *frame, unsigned char **fragments, int *num_fragments) {
    *num_fragments = (frame->size + MAX_FRAME_SIZE - 1) / MAX_FRAME_SIZE;
    *fragments = (unsigned char *)malloc(*num_fragments * MAX_FRAME_SIZE);
    if (*fragments == NULL) {
        perror("Error allocating memory for fragments");
        return -1;
    }

    for (int i = 0; i < *num_fragments; i++) {
        int offset = i * MAX_FRAME_SIZE;
        int size = (offset + MAX_FRAME_SIZE > frame->size) ? (frame->size - offset) : MAX_FRAME_SIZE;
        memcpy(*fragments + offset, frame->data + offset, size);
    }

    return 0;
}

