        int num_fragments = 0;

        if (fragment_frame(&frame, &fragments, &num_fragments) == 0) {
            for (int i = 0; i < num_fragments; i++) {
                udp_packet packet;
                packet.data = fragments + (i * MAX_FRAME_SIZE);
                packet.size = (i == num_fragments - 1) ? (frame.size % MAX_FRAME_SIZE) : MAX_FRAME_SIZE;
                packet.dest_addr.sin_family = AF_INET;
                packet.dest_addr.sin_port = htons(target_port);
                packet.dest_addr.sin_addr.s_addr = inet_addr(target_ip);

                if (send_udp_packet(&packet) != 0) {
