    if (init_device(fd) < 0) {
        close_device(fd);
        close(socket_fd);
        return 1;
    }

    // Enumerate buffers
    if (enumerate_buffers(fd) < 0) {
        close_device(fd);
        close(socket_fd);
        return 1;
    }

    // Map buffers
    if (map_buffers(fd) < 0) {
        close_device(fd);
        close(socket_fd);
        return 1;
    }

    // Start capturing
    if (start_capturing(fd) < 0) {
        unmap_buffers(fd);
        close_device(fd);
        close(socket_fd);
        return 1;
    }

    // Create UDP sender thread
    if (pthread_create(&udp_thread, NULL, udp_sender_thread, NULL) != 0) {
        perror("Error creating UDP sender thread");
        stop_capturing(fd);
        unmap_buffers(fd);
        close_device(fd);
        close(socket_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms

    while (running) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (capture_frame(fd, &buffers[i]) < 0) {
                break; // Exit loop on error
            }
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    pthread_join(udp_thread, NULL);
    stop_capturing(fd);
    unmap_buffers(fd);
    close_device(fd);
    close(socket_fd);

    return 0;
}

