#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 192
#define IMAGE_HEIGHT 108
#define IMAGE_FILE "image.jpg"
#define NUM_BUFFERS 4

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
int         fd = -1;
buffer      *buffers = NULL;
unsigned int n_buffers = 0;
volatile sig_atomic_t stop_flag = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to check V4L2 capabilities
int check_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    printf("Device capabilities: %s\n", cap.card);
    return 0;
}

// Function to set the image format
int set_image_format(int fd) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    printf("Image format set to MJPEG: %dx%d\n", fmt.fmt.pix.width, fmt.fmt.pix.height);
    return 0;
}

// Function to request buffers
int request_buffers(int fd, unsigned int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }

    n_buffers = req.count;
    printf("Requested %d buffers\n", n_buffers);
    return 0;
}

// Function to map buffers
int map_buffers(int fd, buffer *buffers, unsigned int num_buffers) {
    for (unsigned int i = 0; i < num_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }

        printf("Buffer %d mapped at address %p with length %zu\n", i, buffers[i].start, buffers[i].length);
    }
    return 0;
}

// Function to queue a buffer
int queue_buffer(int fd, unsigned int index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    printf("Buffer %d queued\n", index);
    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    printf("Streaming started\n");
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    printf("Buffer %d dequeued, bytesused: %zu\n", buf.index, buf.bytesused);
    return buf.index;
}

// Function to write the image to a file
int write_image_to_file(const char *filename, buffer *buffers, int buffer_index, size_t bytesused) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    if (fwrite(buffers[buffer_index].start, 1, bytesused, fp) != bytesused) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Image written to %s\n", filename);
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }

    printf("Streaming stopped\n");
    return 0;
}

// Function to unmap buffers
int unmap_buffers(buffer *buffers, unsigned int num_buffers) {
    for (unsigned int i = 0; i < num_buffers; i++) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("munmap");
            return -1;
        }
        printf("Buffer %d unmapped\n", i);
    }
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (close(fd) < 0) {
        perror("close");
        return -1;
    }
    printf("Device closed\n");
    return 0;
}

// Function to free the buffer array
int free_buffers(buffer *buffers) {
    free(buffers);
    printf("Buffers freed\n");
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }
    printf("Device opened: %s\n", DEVICE_NAME);

    // Check capabilities
    if (check_capabilities(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Set image format
    if (set_image_format(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    buffers = calloc(NUM_BUFFERS, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (request_buffers(fd, NUM_BUFFERS) < 0) {
        free_buffers(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    if (map_buffers(fd, buffers, NUM_BUFFERS) < 0) {
        free_buffers(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Queue buffers
    for (unsigned int i = 0; i < NUM_BUFFERS; i++) {
        if (queue_buffer(fd, i) < 0) {
            unmap_buffers(buffers, NUM_BUFFERS);
            free_buffers(buffers);
            close_device(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    if (start_streaming(fd) < 0) {
        unmap_buffers(buffers, NUM_BUFFERS);
        free_buffers(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Dequeue a buffer
    int buffer_index = dequeue_buffer(fd);
    if (buffer_index < 0) {
        stop_streaming(fd);
        unmap_buffers(buffers, NUM_BUFFERS);
        free_buffers(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Verify bytesused
    if (buffers[buffer_index].bytesused <= 0) {
        fprintf(stderr, "bytesused is zero or negative\n");
        stop_streaming(fd);
        unmap_buffers(buffers, NUM_BUFFERS);
        free_buffers(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Write image to file
    if (write_image_to_file(IMAGE_FILE, buffers, buffer_index, buffers[buffer_index].bytesused) < 0) {
        stop_streaming(fd);
        unmap_buffers(buffers, NUM_BUFFERS);
        free_buffers(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_streaming(fd) < 0) {
        unmap_buffers(buffers, NUM_BUFFERS);
        free_buffers(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Unmap buffers
    if (unmap_buffers(buffers, NUM_BUFFERS) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Free buffers
    if (free_buffers(buffers) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Close the device
    if (close_device(fd) < 0) {
        return EXIT_FAILURE;
    }

    printf("Program finished\n");
    return EXIT_SUCCESS;
}

