#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <setjmp.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 75

// Structure to hold camera information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void **buffers;
    unsigned int n_buffers;
} camera_t;

// Global variables
static camera_t camera;
static volatile sig_atomic_t terminate = 0;
static jmp_buf env;

// Function prototypes
int open_camera(camera_t *cam);
int init_camera(camera_t *cam);
int start_capturing(camera_t *cam);
int stop_capturing(camera_t *cam);
int uninit_camera(camera_t *cam);
int close_camera(camera_t *cam);
int enqueue_buffer(camera_t *cam, int index);
int dequeue_buffer(camera_t *cam, int index);
int request_buffers(camera_t *cam);
int map_buffers(camera_t *cam);
int unmap_buffers(camera_t *cam);
int wait_for_frame(camera_t *cam);
unsigned char *yuyv_to_rgb24(unsigned char *yuyv_data, int width, int height);
int encode_jpeg(unsigned char *rgb_data, int width, int height, const char *filename);
void signal_handler(int sig);

// Error handling macro
#define CHECK_ERROR(ret, msg) \
    if (ret < 0) { \
        fprintf(stderr, "%s: %s\n", msg, strerror(errno)); \
        longjmp(env, 1); \
    }

int main() {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Initialize camera structure
    camera.fd = -1;
    camera.buffers = NULL;
    camera.n_buffers = 0;

    // Set up error handling
    if (setjmp(env) != 0) {
        fprintf(stderr, "Error occurred, cleaning up...\n");
        goto cleanup;
    }

    // Open camera
    if (open_camera(&camera) < 0) {
        fprintf(stderr, "Failed to open camera\n");
        goto cleanup;
    }

    // Initialize camera
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Failed to initialize camera\n");
        goto cleanup;
    }

    // Request buffers
    if (request_buffers(&camera) < 0) {
        fprintf(stderr, "Failed to request buffers\n");
        goto cleanup;
    }

    // Map buffers
    if (map_buffers(&camera) < 0) {
        fprintf(stderr, "Failed to map buffers\n");
        goto cleanup;
    }

    // Start capturing
    if (start_capturing(&camera) < 0) {
        fprintf(stderr, "Failed to start capturing\n");
        goto cleanup;
    }

    // Wait for frame
    if (wait_for_frame(&camera) < 0) {
        fprintf(stderr, "Failed to wait for frame\n");
        goto cleanup;
    }

    // Dequeue buffer
    if (dequeue_buffer(&camera, 0) < 0) {
        fprintf(stderr, "Failed to dequeue buffer\n");
        goto cleanup;
    }

    // Convert YUYV to RGB24
    unsigned char *rgb_data = yuyv_to_rgb24((unsigned char *)camera.buffers[0], IMAGE_WIDTH, IMAGE_HEIGHT);
    if (rgb_data == NULL) {
        fprintf(stderr, "Failed to convert YUYV to RGB24\n");
        goto cleanup;
    }

    // Encode JPEG
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[64];
    sprintf(filename, "capture_%04d%02d%02d_%02d%02d%02d.jpg", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

    if (encode_jpeg(rgb_data, IMAGE_WIDTH, IMAGE_HEIGHT, filename) < 0) {
        fprintf(stderr, "Failed to encode JPEG\n");
        free(rgb_data);
        goto cleanup;
    }

    free(rgb_data);

    // Stop capturing
    if (stop_capturing(&camera) < 0) {
        fprintf(stderr, "Failed to stop capturing\n");
        goto cleanup;
    }

cleanup:
    // Uninitialize camera
    if (uninit_camera(&camera) < 0) {
        fprintf(stderr, "Failed to uninitialize camera\n");
    }

    // Close camera
    if (close_camera(&camera) < 0) {
        fprintf(stderr, "Failed to close camera\n");
    }

    return EXIT_SUCCESS;
}

int open_camera(camera_t *cam) {
    cam->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (cam->fd < 0) {
        fprintf(stderr, "Error opening device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_camera(camera_t *cam) {
    // Check capabilities
    if (ioctl(cam->fd, VIDIOC_QUERYCAP, &cam->cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set format
    cam->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->fmt.fmt.pix.width = IMAGE_WIDTH;
    cam->fmt.fmt.pix.height = IMAGE_HEIGHT;
    cam->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    cam->fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(cam->fd, VIDIOC_S_FMT, &cam->fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int start_capturing(camera_t *cam) {
    for (int i = 0; i < cam->n_buffers; i++) {
        if (enqueue_buffer(cam, i) < 0) {
            fprintf(stderr, "Error enqueuing buffer\n");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(cam->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int stop_capturing(camera_t *cam) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(cam->fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int uninit_camera(camera_t *cam) {
    if (unmap_buffers(cam) < 0) {
        fprintf(stderr, "Error unmapping buffers\n");
        return -1;
    }

    if (close_camera(cam) < 0) {
        fprintf(stderr, "Error closing camera\n");
        return -1;
    }

    return 0;
}

int close_camera(camera_t *cam) {
    if (cam->fd != -1) {
        close(cam->fd);
        cam->fd = -1;
    }
    return 0;
}

int enqueue_buffer(camera_t *cam, int index) {
    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;
    cam->buf.index = index;

    if (ioctl(cam->fd, VIDIOC_QBUF, &cam->buf) < 0) {
        fprintf(stderr, "Error enqueuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int dequeue_buffer(camera_t *cam, int index) {
    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;
    cam->buf.index = index;

    if (ioctl(cam->fd, VIDIOC_DQBUF, &cam->buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int request_buffers(camera_t *cam) {
    cam->req.count = 4; // Number of buffers
    cam->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(cam->fd, VIDIOC_REQBUFS, &cam->req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (cam->req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    cam->n_buffers = cam->req.count;
    return 0;
}

int map_buffers(camera_t *cam) {
    cam->buffers = calloc(cam->n_buffers, sizeof(void *));
    if (cam->buffers == NULL) {
        fprintf(stderr, "Error allocating buffer memory\n");
        return -1;
    }

    for (int i = 0; i < cam->n_buffers; i++) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(cam->fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            return -1;
        }

        cam->buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, buf.m.offset);
        if (cam->buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

int unmap_buffers(camera_t *cam) {
    if (cam->buffers != NULL) {
        for (int i = 0; i < cam->n_buffers; i++) {
            if (munmap(cam->buffers[i], 0) < 0) {
                fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
                return -1;
            }
        }
        free(cam->buffers);
        cam->buffers = NULL;
    }
    return 0;
}

int wait_for_frame(camera_t *cam) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);

    tv.tv_sec = 2; // 2 seconds timeout
    tv.tv_usec = 0;

    r = select(cam->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal\n");
            return -1;
        }
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    return 0;
}

unsigned char *yuyv_to_rgb24(unsigned char *yuyv_data, int width, int height) {
    unsigned char *rgb_data = (unsigned char *)malloc(width * height * 3);
    if (rgb_data == NULL) {
        fprintf(stderr, "Error allocating memory for RGB data\n");
        return NULL;
    }

    for (int i = 0; i < width * height; i++) {
        int y = yuyv_data[i * 2];
        int u = yuyv_data[i * 2 + 1] - 128;
        int v = yuyv_data[i * 2 + 3] - 128;

        int r = y + 1.402 * v;
        int g = y - 0.344 * u - 0.714 * v;
        int b = y + 1.772 * u;

        r = (r < 0) ? 0 : ((r > 255) ? 255 : r);
        g = (g < 0) ? 0 : ((g > 255) ? 255 : g);
        b = (b < 0) ? 0 : ((b > 255) ? 255 : b);

        rgb_data[i * 3 + 0] = r;
        rgb_data[i * 3 + 1] = g;
        rgb_data[i * 3 + 2] = b;
    }

    return rgb_data;
}

int encode_jpeg(unsigned char *rgb_data, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb_data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
    longjmp(env, 1);
}

