#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl queryctrl;
    int ret;

    // Check if the device exists
    if (access(DEVICE_NAME, F_OK) == -1) {
        fprintf(stderr, "Error: Device %s does not exist.\n", DEVICE_NAME);
        return 1;
    }

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error: Could not open device %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    // Query capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        fprintf(stderr, "Error: VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08X\n", cap.capabilities);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture.\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming.\n");
        close(fd);
        return 1;
    }

    // Enumerate supported formats
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    printf("\nSupported Formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        printf("  Format: %s\n", fmtdesc.description);
        fmtdesc.index++;
    }

    // Enumerate frame sizes and intervals
    frmsize.index = 0;
    frmsize.pixel_format = fmtdesc.pixel_format; // Use the first supported format
    printf("\nSupported Frame Sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  Frame Size: %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
            frmival.index = 0;
            frmival.pixel_format = fmtdesc.pixel_format;
            frmival.width = frmsize.discrete.width;
            frmival.height = frmsize.discrete.height;
            printf("    Supported Frame Intervals:\n");
            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
                printf("      Frame Interval: %d/%d\n", frmival.discrete.numerator, frmival.discrete.denominator);
                frmival.index++;
            }
        }
        frmsize.index++;
    }

    // Query autofocus control
    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl);
    if (ret == -1) {
        fprintf(stderr, "Error: VIDIOC_QUERYCTRL (focus) failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("\nAutofocus Support: ");
    if (queryctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("No autofocus control.\n");
    } else {
        printf("Autofocus is %s.\n", (queryctrl.flags & V4L2_CTRL_FLAG_INACTIVE) ? "disabled" : "enabled");
    }

    close(fd);
    return 0;
}

