#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Define increment and delay values
#define PULSE_WIDTH_INCREMENT 10
#define DELAY_MS 50

// Global variables for servo pulse widths
int pan_pulse_width = CENTER_PULSE_WIDTH;
int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void update_servos();
void handle_button_press(int button_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioPWM(PAN_SERVO_PIN, 0); // Stop pan servo
    gpioPWM(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate(); // Terminate pigpio
}

// Update servo pulse widths
void update_servos() {
    gpioPWM(PAN_SERVO_PIN, pan_pulse_width);
    gpioPWM(TILT_SERVO_PIN, tilt_pulse_width);
}

// Handle button press
void handle_button_press(int button_pin) {
    int new_pan_pulse_width = pan_pulse_width;
    int new_tilt_pulse_width = tilt_pulse_width;

    switch (button_pin) {
        case UP_BUTTON_PIN:
            new_tilt_pulse_width += PULSE_WIDTH_INCREMENT;
            break;
        case DOWN_BUTTON_PIN:
            new_tilt_pulse_width -= PULSE_WIDTH_INCREMENT;
            break;
        case LEFT_BUTTON_PIN:
            new_pan_pulse_width -= PULSE_WIDTH_INCREMENT;
            break;
        case RIGHT_BUTTON_PIN:
            new_pan_pulse_width += PULSE_WIDTH_INCREMENT;
            break;
    }

    // Clamp pulse widths to the allowed range
    if (new_pan_pulse_width < MIN_PULSE_WIDTH) {
        new_pan_pulse_width = MIN_PULSE_WIDTH;
    } else if (new_pan_pulse_width > MAX_PULSE_WIDTH) {
        new_pan_pulse_width = MAX_PULSE_WIDTH;
    }

    if (new_tilt_pulse_width < MIN_PULSE_WIDTH) {
        new_tilt_pulse_width = MIN_PULSE_WIDTH;
    } else if (new_tilt_pulse_width > MAX_PULSE_WIDTH) {
        new_tilt_pulse_width = MAX_PULSE_WIDTH;
    }

    // Update global variables
    pan_pulse_width = new_pan_pulse_width;
    tilt_pulse_width = new_tilt_pulse_width;

    // Update servos
    update_servos();
}

