    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Print startup message
    printf("Pan-Tilt Mount Control\n");
    printf("Pan Servo Pin: %d, Tilt Servo Pin: %d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Center Position: Pan = %d us, Tilt = %d us\n", CENTER_PULSE_WIDTH, CENTER_PULSE_WIDTH);

