#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <errno.h>
#include <wiringPi.h>
#include <jpeglib.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 2000
#define POLL_INTERVAL_MS 100
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 85

// Global variables
static volatile int running = 1;
static char *ip_address = NULL;
static int port = 0;
static char *endpoint_url = NULL;
static char *motion_captures_dir = "motion_captures";
static int socket_fd = -1;
static pthread_t http_thread;
static pthread_mutex_t image_mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned char *image_data = NULL;
static size_t image_size = 0;

// Structure to hold image data
typedef struct {
    unsigned char *data;
    size_t size;
} ImageData;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_sensor();
int debounce_sensor();
int capture_image(char *filename);
int compress_image(unsigned char *input_data, size_t input_size, unsigned char **output_data, size_t *output_size);
int create_json_payload(char *filename, char *timestamp, int motion_status, int gpio_pin, char **json_payload);
int send_http_request(char *json_payload, unsigned char *image_data, size_t image_size);
void *http_request_thread(void *arg);
int create_directory(const char *path);
int check_directory_exists(const char *path);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Shutting down...\n", signal);
    running = 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(GPIO_PIN, INPUT);
    pullUpDnControl(GPIO_PIN, PUD_DOWN);

    return 0;
}

// Read sensor value
int read_sensor() {
    return digitalRead(GPIO_PIN);
}

// Debounce sensor
int debounce_sensor() {
    int count = 0;
    int value = read_sensor();
    for (int i = 0; i < 20; i++) { // Check for 2 seconds (20 * 100ms)
        if (read_sensor() == value) {
            count++;
        }
        delay(POLL_INTERVAL_MS);
    }
    return (count == 20) ? value : 0; // Return the original value if consistent
}

// Capture image from camera (dummy implementation)
int capture_image(char *filename) {
    // In a real implementation, this would use a camera library
    // to capture a JPEG image.
    // For this example, we'll just create a dummy image.
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return -1;
    }

    // Create a dummy image (a simple grayscale gradient)
    unsigned char *dummy_image = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT);
    if (dummy_image == NULL) {
        fprintf(stderr, "Error allocating memory for dummy image\n");
        fclose(fp);
        return -1;
    }

    for (int i = 0; i < IMAGE_WIDTH * IMAGE_HEIGHT; i++) {
        dummy_image[i] = (unsigned char)(i % 256); // Simple grayscale gradient
    }

    fwrite(dummy_image, 1, IMAGE_WIDTH * IMAGE_HEIGHT, fp);
    free(dummy_image);
    fclose(fp);

    return 0;
}

// Compress image using libjpeg
int compress_image(unsigned char *input_data, size_t input_size, unsigned char **output_data, size_t *output_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    jpeg_mem_dest(&cinfo, output_data, output_size);

    cinfo.image_width = IMAGE_WIDTH;
    cinfo.image_height = IMAGE_HEIGHT;
    cinfo.input_components = 1; // Grayscale
    cinfo.in_color_space = JCS_GRAYSCALE;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &input_data[cinfo.next_scanline * IMAGE_WIDTH];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Create JSON payload
int create_json_payload(char *filename, char *timestamp, int motion_status, int gpio_pin, char **json_payload) {
    char json_string[512]; // Adjust size as needed
    snprintf(json_string, sizeof(json_string), 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);

    *json_payload = strdup(json_string); // Allocate memory for the JSON payload
    if (*json_payload == NULL) {
        fprintf(stderr, "Error allocating memory for JSON payload\n");
        return -1;
    }

    return 0;
}

// Send HTTP request using libcurl
int send_http_request(char *json_payload, unsigned char *image_data, size_t image_size) {
    CURL *curl;
    CURLcode res;
    struct curl_httppost *formpost = NULL;
    struct curl_httppost *lastptr = NULL;
    struct curl_slist *headerlist = NULL;

    curl_global_init(CURL_GLOBAL_ALL);

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, endpoint_url);

        // Set headers
        headerlist = curl_slist_append(headerlist, "Content-Type: multipart/form-data");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headerlist);

        // Add JSON payload as form field
        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "json_payload", CURLFORM_COPYCONTENTS, json_payload, CURLFORM_END);

        // Add image data as form field
        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image_data", CURLFORM_BUFFER, "image.jpg", CURLFORM_BUFFERPTR, image_data, CURLFORM_BUFFERLENGTH, image_size, CURLFORM_END);

        curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_formfree(formpost);
        curl_slist_free_all(headerlist);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// HTTP request thread function
void *http_request_thread(void *arg) {
    char *json_payload = (char *)arg;
    unsigned char *compressed_image = NULL;
    size_t compressed_image_size = 0;

    // Compress the image
    if (compress_image(image_data, image_size, &compressed_image, &compressed_image_size) != 0) {
        fprintf(stderr, "Error compressing image\n");
        pthread_exit(NULL);
    }

    // Send the HTTP request
    if (send_http_request(json_payload, compressed_image, compressed_image_size) != 0) {
        fprintf(stderr, "Error sending HTTP request\n");
    }

    // Free the compressed image
    free(compressed_image);

    pthread_exit(NULL);
}

// Create directory
int create_directory(const char *path) {
    if (mkdir(path, 0777) == -1) {
        if (errno == EEXIST) {
            fprintf(stderr, "Directory already exists: %s\n", path);
            return 0; // Directory already exists, not an error
        } else {
            fprintf(stderr, "Error creating directory: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Check if directory exists
int check_directory_exists(const char *path) {
    struct stat st;
    if (stat(path, &st) == -1) {
        if (errno == ENOENT) {
            return 0; // Directory does not exist
        } else {
            fprintf(stderr, "Error checking directory: %s\n", strerror(errno));
            return -1;
        }
    }
    return 1; // Directory exists
}

// Cleanup function
void cleanup() {
    running = 0;

    // Release GPIO resources
    // No explicit GPIO cleanup function in wiringPi, but we can reset the pin mode.
    pinMode(GPIO_PIN, INPUT); // Set back to input
    pullUpDnControl(GPIO_PIN, PUD_OFF); // Disable pull-up/down

    // Cleanup HTTP thread
    pthread_cancel(http_thread);
    pthread_join(http_thread, NULL);

    // Cleanup libcurl
    curl_global_cleanup();

    // Free image data
    if (image_data != NULL) {
        free(image_data);
    }

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Destroy mutex
    pthread_mutex_destroy(&image_mutex);

    fprintf(stderr, "Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <IP address> <port> <endpoint URL>\n", argv[0]);
        return 1;
    }

    ip_address = argv[1];
    port = atoi(argv[2]);
    endpoint_url = argv[3];

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create directory
    if (check_directory_exists(motion_captures_dir) != 1) {
        if (create_directory(motion_captures_dir) != 0) {
            cleanup();
            return 1;
        }
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_ALL);

    // Main loop
    while (running) {
        int motion_detected = debounce_sensor();

        if (motion_detected) {
            // Generate filename
            time_t rawtime;
            struct tm *timeinfo;
            char filename[64];
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%6.6f.jpg", timeinfo);
            snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02dT%02d:%02d:%02d.%06ldZ",
                     timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                     timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, rawtime % 1000000);

            // Capture image
            char filepath[256];
            snprintf(filepath, sizeof(filepath), "%s/%s", motion_captures_dir, filename);
            if (capture_image(filepath) != 0) {
                fprintf(stderr, "Error capturing image\n");
                continue; // Skip to the next iteration
            }

            // Read image data
            FILE *fp = fopen(filepath, "rb");
            if (fp == NULL) {
                fprintf(stderr, "Error opening image file for reading: %s\n", strerror(errno));
                continue;
            }

            fseek(fp, 0, SEEK_END);
            long file_size = ftell(fp);
            fseek(fp, 0, SEEK_SET);

            image_data = (unsigned char *)malloc(file_size);
            if (image_data == NULL) {
                fprintf(stderr, "Error allocating memory for image data\n");
                fclose(fp);
                continue;
            }

            if (fread(image_data, 1, file_size, fp) != (size_t)file_size) {
                fprintf(stderr, "Error reading image data\n");
                free(image_data);
                image_data = NULL;
                fclose(fp);
                continue;
            }

            image_size = (size_t)file_size;
            fclose(fp);

            // Create JSON payload
            char *json_payload = NULL;
            if (create_json_payload(filename, timestamp, motion_detected, GPIO_PIN, &json_payload) != 0) {
                fprintf(stderr, "Error creating JSON payload\n");
                free(json_payload);
                continue;
            }

            // Create HTTP request thread
            pthread_create(&http_thread, NULL, http_request_thread, (void *)json_payload);

            // Wait for the HTTP request to complete (or timeout)
            pthread_join(http_thread, NULL);

            // Free JSON payload
            free(json_payload);

            // Free image data
            free(image_data);
            image_data = NULL;
            image_size = 0;
        }

        delay(POLL_INTERVAL_MS);
    }

    // Cleanup
    cleanup();

    return 0;
}

