        // Add image data as form field
        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image_data", CURLFORM_BUFFER, "image.jpg", CURLFORM_BUFFERPTR, image_data, CURLFORM_BUFFERLENGTH, image_size, CURLFORM_END);

        curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_formfree(formpost);
        curl_slist_free_all(headerlist);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// HTTP request thread function
void *http_request_thread(void *arg) {
    char *json_payload = (char *)arg;
    unsigned char *compressed_image = NULL;
    size_t compressed_image_size = 0;

    // Compress the image
    if (compress_image(image_data, image_size, &compressed_image, &compressed_image_size) != 0) {
        fprintf(stderr, "Error compressing image\n");
        pthread_exit(NULL);
    }

    // Send the HTTP request
    if (send_http_request(json_payload, compressed_image, compressed_image_size) != 0) {
        fprintf(stderr, "Error sending HTTP request\n");
    }

    // Free the compressed image
    free(compressed_image);

    pthread_exit(NULL);
}

// Create directory
int create_directory(const char *path) {
    if (mkdir(path, 0777) == -1) {
        if (errno == EEXIST) {
            fprintf(stderr, "Directory already exists: %s\n", path);
            return 0; // Directory already exists, not an error
        } else {
            fprintf(stderr, "Error creating directory: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Check if directory exists
int check_directory_exists(const char *path) {
    struct stat st;
    if (stat(path, &st) == -1) {
        if (errno == ENOENT) {
            return 0; // Directory does not exist
        } else {
            fprintf(stderr, "Error checking directory: %s\n", strerror(errno));
            return -1;
        }
    }
    return 1; // Directory exists
}

// Cleanup function
void cleanup() {
    running = 0;

    // Release GPIO resources
    // No explicit GPIO cleanup function in wiringPi, but we can reset the pin mode.
    pinMode(GPIO_PIN, INPUT); // Set back to input
    pullUpDnControl(GPIO_PIN, PUD_OFF); // Disable pull-up/down

    // Cleanup HTTP thread
    pthread_cancel(http_thread);
    pthread_join(http_thread, NULL);

    // Cleanup libcurl
    curl_global_cleanup();

    // Free image data
    if (image_data != NULL) {
        free(image_data);
    }

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Destroy mutex
    pthread_mutex_destroy(&image_mutex);

    fprintf(stderr, "Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <IP address> <port> <endpoint URL>\n", argv[0]);
        return 1;
    }

    ip_address = argv[1];
    port = atoi(argv[2]);
    endpoint_url = argv[3];

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create directory
    if (check_directory_exists(motion_captures_dir) != 1) {
        if (create_directory(motion_captures_dir) != 0) {
            cleanup();
            return 1;
        }
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_ALL);

    // Main loop
    while (running) {
        int motion_detected = debounce_sensor();

        if (motion_detected) {
            // Generate filename
            time_t rawtime;
            struct tm *timeinfo;
            char filename[64];
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%6.6f.jpg", timeinfo);
            snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02dT%02d:%02d:%02d.%06ldZ",
                     timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                     timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, rawtime % 1000000);

            // Capture image
            char filepath[256];
            snprintf(filepath, sizeof(filepath), "%s/%s", motion_captures_dir, filename);
            if (capture_image(filepath) != 0) {
                fprintf(stderr, "Error capturing image\n");
                continue; // Skip to the next iteration
            }

            // Read image data
            FILE *fp = fopen(filepath, "rb");
            if (fp == NULL) {
                fprintf(stderr, "Error opening image file for reading: %s\n", strerror(errno));
                continue;
            }

            fseek(fp, 0, SEEK_END);
            long file_size = ftell(fp);
            fseek(fp, 0, SEEK_SET);

            image_data = (unsigned char *)malloc(file_size);
            if (image_data == NULL) {
                fprintf(stderr, "Error allocating memory for image data\n");
                fclose(fp);
                continue;
            }

            if (fread(image_data, 1, file_size, fp) != (size_t)file_size) {
                fprintf(stderr, "Error reading image data\n");
                free(image_data);
                image_data = NULL;
                fclose(fp);
                continue;
            }

            image_size = (size_t)file_size;
            fclose(fp);

            // Create JSON payload
            char *json_payload = NULL;
            if (create_json_payload(filename, timestamp, motion_detected, GPIO_PIN, &json_payload) != 0) {
                fprintf(stderr, "Error creating JSON payload\n");
                free(json_payload);
                continue;
            }

            // Create HTTP request thread
            pthread_create(&http_thread, NULL, http_request_thread, (void *)json_payload);

            // Wait for the HTTP request to complete (or timeout)
            pthread_join(http_thread, NULL);

            // Free JSON payload
            free(json_payload);

            // Free image data
            free(image_data);
            image_data = NULL;
            image_size = 0;
        }

        delay(POLL_INTERVAL_MS);
    }

    // Cleanup
    cleanup();

    return 0;
}

