#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to generate a timestamped filename
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(50 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 50, "%Y%m%d_%H%M%S", timeinfo);
    return filename;
}

// Function to capture an image using raspistill
int capture_image(const char *filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspistill -o %s/%s.jpg --width 640 --height 480 -q 85 --timeout 2000 --nopreview", IMAGE_DIR, filename);
    int status = system(command);
    return status;
}

// Function to log messages to a file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (gpioWaitForEdge(GPIO_PIN, FALLING_EDGE, DEBOUNCE_MS) == 0) {
            char *filename = generate_filename();
            if (filename != NULL) {
                int capture_status = capture_image(filename);
                if (capture_status == 0) {
                    char log_message_buffer[200];
                    snprintf(log_message_buffer, sizeof(log_message_buffer), "Motion detected and image captured: %s.jpg", filename);
                    log_message(log_message_buffer);
                    printf("%s\n", log_message_buffer);
                } else {
                    char log_message_buffer[200];
                    snprintf(log_message_buffer, sizeof(log_message_buffer), "Error capturing image: %s.jpg (raspistill status %d)", filename, capture_status);
                    log_message(log_message_buffer);
                    fprintf(stderr, "%s\n", log_message_buffer);
                }
                free(filename);
            } else {
                log_message("Error generating filename.");
                fprintf(stderr, "Error generating filename.\n");
            }
        }
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

