#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_FILENAME "cropped.yuv"

// Structure to hold camera configuration
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    FILE *fp;
    int running;
} camera_config_t;

// Function prototypes
int open_device(const char *device_name);
int verify_capabilities(int fd);
int set_format(int fd, unsigned int width, unsigned int height, unsigned int pixelformat);
int request_buffers(int fd, unsigned int count);
int start_streaming(int fd);
int capture_frame(camera_config_t *config);
int process_frame(camera_config_t *config, unsigned char *yuyv_data, unsigned int width, unsigned int height);
int write_cropped_yuv(camera_config_t *config, unsigned char *cropped_data);
void signal_handler(int sig);
void cleanup(camera_config_t *config);

// Global variable for signal handling
volatile sig_atomic_t stop_flag = 0;

int main() {
    camera_config_t config = {0};
    config.running = 1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    config.fd = open_device(DEVICE_NAME);
    if (config.fd < 0) {
        fprintf(stderr, "Failed to open device %s\n", DEVICE_NAME);
        return EXIT_FAILURE;
    }

    // Verify capabilities
    if (verify_capabilities(config.fd) < 0) {
        fprintf(stderr, "Failed to verify capabilities\n");
        cleanup(&config);
        return EXIT_FAILURE;
    }

    // Set format
    if (set_format(config.fd, 640, 480, V4L2_PIX_FMT_YUYV) < 0) {
        fprintf(stderr, "Failed to set format\n");
        cleanup(&config);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(config.fd, 1) < 0) {
        fprintf(stderr, "Failed to request buffers\n");
        cleanup(&config);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(config.fd) < 0) {
        fprintf(stderr, "Failed to start streaming\n");
        cleanup(&config);
        return EXIT_FAILURE;
    }

    // Main loop
    while (config.running) {
        if (capture_frame(&config) < 0) {
            fprintf(stderr, "Failed to capture frame\n");
            break;
        }
    }

    // Cleanup
    cleanup(&config);

    return EXIT_SUCCESS;
}

// Function to open the device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to verify capabilities
int verify_capabilities(int fd) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    return 0;
}

// Function to set format
int set_format(int fd, unsigned int width, unsigned int height, unsigned int pixelformat) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pixelformat;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, unsigned int count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));

    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_config_t *config) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(config->fd, &fds);

    tv.tv_sec = 2; // 2 seconds timeout
    tv.tv_usec = 0;

    r = select(config->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal\n");
            return -1; // Retry
        }
        perror("Error in select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(config->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Check frame dimensions
    if (buf.bytesused != config->fmt.fmt.pix.sizeimage) {
        fprintf(stderr, "Frame size mismatch: expected %d, got %d\n", config->fmt.fmt.pix.sizeimage, buf.bytesused);
        if (ioctl(config->fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer after mismatch");
        }
        return -1;
    }

    // Process the frame
    if (process_frame(config, (unsigned char *)config->buffer, config->fmt.fmt.pix.width, config->fmt.fmt.pix.height) < 0) {
        fprintf(stderr, "Failed to process frame\n");
        if (ioctl(config->fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer after processing error");
        }
        return -1;
    }

    if (ioctl(config->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to process the frame
int process_frame(camera_config_t *config, unsigned char *yuyv_data, unsigned int width, unsigned int height) {
    unsigned char *cropped_data = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped_data == NULL) {
        perror("Failed to allocate memory for cropped data");
        return -1;
    }

    // Crop the YUYV image
    for (int i = 0; i < CROP_HEIGHT; i++) {
        for (int j = 0; j < CROP_WIDTH; j++) {
            int y0_index = (i * width + j) * 2;
            int uv_index = y0_index + 1;

            cropped_data[(i * CROP_WIDTH + j) * 2] = yuyv_data[y0_index];
            cropped_data[(i * CROP_WIDTH + j) * 2 + 1] = yuyv_data[uv_index];
        }
    }

    // Write the cropped YUYV data to a file
    if (write_cropped_yuv(config, cropped_data) < 0) {
        fprintf(stderr, "Failed to write cropped YUYV data to file\n");
        free(cropped_data);
        return -1;
    }

    free(cropped_data);
    return 0;
}

// Function to write the cropped YUYV data to a file
int write_cropped_yuv(camera_config_t *config, unsigned char *cropped_data) {
    config->fp = fopen(CROP_FILENAME, "wb");
    if (config->fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_data, 1, CROP_WIDTH * CROP_HEIGHT * 2, config->fp);
    if (bytes_written != CROP_WIDTH * CROP_HEIGHT * 2) {
        perror("Error writing to file");
        fclose(config->fp);
        return -1;
    }

    fclose(config->fp);
    config->fp = NULL; // Reset file pointer
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Cleanup function
void cleanup(camera_config_t *config) {
    if (config->running) {
        config->running = 0;
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(config->fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("Error stopping stream");
        }

        if (config->buffer != NULL) {
            if (munmap(config->buffer, config->fmt.fmt.pix.sizeimage) < 0) {
                perror("Error unmapping buffer");
            }
            config->buffer = NULL;
        }

        if (config->fp != NULL) {
            fclose(config->fp);
            config->fp = NULL;
        }

        if (config->fd > 0) {
            close(config->fd);
            config->fd = 0;
        }
    }
}

