#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servo motors
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define neutral position (90 degrees)
#define NEUTRAL_PULSE_WIDTH 1500 // microseconds

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set servo angle using PWM
int set_servo_angle(int gpio_pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate failure
    }

    // Calculate pulse width based on angle (0-180 maps to 1000-2000 us)
    int pulse_width = (int)(((float)angle / MAX_ANGLE) * 1000 + 1000);

    // Set the servo pulse width
    gpioServo(gpio_pin, pulse_width);

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set GPIO pins to output mode
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set initial servo positions to neutral
    if (set_servo_angle(PAN_SERVO_PIN, 90) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_SERVO_PIN, 90) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Pan and Tilt Servo Control\n");
    printf("Use arrow keys (or 'q' to quit) to control servos.\n");
    printf("Press 'q' to exit.\n");

    int pan_angle = 90;
    int tilt_angle = 90;

    while (program_running) {
        int input = getchar();

        if (input == 'q') {
            break; // Exit loop
        } else if (input == 'a') { // Left arrow
            pan_angle -= 5;
            if (pan_angle < MIN_ANGLE) {
                pan_angle = MIN_ANGLE;
            }
        } else if (input == 'd') { // Right arrow
            pan_angle += 5;
            if (pan_angle > MAX_ANGLE) {
                pan_angle = MAX_ANGLE;
            }
        } else if (input == 'w') { // Up arrow
            tilt_angle -= 5;
            if (tilt_angle < MIN_ANGLE) {
                tilt_angle = MIN_ANGLE;
            }
        } else if (input == 's') { // Down arrow
            tilt_angle += 5;
            if (tilt_angle > MAX_ANGLE) {
                tilt_angle = MAX_ANGLE;
            }
        } else {
            continue; // Ignore other input
        }

        // Set servo angles
        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
            fprintf(stderr, "Error setting pan servo angle.\n");
        }
        if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
            fprintf(stderr, "Error setting tilt servo angle.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Set servos to neutral position before exiting
    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

