// Function to read CPU temperature from file
int read_cpu_temp(float *temp) {
    FILE *fp;
    char buffer[10];

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open CPU temperature file: %s\n", CPU_TEMP_FILE);
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error: Could not read CPU temperature from file: %s\n", CPU_TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    long temp_milli = strtol(buffer, NULL, 10);
    if (errno == ERANGE) {
        fprintf(stderr, "Error: CPU temperature value out of range: %s\n", buffer);
        return -1;
    }

    *temp = (float)temp_milli / 1000.0;
    return 0;
