// Function to read CPU usage from /proc/stat
int read_cpu_usage(float *usage) {
    FILE *fp;
    unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long prev_total = 0, prev_idle_total = 0;
    unsigned long total, idle_total;
    float usage_delta, total_delta;

    fp = fopen(PROC_STAT_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat file: %s\n", PROC_STAT_FILE);
        return -1;
    }

    // Read the first line to get the previous values
    if (fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error: Could not read CPU stats from file: %s\n", PROC_STAT_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Wait for a short period to get the current values
    usleep(100000); // 100ms

    fp = fopen(PROC_STAT_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat file: %s\n", PROC_STAT_FILE);
        return -1;
    }

    if (fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Could not read CPU stats from file: %s\n", PROC_STAT_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    idle_total = idle + iowait;

    total_delta = (float)(total - prev_total);
    usage_delta = (float)((total - prev_total) - (idle_total - prev_idle_total));

    *usage = (usage_delta / total_delta) * 100.0;

    prev_total = total;
    prev_idle_total = idle_total;

    return 0;
}

