// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float cpu_temp, cpu_usage;
    char temp_str[20], usage_str[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SSD1306_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the OLED display
    ssd1306_init();

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        if (read_cpu_temp(&cpu_temp) != 0) {
            cpu_temp = -999.0; // Indicate error
        }

        // Read CPU usage
        if (read_cpu_usage(&cpu_usage) != 0) {
            cpu_usage = -1.0; // Indicate error
        }

        // Format temperature string
        snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", cpu_temp);

        // Format usage string
        snprintf(usage_str, sizeof(usage_str), "Usage: %.1f %%", cpu_usage);

        // Clear the display
        clear_display();

        // Render text
        render_text(0, 0, temp_str);
        render_text(0, 16, usage_str);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

