#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1
#define LCD_ADDR 0x27 // Change if your LCD has a different address
#define LCD_WIDTH 16

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
double current_flow_rate = 0.0;
int i2c_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_print(int line, const char *text);
void lcd_send_command(unsigned char cmd);
void lcd_send_data(unsigned char data);

// LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20
#define LCD_SETCGRAM 0x40
#define LCD_SETDDRAM 0x80

// Flags for display control
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// Flags for entry mode
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// Flags for function set
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Function to initialize the LCD
int lcd_init() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialize LCD in 4-bit mode
    gpioDelay(50000); // Wait for more than 40ms after VCC rises to 4.5V
    lcd_send_command(0x30); // Initialization sequence
    gpioDelay(5000);  // Wait for more than 4.1ms
    lcd_send_command(0x30); // Initialization sequence
    gpioDelay(1000);  // Wait for more than 100us
    lcd_send_command(0x30); // Initialization sequence
    gpioDelay(1000);  // Wait for more than 100us
    lcd_send_command(0x20); // 4-bit mode
    gpioDelay(1000);  // Wait for more than 100us

    lcd_send_command(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_send_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF);
    lcd_clear();
    lcd_send_command(LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT);

    return 0;
}

// Function to clear the LCD display
void lcd_clear() {
    lcd_send_command(LCD_CLEARDISPLAY);
    gpioDelay(2000); // Wait for more than 2ms
}

// Function to print text to the LCD at a specified line
void lcd_print(int line, const char *text) {
    int addr;
    if (line == 0) {
        addr = 0x00;
    } else {
        addr = 0x40;
    }
    lcd_send_command(LCD_SETDDRAM | addr);
    for (int i = 0; text[i] != 0; i++) {
        lcd_send_data(text[i]);
    }
}

// Function to send a command to the LCD
void lcd_send_command(unsigned char cmd) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (cmd & 0xF0);
    data_l = ((cmd << 4) & 0xF0);

    data_t[0] = data_u | 0x0C;  //en=1, rs=0
    data_t[1] = data_u | 0x08;  //en=0, rs=0
    data_t[2] = data_l | 0x0C;  //en=1, rs=0
    data_t[3] = data_l | 0x08;  //en=0, rs=0

    i2cWriteDevice(i2c_handle, data_t, 4);
}

// Function to send data to the LCD
void lcd_send_data(unsigned char data) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    data_t[0] = data_u | 0x0D;  //en=1, rs=1
    data_t[1] = data_u | 0x09;  //en=0, rs=1
    data_t[2] = data_l | 0x0D;  //en=1, rs=1
    data_t[3] = data_l | 0x09;  //en=0, rs=1

    i2cWriteDevice(i2c_handle, data_t, 4);
}

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    // Register callback function for rising edge detection
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback);

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate instantaneous flow rate
        current_flow_rate = (double)pulse_count / PULSES_PER_LITER;

        // Accumulate total volume
        total_volume += (double)pulse_count / PULSES_PER_LITER;

        // Reset pulse count
        pulse_count = 0;

        // Log data to console
        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", current_flow_rate, total_volume);

        // Update LCD
        char lcd_text[LCD_WIDTH + 1];
        snprintf(lcd_text, LCD_WIDTH + 1, "%.2f L/min", current_flow_rate);
        lcd_print(0, lcd_text);
        snprintf(lcd_text, LCD_WIDTH + 1, "%.2f L", total_volume);
        lcd_print(1, lcd_text);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

