#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500

// Global variables
volatile int pulse_count = 0;
int spi_handle;
int i2c_handle;

// Function prototypes
void anemometer_isr(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulse_count, float sample_window_ms);
int read_wind_direction();
void lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);
void signal_handler(int signal);

// Anemometer interrupt handler
void anemometer_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Wind speed calculation
float calculate_wind_speed(int pulse_count, float sample_window_ms)
{
    float frequency = (float)pulse_count / sample_window_ms;
    return frequency * 1.0; // m/s
}

// Wind direction reading
int read_wind_direction()
{
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 configuration: single-ended, channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// LCD initialization
void lcd_init()
{
    // Initialization sequence (PCF8574)
    gpioDelay(15000); // Wait 15ms
    lcd_clear();
    gpioDelay(5000); // Wait 5ms

    // 4-bit initialization
    lcd_print(0, 0, "Initializing...");
    gpioDelay(100000); // Wait 100ms
    lcd_clear();
    gpioDelay(100000); // Wait 100ms

    // 4-bit initialization
    unsigned char init_data[4];
    init_data[0] = 0x33; // Function set: 8-bit interface
    init_data[1] = 0x32; // Function set: 4-bit interface
    init_data[2] = 0x28; // Function set: 2 lines, 5x8 font
    init_data[3] = 0x0C; // Display control: Display on, cursor off, blink off

    for (int i = 0; i < 4; i++) {
        unsigned char data = init_data[i] & 0xF0; // Keep only upper nibble
        i2cWriteByteData(i2c_handle, 0, data | 0x04); // Enable pulse
        i2cWriteByteData(i2c_handle, 0, data & 0x04); // Disable pulse
        gpioDelay(1000); // Wait 1ms
    }

    lcd_clear();
}

// LCD clear
void lcd_clear()
{
    unsigned char data[2];
    data[0] = 0x01; // Clear display command
    i2cWriteByteData(i2c_handle, 0, 0x04); // Enable pulse
    i2cWriteByteData(i2c_handle, 0, 0x00); // Disable pulse
    gpioDelay(2000); // Wait 2ms
}

// LCD print
void lcd_print(int row, int col, const char *text)
{
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    i2cWriteByteData(i2c_handle, 0, 0x04); // Enable pulse
    i2cWriteByteData(i2c_handle, 0, addr);
    i2cWriteByteData(i2c_handle, 0, 0x00); // Disable pulse
    gpioDelay(1000); // Wait 1ms

    for (int i = 0; text[i] != '\0'; i++) {
        i2cWriteByteData(i2c_handle, 0, 0x04); // Enable pulse
        i2cWriteByteData(i2c_handle, 0, text[i]);
        i2cWriteByteData(i2c_handle, 0, 0x00); // Disable pulse
        gpioDelay(1000); // Wait 1ms
    }
}

// Signal handler
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize anemometer interrupt
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read wind direction
        int wind_direction_adc = read_wind_direction();
        if (wind_direction_adc < 0) {
            fprintf(stderr, "Error reading wind direction\n");
            lcd_print(0, 0, "ADC Error");
        } else {
            // Calculate wind speed
            float wind_speed = calculate_wind_speed(pulse_count, SAMPLE_WINDOW_MS);

            // Calculate direction from ADC value
            float direction_degrees = (float)wind_direction_adc / 1023.0 * 360.0;

            // Display data on LCD
            char speed_str[20];
            char direction_str[20];
            snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
            snprintf(direction_str, sizeof(direction_str), "Dir: %.2f deg", direction_degrees);

            lcd_print(0, 0, speed_str);
            lcd_print(1, 0, direction_str);

            // Reset pulse count
            pulse_count = 0;
        }

        gpioDelay(SAMPLE_WINDOW_MS * 1000); // Wait for sample window
    }

    return 0;
}

