    init_data[1] = 0x32; // Function set: 4-bit interface
    init_data[2] = 0x28; // Function set: 2 lines, 5x8 font
    init_data[3] = 0x0C; // Display control: Display on, cursor off, blink off

    for (int i = 0; i < 4; i++) {
        unsigned char data = init_data[i] & 0xF0; // Keep only upper nibble
        i2cWriteByteData(i2c_handle, 0, data | 0x04); // Enable pulse
        i2cWriteByteData(i2c_handle, 0, data & 0x04); // Disable pulse
        gpioDelay(1000); // Wait 1ms
    }

    lcd_clear();
}

// LCD clear
void lcd_clear()
{
    unsigned char data[2];
    data[0] = 0x01; // Clear display command
    i2cWriteByteData(i2c_handle, 0, 0x04); // Enable pulse
    i2cWriteByteData(i2c_handle, 0, 0x00); // Disable pulse
    gpioDelay(2000); // Wait 2ms
}

// LCD print
void lcd_print(int row, int col, const char *text)
{
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    i2cWriteByteData(i2c_handle, 0, 0x04); // Enable pulse
    i2cWriteByteData(i2c_handle, 0, addr);
    i2cWriteByteData(i2c_handle, 0, 0x00); // Disable pulse
    gpioDelay(1000); // Wait 1ms

    for (int i = 0; text[i] != '\0'; i++) {
        i2cWriteByteData(i2c_handle, 0, 0x04); // Enable pulse
        i2cWriteByteData(i2c_handle, 0, text[i]);
        i2cWriteByteData(i2c_handle, 0, 0x00); // Disable pulse
        gpioDelay(1000); // Wait 1ms
    }
}

// Signal handler
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize anemometer interrupt
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read wind direction
        int wind_direction_adc = read_wind_direction();
        if (wind_direction_adc < 0) {
            fprintf(stderr, "Error reading wind direction\n");
            lcd_print(0, 0, "ADC Error");
        } else {
            // Calculate wind speed
            float wind_speed = calculate_wind_speed(pulse_count, SAMPLE_WINDOW_MS);

            // Calculate direction from ADC value
            float direction_degrees = (float)wind_direction_adc / 1023.0 * 360.0;

            // Display data on LCD
            char speed_str[20];
            char direction_str[20];
            snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
            snprintf(direction_str, sizeof(direction_str), "Dir: %.2f deg", direction_degrees);

            lcd_print(0, 0, speed_str);
            lcd_print(1, 0, direction_str);

            // Reset pulse count
            pulse_count = 0;
        }

        gpioDelay(SAMPLE_WINDOW_MS * 1000); // Wait for sample window
    }

    return 0;
}

