            }
        }

        displayFrame(newFrame);
        delay(50); // Adjust delay for animation speed
    }
}

// Function to cleanup GPIO pins
void cleanupGPIO() {
    // Set all row pins to HIGH (turn off LEDs)
    for (int i = 0; i < numRows; i++) {
        digitalWrite(rowPins[i], HIGH);
    }

    // Set all column pins to LOW (turn off LEDs)
    for (int i = 0; i < numCols; i++) {
        digitalWrite(colPins[i], LOW);
    }
}

// Signal handler function
void signalHandler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT. Cleaning up and exiting...\n");
        programRunning = 0; // Set the flag to exit the main loop
    }
}

