// Define GPIO pins
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}

// Define wave parameters
#define WAVE_DURATION 1000 // milliseconds
#define DELAY_MS 150

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nSignal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as output
    int row_pins[] = ROW_PINS;
    for (int i = 0; i < 8; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 0); // Initialize to LOW
    }

    // Set column pins as output
    int col_pins[] = COL_PINS;
    for (int i = 0; i < 8; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1); // Initialize to HIGH (cathode)
    }

    return 0;
}

// Function to create a wave pattern
void create_wave(int row_pins[], int col_pins[]) {
    for (int col = 0; col < 8; col++) {
        // Clear the column
        gpioWrite(col_pins[col], 1);
        gpioDelay(DELAY_MS * 1000); // Delay in microseconds

        // Light up the rows one by one
        for (int row = 0; row < 8; row++) {
            gpioWrite(row_pins[row], 1);
            gpioDelay(DELAY_MS * 1000); // Delay in microseconds
            gpioWrite(row_pins[row], 0);
        }

        gpioDelay(DELAY_MS * 1000); // Delay in microseconds
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    int row_pins[] = ROW_PINS;
    int col_pins[] = COL_PINS;

    // Main loop
    while (!terminate) {
        create_wave(row_pins, col_pins);
    }

    // Cleanup GPIO
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

