// VL53L3CX register addresses (Example - refer to datasheet for complete list)
#define REG_IDENTIFICATION_MODEL_ID 0x0000
#define REG_START_STOP_CONTROL 0x0040
#define REG_RESULT_RANGE_STATUS 0x0050
#define REG_RESULT_SPAD_NB_DETECTED 0x0051
#define REG_RESULT_SIGNAL_RATE 0x0052
#define REG_RESULT_AMBIENT_RATE 0x0054
#define REG_RESULT_DISTANCE 0x005E

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance[NUM_TARGETS];
} SensorData;

// Function prototypes
int init_vl53l3cx();
int read_sensor_data(SensorData *data);
void print_sensor_data(const SensorData *data);
void signal_handler(int signal);

