void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the VL53L3CX sensor
int init_vl53l3cx() {
    // Check sensor model ID (Example - refer to datasheet for correct value)
    int model_id = i2cReadByteData(i2c_handle, REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
