    printf("VL53L3CX model ID: 0x%04X\n", model_id);

    // Stub for proprietary initialization sequence (replace with actual sequence)
    // This is a placeholder and needs to be replaced with the actual initialization sequence
    // as described in the VL53L3CX datasheet.
    // Example: Write a specific value to a register to enable the sensor.
    // Example: i2cWriteByteData(i2c_handle, 0x0010, 0x01); // Example register and value

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, REG_START_STOP_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }

    return 0;
}

