#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A

// Define the register address for distance data (replace with actual address)
#define DISTANCE_REG 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C interface
int init_i2c(int bus, int addr) {
    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance data from the sensor
int read_distance(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit integer (adjust endianness if needed)
    int16_t distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Function to log data to a file
int log_data(FILE *file, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(file, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(I2C_BUS, MLX75031_ADDR) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, attempting to re-initialize I2C\n");
            i2cClose(i2c_handle);
            if (init_i2c(I2C_BUS, MLX75031_ADDR) != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                terminate = 1; // Exit the loop if re-initialization fails
            }
        }

        gpioDelay(100); // Sample every 100 milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

