#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_PIN 7
#define LED_PIN 11
#define LOG_FILE "proximity.log"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to log the detection event
int log_detection() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s Object detected\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(100);        // Wait 100ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Object detected (LOW signal)
            if (log_detection() == 0) {
                blink_led();
            } else {
                fprintf(stderr, "Error logging detection!\n");
            }
            gpioDelay(100); // Debounce delay
        } else {
            gpioDelay(10); // Check every 10ms
        }
    }

    // Cleanup GPIO
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");
    return 0;
}

