FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
void log_data(double distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // Wait 1ms

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_DURATION) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_DURATION) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_DURATION) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_DURATION) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and 2 for the round trip
}

// Log the distance data to a file
void log_data(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance >= 0) {
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "%s - ERROR: Distance out of range (%.2f cm)\n", timestamp, distance);
        } else {
            fprintf(log_file, "%s - Distance: %.2f cm\n", timestamp, distance);
            if (distance < 15.0) {
                fprintf(log_file, "%s - Time to water the plant!\n", timestamp);
            }
        }
    } else {
        fprintf(log_file, "%s - ERROR: Sensor timeout\n", timestamp);
    }
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();
        double distance = calculate_distance(pulse_width);
        log_data(distance);
        gpioDelay(60000); // Wait 60 seconds
    }

    cleanup();
    return 0;
}

