#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROX_DATA_REG 0x0A // Example register address for proximity data
#define BPM_THRESHOLD 50
#define CSV_FILENAME "heartrate.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int read_proximity_data(int *proximity);
float calculate_bpm(int proximity);
char* get_iso8601_timestamp();
int write_to_csv(char *timestamp, float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read proximity data from the sensor
int read_proximity_data(int *proximity) {
    int result = i2cReadWordData(i2c_handle, PROX_DATA_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    *proximity = result;
    return 0;
}

// Calculate beats per minute (BPM) from proximity data
float calculate_bpm(int proximity) {
    // Simple threshold-based BPM calculation
    if (proximity > BPM_THRESHOLD) {
        return 120.0; // Peak BPM
    } else {
        return 60.0;  // Low BPM
    }
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Write timestamp and BPM to CSV file
int write_to_csv(char *timestamp, float bpm) {
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, bpm);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int proximity;
    char *timestamp;
    float bpm;

    // Main loop
    while (running) {
        // Read proximity data
        if (read_proximity_data(&proximity) == 0) {
            // Calculate BPM
            bpm = calculate_bpm(proximity);

            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Write to CSV file
            if (write_to_csv(timestamp, bpm) != 0) {
                fprintf(stderr, "Error writing to CSV file!\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Skipping sample due to read error.\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

