#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define constants
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define TIMEOUT_MS 100
#define LOG_FILE "distance_log.txt"

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int verify_sensor_presence(int fd);
int configure_gpio(int pin);
int read_distance(int fd);
int log_distance(FILE *fp, int distance);
void signal_handler(int signal);

// Function to verify sensor presence
int verify_sensor_presence(int fd) {
    int sensor_id;
    // Read the sensor ID register (0xC0)
    sensor_id = wiringPiI2CReadReg8(fd, 0xC0);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }

    // Check if the sensor ID is 0xEE (expected for VL53L0X)
    if (sensor_id != 0xEE) {
        fprintf(stderr, "Sensor not found. Expected 0xEE, got 0x%02X\n", sensor_id);
        return -1;
    }

    printf("VL53L0X sensor found!\n");
    return 0;
}

// Function to configure GPIO pin
int configure_gpio(int pin) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(pin, INPUT);
    pullUpDnControl(pin, PUD_UP);

    printf("GPIO pin %d configured as input with pull-up resistor.\n", pin);
    return 0;
}

// Function to read distance from VL53L0X
int read_distance(int fd) {
    int distance = -1; // Initialize to -1 to indicate error
    int timeout_counter = 0;

    // Start a single measurement
    if (wiringPiI2CWriteReg8(fd, 0x00, 0x01) < 0) {
        fprintf(stderr, "Error starting measurement: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the interrupt to be set (polling with timeout)
    while (digitalRead(GPIO_PIN) == HIGH) {
        delay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
        if (timeout_counter > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for interrupt.\n");
            return -1;
        }
    }

    // Read the distance from the result registers (0x14-0x15)
    int msb = wiringPiI2CReadReg8(fd, 0x14);
    int lsb = wiringPiI2CReadReg8(fd, 0x15);

    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    distance = (msb << 8) | lsb;

    // Clear the interrupt by writing 0x04 to 0x00
    if (wiringPiI2CWriteReg8(fd, 0x00, 0x04) < 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

