    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = wiringPiI2CSetup(VL53L0X_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Verify sensor presence
    if (verify_sensor_presence(i2c_fd) != 0) {
        fprintf(stderr, "Sensor verification failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Configure GPIO pin
    if (configure_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO configuration failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Starting distance measurement loop...\n");

    // Main loop
    while (program_running) {
        // Wait for falling edge on GPIO pin
        while (digitalRead(GPIO_PIN) == HIGH) {
            delay(1); // Small delay to avoid busy-waiting
        }

        // Read distance
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            // Log distance
            if (log_distance(log_file, distance) != 0) {
                fprintf(stderr, "Error logging distance.\n");
            }
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        // Wait for a short period before next measurement
        delay(50); // 50ms delay
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program finished.\n");
    return 0;
}

