#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x70
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define CONFIG_REG 0x02
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_MS 200
#define TRIGGER_DELAY_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int trigger_measurement();
int read_distance(uint16_t *distance);
int log_distance(uint16_t distance);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t range_config;
    uint8_t timing_config;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the CH101 sensor
int init_sensor() {
    // Example configuration: Set range to 100cm and timing to 100ms
    sensor_config_t config = { .range_config = 0x0A, .timing_config = 0x06 };

    // Write configuration to the sensor
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = config.range_config;
    buf[2] = config.timing_config;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }

    return 0;
}

// Trigger a distance measurement
int trigger_measurement() {
    char buf[1];
    buf[0] = 0x01; // Trigger measurement

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }

    return 0;
}

// Read the distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[1];
    char read_buf[2];

    // Write the register address to read from
    buf[0] = DISTANCE_REG;
    int write_result = i2cWriteDevice(i2c_handle, buf, 1);
    if (write_result != 0) {
        fprintf(stderr, "Failed to write register address: %d\n", write_result);
        return -1;
    }

    // Read two bytes from the distance register
    int read_result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (read_result != 2) {
        fprintf(stderr, "Failed to read distance: %d\n", read_result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (read_buf[0] << 8) | read_buf[1];

    return 0;
}

// Log the distance to a file
int log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d\n", timestamp, distance);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t distance;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(TRIGGER_DELAY_MS); // Wait for measurement

        // Read distance
        if (read_distance(&distance) != 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log distance
        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next sample
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

