            fprintf(stderr, "Error logging distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next sample
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

