#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define SAMPLE_INTERVAL 100 // ms

// ICU-20201 Registers (Example - Refer to datasheet for correct values)
#define ICU20201_REG_WHO_AM_I 0x00
#define ICU20201_REG_DISTANCE_MSB 0x01
#define ICU20201_REG_DISTANCE_LSB 0x02
#define ICU20201_REG_CONFIG 0x03

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int read_distance(float *distance);
void control_led(int on);
int log_data(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor ID (Example - Refer to datasheet for correct value)
    int sensor_id = i2cReadByteData(i2c_handle, ICU20201_REG_WHO_AM_I);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        i2cClose(i2c_handle);
        return -1;
    }
    if (sensor_id != 0x41) { // Expected value for ICU-20201
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure sensor (Example - Refer to datasheet for correct values)
    if (i2cWriteByteData(i2c_handle, ICU20201_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error configuring sensor\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// GPIO initialization
int initialize_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Read distance from sensor
int read_distance(float *distance) {
    int msb, lsb;

    msb = i2cReadByteData(i2c_handle, ICU20201_REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB\n");
        return -1;
    }

    lsb = i2cReadByteData(i2c_handle, ICU20201_REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB\n");
        return -1;
    }

    // Combine MSB and LSB to get the distance in cm (Example - Refer to datasheet for correct conversion)
    *distance = (float)((msb << 8) | lsb) / 10.0; // Example conversion

    return 0;
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log data to file
int log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }

            if (log_data(distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

