#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_PS1_DATA0 0x18
#define SI1182_REG_MEAS_RATE0 0x08
#define SI1182_REG_ALS_RATE 0x0A
#define SI1182_REG_PS_RATE 0x0C
#define SI1182_REG_PS_LED21_SELECT 0x0F
#define SI1182_REG_PS_ENCODING 0x10
#define SI1182_REG_PS_ADC_GAIN 0x11
#define SI1182_REG_ALS_ADC_GAIN 0x12
#define SI1182_REG_PS_ADC_MISC 0x13
#define SI1182_REG_ALS_ADC_MISC 0x14
#define SI1182_REG_PS_LED_DRIVE 0x15
#define SI1182_REG_ALS_LED_DRIVE 0x16
#define SI1182_REG_PS_MEAS_RATE 0x17
#define SI1182_REG_ALS_MEAS_RATE 0x18
#define SI1182_REG_INT_CFG 0x03
#define SI1182_REG_IRQ_ENABLE 0x04
#define SI1182_REG_IRQ_MODE1 0x05
#define SI1182_REG_IRQ_MODE2 0x06
#define SI1182_REG_HW_KEY 0x07
#define SI1182_REG_MEAS_CTRL 0x09
#define SI1182_REG_PS_LED123_SELECT 0x0E
#define SI1182_REG_PS_LED_SELECT 0x0F
#define SI1182_REG_PS_ENCODING 0x10
#define SI1182_REG_PS_ADC_GAIN 0x11
#define SI1182_REG_ALS_ADC_GAIN 0x12
#define SI1182_REG_PS_ADC_MISC 0x13
#define SI1182_REG_ALS_ADC_MISC 0x14
#define SI1182_REG_PS_LED_DRIVE 0x15
#define SI1182_REG_ALS_LED_DRIVE 0x16
#define SI1182_REG_PS_MEAS_RATE 0x17
#define SI1182_REG_ALS_MEAS_RATE 0x18
#define SI1182_REG_INT_CFG 0x03
#define SI1182_REG_IRQ_ENABLE 0x04
#define SI1182_REG_IRQ_MODE1 0x05
#define SI1182_REG_IRQ_MODE2 0x06
#define SI1182_REG_HW_KEY 0x07
#define SI1182_REG_MEAS_CTRL 0x09

#define SI1182_HW_KEY_VALUE 0x17
#define SI1182_RESET_CMD 0x01

#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1182();
int read_sensor_data(int *proximity, int *ambient_light);
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1182 sensor
int init_si1182() {
    int status;
    int retries = 0;

    // Reset the sensor
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_HW_KEY, SI1182_HW_KEY_VALUE);
        if (status >= 0) break; // Success
        gpioDelay(1000); // Wait 1ms before retrying
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write HW_KEY register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_RESET_CMD, 0x00);
        if (status >= 0) break; // Success
        gpioDelay(1000); // Wait 1ms before retrying
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write RESET_CMD register after multiple retries.\n");
        return -1;
    }

    gpioDelay(10000); // Wait for reset to complete

    // Configure sensor parameters (example configuration)
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_MEAS_RATE0, 0x0A); // 100ms measurement rate
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0 register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_PS_RATE, 0x0A); // 100ms proximity rate
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write PS_RATE register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_ALS_RATE, 0x0A); // 100ms ALS rate
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write ALS_RATE register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_PS_LED_DRIVE, 0x03); // LED drive strength
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write PS_LED_DRIVE register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_ALS_LED_DRIVE, 0x03); // ALS LED drive strength
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write ALS_LED_DRIVE register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_PS_ADC_GAIN, 0x05); // Proximity ADC gain
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write PS_ADC_GAIN register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_ALS_ADC_GAIN, 0x05); // ALS ADC gain
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write ALS_ADC_GAIN register after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, SI1182_REG_MEAS_CTRL, 0x07); // Enable ALS and PS
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to write MEAS_CTRL register after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    int status;
    int retries = 0;
    uint8_t data[4];

    // Read proximity data
    while (retries < RETRY_COUNT) {
        status = i2cReadI2CBlockData(i2c_handle, SI1182_REG_PS1_DATA0, (char *)data, 2);
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to read proximity data after multiple retries.\n");
        return -1;
    }
    *proximity = (data[1] << 8) | data[0];

    // Read ambient light data
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cReadI2CBlockData(i2c_handle, SI1182_REG_ALS_VIS_DATA0, (char *)data, 2);
        if (status >= 0) break;
        gpioDelay(1000);
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to read ambient light data after multiple retries.\n");
        return -1;
    }
    *ambient_light = (data[1] << 8) | data[0];

    return 0;
}

// Function to log data to a file
int log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

