#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L0X_REG_SYSRANGE_START 0x000

// Expected model ID
#define VL53L0X_MODEL_ID 0xEACC

// I2C handle
int i2c_handle;

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x(int handle) {
    uint8_t model_id;

    // Check model ID
    if (read_register(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X, expected 0x%02X)\n", model_id, VL53L0X_MODEL_ID);
        return -1;
    }

    // Start continuous ranging
    if (write_register(handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance(int handle, int *distance) {
    uint8_t range_status;
    uint8_t range_data[2];

    // Read range status
    if (read_register(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance data (2 bytes)
    if (i2cReadI2CBlockData(handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)range_data, 2) != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    *distance = (range_data[0] << 8) | range_data[1];

    return 0;
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int distance;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print distance
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

