#include <time.h>
#include <signal.h>
#include <unistd.h>

// OPT3101 I2C address
#define OPT3101_ADDR 0x64

// Register addresses (Example - adjust based on datasheet)
#define REG_CH0_DISTANCE 0x00
#define REG_AMBIENT_LIGHT 0x02
#define REG_ERROR_FLAGS 0x04

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a register from the OPT3101
int read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a register to the OPT3101
int write_register(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the OPT3101
int init_opt3101(int handle) {
    // Example initialization sequence (adjust based on datasheet)
    if (write_register(handle, 0x01, 0x01) < 0) return -1; // Example register write
    gpioDelay(1000); // Delay for 1ms
    if (write_register(handle, 0x02, 0x02) < 0) return -1; // Example register write
    gpioDelay(1000); // Delay for 1ms
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3101
    if (init_opt3101(i2c_handle) < 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[4]; // Buffer to hold sensor data
        uint16_t distance;
        uint16_t ambient_light;
        uint16_t error_flags;

        // Read distance from channel 0
        if (read_register(i2c_handle, REG_CH0_DISTANCE, data, 2) < 0) {
            fprintf(stderr, "Error reading distance data\n");
        } else {
            distance = (data[0] << 8) | data[1];
        }

        // Read ambient light value
        if (read_register(i2c_handle, REG_AMBIENT_LIGHT, data, 2) < 0) {
            fprintf(stderr, "Error reading ambient light data\n");
        } else {
            ambient_light = (data[0] << 8) | data[1];
        }

        // Read error flags
        if (read_register(i2c_handle, REG_ERROR_FLAGS, data, 2) < 0) {
            fprintf(stderr, "Error reading error flags\n");
        } else {
            error_flags = (data[0] << 8) | data[1];
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Log data to console
        printf("%s - Distance: %u mm, Ambient Light: %u, Error Flags: 0x%04X\n", buf, distance, ambient_light, error_flags);

        gpioDelay(500000); // Wait 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

