#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MAX_PULSE_DURATION 38000 // Maximum pulse duration in microseconds (38ms)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 2; // Indicate that falling edge has been received
    }
}

// Calculate distance function
double calculate_distance(int pulse_duration) {
    if (pulse_duration <= 0) {
        return -1.0; // Indicate invalid pulse duration
    }
    if (pulse_duration > MAX_PULSE_DURATION) {
        return -2.0; // Indicate timeout
    }
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Convert microseconds to seconds
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for ECHO_PIN
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for a short period to allow the sensor to receive the echo
        gpioDelay(50); // 50 milliseconds

        // Calculate the pulse duration
        int pulse_duration = echo_end_tick - echo_start_tick;

        // Reset echo flags
        echo_received = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;

        // Calculate the distance
        double distance = calculate_distance(pulse_duration);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the data
        if (distance >= 0) {
            printf("%s Distance: %.2f cm\n", timestamp, distance);
        } else if (distance == -1.0) {
            fprintf(stderr, "%s Error: Invalid pulse duration (%d us)\n", timestamp, pulse_duration);
        } else if (distance == -2.0) {
            fprintf(stderr, "%s Error: Timeout waiting for echo\n", timestamp);
        } else {
            fprintf(stderr, "%s Error: Unknown error\n", timestamp);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

