#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define NUM_BINS 64
#define DISTANCE_THRESHOLD 1.0 // meters
#define ALERT_LED_GPIO 17
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Magic word header
const unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int max_size);
int validate_magic_word(const unsigned char *buffer, const unsigned char *magic_word, int size);
int decode_range_profile(const unsigned char *buffer, short *range_profile, int size);
int detect_target(const short *range_profile, int size, float threshold);
int log_intrusion(const char *timestamp, float distance);
int activate_alert_led(int gpio_pin, int duration_ms);
void signal_handler(int signal);
void cleanup();

// Function to initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from UART
int read_uart_data(int fd, unsigned char *buffer, int max_size) {
    ssize_t bytes_read = read(fd, buffer, max_size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    }
    return (int)bytes_read;
}

// Function to validate magic word
int validate_magic_word(const unsigned char *buffer, const unsigned char *magic_word, int size) {
    return memcmp(buffer, magic_word, size) == 0;
}

// Function to decode range profile
int decode_range_profile(const unsigned char *buffer, short *range_profile, int size) {
    if (size != RANGE_PROFILE_SIZE) {
        fprintf(stderr, "Error: Invalid range profile size (%d bytes, expected %d bytes)\n", size, RANGE_PROFILE_SIZE);
        return -1;
    }

    for (int i = 0; i < NUM_BINS; i++) {
        range_profile[i] = (short)((buffer[2 * i + 1] << 8) | buffer[2 * i]); // Little-endian
    }
    return 0;
}

// Function to detect target
int detect_target(const short *range_profile, int size, float threshold) {
    for (int i = 0; i < size; i++) {
        if (range_profile[i] < (short)(threshold * 1000)) { // Convert meters to mm
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Function to log intrusion
int log_intrusion(const char *timestamp, float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to activate alert LED
int activate_alert_led(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(gpio_pin, 0); // Turn LED off
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    program_running = 0;
}

// Cleanup function
