    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(gpio_pin, 0); // Turn LED off
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
