#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x64
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define LOG_FILE "distance_log.txt"
#define SLEEP_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_distance(float *distance);
int log_distance(float distance);
int check_distance_threshold(float distance);
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int integration_time;
    int range;
} sensor_config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(float *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buffer[2]; // Example buffer to store the distance data
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Small delay for the sensor to perform the measurement

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert the raw data to a distance in centimeters (example)
    int raw_distance = (buffer[0] << 8) | buffer[1];
    *distance = (float)raw_distance / 10.0; // Example conversion

    return 0;
}

// Function to log the distance to a file
int log_distance(float distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to check if the distance is below the threshold
int check_distance_threshold(float distance) {
    return (distance < DISTANCE_THRESHOLD) ? 1 : 0;
}

// Function to trigger the alert (set GPIO HIGH)
void trigger_alert() {
    gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW
    gpioSetMode(ALERT_GPIO, PI_INPUT); // Set GPIO to input mode
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set GPIO mode for alert
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error logging distance.\n");
            }

            if (check_distance_threshold(distance)) {
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(SLEEP_MS); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

