#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x40
#define LED_GPIO 18
#define BLINK_FREQ_MIN 0.1  // Hz
#define BLINK_FREQ_MAX 10.0 // Hz
#define BLINK_PERIOD_US 500000 // 0.5 seconds
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
float calculate_blink_frequency(uint16_t distance);
void control_led(float blink_frequency);
void log_data(uint16_t distance, float blink_frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201
int read_distance(uint16_t *distance) {
    char buf[2];
    int retries = 3;

    while (retries > 0) {
        int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", bytes_read, retries);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Calculate blink frequency based on distance
float calculate_blink_frequency(uint16_t distance) {
    // Map distance (0-4000mm) to blink frequency (0.1-10Hz)
    float blink_frequency = BLINK_FREQ_MIN + (float)distance / 4000.0 * (BLINK_FREQ_MAX - BLINK_FREQ_MIN);
    if (blink_frequency < BLINK_FREQ_MIN) blink_frequency = BLINK_FREQ_MIN;
    if (blink_frequency > BLINK_FREQ_MAX) blink_frequency = BLINK_FREQ_MAX;
    return blink_frequency;
}

// Control LED blinking
void control_led(float blink_frequency) {
    if (blink_frequency <= 0.0) {
        gpioWrite(LED_GPIO, 0); // Turn off LED
        return;
    }

    // Calculate on and off times based on frequency
    uint32_t on_time_us = (uint32_t)(BLINK_PERIOD_US / (2.0 * blink_frequency));
    uint32_t off_time_us = BLINK_PERIOD_US - on_time_us;

    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(on_time_us);

    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioDelay(off_time_us);
}

// Log data to stdout
void log_data(uint16_t distance, float blink_frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %u mm, Blink Frequency: %.2f Hz\n", timestamp, distance, blink_frequency);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;
    float blink_frequency;

    printf("Starting distance measurement...\n");

    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Calculate blink frequency
            blink_frequency = calculate_blink_frequency(distance);

            // Control LED
            control_led(blink_frequency);

            // Log data
            log_data(distance, blink_frequency);
        } else {
            fprintf(stderr, "Failed to read distance, skipping logging.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

