    int mlx75030_address;
    int measure_command;
    int measure_delay_us;
    int sample_interval_ms;
    int max_retries;
    int retry_delay_ms;
    char *csv_filename;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_distance(int handle);
int log_data(FILE *fp, time_t timestamp, int distance_cm);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read distance from sensor
int read_distance(int handle) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        result = i2cWriteByteData(handle, MEASURE_CMD, 0); // No data to write, just command
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(MEASURE_DELAY_US); // Delay after command

        // Read distance data
        char buffer[2];
        result = i2cReadI2CBlockData(handle, 0, buffer, 2); // Read 2 bytes from register 0
        if (result < 0) {
            fprintf(stderr, "Error reading from I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert to distance (example, adjust based on datasheet)
        int distance_cm = (buffer[0] << 8) | buffer[1];
        return distance_cm;
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Log data to CSV file
int log_data(FILE *fp, time_t timestamp, int distance_cm) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp_str, distance_cm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .mlx75030_address = MLX75030_ADDR,
        .measure_command = MEASURE_CMD,
        .measure_delay_us = MEASURE_DELAY_US,
        .sample_interval_ms = SAMPLE_INTERVAL_MS,
        .max_retries = MAX_RETRIES,
        .retry_delay_ms = RETRY_DELAY_MS,
        .csv_filename = CSV_FILENAME
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.mlx75030_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.csv_filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int distance_cm = read_distance(i2c_handle);
        if (distance_cm >= 0) {
            // Get timestamp
            time_t now = time(NULL);

            // Log data
            if (log_data(log_file, now, distance_cm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait for next sample
        gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

