#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define LOG_FILE "proximity_log.txt"

// Structure to hold sensor state and last transition time
typedef struct {
    int gpio;
    int state;
    long long last_transition_time;
} sensor_t;

// Global variables
FILE *log_file = NULL;
sensor_t sensor1, sensor2;

// Function prototypes
int initialize_gpio();
int read_sensor(sensor_t *sensor);
int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the pigpio library and sets the GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Initialize sensor structures
    sensor1.gpio = SENSOR_1_GPIO;
    sensor1.state = gpioRead(SENSOR_1_GPIO);
    sensor1.last_transition_time = 0;

    sensor2.gpio = SENSOR_2_GPIO;
    sensor2.state = gpioRead(SENSOR_2_GPIO);
    sensor2.last_transition_time = 0;

    return 0;
}

// Reads the sensor value and applies debouncing
int read_sensor(sensor_t *sensor) {
    int new_state = gpioRead(sensor->gpio);
    long long current_time = gpioTick();

    if (new_state != sensor->state) {
        if (current_time - sensor->last_transition_time > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
            sensor->state = new_state;
            sensor->last_transition_time = current_time;
            return 1; // State changed
        }
    }
    return 0; // State unchanged
}

// Logs the event to the file
int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_sensor(&sensor1)) {
            if (sensor1.state == 0) { // Obstacle detected
                log_event(1, "DETECTED");
            } else { // Obstacle cleared
                log_event(1, "CLEARED");
            }
        }

        if (read_sensor(&sensor2)) {
            if (sensor2.state == 0) { // Obstacle detected
                log_event(2, "DETECTED");
            } else { // Obstacle cleared
                log_event(2, "CLEARED");
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

