#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_MSB_REG 0x01
#define DISTANCE_LSB_REG 0x02
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave_address(int fd, int addr);
int i2c_write_read(int fd, unsigned char *write_data, int write_len, unsigned char *read_data, int read_len);
int read_distance(int fd, int *distance_mm);
int log_data(FILE *fp, const char *timestamp, int distance_mm);
void signal_handler(int sig);
char* get_iso8601_timestamp();

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write-read function
int i2c_write_read(int fd, unsigned char *write_data, int write_len, unsigned char *read_data, int read_len) {
    if (write(fd, write_data, write_len) != write_len) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, read_data, read_len) != read_len) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read distance function
int read_distance(int fd, int *distance_mm) {
    unsigned char write_data[1] = {MEAS_STATUS_REG};
    unsigned char read_data[2];
    int status;
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = TIMEOUT_MS * 1000000; // Timeout in nanoseconds

    // Poll MEAS_STATUS register
    while (1) {
        if (i2c_write_read(fd, write_data, 1, read_data, 1) < 0) {
            return -1;
        }

        status = read_data[0] & 0x01; // Check bit 0 for measurement ready

        if (status) {
            break; // Measurement ready
        }

        if (nanosleep(&req, &rem) < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, continue polling
                continue;
            }
            fprintf(stderr, "Error in nanosleep: %s\n", strerror(errno));
            return -1;
        }
    }

    // Read distance data
    write_data[0] = DISTANCE_MSB_REG;
    if (i2c_write_read(fd, write_data, 1, read_data, 2) < 0) {
        return -1;
    }

    *distance_mm = (read_data[0] << 8) | read_data[1];

    return 0;
}

// Log data function
int log_data(FILE *fp, const char *timestamp, int distance_mm) {
    if (fprintf(fp, "%s,%d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    int distance_mm;
    char *timestamp;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set slave address
    if (i2c_set_slave_address(i2c_fd, CH101_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(i2c_fd, &distance_mm) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(csv_file, timestamp, distance_mm) != 0) {
                fprintf(stderr, "Error logging data, but continuing...\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error reading distance, but continuing...\n");
        }

        // Wait for the next sample
        struct timespec req, rem;
        req.tv_sec = 0;
        req.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // Sample interval in nanoseconds
        nanosleep(&req, &rem);
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

