int i2c_read_bytes(int fd, uint16_t reg, uint8_t *data, int len) {
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, 2) != 2) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint16_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    memcpy(buf + 2, data, len);

    if (write(fd, buf, len + 2) != len + 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// VL53L5CX initialization function
