        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500 * 1000 * 1000; // 500ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

