#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A

// Define the register address for distance reading (replace with actual address)
#define DISTANCE_REG 0x00

// Global variables for graceful shutdown
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle, int *distance) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (result >= 0) {
            *distance = result; // Assuming distance is a 16-bit value
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance;
        time_t current_time;
        struct tm *time_info;
        char time_string[20];

        // Read distance
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

            // Log the data
            printf("%s Distance: %d\n", time_string, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

