#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L4CX_REG_SYSTEM_START 0x000D
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L4CX_REG_INTERRUPT_CONFIG_GPIO_CONTROL 0x001E
#define VL53L4CX_REG_INTERRUPT_CLEAR 0x0015
#define VL53L4CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l4cx_init(int i2c_handle);
int vl53l4cx_read_distance(int i2c_handle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// VL53L4CX initialization function
int vl53l4cx_init(int i2c_handle) {
    int status;
    uint8_t data;

    // Check device ID
    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, (char *)&data, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", status);
        return -1;
    }
    if (data != 0xEA) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", data);
        return -1;
    }

    // Set I2C slave address
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L4CX_ADDR);
    if (status < 0) {
        fprintf(stderr, "Error setting I2C slave address: %d\n", status);
        return -1;
    }

    // Configure interrupt GPIO
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_CONFIG_GPIO_CONTROL, 0x01); // Enable interrupt on new sample
    if (status < 0) {
        fprintf(stderr, "Error configuring interrupt GPIO: %d\n", status);
        return -1;
    }

    // Start the sensor
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_SYSTEM_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting sensor: %d\n", status);
        return -1;
    }

    return 0;
}

// VL53L4CX read distance function
int vl53l4cx_read_distance(int i2c_handle) {
    int status;
    uint8_t data[2];
    int distance;

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", status);
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

int main() {
    int distance;
    struct timespec ts;
    char timestamp[30];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Poll interrupt status
        uint8_t interrupt_status;
        int status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS, (char *)&interrupt_status, 1);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            continue; // Continue to the next cycle
        }

        // Check if new measurement is ready
        if ((interrupt_status & 0x01) == 0) {
            // Read distance
            distance = vl53l4cx_read_distance(i2c_handle);
            if (distance >= 0) {
                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    // Format timestamp
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

                    // Log data
                    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
                } else {
                    fprintf(stderr, "Error getting timestamp\n");
                }

                // Clear interrupt
                status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_CLEAR, 0x01);
                if (status < 0) {
                    fprintf(stderr, "Error clearing interrupt: %d\n", status);
                }
            } else {
                fprintf(stderr, "Error reading distance\n");
            }
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

