#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000        // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_DURATION 500    // ms

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, unsigned int tick);
float calculateDistance(unsigned int pulse_width);
void activateBuzzer();
void deactivateBuzzer();
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo started
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Indicate that echo ended
    }
}

// Function to calculate distance from pulse width
float calculateDistance(unsigned int pulse_width) {
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2
    return distance;
}

// Function to activate the buzzer
void activateBuzzer() {
    gpioWrite(BUZZER_PIN, 1);
}

// Function to deactivate the buzzer
void deactivateBuzzer() {
    gpioWrite(BUZZER_PIN, 0);
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    deactivateBuzzer();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        triggerSensor();

        // Wait for echo or timeout
        int count = 0;
        while (!echo_received && count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1 us
            count++;
        }

        if (echo_received) {
            unsigned int pulse_width = end_tick - start_tick;
            float distance = calculateDistance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                printf("Distance: %.2f cm\n", distance);

                if (distance < 30.0) {
                    activateBuzzer();
                } else {
                    deactivateBuzzer();
                }
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

