#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define TRIG_PIN 23
#define ECHO_PIN 24
#define SAMPLING_INTERVAL_MS 200
#define TIMEOUT_US 60000 // 60ms
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width_us);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0) {
        if (echo_received) {
            falling_tick = tick;
            echo_received = 0; // Reset flag
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width_us) {
    return (pulse_width_us * 0.0343) / 2.0;
}

// Function to log distance to stdout and file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for ECHO_PIN
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(SAMPLING_INTERVAL_MS); // Wait for sampling interval

        uint32_t pulse_width_us = falling_tick - rising_tick;

        if (pulse_width_us >= MIN_PULSE_WIDTH_US && pulse_width_us <= MAX_PULSE_WIDTH_US) {
            double distance = calculate_distance(pulse_width_us);
            log_distance(distance);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            if (pulse_width_us < MIN_PULSE_WIDTH_US) {
                fprintf(stderr, "%s WARNING: Pulse width too short (%u us)\n", timestamp, pulse_width_us);
                if (log_file != NULL) {
                    fprintf(log_file, "%s WARNING: Pulse width too short (%u us)\n", timestamp, pulse_width_us);
                    fflush(log_file);
                }
            } else {
                fprintf(stderr, "%s WARNING: Pulse width too long (%u us)\n", timestamp, pulse_width_us);
                if (log_file != NULL) {
                    fprintf(log_file, "%s WARNING: Pulse width too long (%u us)\n", timestamp, pulse_width_us);
                    fflush(log_file);
                }
            }
        }

        // Check for timeout
        if (gpioTick() - rising_tick > TIMEOUT_US) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(stderr, "%s TIMEOUT: No echo received within timeout period\n", timestamp);
            if (log_file != NULL) {
                fprintf(log_file, "%s TIMEOUT: No echo received within timeout period\n", timestamp);
                fflush(log_file);
            }
        }
    }

    // Cleanup
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

