{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading register value\n");
        return -1;
    }
    return 0;
}

