#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_OPEN 50  // cm
#define DISTANCE_THRESHOLD_CLOSE 60 // cm
#define SERVO_OPEN_PULSE_WIDTH 1500  // us
#define SERVO_CLOSE_PULSE_WIDTH 1000 // us
#define LOG_FILE "parking_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_servo(int open);
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to read a single byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading register value\n");
        return -1;
    }
    return 0;
}

// Function to write a single byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register value\n");
        return -1;
    }
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0)
    {
        fprintf(stderr, "VL53L1X initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        int distance = read_distance();

        if (distance >= 0)
        {
            if (distance < DISTANCE_THRESHOLD_OPEN)
            {
                control_servo(1); // Open gate
                log_event("Gate Open", distance);
            }
            else if (distance > DISTANCE_THRESHOLD_CLOSE)
            {
                control_servo(0); // Close gate
                log_event("Gate Closed", distance);
            }
        }
        else
        {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Cleanup
    control_servo(0); // Ensure gate is closed on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

