    // Example: Write to a specific register to initialize the sensor
    char init_data[] = {0x00, 0x01}; // Example initialization data
    if (i2cWriteDevice(i2c_handle, init_data, 2) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        return -1;
    }

    // Add more initialization steps as needed

    return 0;
}

// VL53L1X Distance Reading Function
int vl53l1x_read_distance(int i2c_handle) {
    // Implement VL53L1X distance reading sequence here
    // This is a placeholder - replace with actual reading code
    // Refer to the VL53L1X datasheet for the correct reading sequence
    // Example: Write to a register to start ranging, then read the distance
    char start_ranging[] = {VL53L1X_REG_SYSRANGE_START, 0x01};
    char range_status[2];
    int distance = -1; // Default to -1 to indicate error

    if (i2cWriteDevice(i2c_handle, start_ranging, 2) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10000); // 10ms

    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)&distance, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    // Byte swap if needed (VL53L1X returns big-endian)
    distance = (distance >> 8) | (distance << 8);

    return distance;
}

