    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_GATE_OPEN, 1);
        gpioWrite(GPIO_GATE_CLOSE, 0);
        log_event("Gate OPEN");
    } else {
        gpioWrite(GPIO_GATE_OPEN, 0);
        gpioWrite(GPIO_GATE_CLOSE, 1);
        log_event("Gate CLOSE");
    }
}

// Logging Function
