#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_THRESHOLD_CLOSE 100 // mm
#define DISTANCE_THRESHOLD_FAR 300   // mm
#define GPIO_INTERRUPT_PIN 24
#define MAX_RETRIES 3
#define MAX_DELAY_MS 100

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile int distance_ready = 0;
volatile int distance = 0;
volatile int motor_state = 0; // 0: stopped, 1: forward, -1: backward

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void motor_control(int distance);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// VL53L1X Initialization Sequence (Example - Adjust based on datasheet)
int vl53l1x_init() {
    uint8_t data[2];
    int status;

    // Soft reset (example)
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Value to write
    status = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (status != 0) {
        fprintf(stderr, "Error: Soft reset write failed (status %d)\n", status);
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    // Start measurement (example)
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01;
    status = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (status != 0) {
        fprintf(stderr, "Error: Start measurement write failed (status %d)\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X Distance Reading Function
int vl53l1x_read_distance(int *distance) {
    uint8_t data[1];
    uint8_t result[2];
    int status;
    int retries = 0;
    int delay_ms = 1;

    // Poll status register until data ready
    while (!distance_ready && retries < MAX_RETRIES) {
        data[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
        status = i2cWriteDevice(i2c_handle, (char *)data, 1);
        if (status != 0) {
            fprintf(stderr, "Error: Writing to status register failed (status %d)\n", status);
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            if (delay_ms > MAX_DELAY_MS) delay_ms = MAX_DELAY_MS;
            retries++;
            continue;
        }

        status = i2cReadDevice(i2c_handle, (char *)result, 2);
        if (status != 0) {
            fprintf(stderr, "Error: Reading distance failed (status %d)\n", status);
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            if (delay_ms > MAX_DELAY_MS) delay_ms = MAX_DELAY_MS;
            retries++;
            continue;
        }

        // Check data ready bit (example)
        if ((result[0] & 0x01) == 0) {
            gpioDelay(1000); // 1ms delay
        } else {
            distance_ready = 1;
        }
    }

    if (!distance_ready) {
        fprintf(stderr, "Error: Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, (char *)data, 1);
    if (status != 0) {
        fprintf(stderr, "Error: Writing to distance register failed (status %d)\n", status);
        return -1;
    }

    status = i2cReadDevice(i2c_handle, (char *)result, 2);
    if (status != 0) {
        fprintf(stderr, "Error: Reading distance failed (status %d)\n", status);
        return -1;
    }

    *distance = (result[0] << 8) | result[1];
    distance_ready = 0; // Reset flag
    return 0;
}

// Motor Control Function
void motor_control(int distance) {
    if (distance < DISTANCE_THRESHOLD_CLOSE && motor_state != 1) {
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        motor_state = 1;
        printf("Motor: Forward (Distance: %d mm)\n", distance);
    } else if (distance > DISTANCE_THRESHOLD_FAR && motor_state != -1) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        motor_state = -1;
        printf("Motor: Backward (Distance: %d mm)\n", distance);
    } else if (motor_state != 0) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        motor_state = 0;
        printf("Motor: Stopped (Distance: %d mm)\n", distance);
    }
}

// Interrupt Handler Function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == RISING_EDGE) {
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            motor_control(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance in interrupt handler\n");
        }
    }
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop the motor
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (status %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_INTERRUPT_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

