#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define TOUCH_STATUS_REG 0x00
#define ELE0_TOUCH_THRESHOLD_REG 0x41
#define ELE0_RELEASE_THRESHOLD_REG 0x42
#define MPR121_SOFT_RESET 0x80
#define MPR121_ELECTRODE_CONFIG 0x5E

#define LED_GPIO 17
#define LED_BITS {17, 18, 27, 22}
#define NUM_ELECTRODES 12
#define PROXIMITY_THRESHOLD 50
#define DEBOUNCE_DELAY_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
int set_led_pattern(int pattern);
int log_event(int electrode, int proximity);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    set_led_pattern(0); // Turn off LEDs
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity and release thresholds
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_handle, ELE0_TOUCH_THRESHOLD_REG + 2 * i, PROXIMITY_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, ELE0_RELEASE_THRESHOLD_REG + 2 * i, 10) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Read touch status
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, TOUCH_STATUS_REG, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Set LED pattern
int set_led_pattern(int pattern) {
    int led_gpios[] = LED_BITS;
    for (int i = 0; i < 4; i++) {
        gpioWrite(led_gpios[i], (pattern >> i) & 1);
    }
    return 0;
}

// Log event
int log_event(int electrode, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Electrode %d touched (Proximity: %d)\n", timestamp, electrode, proximity);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIOs as output
    int led_gpios[] = LED_BITS;
    for (int i = 0; i < 4; i++) {
        gpioSetMode(led_gpios[i], PI_OUTPUT);
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status = 0;
    int last_touch_status = 0;
    int led_pattern = 0;

    printf("Proximity-based interactive art installation started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status != last_touch_status) {
                for (int i = 0; i < NUM_ELECTRODES; i++) {
                    int electrode_touched = (touch_status >> i) & 1;
                    if (electrode_touched) {
                        log_event(i, 1); // Proximity detected
                        led_pattern = (1 << i); // Set LED pattern
                        set_led_pattern(led_pattern);
                    } else {
                        log_event(i, 0); // No proximity
                    }
                }
                last_touch_status = touch_status;
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }
        gpioDelay(DEBOUNCE_DELAY_MS); // Debounce delay
    }

    cleanup();
    return 0;
}

