#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long long measure_pulse_width();
double calculate_distance(long long pulse_width);
void log_distance(double distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for rising edge
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for falling edge
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 for us to s conversion, then divide by 2 for one-way distance
}

// Log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(log_file, "%s ERROR: Distance out of range (%.2f cm)\n", timestamp, distance);
    } else {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
    }

    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        trigger_pulse();
        long long pulse_width = measure_pulse_width();
        double distance = calculate_distance(pulse_width);

        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(log_file, "ERROR: Failed to measure distance\n");
            fflush(log_file);
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

