#define MIN_PULSE_WIDTH 58      // microseconds
#define MAX_PULSE_WIDTH 25000   // microseconds
#define SPEED_OF_SOUND 34300.0  // cm/s

// Global variables
static volatile unsigned int echo_start_tick = 0;
static volatile unsigned int echo_end_tick = 0;
static volatile int echo_valid = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt service routine (ISR) for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set validity flag
    }
}

// Function to calculate distance in meters
double calculate_distance(unsigned int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert microseconds to seconds
