#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define POLL_INTERVAL 100 // ms

// VL53L1X Register Addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// VL53L1X Initialization
int init_vl53l1x() {
    // Example initialization sequence (refer to VL53L1X datasheet)
    char data[2];
    int status;

    // Check device ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    if (data[0] != 0xEA) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02x\n", data[0]);
        return -1;
    }

    // Add more initialization steps here based on the VL53L1X datasheet

    return 0;
}

// Read Distance from VL53L1X
int read_distance(int *distance) {
    char data[1];
    char result[2];
    int status;

    // Read data ready status
    data[0] = VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, result, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    if (result[0] & 0x01) {
        // Data is ready
        // Read distance
        data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
        status = i2cWriteDevice(i2c_handle, data, 1);
        if (status != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", status);
            return -1;
        }
        status = i2cReadDevice(i2c_handle, result, 2);
        if (status != 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", status);
            return -1;
        }

        *distance = (result[0] << 8) | result[1];
        return 0;
    } else {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }
}

