void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_GPIO, 1); // Open gate
    } else {
        gpioWrite(GATE_GPIO, 0); // Close gate
    }
}

// Log Data to File
void log_data(int distance, int gate_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d cm, Gate: %s\n", timestamp, distance, gate_state ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int distance;
    int gate_state = 0; // 0 = closed, 1 = open
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GATE_GPIO as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initialize to closed state

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_gate(distance);
            int current_gate_state = gpioRead(GATE_GPIO);
            if (current_gate_state != gate_state) {
                log_data(distance, current_gate_state);
                gate_state = current_gate_state;
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(POLL_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

