#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_RANGE 180.0
#define DISTANCE_MIN 200.0 // cm
#define DISTANCE_MAX 400.0 // cm
#define MOVING_AVG_SIZE 5
#define TIMEOUT_US 30000 // 30ms

// Global variables
volatile unsigned int pulse_width = 0;
volatile int new_pulse = 0;
volatile sig_atomic_t terminate = 0;

// Moving average filter buffer
float distance_buffer[MOVING_AVG_SIZE];
int buffer_index = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(unsigned int pulse_width);
float moving_average(float new_distance);
int set_servo_angle(int angle);
void log_data(float distance, int angle);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        uint32_t end_tick = tick;
        if (end_tick < start_tick) {
            // Handle tick counter wrap-around
            end_tick += (0xFFFFFFFF - start_tick) + 1;
        }
        pulse_width = end_tick - start_tick;
        new_pulse = 1;
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width > TIMEOUT_US) {
        return -1.0; // Timeout
    }
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
    return distance;
}

// Function to implement a moving average filter
float moving_average(float new_distance) {
    distance_buffer[buffer_index] = new_distance;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_buffer[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return -1;
    }

    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (float)angle / SERVO_RANGE * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Function to log data to a CSV file
void log_data(float distance, int angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(fp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Initialize distance buffer
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        distance_buffer[i] = 0.0;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for a short period to allow the sensor to settle
        gpioDelay(50); // 50 ms

        // Read the pulse width
        unsigned int current_pulse_width = pulse_width;
        pulse_width = 0; // Reset pulse_width for the next measurement
        new_pulse = 0;

        // Calculate the distance
        float distance = calculate_distance(current_pulse_width);

        // Filter the distance
        float filtered_distance = moving_average(distance);

        // Validate the distance
        if (filtered_distance < DISTANCE_MIN || filtered_distance > DISTANCE_MAX) {
            filtered_distance = -1.0;
        }

        // Set the servo angle
        int angle = (int)((filtered_distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * 180.0);
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
        }

        // Log the data
        log_data(filtered_distance, angle);

        // Delay before the next measurement
        gpioDelay(100); // 100 ms
    }

    // Stop the servo
    set_servo_angle(90); // Set to 90 degrees before stopping
    gpioDelay(100); // Allow time for servo to stop

    // Cleanup
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

