#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define WARNING_THRESHOLD 200 // mm

// VL53L1X Register Addresses (Example - Refer to Datasheet for full list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global Variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular Buffer
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void update_circular_buffer(int distance);
int check_warning_condition(int distance);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// VL53L1X Initialization
int vl53l1x_init() {
    // Example initialization sequence (Refer to VL53L1X datasheet)
    // This is a simplified example and may need adjustments based on your specific application
    char data[2];
    int status;

    // Check device ID (Example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Start ranging
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01; // Start ranging
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance(int *distance) {
    char data[1];
    char result[2];
    int status;

    // Read range status
    data[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device (range status): %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, result, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device (range status): %d\n", status);
        return -1;
    }

    // Read distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device (distance): %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, result, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device (distance): %d\n", status);
        return -1;
    }

    *distance = (result[0] << 8) | result[1];

    return 0;
}

// Update Circular Buffer
void update_circular_buffer(int distance) {
    distance_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check Warning Condition
int check_warning_condition(int distance) {
    return (distance < WARNING_THRESHOLD) ? 1 : 0;
}

int main() {
    int distance;
    int warning;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (vl53l1x_read_distance(&distance) == 0) {
            // Update circular buffer
            update_circular_buffer(distance);

            // Check warning condition
            warning = check_warning_condition(distance);

            // Control LED
            gpioWrite(GPIO_LED, warning);

            printf("Distance: %d mm, Warning: %d\n", distance, warning);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Cleanup
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

