    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device (distance): %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, result, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device (distance): %d\n", status);
        return -1;
    }

    *distance = (result[0] << 8) | result[1];

    return 0;
}

// Update Circular Buffer
void update_circular_buffer(int distance) {
    distance_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check Warning Condition
int check_warning_condition(int distance) {
    return (distance < WARNING_THRESHOLD) ? 1 : 0;
}

int main() {
    int distance;
    int warning;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (vl53l1x_read_distance(&distance) == 0) {
            // Update circular buffer
            update_circular_buffer(distance);

            // Check warning condition
            warning = check_warning_condition(distance);

            // Control LED
            gpioWrite(GPIO_LED, warning);

            printf("Distance: %d mm, Warning: %d\n", distance, warning);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Cleanup
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

