long measurePulseWidth() {
    echo_received = 0;
    echo_start_tick = 0;
    echo_end_tick = 0;

    // Wait for echo to start
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1; // Indicate timeout error
    }

    echo_start_tick = gpioTick();

    // Wait for echo to end
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1; // Indicate timeout error
    }

    echo_end_tick = gpioTick();

    return echo_end_tick - echo_start_tick;
}

