#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x60
#define SI1175_ALS_VIS_DATA0 0x22
#define SI1175_ALS_VIS_DATA1 0x23
#define SI1175_REG_PART_ID 0x00
#define SI1175_PART_ID 0x75
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_als_value(uint16_t *als_value);
char *get_iso8601_timestamp();
int write_to_log(const char *timestamp, uint16_t als_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor ID
    int part_id = i2cReadByteData(i2c_handle, SI1175_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (part_id != SI1175_PART_ID) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1175_PART_ID);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    printf("I2C initialized successfully.\n");
    return 0;
}

// Function to read ALS value from the sensor
int read_als_value(uint16_t *als_value) {
    int als_low, als_high;

    als_low = i2cReadByteData(i2c_handle, SI1175_ALS_VIS_DATA0);
    if (als_low < 0) {
        fprintf(stderr, "Error reading ALS low byte: %d\n", als_low);
        return -1;
    }

    als_high = i2cReadByteData(i2c_handle, SI1175_ALS_VIS_DATA1);
    if (als_high < 0) {
        fprintf(stderr, "Error reading ALS high byte: %d\n", als_high);
        return -1;
    }

    *als_value = (als_high << 8) | als_low;
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write the timestamp and ALS value to the log file
int write_to_log(const char *timestamp, uint16_t als_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%u\n", timestamp, als_value) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
        printf("I2C connection closed.\n");
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
        printf("Log file closed.\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
        fflush(log_file);
    }

    // Main loop
    while (!terminate) {
        uint16_t als_value;
        char *timestamp;

        if (read_als_value(&als_value) == 0) {
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (write_to_log(timestamp, als_value) != 0) {
                    fprintf(stderr, "Error writing to log.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        } else {
            fprintf(stderr, "Error reading ALS value.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

