#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define RESET_REG 0x07
#define RESET_VALUE 0x01
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x50
#define ALS_DATA_REG 0x22
#define PROX_DATA_REG 0x24
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "si1120_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1120();
int read_si1120_data(uint16_t *als, uint16_t *prox);
void log_data(uint16_t als, uint16_t prox);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Initialize Si1120 sensor
int init_si1120() {
    int retries = 0;
    int result;

    // Reset the sensor
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, RESET_REG, RESET_VALUE);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error resetting Si1120 (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset Si1120 after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Verify Part ID
    retries = 0;
    int part_id;
    while (retries < MAX_RETRIES) {
        part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (part_id >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading Part ID (attempt %d): %d\n", retries + 1, part_id);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read Part ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }

    return 0;
}

// Read ALS and Proximity data from Si1120
int read_si1120_data(uint16_t *als, uint16_t *prox) {
    int retries = 0;
    int result;
    uint8_t als_low, als_high, prox_low, prox_high;

    // Read ALS data
    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, (char *)&als_low, 1);
        if (result == 1) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading ALS low byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ALS low byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG + 1, (char *)&als_high, 1);
        if (result == 1) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading ALS high byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ALS high byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Read Proximity data
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, PROX_DATA_REG, (char *)&prox_low, 1);
        if (result == 1) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading Proximity low byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read Proximity low byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, PROX_DATA_REG + 1, (char *)&prox_high, 1);
        if (result == 1) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading Proximity high byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
