// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define RESET_REG 0x07
#define RESET_VALUE 0x01
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x50
#define ALS_DATA_REG 0x22
#define PROX_DATA_REG 0x24
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "si1120_log.txt"

