void log_data(uint16_t als, uint16_t prox);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Initialize Si1120 sensor
int init_si1120() {
    int retries = 0;
    int result;

    // Reset the sensor
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, RESET_REG, RESET_VALUE);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error resetting Si1120 (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset Si1120 after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Verify Part ID
    retries = 0;
    int part_id;
    while (retries < MAX_RETRIES) {
        part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (part_id >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading Part ID (attempt %d): %d\n", retries + 1, part_id);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read Part ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }

