    // Reset the device
    result = i2cWriteByteData(i2c_handle, 0x17, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145 (Error code: %d)\n", result);
        return -1;
    }
    gpioDelay(10); // Delay after reset

    // Configure PS1
    result = i2cWriteByteData(i2c_handle, 0x03, 0x01); // PS1_ADCMUX
    if (result < 0) {
        fprintf(stderr, "Error: Failed to configure PS1_ADCMUX (Error code: %d)\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, 0x04, 0x00); // PS1_ADC_GAIN
    if (result < 0) {
        fprintf(stderr, "Error: Failed to configure PS1_ADC_GAIN (Error code: %d)\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, 0x05, 0x00); // PS1_ADC_MISC
    if (result < 0) {
        fprintf(stderr, "Error: Failed to configure PS1_ADC_MISC (Error code: %d)\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, 0x08, 0x00); // PS1_MEAS_RATE
    if (result < 0) {
        fprintf(stderr, "Error: Failed to configure PS1_MEAS_RATE (Error code: %d)\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, 0x09, 0x00); // PS1_MEAS_COUNT
    if (result < 0) {
        fprintf(stderr, "Error: Failed to configure PS1_MEAS_COUNT (Error code: %d)\n", result);
        return -1;
