#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in µs
#define DISTANCE_THRESHOLD 20.0 // Distance threshold in cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_width);
void buzzer_control(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Indicate falling edge received
    }
}

// Function to calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert pulse width to seconds and divide by 2
}

// Function to control the buzzer
void buzzer_control(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor for echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program running. Press Ctrl+C to exit.\n");

    while (1) {
        trigger_pulse();

        // Wait for echo to be received (with timeout)
        int timeout_count = 0;
        while (!echo_received && timeout_count < 1000) {
            gpioDelay(1); // Wait 1 ms
            timeout_count++;
        }

        if (echo_received) {
            unsigned int pulse_width = end_tick - start_tick;
            double distance = calculate_distance(pulse_width);

            printf("Distance: %.2f cm\n", distance);
            buzzer_control(distance);
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

