#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define TIMEOUT_US 50000 // 50ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCtrl+C pressed. Exiting...\n");
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0;
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 for us to s conversion, 2 for one-way distance

    return distance;
}

// Function to set servo angle
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Map angle (0-180) to pulse width (SERVO_MIN_PULSE_WIDTH - SERVO_MAX_PULSE_WIDTH)
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * SERVO_RANGE);

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Parking assist system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float distance = measure_distance();

        if (distance > 0) {
            // Calculate servo angle
            int angle;
            if (distance > 200) {
                angle = 0;
            } else if (distance < 20) {
                angle = 180;
            } else {
                angle = (int)(((200.0 - distance) / 110.0) * 90.0);
            }

            // Set servo angle
            set_servo_angle(angle);

            // Print distance and servo angle
            printf("Distance: %.2f cm, Servo Angle: %d\n", distance, angle);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(100); // Update every 100ms
    }

    // Stop servo motor
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Parking assist system stopped.\n");

    return 0;
}

