#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0
#define TIMEOUT_US 50000       // 50ms

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getEchoPulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }
    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }
    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate timeout
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to servo angle
float mapDistanceToAngle(float distance) {
    if (distance < 0) {
        return -1.0; // Indicate invalid distance
    }

    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the servo angle
int setServoAngle(float angle) {
    if (angle < 0) {
        return -1; // Indicate invalid angle
    }

    // Calculate pulse width (500us for 0°, 2500us for 180°)
    int pulse_width = (int)(500 + (angle / MAX_ANGLE) * 2000);

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor and servo control program\n");
    printf("Press Ctrl+C to exit\n");

    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_width = getEchoPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to an angle
        float angle = mapDistanceToAngle(distance);

        // Set the servo angle
        if (setServoAngle(angle) != 0) {
            fprintf(stderr, "Error setting servo angle\n");
        }

        // Print the distance and angle
        if (distance >= 0) {
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            printf("Timeout or invalid distance\n");
        }

        // Pause for 100ms
        gpioDelay(100);
    }

    // Stop the servo
    setServoAngle(0.0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated successfully\n");
    return 0;
}

