#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// CRC polynomial
#define CRC_POLY 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    uint8_t temp_crc = crc8((uint8_t *)buf, 2);
    uint8_t hum_crc = crc8((uint8_t *)buf + 3, 2);

    if (temp_crc != buf[2] || hum_crc != buf[5]) {
        fprintf(stderr, "CRC checksum failure!\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    uint16_t hum_raw = (buf[3] << 8) | buf[4];

    data->temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    data->humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sht40(&sensor_data) == 0) {
            // Get current time
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Print temperature and humidity
            printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", asctime(timeinfo), sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-opening I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-opening fails
            }
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

