#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x21
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int convert_data(uint8_t *data, float *pressure_pa, float *temperature_c);
int log_data(float pressure_pa, float temperature_c);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait 1ms
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert data
int convert_data(uint8_t *data, float *pressure_pa, float *temperature_c) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    *pressure_pa = (float)raw_pressure / 60.0; // Scale factor from datasheet
    *temperature_c = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Log data
int log_data(float pressure_pa, float temperature_c) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fflush(fp);
    fclose(fp);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    float pressure_pa, temperature_c;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(10); // Wait 10ms before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(10); // Wait 10ms before retrying
            continue;
        }

        // Convert data
        if (convert_data(sensor_data, &pressure_pa, &temperature_c) != 0) {
            fprintf(stderr, "Error converting data\n");
            continue;
        }

        // Log data
        if (log_data(pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

