int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
