#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SDP800_I2C_ADDR 0x25
#define TRIGGER_CMD_MSB 0x36
#define TRIGGER_CMD_LSB 0x2F
#define DATA_LENGTH 9
#define SCALE_FACTOR_LENGTH 3
#define PRESSURE_OFFSET 0
#define TEMPERATURE_OFFSET 3
#define SCALE_FACTOR_OFFSET 6
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int length);
sensor_data_t process_sensor_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    size_t i, j;
    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger continuous measurement
int trigger_measurement() {
    char cmd[2] = {TRIGGER_CMD_MSB, TRIGGER_CMD_LSB};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int length) {
    uint8_t crc_calculated = crc8(data, length);
    uint8_t crc_received = data[length - 1];

    if (crc_calculated != crc_received) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", crc_calculated, crc_received);
        return -1;
    }
    return 0;
}

// Process sensor data
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Apply scaling factors
    sensor_data.pressure = (float)raw_pressure / PRESSURE_SCALE_FACTOR;
    sensor_data.temperature = (float)raw_temperature / TEMPERATURE_SCALE_FACTOR;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(data_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open data file
    data_file = fopen("airflow_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    fflush(data_file);

    uint8_t sensor_data[DATA_LENGTH];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        gpioDelay(45000); // Wait 45ms for measurement

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Validate CRC checksums
        if (validate_crc(sensor_data, 2) != 0 || validate_crc(sensor_data + 3, 2) != 0 || validate_crc(sensor_data + 6, 2) != 0) {
            fprintf(stderr, "Error validating CRC, skipping data point...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Process sensor data
        processed_data = process_sensor_data(sensor_data);

        // Log data
        log_data(processed_data);

        gpioDelay(100000); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

