#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_COUNT 3
#define SLEEP_SECONDS 2

// Structure for storing temperature and timestamp
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

// Circular buffer
TemperatureReading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
void print_buffer();
void control_fan(float temperature);
void signal_handler(int signal);

// Function to read temperature from Si7021
int read_temperature(float *temperature) {
    int raw_temperature;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        raw_temperature = i2cReadWordData(i2c_handle, TEMP_CMD);
        if (raw_temperature >= 0) {
            *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, raw_temperature);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("%s: %.2f\n", timestamp_str, buffer[index].temperature);
    }
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            control_fan(temperature);
            print_buffer();
        } else {
            fprintf(stderr, "Failed to read temperature. Check sensor connection.\n");
        }

        gpioDelay(SLEEP_SECONDS * 1000); // Sleep for 2 seconds
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

