#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86
#define CMD_READ_MEASUREMENT 0xe4b8

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len, uint8_t crc);
sensor_data_t parse_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8-Dallas/Maxim algorithm
uint8_t crc8(const uint8_t *data, int len, uint8_t crc) {
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Parse raw data into sensor values
sensor_data_t parse_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // CRC check for CO2
    uint8_t co2_data[2] = {data[0], data[1]};
    uint8_t co2_crc = data[2];
    uint8_t co2_crc_calculated = crc8(co2_data, 2, 0xFF);
    if (co2_crc != co2_crc_calculated) {
        fprintf(stderr, "CO2 CRC check failed\n");
        sensor_data.co2 = 0; // Set to 0 on error
    } else {
        sensor_data.co2 = (data[0] << 8) | data[1];
    }

    // CRC check for Temperature
    uint8_t temp_data[2] = {data[3], data[4]};
    uint8_t temp_crc = data[5];
    uint8_t temp_crc_calculated = crc8(temp_data, 2, 0xFF);
    if (temp_crc != temp_crc_calculated) {
        fprintf(stderr, "Temperature CRC check failed\n");
        sensor_data.temperature = -999.0; // Set to error value
    } else {
        int16_t temp_raw = (data[3] << 8) | data[4];
        sensor_data.temperature = -45 + 175 * (float)temp_raw / 65535.0;
    }

    // CRC check for Humidity
    uint8_t humidity_data[2] = {data[6], data[7]};
    uint8_t humidity_crc = data[8];
    uint8_t humidity_crc_calculated = crc8(humidity_data, 2, 0xFF);
    if (humidity_crc != humidity_crc_calculated) {
        fprintf(stderr, "Humidity CRC check failed\n");
        sensor_data.humidity = -999.0; // Set to error value
    } else {
        uint16_t humidity_raw = (data[6] << 8) | data[7];
        sensor_data.humidity = 100 * (float)humidity_raw / 65535.0;
    }

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for at least one second
    sleep(1);

    uint8_t data_ready_buf[3];
    uint8_t measurement_data[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Check data ready flag
        if (send_command(CMD_READ_MEASUREMENT) != 0) {
            fprintf(stderr, "Failed to send read measurement command\n");
            break;
        }

        if (read_data(data_ready_buf, 3) != 0) {
            fprintf(stderr, "Failed to read data ready flag\n");
            break;
        }

        // Verify data ready flag
        if ((data_ready_buf[0] == 0xE4) && (data_ready_buf[1] == 0xB8) && (data_ready_buf[2] == 0x00)) {
            // Read measurement data
            if (read_data(measurement_data, 9) != 0) {
                fprintf(stderr, "Failed to read measurement data\n");
                break;
            }

            // Parse data
            sensor_data = parse_data(measurement_data);

            // Log data
            log_data(sensor_data);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Stop periodic measurement
    if (send_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send stop periodic measurement command\n");
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

