#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_READ_MEASUREMENT 0xec05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// Data Structures
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global Variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c();
int init_scd40();
int read_scd40_data(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
void print_buffer(circular_buffer_t *buffer);
void control_led(int co2_ppm);
void signal_handler(int signal);
void cleanup();

// Function Implementations
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int init_scd40() {
    uint8_t cmd[2];
    cmd[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for sensor to start

    return 0;
}

int read_scd40_data(sensor_data_t *data) {
    uint8_t cmd[2];
    cmd[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to request measurement: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    uint8_t raw_data[9];
    result = i2cReadDevice(i2c_handle, (char *)raw_data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC Check
    if (crc8(raw_data, 2) != raw_data[2] ||
        crc8(raw_data + 3, 2) != raw_data[5] ||
        crc8(raw_data + 6, 2) != raw_data[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data
    data->co2 = (raw_data[0] << 8) | raw_data[1];
    data->temperature = -45 + 175 * ((float)((raw_data[3] << 8) | raw_data[4])) / 65535.0;
    data->humidity = 100 * ((float)((raw_data[6] << 8) | raw_data[7])) / 65535.0;

    return 0;
}

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

void print_buffer(circular_buffer_t *buffer) {
    printf("CO2,Temperature,Humidity\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%d,%.2f,%.2f\n", buffer->data[index].co2, buffer->data[index].temperature, buffer->data[index].humidity);
    }
}

void control_led(int co2_ppm) {
    if (co2_ppm > CO2_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    uint8_t cmd[2];
    cmd[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    gpioDelay(10); // Wait for sensor to stop

    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize SCD40
    if (init_scd40() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_scd40_data(&sensor_data) == 0) {
            add_to_buffer(&buffer, sensor_data);
            print_buffer(&buffer);
            control_led(sensor_data.co2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

