#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define TIMEOUT_US 50000 // 50ms
#define SAMPLE_INTERVAL_S 5
#define MAX_FAILURES 3

// Global variables
FILE *log_file = NULL;
int pigpio_initialized = 0;
int consecutive_failures = 0;

// Function prototypes
int initialize_pigpio();
int read_temperature(double *temperature);
int log_temperature(double temperature);
void signal_handler(int signal);
void cleanup();

int main() {
    double temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
            consecutive_failures = 0; // Reset failure count on success
        } else {
            consecutive_failures++;
            fprintf(stderr, "Failed to read temperature. Failure count: %d\n", consecutive_failures);
            if (consecutive_failures >= MAX_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                fflush(log_file);
                consecutive_failures = 0; // Reset after logging
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    return 0;
}

int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;
    return 0;
}

int read_temperature(double *temperature) {
    int start_sec, start_micros, end_sec, end_micros;
    long pulse_width, total_width;

    // Wait for the rising edge
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    while (gpioRead(GPIO_PIN) == 0) {
        gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
        if ((end_sec - start_sec) * 1000000 + (end_micros - start_micros) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return 1;
        }
    }

    // Measure the pulse width
    gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    while (gpioRead(GPIO_PIN) == 1) {
        gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
        if ((end_sec - start_sec) * 1000000 + (end_micros - start_micros) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return 1;
        }
    }
    gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);

    pulse_width = (end_sec - start_sec) * 1000000 + (end_micros - start_micros);
    total_width = pulse_width; // Total width is the same as pulse width for PWM

    // Calculate temperature (example formula, adjust as needed)
    *temperature = (double)pulse_width / total_width * 100.0; // Example conversion

    // Validate temperature range
    if (*temperature < -40.0 || *temperature > 150.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", *temperature);
        return 1;
    }

    return 0;
}

int log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file);

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    if (pigpio_initialized) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

