#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define DATA_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define ONE_HOUR_PERIOD 3600 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], int nbrOfBytes);
SensorData convert_data(uint8_t *data);
SensorData add_offset(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);

// CRC lookup table
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)command, 2) == 2) {
            gpioDelay(20); // Wait for measurement (datasheet specifies 15ms)
            if (i2cReadDevice(i2c_handle, (char *)data, 6) == 6) {
                return 0; // Success
            }
        }
        fprintf(stderr, "I2C read failed, retrying...\n");
        gpioDelay(1000); // 1 second delay
        retries--;
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure
}

// Function to calculate CRC
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = calculate_crc(data, nbrOfBytes);
    return (crc == data[nbrOfBytes]);
}

// Function to convert raw data to temperature and humidity
SensorData convert_data(uint8_t *data) {
    SensorData sensor_data;
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to add a sinusoidal offset
SensorData add_offset(SensorData data) {
    time_t now = time(NULL);
    double seconds_since_midnight = difftime(now, mktime(localtime(&now)));
    double offset_temperature = 2.0 * sin(2.0 * M_PI * seconds_since_midnight / ONE_HOUR_PERIOD);
    double offset_humidity = 5.0 * sin(2.0 * M_PI * seconds_since_midnight / ONE_HOUR_PERIOD);

    data.temperature += offset_temperature;
    data.humidity += offset_humidity;

    // Clamp values to reasonable ranges
    if (data.temperature < -40.0) data.temperature = -40.0;
    if (data.temperature > 125.0) data.temperature = 125.0;
    if (data.humidity < 0.0) data.humidity = 0.0;
    if (data.humidity > 100.0) data.humidity = 100.0;

    return data;
}

// Function to log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[6];
    SensorData raw_data, offset_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 2) && validate_crc(sensor_data + 3, 2)) {
                // Convert data
                raw_data = convert_data(sensor_data);

                // Add offset
                offset_data = add_offset(raw_data);

                // Log data
                log_data(offset_data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
                fprintf(log_file, "NaN,NaN\n");
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            fprintf(log_file, "NaN,NaN\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for the next sample
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

