    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

