#define SI7021_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "environment.log"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t cmd, uint16_t *data);
uint8_t crc8(const uint8_t *data, int len, uint8_t crc);
sensor_data_t process_sensor_data(uint16_t raw_temp, uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry and timeout
int read_sensor_data(uint8_t cmd, uint16_t *data) {
    int retries = 3;
    int delay_ms = 10;
    int bytes_read;
    uint8_t buf[3];

    while (retries > 0) {
        i2cWriteByte(i2c_handle, cmd);
        gpioDelay(10); // Small delay after writing command

        bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 3);

        if (bytes_read == 3) {
            *data = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries left: %d\n", bytes_read, retries);
            retries--;
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
