    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temp, raw_humidity;
        sensor_data_t data;

        // Read temperature
        if (read_sensor_data(TEMP_CMD, &raw_temp) != 0) {
            fprintf(stderr, "Error reading temperature.\n");
            continue; // Skip to next iteration
        }

        // Read humidity
        if (read_sensor_data(HUMID_CMD, &raw_humidity) != 0) {
            fprintf(stderr, "Error reading humidity.\n");
            continue; // Skip to next iteration
        }

        // Process sensor data
        data = process_sensor_data(raw_temp, raw_humidity);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

