#include <time.h>
#include <signal.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(float *pressure, float *temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    // Register signal handler for graceful termination
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.pressure, &sensor_data.temperature) == 0) {
            // Log data
            if (log_data(sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize the LPS33HW sensor
int init_sensor() {
    // Enable continuous data acquisition (ODR = 10 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x10) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return 1;
    }
    return 0;
}

// Read pressure and temperature data from the sensor
int read_sensor_data(float *pressure, float *temperature) {
    char buffer[5];
    int16_t pressure_raw, temperature_raw;

    // Read pressure data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        fprintf(stderr, "Failed to read pressure data\n");
        return 1;
    }

    pressure_raw = (int16_t)((buffer[2] << 8) | buffer[1]);
    *pressure = (float)pressure_raw / 4096.0; // hPa

    // Read temperature data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return 1;
    }

    temperature_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    *temperature = (float)temperature_raw / 100.0; // °C

    return 0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

