#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define DEFAULT_INTERVAL_MS 1000
#define READ_CMD 0x362F // Trigger continuous measurement without averaging
#define PRESSURE_MSB_REG 0x00
#define PRESSURE_LSB_REG 0x01
#define PRESSURE_CRC_REG 0x02
#define TEMP_MSB_REG 0x03
#define TEMP_LSB_REG 0x04
#define TEMP_CRC_REG 0x05
#define SCALE_FACTOR_MSB_REG 0x06
#define SCALE_FACTOR_LSB_REG 0x07
#define SCALE_FACTOR_CRC_REG 0x08

// Global variables
int i2c_handle;
int sampling_interval_ms = DEFAULT_INTERVAL_MS;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    float scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int verify_crc(uint8_t data, uint8_t crc);
void print_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        sampling_interval_ms = atoi(argv[1]);
        if (sampling_interval_ms <= 0) {
            fprintf(stderr, "Invalid sampling interval. Using default: %d ms\n", DEFAULT_INTERVAL_MS);
            sampling_interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            print_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d ms\n", sampling_interval_ms);
        }

        gpioDelay(sampling_interval_ms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Send trigger measurement command
    char cmd[2] = {(READ_CMD >> 8) & 0xFF, READ_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);

    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }

    // Verify CRC for pressure
    if (verify_crc(buffer[0], buffer[2]) != 0) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return 1;
    }

    // Verify CRC for temperature
    if (verify_crc(buffer[3], buffer[5]) != 0) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return 1;
    }

    // Verify CRC for scale factor
    if (verify_crc(buffer[6], buffer[8]) != 0) {
        fprintf(stderr, "Scale Factor CRC check failed\n");
        return 1;
    }

    // Convert data
    int16_t pressure_raw = (buffer[0] << 8) | buffer[1];
    int16_t temperature_raw = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor_raw = (buffer[6] << 8) | buffer[7];

    data->pressure = (float)pressure_raw / 240.0; // Scale factor from datasheet
    data->temperature = (float)temperature_raw / 200.0; // Scale factor from datasheet
    data->scale_factor = (float)scale_factor_raw / 65536.0; // Scale factor from datasheet

    return 0;
}

// Verify CRC
int verify_crc(uint8_t data, uint8_t crc) {
    uint8_t calculated_crc = crc8(&data, 1);
    if (calculated_crc != crc) {
        return 1; // CRC check failed
    }
    return 0; // CRC check passed
}

// Print sensor data
void print_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f Pa, Temperature: %.2f °C, Scale Factor: %.6f\n",
           timestamp, data.pressure, data.temperature, data.scale_factor);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

