#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_COMMAND >> 8); // MSB
    if (result != 0) {
        fprintf(stderr, "Error writing MSB of measurement command: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_COMMAND & 0xFF); // LSB
    if (result != 0) {
        fprintf(stderr, "Error writing LSB of measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 45ms)
    gpioDelay(45000); // 45ms

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // CRC validation
    for (int i = 0; i < 6; i++) {
        if (crc8(buffer + i, 2) != buffer[i + 6]) {
            fprintf(stderr, "CRC mismatch at byte %d\n", i);
            return -1;
        }
    }

