    float temperature_scale_factor = (float)((buffer[8] << 8) | buffer[9]) / 65535.0;

    // Apply scaling
    data->pressure = (float)raw_pressure * pressure_scale_factor;
    data->temperature = (float)raw_temperature * temperature_scale_factor;

