#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONVERSION_DELAY_MS 15
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Configure the sensor (14-bit resolution, temperature and humidity)
    char config_data[2] = {CONFIG_REG, 0x00}; // Default configuration
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Sensor reading function
int read_sensor(float *temperature, float *humidity) {
    char trigger_data[1] = {TEMP_REG};
    char raw_data[4];

    // Trigger temperature and humidity measurement
    if (i2cWriteDevice(i2c_handle, trigger_data, 1) != 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion (at least 15ms)
    gpioDelay(CONVERSION_DELAY_MS * 1000); // Convert ms to microseconds

    // Read temperature and humidity data
    if (i2cReadDevice(i2c_handle, raw_data, 4) != 4) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temp_raw = (raw_data[0] << 8) | raw_data[1];
    uint16_t humid_raw = (raw_data[2] << 8) | raw_data[3];

    *temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humid_raw / 65536.0) * 100.0;

    return 0;
}

// Data logging function
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

