#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_CMD 0xE3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from Si7051 sensor
int read_temperature(int i2c_handle, float *temperature) {
    int raw_temperature;
    int result;

    // Send temperature measurement command
    result = i2cWriteByteData(i2c_handle, TEMP_CMD, 0); // No register address needed for this command
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (typical conversion time is 10ms)
    gpioDelay(20); // Wait 20ms

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, 0); // No register address needed
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temperature);
        return -1;
    }

    // Convert raw temperature to Celsius
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    return 0;
}

int main() {
    float temperature;
    int retry;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_temperature(i2c_handle, &temperature) == 0) {
                // Get current time
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char buf[80];
                strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

                // Log temperature with timestamp
                printf("%s Temperature: %.2f °C\n", buf, temperature);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Temperature read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS); // Wait before retrying
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Temperature read failed after multiple retries.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

