int read_pressure(int i2c_handle, float *pressure) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }

    // Convert the raw data to a pressure value (example conversion)
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    *pressure = (float)raw_pressure / 10.0; // Example scaling factor

    return 0;
}

