void log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Pressure: %.2f Pa\n", timestamp_str, data.pressure);
}

// Function to cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    float pressure;
    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read pressure
        if (read_pressure(i2c_handle, &pressure) == 0) {
            // Get current timestamp
            sensor_data.timestamp = time(NULL);
            sensor_data.pressure = pressure;

            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }

        // Wait 500ms
        gpioDelay(500000); // pigpio's delay function
    }

    // Cleanup resources
    cleanup();

    return 0;
}

