#include <unistd.h>

// Define the I2C address of the ICP-10101 sensor
#define ICP10101_ADDR 0x69

// Define the register addresses for temperature and pressure measurement
#define TEMP_MSB_REG 0x00
#define PRESS_MSB_REG 0x03

// Define the default values for temperature and pressure
#define DEFAULT_TEMP 25.0
#define DEFAULT_PRESS 101325.0

// Global variables for I2C handle and program termination flag
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int is_sensor_absent(sensor_data_t data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Function to initialize the I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0); // Open I2C bus 1, sensor address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and pressure data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    // Trigger measurement (no-op command)
    result = i2cWriteByteData(i2c_handle, 0x06, 0x03); // Example command, check datasheet
    if (result < 0) {
        log_error("Error triggering measurement");
        return -1;
    }
    gpioDelay(7); // Wait 7ms

    // Read temperature data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, TEMP_MSB_REG, buf, 2);
    if (result < 0) {
        log_error("Error reading temperature data");
        return -1;
    }
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    data->temperature = (float)raw_temp / 100.0; // Example conversion, check datasheet

    // Read pressure data (3 bytes)
    result = i2cReadI2CBlockData(i2c_handle, PRESS_MSB_REG, buf, 3);
    if (result < 0) {
        log_error("Error reading pressure data");
        return -1;
    }
    int32_t raw_press = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    data->pressure = (float)raw_press / 100.0; // Example conversion, check datasheet

    return 0;
}

// Function to check if the sensor is absent
int is_sensor_absent(sensor_data_t data) {
    // Check if temperature and pressure are within a reasonable range
    if (data.temperature < -50.0 || data.temperature > 100.0 ||
        data.pressure < 90000.0 || data.pressure > 110000.0) {
        return 1; // Sensor absent
    }
    return 0; // Sensor present
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(stderr, "%s - ERROR: %s\n", timestamp, message);
}

// Function to cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Check if sensor is absent
            if (is_sensor_absent(sensor_data)) {
                log_error("Sensor absent");
            } else {
                // Get current timestamp
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

                // Print sensor data with timestamp
                printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, sensor_data.temperature, sensor_data.pressure);
            }
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

