#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F // Trigger continuous measurement without averaging
#define LOG_FILE "airflow_log.csv"
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(int16_t *pressure);
uint8_t calculate_crc(uint8_t data[], int len);
int log_data(int16_t pressure);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int16_t pressure;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor(int16_t *pressure) {
    char buf[3];
    int bytes_read;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0, MEASURE_CMD >> 8) < 0) {
        fprintf(stderr, "Error writing MSB of measurement command: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0, MEASURE_CMD & 0xFF) < 0) {
        fprintf(stderr, "Error writing LSB of measurement command: %d\n", i2c_handle);
        return -1;
    }

    // Wait for at least 8ms
    gpioDelay(8000); // Delay in microseconds

    // Read 3 bytes of data
    bytes_read = i2cReadDevice(i2c_handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    // Verify CRC
    uint8_t data[2] = {buf[0], buf[1]};
    uint8_t crc_calculated = calculate_crc(data, 2);
    uint8_t crc_received = buf[2];

    if (crc_calculated != crc_received) {
        fprintf(stderr, "CRC error: calculated 0x%02X, received 0x%02X\n", crc_calculated, crc_received);
        return -1;
    }

    // Convert data to pressure (Pa)
    *pressure = (int16_t)((buf[0] << 8) | buf[1]);

    return 0;
}

// Function to calculate CRC-8
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log data to file
int log_data(int16_t pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Check if the file exists. If not, add a header row.
    if (access(LOG_FILE, F_OK) == -1) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
            return -1;
        }
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    } else {
        fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for appending: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(fp, "%s,%d\n", timestamp, pressure);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    int16_t pressure;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor(&pressure) == 0) {
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

