#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define MLX90821_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address
#define LOG_FILE "pressure_log.csv"
#define SAFE_PRESSURE_MIN 200.0
#define SAFE_PRESSURE_MAX 250.0

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
float read_pressure();
int log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (example)
typedef struct {
    int i2c_bus;
    int mlx90821_address;
    char *log_file_name;
} config_t;

config_t config = {I2C_BUS, MLX90821_ADDR, LOG_FILE};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float pressure = read_pressure();

        if (pressure >= 0) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.mlx90821_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

float read_pressure() {
    int retries = 3;
    int bytes_read;
    unsigned char buffer[2]; // Assuming 2 bytes for pressure data
    float pressure = -1.0;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, (char *)buffer, 2);

        if (bytes_read == 2) {
            // Combine the two bytes into a 16-bit value
            int16_t raw_pressure = (buffer[0] << 8) | buffer[1];

            // Convert raw data to kPa (example conversion, adjust as needed)
            pressure = (float)raw_pressure / 10.0; // Example scaling
            return pressure;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, bytes_read);
            retries--;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read pressure after multiple retries\n");
    return -1.0; // Indicate failure
}

int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file is newly created (size == 0)
    struct stat st;
    if (stat(config.log_file_name, &st) == -1) {
        if (errno == ENOENT) {
            // File doesn't exist, create it and write the header
            log_file = fopen(config.log_file_name, "w");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file for writing\n");
                return -1;
            }
            fprintf(log_file, "timestamp,pressure_kPa\n");
        } else {
            fprintf(stderr, "Error getting file status\n");
            return -1;
        }
    } else {
        // File exists, open in append mode
        log_file = fopen(config.log_file_name, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for appending\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing
    return 0;
}

void check_pressure_range(float pressure) {
    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "Warning: Pressure outside safe range (%.2f kPa)\n", pressure);
    }
}

