#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1MB
#define MEASUREMENT_INTERVAL 5 // seconds
#define TRIGGER_DELAY 40 // milliseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint16_t *raw_data);
sensor_data_t process_sensor_data(uint16_t raw_data);
int log_data(sensor_data_t data);
void rotate_log_file();
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, 0x00); // Trigger measurement
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(TRIGGER_DELAY * 1000); // Wait for measurement (40ms)
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *raw_data) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *raw_data = (buf[0] << 8) | buf[1];
    return 0;
}

// Process sensor data
sensor_data_t process_sensor_data(uint16_t raw_data) {
    sensor_data_t data;

    // Status bits
    data.status = (raw_data >> 12) & 0x0F;

    // Humidity
    uint16_t humidity_raw = (raw_data >> 4) & 0x3FFF;
    data.humidity = (float)humidity_raw / 16383 * 100;

    // Temperature
    uint16_t temperature_raw = raw_data & 0x0FFF;
    data.temperature = (float)temperature_raw / 16383 * 165 - 40;

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check file size and rotate if necessary
    struct stat st;
    if (stat(LOG_FILE, &st) == 0) {
        if (st.st_size > LOG_FILE_SIZE_LIMIT) {
            rotate_log_file();
        }
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Write data to log file
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, data.temperature, data.humidity, data.status);
    fclose(fp);

    return 0;
}

// Rotate log file
void rotate_log_file() {
    if (rename(LOG_FILE, "environmental_data.log.1") != 0) {
        fprintf(stderr, "Error rotating log file: %s\n", strerror(errno));
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_data;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(&raw_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Process sensor data
        sensor_data_t data = process_sensor_data(raw_data);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

