    unsigned int start_time, end_time, pulse_width;
    int i;

    // Wait for the start of the SENT frame (falling edge)
    int level = gpioRead(GPIO_PIN);
    while (level == PI_HIGH && !terminate) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        level = gpioRead(GPIO_PIN);
    }

    if (terminate) return -1;

    start_time = gpioTick();

    // Read 32 bits of data
    *data = 0;
    for (i = 0; i < 32; i++) {
        // Wait for the rising edge
        level = gpioRead(GPIO_PIN);
        while (level == PI_LOW && !terminate) {
            gpioDelay(1);
            level = gpioRead(GPIO_PIN);
        }
        if (terminate) return -1;

        end_time = gpioTick();
        pulse_width = end_time - start_time;
        start_time = end_time;

        // Validate pulse width
        if (pulse_width < 12 || pulse_width > 271) {
            fprintf(stderr, "Error: Invalid pulse width: %d\n", pulse_width);
            return -1;
        }

        // Determine nibble value based on pulse width
        int nibble;
        if (pulse_width < 100) {
