    // Calculate expected checksum
    int expected_checksum = (sensor_data.status >> 2) & 0x3;

    // Validate checksum
    if (checksum_raw != expected_checksum) {
        fprintf(stderr, "Error: Checksum mismatch: expected %d, got %d\n", expected_checksum, checksum_raw);
        sensor_data.pressure = -1.0; // Indicate error
        return sensor_data;
    }

    // Convert pressure data to pressure in Pascals
    sensor_data.pressure = (float)pressure_raw * 0.0625; // 0.0625 Pa per nibble

    return sensor_data;
