    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.pressure >= 0) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, data.pressure);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Invalid sensor data, not logging.\n");
    }

    return 0;
