    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    fprintf(stdout, "Starting pressure sensor data logging...\n");

    while (!terminate) {
        // Read SENT data
        read_result = read_sent_data(&sent_data);
        if (read_result == 0) {
            // Decode SENT data
            sensor_data = decode_sent_data(sent_data);

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading SENT data\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

