#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
double read_temperature();
void store_temperature(double temperature);
void flush_buffer();
void signal_handler(int signal);

// Structure to hold temperature data with timestamp
typedef struct {
    time_t timestamp;
    double temperature;
} TemperatureData;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
double read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    double temperature = raw_temp * 0.0078125; // Resolution is 0.0078125 degrees C
    return temperature;
}

// Store temperature in the circular buffer
void store_temperature(double temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Flush the buffer to a file
void flush_buffer() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file for writing!\n");
        return;
    }

    // Write the entire buffer to the file
    size_t bytes_written = fwrite(temperature_buffer, sizeof(double), BUFFER_SIZE, fp);
    if (bytes_written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to log file!\n");
    }

    fclose(fp);
    printf("Buffer flushed to file.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            store_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        time_sleep(SAMPLE_INTERVAL);
    }

    // Flush the buffer before exiting
