#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 commands
#define SHTC3_MEASURE_NORMAL 0x7866

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_shtc3(uint16_t *temperature, uint16_t *humidity);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_data(uint16_t temperature, uint16_t humidity);
sensor_data_t process_data(uint16_t raw_temperature, uint16_t raw_humidity);
int log_data(sensor_data_t data);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8-ATM polynomial 0x31 (x^8 + x^5 + x^4 + 1)
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    sensor_data_t data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_shtc3(&raw_temperature, &raw_humidity) == 0) {
            // Validate data
            if (validate_data(raw_temperature, raw_humidity) == 0) {
                // Process data
                data = process_data(raw_temperature, raw_humidity);

                // Log data
                if (log_data(data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }

                // Print data
                print_data(data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature and humidity from SHTC3
int read_shtc3(uint16_t *temperature, uint16_t *humidity) {
    char buf[6];
    uint8_t cmd[2] = {(SHTC3_MEASURE_NORMAL >> 8) & 0xFF, SHTC3_MEASURE_NORMAL & 0xFF};

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return 1;
    }

    // Wait for measurement to complete (at least 12.4ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return 1;
    }

    // Extract temperature and humidity values
    *temperature = (buf[0] << 8) | buf[1];
    *humidity = (buf[3] << 8) | buf[4];

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;
    int byteNr;

    for (byteNr = 0; byteNr < nbrOfBytes; ++byteNr) {
        crc ^= (data[byteNr]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Validate data using CRC-8 checksum
int validate_data(uint16_t temperature, uint16_t humidity) {
    uint8_t temp_data[2] = {(temperature >> 8) & 0xFF, temperature & 0xFF};
    uint8_t hum_data[2] = {(humidity >> 8) & 0xFF, humidity & 0xFF};

    uint8_t temp_crc = calculate_crc(temp_data, 2);
    uint8_t hum_crc = calculate_crc(hum_data, 2);

    if (temp_crc != (temp_data[0] >> 0) & 0xFF) return 1;
    if (hum_crc != (hum_data[0] >> 0) & 0xFF) return 1;

    return 0;
}

// Process raw data to temperature and humidity
sensor_data_t process_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    sensor_data_t data;

    // Convert raw data to temperature (Celsius)
    data.temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    // Convert raw data to humidity (%RH)
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Check if the file is empty, if so, add the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%)\n");
    }

    // Write data to file
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Print data to stdout
void print_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

