#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x28
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t flow;
    uint16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
float convert_flow_to_slpm(uint16_t raw_flow);
float convert_temperature_to_celsius(uint16_t raw_temperature);
int log_data(float flow_slpm, float temperature_celsius);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    char buffer[4];
    sensor_data_t data;
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        data.flow = 0; // Set to 0 to avoid garbage values
        data.temperature = 0;
        return data;
    }

    // Extract raw data
    data.flow = ((uint16_t)buffer[0] << 8) | (uint16_t)buffer[1];
    data.temperature = ((uint16_t)buffer[2] << 8) | (uint16_t)buffer[3];

    return data;
}

// Function to convert raw flow data to SLPM
float convert_flow_to_slpm(uint16_t raw_flow) {
    // Honeywell HAFUHH0025PA3: 0-25 SLPM, 0-16383 raw value
    return ((float)raw_flow / 16383.0) * 25.0;
}

// Function to convert raw temperature data to Celsius
float convert_temperature_to_celsius(uint16_t raw_temperature) {
    // Honeywell HAFUHH0025PA3: 0-100°C, 0-16383 raw value
    return ((float)raw_temperature / 16383.0) * 100.0;
}

// Function to log data to file
int log_data(float flow_slpm, float temperature_celsius) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, flow_slpm, temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data();

        if (sensor_data.flow != 0 || sensor_data.temperature != 0) {
            float flow_slpm = convert_flow_to_slpm(sensor_data.flow);
            float temperature_celsius = convert_temperature_to_celsius(sensor_data.temperature);

            if (log_data(flow_slpm, temperature_celsius) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

