#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100
#define MAX_RETRIES 3
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG "dht11_errors.txt"

// Structure to hold DHT11 data
typedef struct {
    int humidity_int;
    int humidity_dec;
    int temperature_int;
    int temperature_dec;
    int checksum;
} DHT11Data;

// Function prototypes
int initialize_gpio();
int read_dht11(DHT11Data *data);
int decode_dht11_data(const unsigned int *data, DHT11Data *dht_data);
int verify_checksum(const DHT11Data *dht_data);
int write_to_file(const DHT11Data *dht_data);
void log_error(const char *message);
void signal_handler(int signal);

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

int main() {
    DHT11Data dht_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        log_error("Failed to initialize pigpio. Exiting.");
        return 1;
    }

    // Main loop
    while (program_running) {
        if (read_dht11(&dht_data) == 0) {
            if (verify_checksum(&dht_data) == 0) {
                if (write_to_file(&dht_data) != 0) {
                    log_error("Failed to write data to file.");
                }
            } else {
                log_error("Checksum verification failed.");
            }
        } else {
            log_error("Failed to read DHT11 data.");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    return 0;
}

// Read DHT11 data
int read_dht11(DHT11Data *dht_data) {
    int retries = 0;
    unsigned int data[5] = {0};

    // Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20us

    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for response (low)
    int timeout = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            log_error("Timeout waiting for response low.");
            return 1;
        }
    }

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            log_error("Timeout waiting for response high.");
            return 1;
        }
    }

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            log_error("Timeout waiting for response low after high.");
            return 1;
        }
    }

    // Read 40 bits of data
    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > TIMEOUT_US) {
                log_error("Timeout waiting for data low.");
                return 1;
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > TIMEOUT_US) {
                log_error("Timeout waiting for data high.");
                return 1;
            }
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Decode data
    if (decode_dht11_data(data, dht_data) != 0) {
        log_error("Failed to decode DHT11 data.");
        return 1;
    }

    return 0;
}

// Decode DHT11 data
int decode_dht11_data(const unsigned int *data, DHT11Data *dht_data) {
    dht_data->humidity_int = (data[0] & 0xFF);
    dht_data->humidity_dec = 0; // Always 0 for DHT11
    dht_data->temperature_int = (data[2] & 0xFF);
    dht_data->temperature_dec = 0; // Always 0 for DHT11
    dht_data->checksum = data[4];

    return 0;
}

// Verify checksum
int verify_checksum(const DHT11Data *dht_data) {
    int humidity = dht_data->humidity_int;
    int temperature = dht_data->temperature_int;
    int checksum = dht_data->checksum;

    int sum = humidity + temperature;
    if (sum != checksum) {
        return 1; // Checksum failure
    }

    return 0; // Checksum OK
}

// Write data to file
int write_to_file(const DHT11Data *dht_data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file.");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, dht_data->humidity_int, dht_data->humidity_dec, dht_data->temperature_int, dht_data->temperature_dec);
    fclose(fp);

    return 0;
}

// Log error to file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,ERROR: %s\n", timestamp, message);
    fclose(fp);
    fprintf(stderr, "%s,ERROR: %s\n", timestamp, message);
}

// Signal handler
