#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define LOG_FILE "sht31d_data.log"
#define RETRY_COUNT 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_measurement_command();
int read_sensor_data(unsigned char *data);
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes);
int validate_crc(unsigned char data[], int nbrOfBytes, unsigned char checksum);
sensor_data_t process_sensor_data(unsigned char *data);
int log_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send measurement command
int send_measurement_command() {
    unsigned char command[2];
    command[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    command[1] = MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(unsigned char data[], int nbrOfBytes, unsigned char checksum) {
    unsigned char calculated_crc = calculate_crc(data, nbrOfBytes);
    if (calculated_crc != checksum) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, checksum);
        return -1;
    }
    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(unsigned char *data) {
    sensor_data_t sensor_data;

    // Temperature calculation
    unsigned short temperature_raw = (data[0] << 8) | data[1];
    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);

    // Humidity calculation
    unsigned short humidity_raw = (data[3] << 8) | data[4];
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to log sensor data
int log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    unsigned char data[6];
    sensor_data_t sensor_data;
    int retry;

    while (!terminate) {
        // Send measurement command
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (send_measurement_command() == 0) {
                break;
            }
            retry++;
            gpioDelay(100); // Wait 100ms before retrying
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to send measurement command after multiple retries\n");
            continue; // Skip to the next iteration
        }

        // Wait for measurement (at least 15ms)
        gpioDelay(20);

        // Read sensor data
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(data) == 0) {
                break;
            }
            retry++;
            gpioDelay(100); // Wait 100ms before retrying
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
            continue; // Skip to the next iteration
        }

        // Validate CRC checksums
        if (validate_crc(data, 2, data[2]) != 0 || validate_crc(data + 3, 2, data[5]) != 0) {
            fprintf(stderr, "CRC validation failed, skipping data point\n");
            continue; // Skip to the next iteration
        }

        // Process sensor data
        sensor_data = process_sensor_data(data);

        // Log sensor data
        log_sensor_data(sensor_data);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

