#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses and registers
#define SENSOR1_ADDR 0x38
#define SENSOR2_ADDR 0x39
#define ADPD105_REG_DATA_0 0x00
#define ADPD105_REG_DATA_1 0x01
#define ADPD105_REG_DATA_2 0x02
#define ADPD105_REG_DATA_3 0x03
#define ADPD105_REG_CONFIG 0x04
#define ADPD105_REG_STATUS 0x05

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    exit(0);
}

// Function to read data from ADPD105 sensor
int read_adpd105_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[4];
    int result;

    // Read 4 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, ADPD105_REG_DATA_0, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data from sensor: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit values
    *red = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *green = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *blue = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);

    return 0;
}

// Function to calculate CCT from RGB values (simplified formula)
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    // This is a placeholder.  A real implementation would use a more complex formula.
    // For example, using a lookup table or polynomial fitting.
    // This example just returns a dummy value.
    return (float)(red + green + blue) / 3.0;
}

// Function to log CCT data to a file
int log_cct_data(FILE *fp, float cct) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, cct) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0); // Bus 1, address 0x38, no flags
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1, cct2, average_cct;

        // Read data from sensor 1
        if (read_adpd105_data(i2c_handle1, &red1, &green1, &blue1) != 0) {
            fprintf(stderr, "Error reading from sensor 1, skipping cycle\n");
            sleep(1);
            continue;
