#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define HYSTERESIS_DELAY_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void control_led(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int stts2004_address;
    int led_gpio;
    float temp_threshold_high;
    float temp_threshold_low;
    int hysteresis_delay_ms;
} config_t;

config_t config = {
    I2C_BUS,
    STTS2004_ADDR,
    LED_GPIO,
    TEMP_THRESHOLD_HIGH,
    TEMP_THRESHOLD_LOW,
    HYSTERESIS_DELAY_MS
};

int main() {
    float temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read temperature
        result = read_temperature(&temperature);
        if (result != 0) {
            fprintf(stderr, "Failed to read temperature\n");
        } else {
            // Control LED
            control_led(temperature);

            // Log temperature with timestamp
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            printf("%s Temperature: %.2f °C\n", buf, temperature);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.stts2004_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from STTS2004
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 256.0;

    return 0;
}

// Control LED based on temperature
void control_led(float temperature) {
    static int led_state = 0; // 0 = off, 1 = on
    static time_t last_change_time = 0;

    if (temperature > config.temp_threshold_high && led_state == 0) {
        // Temperature above threshold and LED is off
        led_state = 1;
        gpioWrite(config.led_gpio, 1); // Turn LED on
        last_change_time = time(NULL);
    } else if (temperature < config.temp_threshold_low && led_state == 1) {
        // Temperature below threshold and LED is on
        // Check hysteresis delay
        if (time(NULL) - last_change_time >= config.hysteresis_delay_ms / 1000.0) {
            led_state = 0;
            gpioWrite(config.led_gpio, 0); // Turn LED off
            last_change_time = time(NULL);
        }
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(config.led_gpio, 0);

    // Close I2C device
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

