#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F // Trigger continuous measurement without averaging
#define SCALE_FACTOR_CMD 0x3615 // Read scale factor
#define DATA_FILE "flow_data.txt"
#define ERROR_FILE "error_log.txt"
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    float scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int read_scale_factor(float *scale_factor);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF);
    if (result < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for at least 45ms
    gpioDelay(45000);

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure and temperature
    if (!validate_crc(buffer, 2, buffer[2])) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Extract pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // Convert to physical units (refer to SDP800 datasheet)
    data->pressure = (float)raw_pressure / 240.0; // Pa
    data->temperature = (float)raw_temperature / 200.0; // °C

    // Read scale factor
    if (read_scale_factor(&data->scale_factor) != 0) {
        fprintf(stderr, "Error reading scale factor\n");
        return -1;
    }

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t crc_calculated = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

// Read scale factor
int read_scale_factor(float *scale_factor) {
    uint8_t buffer[3];
    int result;

    // Send read scale factor command
    result = i2cWriteByteData(i2c_handle, (SCALE_FACTOR_CMD >> 8) & 0xFF, SCALE_FACTOR_CMD & 0xFF);
    if (result < 0) {
        fprintf(stderr, "Error writing scale factor command: %d\n", result);
        return -1;
    }

    // Read 3 bytes of scale factor data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading scale factor data: %d\n", result);
        return -1;
    }

    // Validate CRC for scale factor
    if (!validate_crc(buffer, 3, buffer[2])) {
        fprintf(stderr, "CRC error for scale factor data\n");
        return -1;
    }

    // Extract scale factor
    int16_t raw_scale_factor = (buffer[0] << 8) | buffer[1];
    *scale_factor = (float)raw_scale_factor / 100.0;

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.pressure, data.temperature, data.scale_factor);
    fflush(data_file); // Ensure data is written to disk immediately

    return 0;
