#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_hdc1080(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure the HDC1080 (example configuration)
    char config_data[3];
    config_data[0] = CONFIGURATION_REG;
    config_data[1] = 0x00; // Resolution: 14-bit, Heater: Off
    config_data[2] = 0x00;

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from HDC1080
int read_hdc1080(sensor_data_t *data) {
    char trigger_data[1];
    char raw_data[4];
    unsigned int temperature_raw, humidity_raw;

    // Trigger temperature and humidity measurement
    trigger_data[0] = TEMPERATURE_REG;
    if (i2cWriteDevice(i2c_handle, trigger_data, 1) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }

    // Wait for conversion (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature and humidity data
    if (i2cReadDevice(i2c_handle, raw_data, 4) != 4) {
        fprintf(stderr, "Failed to read data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    temperature_raw = (raw_data[0] << 8) | raw_data[1];
    humidity_raw = (raw_data[2] << 8) | raw_data[3];

    data->temperature = ((float)temperature_raw / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)humidity_raw / 65536.0) * 100.0;

    return 0;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int retries = 3; // Number of retries for I2C communication

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    printf("HDC1080 data logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data with retries
        int read_success = 0;
        for (int i = 0; i < retries; i++) {
            if (read_hdc1080(&sensor_data) == 0) {
                read_success = 1;
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", i + 1, retries);
                gpioDelay(100000); // Wait 100ms before retrying
            }
        }

        if (read_success) {
            // Log data every 5 seconds
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
        }

        sleep(5); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

