#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define LOG_FILE "temperature_log.txt"

static int i2c_fd = -1;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40
int read_sts40_temperature(float *temperature) {
    uint8_t buf[3];
    int ret;

    // Send measurement command
    uint8_t cmd = MEASURE_HIGH_PRECISION;
    ret = write(i2c_fd, &cmd, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion (at least 10ms)
    usleep(10000); // 10ms

    // Read 3 bytes of data
    ret = read(i2c_fd, buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Verify CRC
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    // Convert data to temperature
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * raw_temperature) / 65535.0;

    return 0;
}

// Function to get ISO 8601 timestamp
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", info);
}

// Function to log temperature to file
int log_temperature(float temperature) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp);

    if (log_fp == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_fp, "%s, %.2f\n", timestamp, temperature);
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    float temperature;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        ret = read_sts40_temperature(&temperature);
        if (ret == 0) {
            ret = log_temperature(temperature);
            if (ret != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

    return 0;
}

