#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t crc)
{
    for (int i = 0; i < len; i++)
    {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
        {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31; // Polynomial: x^8 + x^5 + x^4 + 1
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD >> 8); // MSB
    if (result < 0) {
        fprintf(stderr, "Failed to write MSB of measurement command: %d\n", result);
        return 1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD & 0xFF); // LSB
    if (result < 0) {
        fprintf(stderr, "Failed to write LSB of measurement command: %d\n", result);
        return 1;
    }

    // Wait for measurement (at least 50ms)
    gpioDelay(50);

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read 9 bytes of data: %d\n", result);
        return 1;
    }

    // Validate CRC for pressure and temperature
    if (!validate_crc(buffer, 2, buffer[2])) {
        fprintf(stderr, "CRC check failed for pressure\n");
        return 1;
    }
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "CRC check failed for temperature\n");
        return 1;
    }

    // Convert data
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data->pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data->temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = crc8(data, len, 0xFF);
    return (calculated_crc == crc);
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

