#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_CAPACITY 100
#define CSV_FILE_PATH "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_PATH "/var/log/scd40_error.log"
#define LOGGING_INTERVAL_SEC 60

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86
#define CMD_READ_MEASUREMENT 0xe4b8

// Data Structures
typedef struct {
    float co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
static volatile int running = 1;
static int i2c_handle;
static CircularBuffer buffer;
static pthread_t logging_thread;

// Function Prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
int validate_crc(uint16_t data, uint8_t crc);
int buffer_add(CircularBuffer *buffer, SensorData data);
SensorData buffer_get(CircularBuffer *buffer, int index);
int write_csv(const char *filename, CircularBuffer *buffer);
void *logging_thread_func(void *arg);
void signal_handler(int signal);

// CRC-8-Dallas/Maxim Algorithm
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send Command
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read Data
int read_data(int handle, uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    char buf[9];
    int result = i2cReadDevice(handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    uint8_t co2_msb = buf[0];
    uint8_t co2_lsb = buf[1];
    uint8_t co2_crc = buf[2];

    uint8_t temp_msb = buf[3];
    uint8_t temp_lsb = buf[4];
    uint8_t temp_crc = buf[5];

    uint8_t hum_msb = buf[6];
    uint8_t hum_lsb = buf[7];
    uint8_t hum_crc = buf[8];

    uint8_t co2_data[2] = {co2_msb, co2_lsb};
    uint8_t temp_data[2] = {temp_msb, temp_lsb};
    uint8_t hum_data[2] = {hum_msb, hum_lsb};

    if (!validate_crc(*(uint16_t*)co2_data, co2_crc) ||
        !validate_crc(*(uint16_t*)temp_data, temp_crc) ||
        !validate_crc(*(uint16_t*)hum_data, hum_crc)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    *co2 = *(uint16_t*)co2_data;
    *temperature = *(uint16_t*)temp_data;
    *humidity = *(uint16_t*)hum_data;

    return 0;
}

// Validate CRC
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;
    return (crc8(data_bytes, 2) == crc);
}

// Circular Buffer Add
int buffer_add(CircularBuffer *buffer, SensorData data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count == BUFFER_CAPACITY) {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Circular Buffer Get
SensorData buffer_get(CircularBuffer *buffer, int index) {
    pthread_mutex_lock(&buffer->mutex);
    SensorData data = buffer->data[index];
    pthread_mutex_unlock(&buffer->mutex);
    return data;
}

// Write CSV
int write_csv(const char *filename, CircularBuffer *buffer) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,co2,temperature,humidity\n");
    }

    pthread_mutex_lock(&buffer->mutex);
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->tail + i) % BUFFER_CAPACITY;
        SensorData data = buffer->data[index];
        fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", time(NULL), data.co2, data.temperature, data.humidity);
    }
    pthread_mutex_unlock(&buffer->mutex);

    fclose(fp);
    return 0;
}

// Logging Thread Function
void *logging_thread_func(void *arg) {
    CircularBuffer *buffer = (CircularBuffer *)arg;
    while (running) {
        sleep(LOGGING_INTERVAL_SEC);
        if (write_csv(CSV_FILE_PATH, buffer) != 0) {
            fprintf(stderr, "Failed to write to CSV file\n");
        }
    }
    return NULL;
}

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

int main() {
    // Initialize Circular Buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    pthread_mutex_init(&buffer.mutex, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Start Periodic Measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    sleep(1); // Wait for sensor to start

    // Create Logging Thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, &buffer) != 0) {
        fprintf(stderr, "Failed to create logging thread\n");
        running = 0; // Stop the main loop
    }

    // Set Signal Handler
    signal(SIGINT, signal_handler);

    // Main Loop
    uint16_t co2, temperature, humidity;
    SensorData data;
    while (running) {
        if (read_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            data.co2 = co2;
            data.temperature = temperature / 65536.0 * 175.0 - 45.0; // Convert to Celsius
            data.humidity = humidity / 65536.0 * 100.0;
            buffer_add(&buffer, data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(5);
    }

    // Stop Periodic Measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Join Logging Thread
    pthread_join(logging_thread, NULL);

    // Flush Buffered Data
    if (write_csv(CSV_FILE_PATH, &buffer) != 0) {
        fprintf(stderr, "Failed to flush buffered data\n");
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Destroy Mutex
    pthread_mutex_destroy(&buffer.mutex);

    printf("Program terminated successfully\n");
    return 0;
}

