#define FAN_GPIO 18
#define HYSTERESIS_ON 30.0
#define HYSTERESIS_OFF 28.0
#define LOG_FILE "temperature_log.txt"
#define SLEEP_DURATION 2 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature(int reg);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from a register
float read_temperature(int reg) {
    int raw_data;
    int retries = 3;
    while (retries > 0) {
        raw_data = i2cReadWordData(i2c_handle, reg);
        if (raw_data >= 0) {
            // Success
            return (float)raw_data * 0.02 - 273.15; // Convert to Celsius
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, raw_data);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -273.15; // Indicate error
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > HYSTERESIS_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON\n");
    } else if (object_temp < HYSTERESIS_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

