    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        float object_temp = read_temperature(OBJECT_TEMP_REG);

        if (ambient_temp > -273.0 && object_temp > -273.0) {
            log_temperature(ambient_temp, object_temp);
            control_fan(object_temp);
        } else {
            fprintf(stderr, "Invalid temperature reading. Skipping logging.\n");
        }

        gpioDelay(SLEEP_DURATION * 1000000); // Sleep for 2 seconds
    }

    // Cleanup and exit
    cleanup();
