#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd;

// Function to read data from SHT40 sensor with retries
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        // Convert data
        uint16_t temp_ticks = (buf[0] << 8) | buf[1];
        uint16_t hum_ticks = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (float)temp_ticks / 65535.0;
        *humidity = 100.0 * (float)hum_ticks / 65535.0;

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to handle HTTP requests
void handle_request(int client_socket) {
    char buffer[1024] = {0};
    ssize_t valread;

    valread = recv(client_socket, buffer, 1024, 0);
    if (valread < 0) {
        perror("recv failed");
        close(client_socket);
        return;
    }

    // Send HTTP response
    char response[1024];
    snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>SHT40 Data</h1><p>Temperature: %.2f &deg;C</p><p>Humidity: %.2f %%</p></body></html>", temperature, humidity);

    send(client_socket, response, strlen(response), 0);
    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    i2cClose(i2c_handle);
    close(server_fd);
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    int new_socket;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Main loop
    while (1) {
        // Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening
        }

        // Read sensor data
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            handle_request(new_socket);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            // Send error response
            char error_response[1024];
            snprintf(error_response, sizeof(error_response), "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>Error</title></head><body><h1>Error</h1><p>Failed to read sensor data</p></body></html>");
            send(new_socket, error_response, strlen(error_response), 0);
            close(new_socket);
        }
    }

    // Cleanup (should not reach here in normal operation due to the infinite loop)
    i2cClose(i2c_handle);
    close(server_fd);
    gpioTerminate();

    return 0;
}

