int read_temperature_humidity(int handle, float *temperature, float *humidity)
{
    uint8_t data[4];
    int retries = 3;
    int result;

    // Trigger measurement
    while (retries > 0) {
        result = write_register(handle, MEASUREMENT_CONFIG, 0x00);
        if (result == 0) break;
        retries--;
        gpioDelay(10); // Wait 10ms before retrying
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete (at least 5ms)

    // Read temperature and humidity registers
    retries = 3;
    while (retries > 0) {
        result = read_register(handle, TEMPERATURE_REG, data, 4);
        if (result == 0) break;
        retries--;
        gpioDelay(10); // Wait 10ms before retrying
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature and humidity after multiple retries.\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[2] << 8) | data[3];

