#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0 // CE0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define TARGET_TEMP_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define PID_PERIOD 1.0 // seconds
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Target Temperature Profile
typedef struct {
    float time;
    float temperature;
} TargetProfilePoint;

TargetProfilePoint *target_profile = NULL;
int target_profile_size = 0;

// Function Prototypes
int read_max6675(int spi_handle, float *temperature);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_relay_duty_cycle(int gpio, float duty_cycle);
void log_data(FILE *fp, float temperature, float pid_output);
void load_target_profile(const char *filename, TargetProfilePoint **profile, int *size);
void free_target_profile(TargetProfilePoint *profile, int size);
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_max6675(int spi_handle, float *temperature) {
    char tx_buf[2] = {0x00, 0x00};
    char rx_buf[2];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1; // Indicate error
    }

    // Convert the received data to temperature (Celsius)
    int raw_data = (rx_buf[0] << 8) | rx_buf[1];
    raw_data = raw_data >> 2; // Remove status bits

    if (raw_data & 0x04) {
        fprintf(stderr, "MAX6675: Thermocouple open\n");
        return -1; // Thermocouple open
    }

    *temperature = (float)(raw_data >> 3) * 0.25;
    return 0; // Indicate success
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;

    // Clamp the output to 0.0 to 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set relay duty cycle
void set_relay_duty_cycle(int gpio, float duty_cycle) {
    int pwm_range = 1000; // Adjust as needed
    int pwm_value = (int)(duty_cycle * pwm_range);
    gpioPWM(gpio, pwm_value);
}

// Function to log data to file
void log_data(FILE *fp, float temperature, float pid_output) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pid_output);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to load target temperature profile from file
void load_target_profile(const char *filename, TargetProfilePoint **profile, int *size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening target temperature profile file");
        *profile = NULL;
        *size = 0;
        return;
    }

    char line[256];
    *size = 0;
    while (fgets(line, sizeof(line), fp)) {
        (*size)++;
    }
    rewind(fp);

    *profile = (TargetProfilePoint *)malloc(sizeof(TargetProfilePoint) * (*size));
    if (*profile == NULL) {
        perror("Error allocating memory for target profile");
        fclose(fp);
        *size = 0;
        return;
    }

    int i = 0;
    while (fgets(line, sizeof(line), fp)) {
