int target_profile_size = 0;

// Function Prototypes
int read_max6675(int spi_handle, float *temperature);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_relay_duty_cycle(int gpio, float duty_cycle);
void log_data(FILE *fp, float temperature, float pid_output);
void load_target_profile(const char *filename, TargetProfilePoint **profile, int *size);
void free_target_profile(TargetProfilePoint *profile, int size);
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_max6675(int spi_handle, float *temperature) {
    char tx_buf[2] = {0x00, 0x00};
    char rx_buf[2];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1; // Indicate error
    }

    // Convert the received data to temperature (Celsius)
    int raw_data = (rx_buf[0] << 8) | rx_buf[1];
    raw_data = raw_data >> 2; // Remove status bits

    if (raw_data & 0x04) {
        fprintf(stderr, "MAX6675: Thermocouple open\n");
        return -1; // Thermocouple open
    }

    *temperature = (float)(raw_data >> 3) * 0.25;
    return 0; // Indicate success
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;

    // Clamp the output to 0.0 to 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

