#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <dirent.h>
#include <errno.h>

// Constants
#define DS18B20_DIR "/sys/bus/w1/devices/"
#define LOG_FILE "greenhouse.log"
#define MAX_SENSORS 4
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    char id[20];
    float temperature;
    int present;
} sensor_data_t;

// Structure to hold PID gains
typedef struct {
    float Kp;
    float Ki;
    float Kd;
} pid_gains_t;

// Structure to hold PID state
typedef struct {
    float integral;
    float previous_error;
} pid_state_t;

// Function prototypes
int initialize_gpio();
int read_temperature(const char *sensor_id, float *temperature);
int validate_crc(const char *sensor_id, const char *data);
int find_sensors(sensor_data_t sensors[], int max_sensors);
float calculate_average_temperature(const sensor_data_t sensors[], int num_sensors);
float pid_control(float setpoint, float actual_temperature, pid_gains_t gains, pid_state_t *state);
int set_pwm_duty_cycle(int duty_cycle);
int set_relay_state(int state);
int log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle);
void signal_handler(int signal);

// PID control function
float pid_control(float setpoint, float actual_temperature, pid_gains_t gains, pid_state_t *state) {
    float error = setpoint - actual_temperature;
    state->integral += error * SAMPLE_INTERVAL;
    float derivative = (error - state->previous_error) / SAMPLE_INTERVAL;
    float output = (gains.Kp * error) + (gains.Ki * state->integral) + (gains.Kd * derivative);
    state->previous_error = error;
    return output;
}

// Set PWM duty cycle function
int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }
    gpioPWM(18, duty_cycle * 2.55); // pigpio duty cycle range is 0-255
    return 0;
}

// Set relay state function
int set_relay_state(int state) {
    gpioWrite(17, state); // 1 for ON, 0 for OFF
    return 0;
}

// Log data function
int log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        perror("localtime");
        return -1;
    }
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, average_temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize GPIO function
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(17, PI_OUTPUT); // Relay enable
    gpioSetMode(18, PI_OUTPUT); // PWM output
    gpioSetPWMfrequency(18, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(18, 255); // Set PWM range to 0-255

    return 0;
}

// Read temperature function
int read_temperature(const char *sensor_id, float *temperature) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/w1_slave", DS18B20_DIR, sensor_id);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    fclose(fp);

    if (validate_crc(sensor_id, line1) != 0 || validate_crc(sensor_id, line2) != 0) {
        fprintf(stderr, "Error: CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: Temperature data not found in line 2\n");
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    return 0;
}

// Validate CRC function
int validate_crc(const char *sensor_id, const char *data) {
    // Implement CRC validation if needed (e.g., using a lookup table)
    // This is a placeholder; no actual CRC validation is performed here.
    return 0; // Assume CRC is valid for simplicity
}

// Find sensors function
int find_sensors(sensor_data_t sensors[], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int sensor_count = 0;

    dir = opendir(DS18B20_DIR);
    if (dir == NULL) {
        perror("Error opening directory");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && sensor_count < max_sensors) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(sensors[sensor_count].id, ent->d_name, sizeof(sensors[sensor_count].id) - 1);
            sensors[sensor_count].id[sizeof(sensors[sensor_count].id) - 1] = '\0'; // Ensure null termination
            sensors[sensor_count].temperature = 0.0;
            sensors[sensor_count].present = 1; // Assume present initially
            sensor_count++;
        }
    }

    closedir(dir);
    return sensor_count;
}

// Calculate average temperature function
float calculate_average_temperature(const sensor_data_t sensors[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].present) {
            sum += sensors[i].temperature;
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Return 0 if no valid sensors are present
    }
}

int main(int argc, char *argv[]) {
    float setpoint = 25.0; // Default setpoint
    pid_gains_t gains = {0.5, 0.01, 0.1}; // Default gains
    pid_state_t pid_state = {0.0, 0.0};
    int duty_cycle = 0;
    int relay_state = 0;
    sensor_data_t sensors[MAX_SENSORS];
    int num_sensors;
    float average_temperature;
    float pid_output;

    // Parse command-line arguments
    if (argc > 1) {
        setpoint = atof(argv[1]);
    }
    if (argc > 4) {
        gains.Kp = atof(argv[2]);
        gains.Ki = atof(argv[3]);
        gains.Kd = atof(argv[4]);
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Find sensors
        num_sensors = find_sensors(sensors, MAX_SENSORS);
        if (num_sensors < 0) {
            fprintf(stderr, "Error: Failed to find sensors\n");
            break;
        }

        // Read temperatures from sensors
        for (int i = 0; i < num_sensors; i++) {
            if (sensors[i].present) {
                if (read_temperature(sensors[i].id, &sensors[i].temperature) != 0) {
                    fprintf(stderr, "Error: Failed to read temperature from sensor %s\n", sensors[i].id);
                    sensors[i].present = 0; // Mark sensor as absent
                }
            }
        }

        // Calculate average temperature
        average_temperature = calculate_average_temperature(sensors, num_sensors);

        // PID control
        pid_output = pid_control(setpoint, average_temperature, gains, &pid_state);

        // Set PWM duty cycle and relay state
        duty_cycle = (int)pid_output;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;
        set_pwm_duty_cycle(duty_cycle);
        set_relay_state(1); // Turn on relay

        // Log data
        log_data(average_temperature, setpoint, pid_output, duty_cycle);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    set_pwm_duty_cycle(0); // Turn off PWM
    set_relay_state(0); // Turn off relay

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return 0;
}

