// Find sensors function
int find_sensors(sensor_data_t sensors[], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int sensor_count = 0;

    dir = opendir(DS18B20_DIR);
    if (dir == NULL) {
        perror("Error opening directory");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && sensor_count < max_sensors) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(sensors[sensor_count].id, ent->d_name, sizeof(sensors[sensor_count].id) - 1);
            sensors[sensor_count].id[sizeof(sensors[sensor_count].id) - 1] = '\0'; // Ensure null termination
            sensors[sensor_count].temperature = 0.0;
            sensors[sensor_count].present = 1; // Assume present initially
            sensor_count++;
        }
    }

    closedir(dir);
    return sensor_count;
}

// Calculate average temperature function
float calculate_average_temperature(const sensor_data_t sensors[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].present) {
            sum += sensors[i].temperature;
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Return 0 if no valid sensors are present
    }
}

int main(int argc, char *argv[]) {
    float setpoint = 25.0; // Default setpoint
    pid_gains_t gains = {0.5, 0.01, 0.1}; // Default gains
    pid_state_t pid_state = {0.0, 0.0};
    int duty_cycle = 0;
    int relay_state = 0;
    sensor_data_t sensors[MAX_SENSORS];
    int num_sensors;
    float average_temperature;
    float pid_output;

    // Parse command-line arguments
    if (argc > 1) {
        setpoint = atof(argv[1]);
    }
    if (argc > 4) {
        gains.Kp = atof(argv[2]);
        gains.Ki = atof(argv[3]);
        gains.Kd = atof(argv[4]);
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Find sensors
        num_sensors = find_sensors(sensors, MAX_SENSORS);
        if (num_sensors < 0) {
            fprintf(stderr, "Error: Failed to find sensors\n");
            break;
        }

        // Read temperatures from sensors
        for (int i = 0; i < num_sensors; i++) {
            if (sensors[i].present) {
                if (read_temperature(sensors[i].id, &sensors[i].temperature) != 0) {
                    fprintf(stderr, "Error: Failed to read temperature from sensor %s\n", sensors[i].id);
                    sensors[i].present = 0; // Mark sensor as absent
                }
            }
        }

        // Calculate average temperature
        average_temperature = calculate_average_temperature(sensors, num_sensors);

        // PID control
        pid_output = pid_control(setpoint, average_temperature, gains, &pid_state);

        // Set PWM duty cycle and relay state
        duty_cycle = (int)pid_output;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;
        set_pwm_duty_cycle(duty_cycle);
        set_relay_state(1); // Turn on relay

        // Log data
        log_data(average_temperature, setpoint, pid_output, duty_cycle);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    set_pwm_duty_cycle(0); // Turn off PWM
    set_relay_state(0); // Turn off relay

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return 0;
}

