#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_trigger_measurement(int i2c_handle);
int aht20_read_data(int i2c_handle, uint8_t *data);
float aht20_convert_humidity(uint8_t *data);
void control_relay(int gpio_pin, int state);
void log_humidity(float humidity);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// AHT20 Trigger Measurement
int aht20_trigger_measurement(int i2c_handle) {
    uint8_t command[3] = {0xAC, 0x33, 0x00};
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, (char *)command, 3);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (trigger): %d, retry %d\n", result, retries + 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    fprintf(stderr, "Failed to trigger measurement after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// AHT20 Read Data
int aht20_read_data(int i2c_handle, uint8_t *data) {
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read error: %d, retry %d\n", result, retries + 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    fprintf(stderr, "Failed to read data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// AHT20 Convert Humidity
float aht20_convert_humidity(uint8_t *data) {
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    return ((float)humidity_raw / 0x100000) * 100;
}

// Control Relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log Humidity
void log_humidity(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    uint8_t data[6];
    float humidity;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting humidity monitoring...\n");

    while (!terminate) {
        // Trigger measurement
        if (aht20_trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

            // Read data
            if (aht20_read_data(i2c_handle, data) != 0) {
                fprintf(stderr, "Failed to read data\n");
            } else {
                // Verify status
                status = (data[0] & 0x80) ? 1 : 0; // Check bit 7
                if (status == 0) {
                    // Convert humidity
                    humidity = aht20_convert_humidity(data);

                    // Log humidity
                    log_humidity(humidity);

                    // Control relay
                    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                        control_relay(GPIO_RELAY, 1); // Activate
                    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                        control_relay(GPIO_RELAY, 0); // Deactivate
                    }
                } else {
                    fprintf(stderr, "Sensor busy or not calibrated\n");
                }
            }
        }

        gpioDelay(5000000); // Poll every 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly\n");
    return 0;
}

