        syslog(LOG_ERR, "Failed to read humidity data");
        return -1.0;
    }

    raw_humidity = (data[0] << 8) | data[1];
    humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;

    return humidity;
}

// Function to read temperature from HTU21D
float read_temperature(int fd) {
    uint8_t data[3];
    uint16_t raw_temperature;
    float temperature;

    if (i2c_write_byte(fd, MEASURE_TEMP_HOLD) < 0) {
        syslog(LOG_ERR, "Failed to trigger temperature measurement");
        return -1.0;
    }
    usleep(100000); // Wait for measurement (at least 50ms)

    if (i2c_read_bytes(fd, data, 3) < 0) {
        syslog(LOG_ERR, "Failed to read temperature data");
        return -1.0;
    }

    raw_temperature = (data[0] << 8) | data[1];
    temperature = -46.85 + 175.72 * (raw_temperature / 65536.0);

    return temperature;
}

// Function to format data as JSON
char *format_json(float humidity, float temperature) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 100, "{\"humidity\": %.2f, \"temperature\": %.2f}", humidity, temperature);
    return json_string;
}

// Function to post data to API endpoint
int post_data(const char *json_data) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // HTTP port
    if (inet_pton(AF_INET, "api.example.com", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char request[512];
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", strlen(json_data), json_data);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = false;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, HTU21D_ADDR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Humidity sensor started");

    while (running) {
        float humidity = read_humidity(i2c_fd);
        float temperature = read_temperature(i2c_fd);

        if (humidity >= 0.0 && temperature > -273.0) {
            char *json_data = format_json(humidity, temperature);
            if (json_data != NULL) {
                if (post_data(json_data) == 0) {
                    syslog(LOG_INFO, "Data posted successfully: %s", json_data);
                } else {
                    syslog(LOG_ERR, "Failed to post data");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        sleep(POLL_INTERVAL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    closelog();
    return 0;
}

