#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS 1
#define RETRY_COUNT 3
#define BACKOFF_MS 10
#define LOG_FILE_PREFIX "sensor_log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir(int *motion_detected);
int log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} SensorData;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData data;

        // Read sensor data
        if (read_tmp117(&data.temperature) != 0) {
            fprintf(stderr, "Error reading TMP117\n");
            data.temperature = -999.0; // Indicate error
        }
        if (read_aht20(&data.humidity) != 0) {
            fprintf(stderr, "Error reading AHT20\n");
            data.humidity = -999.0; // Indicate error
        }
        if (read_pir(&data.motion_detected) != 0) {
            fprintf(stderr, "Error reading PIR sensor\n");
            data.motion_detected = -1; // Indicate error
        }

        // Log data
        if (log_data(data.temperature, data.humidity, data.motion_detected) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int init_gpio() {
    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0); // Open I2C device for TMP117
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device for TMP117: %s\n", strerror(errno));
        return 1;
    }
    i2cClose(i2c_handle);

    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0); // Open I2C device for AHT20
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device for AHT20: %s\n", strerror(errno));
        return 1;
    }
    i2cClose(i2c_handle);

    return 0;
}

// Read temperature from TMP117
int read_tmp117(float *temperature) {
    int handle, result;
    unsigned char buf[2];
    int16_t raw_temp;

    handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device for TMP117: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(BACKOFF_MS * 1000); // Delay in microseconds
        }
    }

    i2cClose(handle);

    if (result != 2) {
        fprintf(stderr, "Failed to read TMP117 after multiple retries\n");
        return 1;
    }

    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp * 0.0078125;

    return 0;
}

// Read humidity from AHT20
int read_aht20(float *humidity) {
    int handle, result;
    unsigned char buf[6];
    uint32_t raw_humidity;

    handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device for AHT20: %s\n", strerror(errno));
        return 1;
    }

    // Trigger measurement
    unsigned char init_cmd[3] = {0xBE, 0x08, 0x00};
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(handle, init_cmd, 3);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error triggering AHT20 (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(BACKOFF_MS * 1000); // Delay in microseconds
        }
    }

    if (result != 0) {
        fprintf(stderr, "Failed to trigger AHT20 after multiple retries\n");
        i2cClose(handle);
        return 1;
    }

    gpioDelay(8000); // Wait for measurement (8ms)

    // Read data
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(handle, buf, 6);
        if (result == 6) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading AHT20 (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(BACKOFF_MS * 1000); // Delay in microseconds
        }
    }

    i2cClose(handle);

    if (result != 6) {
        fprintf(stderr, "Failed to read AHT20 after multiple retries\n");
        return 1;
    }

    // Check status bit
    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy\n");
        return 1;
    }

    raw_humidity = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    *humidity = ((float)raw_humidity / 0x100000) * 100;

    return 0;
}

// Read motion detection from PIR sensor
int read_pir(int *motion_detected) {
    *motion_detected = gpioRead(PIR_GPIO);
    return 0;
}

// Log data to CSV file
int log_data(float temperature, float humidity, int motion_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[50];
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Create filename based on date
    strftime(filename, sizeof(filename), "%Y-%m-%d.csv", timeinfo);

    // Get timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    // Write data to log file
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);

    // Close log file
    fclose(log_file);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close I2C device
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

