#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received termination signal. Stopping motor and exiting...");
        gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    return rain_detected;
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
    } else { // Stop
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
    }
    gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
    gpioDelay(5000000); // 5 seconds
    gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on the rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Rain sensor monitoring started.");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0) { // Active low
            log_event("Rain detected!");
            control_motor(1); // Close window
            log_event("Window closed.");
        }

        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();

    return 0;
}

