#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variables for CPU load and pigpio initialization
double cpu_load = 0.0;
int pigpio_initialized = 0;

// Function prototypes
double read_cpu_load();
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    set_led_color(0, 0, 0); // Turn off the LED
    if (pigpio_initialized) {
        gpioTerminate();
    }
    exit(0);
}

// Function to read CPU load from /proc/stat
double read_cpu_load() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    double cpu_usage;
    static unsigned long long prev_total = 0, prev_idle_total = 0;
    unsigned long long total, idle_total;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return 0.0; // Return 0.0 on error
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return 0.0;
    }

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    idle_total = idle + iowait;

    if (prev_total != 0) {
        unsigned long long diff_total = total - prev_total;
        unsigned long long diff_idle = idle_total - prev_idle_total;

        cpu_usage = (double)(diff_total - diff_idle) / diff_total * 100.0;
    } else {
        cpu_usage = 0.0;
    }

    prev_total = total;
    prev_idle_total = idle_total;

    return cpu_usage;
}

