// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20
#define TEMP_THRESHOLD_LOW 25.0
#define TEMP_THRESHOLD_HIGH 40.0
#define TEMP_THRESHOLD_HIGHER 60.0

// Data structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} buffer_entry_t;

// Global variables
int spi_handle;
buffer_entry_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool running = true;

// Function prototypes
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
int set_fan_speed(int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    char rx_buffer[4];
    int result;

    result = spiRead(spi_handle, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI read failed (%d)\n", result);
        return -1;
    }

    // Check for fault bits
    if (rx_buffer[3] & 0x01) {
        fprintf(stderr, "Error: MAX31855 Fault detected!\n");
        return -1;
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 2;
    *temperature = thermocouple_data * 0.25;

    return 0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_THRESHOLD_LOW) {
        return 0;
    } else if (temperature < TEMP_THRESHOLD_HIGH) {
        return (int)(((temperature - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW)) * 50);
    } else if (temperature < TEMP_THRESHOLD_HIGHER) {
        return (int)(((temperature - TEMP_THRESHOLD_HIGH) / (TEMP_THRESHOLD_HIGHER - TEMP_THRESHOLD_HIGH)) * 150 + 50);
    } else {
        return 200;
    }
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Invalid duty cycle value (%d)\n", duty_cycle);
        return -1;
    }

    gpioPWM(FAN_GPIO, duty_cycle);
    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&circular_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%d] Timestamp: %s, Temperature: %.2f, Duty Cycle: %d\n",
               index, timestamp_str, circular_buffer[index].temperature, circular_buffer[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping...\n", signal);
    running = false;
}

int main() {
    float temperature;
    int duty_cycle;
    time_t current_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read temperature from MAX31855
        if (read_max31855(&temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            if (set_fan_speed(duty_cycle) == 0) {
                // Get current timestamp
                current_time = time(NULL);

                // Add data to circular buffer
                add_to_buffer(current_time, temperature, duty_cycle);

                // Print buffer contents periodically
                if (buffer_index % 5 == 0) {
                    print_buffer();
                }
            } else {
                fprintf(stderr, "Error: Failed to set fan speed\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read temperature\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print buffer contents before exiting
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature-controlled fan stopped.\n");

    return 0;
}

