        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    uint8_t data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int32_t *raw_temp) {
    uint8_t write_data[2];
    uint8_t read_data[2];

    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, write_data[0], (char *)&write_data[1], 1) != 1) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(5); // Wait 4.5ms

    write_data[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, write_data[0], (char *)&write_data[0], 0) != 0) {
        fprintf(stderr, "Error writing read temperature command: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)read_data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int32_t *raw_pressure) {
    uint8_t write_data[2];
    uint8_t read_data[3];

    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, write_data[0], (char *)&write_data[1], 1) != 1) {
        fprintf(stderr, "Error writing pressure command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    write_data[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, write_data[0], (char *)&write_data[0], 0) != 0) {
        fprintf(stderr, "Error writing read pressure command: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)read_data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = ((uint32_t)read_data[0] << 16 | (uint32_t)read_data[1] << 8 | (uint32_t)read_data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((int32_t)raw_temp - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((int32_t)raw_temp - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    int32_t X4 = ((int32_t)ac2 * B6) / pow(2, 11);
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) / 4;

    uint32_t X1_pressure = ((uint32_t)ac3 * B6) / pow(2, 13);
    uint32_t X2_pressure = ((uint32_t)b1 * ((B6 * B6) / pow(2, 12))) / pow(2, 16);
    uint32_t X3_pressure = ((X1_pressure + X2_pressure + 2) / pow(2, 2));
    uint32_t B4 = ((uint32_t)ac4 * (X3_pressure + 32768)) / pow(2, 15);
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }

    X1_pressure = (p / pow(2, 8)) * (p / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * p) / pow(2, 16);

    double pressure = p + (X1_pressure + X2_pressure + 3791) / pow(2, 4);
    return pressure;
}

// Function to log data to file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode and pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int32_t raw_temp, raw_pressure;
        double temperature, pressure;

        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading sensor data, retrying...\n");
                gpioDelay(1000); // Wait 1 second before retrying
                continue;
            }

            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temp);
            pressure = calculate_pressure(raw_pressure, raw_temp);

            // Log data
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

