#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define RTD_NOMINAL 100.0 // Pt100
#define RREF 430.0
#define WIRE_RESISTOR 100.0
#define LOG_FILE "rtd_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int read_max31865(int *data);
float calculate_temperature(int rtd_value);
int log_data(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for MAX31865 configuration
typedef struct {
    unsigned char config;
} max31865_config_t;

// Function to initialize the SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MAX31865
int read_max31865(int *data) {
    char tx_buf[4] = {0}; // Dummy data to send (read command)
    char rx_buf[4];

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Combine the received bytes into a 32-bit integer
    *data = (rx_buf[0] << 24) | (rx_buf[1] << 16) | (rx_buf[2] << 8) | rx_buf[3];

    return 0;
}

// Function to calculate temperature from RTD value
float calculate_temperature(int rtd_value) {
    float rtd_resistance = (float)rtd_value * RREF / 32768.0;
    float temperature = (rtd_resistance / WIRE_RESISTOR - 1.0) / 0.00385;
    return temperature;
}

// Function to log data to a file
int log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int rtd_value;
    float temperature;

    // Main loop
    while (!terminate) {
        if (read_max31865(&rtd_value) == 0) {
            // Check for fault bit (bit 2 of byte 3)
            if ((rtd_value >> 2) & 1) {
                fprintf(stderr, "Fault detected!\n");
            } else {
                temperature = calculate_temperature(rtd_value);
                log_data(temperature);
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading MAX31865!\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

