#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA_PRESS_MSB 0xF7
#define BME280_REG_DATA_PRESS_LSB 0xF8
#define BME280_REG_DATA_PRESS_XLSB 0xF9
#define BME280_REG_DATA_TEMP_MSB 0xFA
#define BME280_REG_DATA_TEMP_LSB 0xFB
#define BME280_REG_DATA_TEMP_XLSB 0xFC
#define BME280_REG_DATA_HUM_MSB 0xFD
#define BME280_REG_DATA_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Oversampling settings
#define BME280_OVERSAMPLING_TEMP 2 // x4
#define BME280_OVERSAMPLING_HUM 5  // x16
#define BME280_OVERSAMPLING_PRESS 16 // x128

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int bme280_init();
int bme280_read_calibration_data();
int bme280_read_data(int32_t *temperature, int32_t *pressure, int32_t *humidity);
double bme280_compensate_temperature(int32_t adc_T);
double bme280_compensate_pressure(int32_t adc_P, double t_fine);
double bme280_compensate_humidity(int32_t adc_H, double t_fine);
char* get_timestamp();
int log_data(double temperature, double humidity, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize BME280 sensor
int bme280_init() {
    // Check chip ID
    int chip_id = i2cReadByteData(i2c_handle, BME280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        return -1;
    }
    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (bme280_read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Set humidity oversampling
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, BME280_OVERSAMPLING_HUM) < 0) {
        fprintf(stderr, "Error writing to CTRL_HUM register\n");
        return -1;
    }

    // Set temperature and pressure oversampling and power mode
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, (BME280_OVERSAMPLING_TEMP << 5) | (BME280_OVERSAMPLING_PRESS << 2) | 0x03) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    return 0;
}

// Read calibration data from BME280
int bme280_read_calibration_data() {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)data, 26) < 0) {
        fprintf(stderr, "Error reading calibration data block 1\n");
        return -1;
    }

    uint8_t data2[7];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_26, (char *)data2, 7) < 0) {
        fprintf(stderr, "Error reading calibration data block 2\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib.dig_H1 = data[25];
    calib.dig_H2 = (int16_t)data2[0] | ((int16_t)data2[1] << 8);
    calib.dig_H3 = data2[2];
    calib.dig_H4 = (int16_t)((data2[3] << 4) | (data2[4] & 0x0F));
    calib.dig_H5 = (int16_t)((data2[5] << 4) | (data2[4] >> 4));
    calib.dig_H6 = (int8_t)data2[6];

    return 0;
}

// Read raw temperature, pressure and humidity data from BME280
int bme280_read_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t data[8];

    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_DATA_PRESS_MSB, (char *)data, 8) < 0) {
        fprintf(stderr, "Error reading data block\n");
