#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 0 // Standard resolution

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 10 Hz = 600 samples)
#define BUFFER_SIZE 600

// Sampling interval (50 ms)
#define SAMPLING_INTERVAL 50000 // microseconds

// Structure to hold pressure data with timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} PressureData;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
PressureData pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
float calculate_pressure(int raw_temp, int raw_pressure);
void add_to_buffer(float pressure);
float calculate_rolling_average();
void check_pressure_deviation(float current_pressure, float rolling_average);
void signal_handler(int signal);
void timer_callback();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temp) {
    char data[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int *raw_pressure) {
    char data[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms (OSS = 0)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_temp, int raw_pressure) {
    long x1, x2, x3, b3, b5, b6, p;
