void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data(bmp180_calibration_data_t *cal_data) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal_data->ac1 = (buf[0] << 8) | buf[1];
    cal_data->ac2 = (buf[2] << 8) | buf[3];
    cal_data->ac3 = (buf[4] << 8) | buf[5];
    cal_data->ac4 = (buf[6] << 8) | buf[7];
    cal_data->ac5 = (buf[8] << 8) | buf[9];
    cal_data->ac6 = (buf[10] << 8) | buf[11];
    cal_data->b1 = (buf[12] << 8) | buf[13];
    cal_data->b2 = (buf[14] << 8) | buf[15];
    cal_data->mb = (buf[16] << 8) | buf[17];
    cal_data->mc = (buf[18] << 8) | buf[19];
    cal_data->md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms (OSS = 0)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp, bmp180_calibration_data_t cal_data) {
    long x1 = (((long)raw_temp - (long)cal_data.ac6) * (long)cal_data.ac5) >> 15;
    long x2 = ((long)cal_data.mc << 11) / (x1 + cal_data.md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temp, bmp180_calibration_data_t cal_data) {
    long x1 = (((long)raw_temp - (long)cal_data.ac6) * (long)cal_data.ac5) >> 15;
    long x2 = ((long)cal_data.mc << 11) / (x1 + cal_data.md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)cal_data.b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)cal_data.ac2 * b6) >> 11;
    long b3 = (((((long)cal_data.ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long x5 = ((unsigned long)cal_data.ac4 * (unsigned long)(b6)) >> 15;
    unsigned long x6 = ((unsigned long)cal_data.b1 * (unsigned long)(b6 * b6) >> 12) >> 16;
    unsigned long b4 = x5 + x6;

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to log data to a file
int log_data(double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }

    double temperature = calculate_temperature(raw_temp, calibration_data);
    double pressure = calculate_pressure(raw_pressure, raw_temp, calibration_data);

    if (log_data(temperature, pressure) != 0) {
        fprintf(stderr, "Error logging data\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up timer interrupt (every 500ms)
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer interrupt\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

