#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define SLEEP_SECONDS 5

static volatile int running = 1;
static FILE *log_fp = NULL;

// Function to read the CPU temperature from the thermal zone file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to map the temperature to a PWM duty cycle
int map_temp_to_duty(int temp) {
    int duty_cycle;

    if (temp < 40000) {
        duty_cycle = 0;
    } else if (temp > 70000) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((float)(temp - 40000) / (70000 - 40000)) * 255);
    }

    return duty_cycle;
}

// Function to set the PWM duty cycle on the specified GPIO pin
int set_pwm_duty(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log the current timestamp, temperature, and duty cycle to a file
int log_data(int temp, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s, Temperature: %d, Duty Cycle: %d\n", timestamp, temp, duty_cycle);
    fflush(log_fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int temp, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to PWM output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading CPU temperature, using previous value or exiting.\n");
            // Consider adding a retry mechanism here or exiting if it's critical
        }

        // Map temperature to duty cycle
        duty_cycle = map_temp_to_duty(temp);

        // Set PWM duty cycle
        if (set_pwm_duty(duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, using previous value or exiting.\n");
            // Consider adding a retry mechanism here or exiting if it's critical
        }

        // Log data
        if (log_data(temp, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Stop PWM and terminate pigpio
    gpioPWM(GPIO_PIN, 0); // Stop PWM
    gpioTerminate();

    // Close log file
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    printf("Fan control program stopped.\n");

    return 0;
}

