// BMP280 initialization function
int bmp280_init(int i2c_fd, bmp280_calib_data *calib) {
    uint8_t id;
    uint8_t buffer[26];

    // Check the device ID
    if (i2cReadI2CBlockData(i2c_fd, BMP280_REG_ID, (char *)&id, 1) != 1) {
        fprintf(stderr, "Error reading BMP280 ID: %s\n", strerror(errno));
        return -1;
