}

// BMP280 read raw data function
int bmp280_read_raw(int i2c_fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    if (i2cReadI2CBlockData(i2c_fd, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
