int load_configuration(const char *filename) {
    json_t *root, *target, *kp_val, *ki_val, *kd_val;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        fprintf(stderr, "Using default values: target=%.2f, Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
                DEFAULT_TARGET_TEMPERATURE, DEFAULT_KP, DEFAULT_KI, DEFAULT_KD);
        target_temperature = DEFAULT_TARGET_TEMPERATURE;
        kp = DEFAULT_KP;
        ki = DEFAULT_KI;
        kd = DEFAULT_KD;
        return -1;
    }

    target = json_object_get(root, "target_temperature");
    kp_val = json_object_get(root, "kp");
    ki_val = json_object_get(root, "ki");
    kd_val = json_object_get(root, "kd");

    if (!json_is_real(target) || !json_is_real(kp_val) || !json_is_real(ki_val) || !json_is_real(kd_val)) {
        fprintf(stderr, "Error: Invalid configuration file format\n");
        json_decref(root);
        return -1;
    }

    target_temperature = json_real_value(target);
    kp = json_real_value(kp_val);
    ki = json_real_value(ki_val);
    kd = json_real_value(kd_val);

    json_decref(root);
    printf("Configuration loaded: target=%.2f, Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
           target_temperature, kp, ki, kd);
    return 0;
