    if (spiRead(spi_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1000.0; // Indicate error
    }

    // Extract RTD resistance (12-bit value)
    int rtd_raw = ((data[0] << 8) | data[1]) >> 4;

    // Check for fault
    if (data[3] & 0x07) {
        fprintf(stderr, "Error: MAX31865 fault detected\n");
        return -1000.0; // Indicate error
    }

    // Convert RTD resistance to temperature (PT100)
    rtd_resistance = (double)rtd_raw * 430.0 / 32768.0;

    // Simplified PT100 temperature calculation (approximation)
    temperature = (rtd_resistance - 100.0) / 0.385; // Approximate formula for PT100

    return temperature;
}

