    double current_temperature, error, derivative, output;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Load configuration
    if (load_configuration(CONFIG_FILE) != 0) {
        // Use default values if loading fails
        target_temperature = DEFAULT_TARGET_TEMPERATURE;
        kp = DEFAULT_KP;
        ki = DEFAULT_KI;
        kd = DEFAULT_KD;
    }

    // Configure GPIO18 as PWM output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        current_temperature = read_temperature();

        if (current_temperature < -900.0) {
            fprintf(stderr, "Error: Invalid temperature reading\n");
            pwm_failsafe();
        }

        // Check for temperature limits
        if (current_temperature > MAX_TEMPERATURE) {
            fprintf(stderr, "Error: Temperature exceeds limit (%.2f > %.2f)\n", current_temperature, MAX_TEMPERATURE);
            pwm_failsafe();
        }

        // Calculate error
        error = target_temperature - current_temperature;

        // Calculate integral
        integral += error;

        // Calculate derivative
        derivative = error - previous_error;

        // Calculate output
        output = kp * error + ki * integral + kd * derivative;

        // Limit output to PWM range
        if (output < 0) output = 0;
        if (output > PWM_RANGE) output = PWM_RANGE;

        // Set PWM duty cycle
        duty_cycle = (int)output;
        set_pwm_duty_cycle(duty_cycle);

        // Log data
        gettimeofday(&tv, NULL);
        printf("Temperature: %.2f, Duty Cycle: %d, Error: %.2f, Integral: %.2f, Derivative: %.2f\n",
               current_temperature, duty_cycle, error, integral, derivative);

        // Update previous error
        previous_error = error;

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    set_pwm_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
