        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for fan control as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer callback\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Keep the program running
    while (1) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

