    gpioDelay(5000); // Wait 4.5ms (minimum)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data.\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing pressure command.\n");
        return -1;
    }

    gpioDelay(26000); // Wait 25.5ms (maximum for OSS = 3)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading pressure data.\n");
        return -1;
