#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define KP 1.0
#define KI 0.1
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature, int *fault);
float calculate_duty_cycle(float temperature, float target_temperature, float kp, float ki, float *integral, float *previous_error);
void set_heater_duty_cycle(int gpio, float duty_cycle);
void log_data(FILE *log_file, float temperature, float duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature, int *fault) {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        *fault = 1; // Open circuit
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1;
    }
    if (buffer[3] & 0x02) {
        *fault = 2; // Short to GND
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }
    if (buffer[3] & 0x04) {
        *fault = 3; // Short to VCC
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;

    // Convert to Celsius
    *temperature = raw_temp * 0.25;

    return 0; // Indicate success
}

// Function to calculate duty cycle using PI controller
float calculate_duty_cycle(float temperature, float target_temperature, float kp, float ki, float *integral, float *previous_error) {
    float error = target_temperature - temperature;
    *integral += error;

    // Anti-windup
    float integral_limit = 100.0; // Adjust as needed
    if (*integral > integral_limit) *integral = integral_limit;
    if (*integral < -integral_limit) *integral = -integral_limit;

    float derivative = error - *previous_error;
    float output = kp * error + ki * (*integral);

    *previous_error = error;

    // Clamp duty cycle between 0 and 100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int gpio, float duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0 / 100.0);
    gpioPWM(gpio, pwm_value);
}

// Function to log data to file
void log_data(FILE *log_file, float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(HEATER_GPIO, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, duty_cycle;
    int fault;
    float integral = 0.0;
    float previous_error = 0.0;

    // Main loop
    while (!terminate) {
        if (read_max31855(spi_handle, &temperature, &fault) == 0) {
            duty_cycle = calculate_duty_cycle(temperature, TARGET_TEMPERATURE, KP, KI, &integral, &previous_error);
            set_heater_duty_cycle(HEATER_GPIO, duty_cycle);
            log_data(log_file, temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            set_heater_duty_cycle(HEATER_GPIO, 0.0);
            log_data(log_file, -999.0, 0.0); // Log error
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    set_heater_duty_cycle(HEATER_GPIO, 0.0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

