#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds
#define TEMP_RED   60000
#define TEMP_GREEN 50000
#define TEMP_BLUE  40000

// Define PWM range
#define PWM_RANGE 255

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global volatile flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    int temp;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file!\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file!\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, PWM_RANGE - red);
    gpioPWM(GREEN_PIN, PWM_RANGE - green);
    gpioPWM(BLUE_PIN, PWM_RANGE - blue);
}

int main()
{
    int temp;
    int red, green, blue;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed!\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Handle error, maybe set a default color or exit
        } else {
            // Determine LED color based on temperature
            if (temp >= TEMP_RED) {
                red = 255;
                green = 0;
                blue = 0;
            } else if (temp >= TEMP_GREEN) {
                red = 0;
                green = 255;
                blue = 0;
            } else if (temp >= TEMP_BLUE) {
                red = 0;
                green = 0;
                blue = 255;
            } else {
                red = 0;
                green = 0;
                blue = 0;
            }

            // Set LED color
            set_led_color(red, green, blue);

            // Print temperature and LED color
            printf("Temperature: %d m°C, LED: R=%d, G=%d, B=%d\n", temp, red, green, blue);
        }

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500 ms
    }

    // Cleanup and exit
    set_led_color(255, 255, 255); // Turn off LED
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

