#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read DHT22 data
int read_dht22(DHT22Data *data) {
    int i, j;
    int bit_count = 0;
    int data_bits[40] = {0};
    unsigned int start_time, end_time;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Changed from 40 to 30 us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Check every 1 us
        timeout++;
        if (timeout > 1000) {
            fprintf(stderr, "DHT22 timeout waiting for start signal\n");
            return -1;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 1000) {
                fprintf(stderr, "DHT22 timeout waiting for bit start\n");
                return -1;
            }
        }

        start_time = gpioTick();

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 1000) {
                fprintf(stderr, "DHT22 timeout waiting for bit end\n");
                return -1;
            }
        }
        end_time = gpioTick();

        if ((end_time - start_time) > 40) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert the data bits to bytes
    unsigned char humidity_int = 0;
    unsigned char humidity_dec = 0;
    unsigned char temperature_int = 0;
    unsigned char temperature_dec = 0;
    unsigned char checksum = 0;

    for (i = 0; i < 8; i++) {
        humidity_int <<= 1;
        humidity_int |= data_bits[i];
    }

    for (i = 8; i < 16; i++) {
        humidity_dec <<= 1;
        humidity_dec |= data_bits[i];
    }

    for (i = 16; i < 24; i++) {
        temperature_int <<= 1;
        temperature_int |= data_bits[i];
    }

    for (i = 24; i < 32; i++) {
        temperature_dec <<= 1;
        temperature_dec |= data_bits[i];
    }

    for (i = 32; i < 40; i++) {
        checksum <<= 1;
        checksum |= data_bits[i];
    }

    // Validate checksum
    unsigned char checksum_calculated = humidity_int + humidity_dec + temperature_int + temperature_dec;
    if (checksum != checksum_calculated) {
        fprintf(stderr, "Checksum mismatch: calculated 0x%02X, received 0x%02X\n", checksum_calculated, checksum);
        return -1;
    }

    // Convert data to temperature and humidity
    data->humidity = (float)humidity_int + (float)humidity_dec / 10.0;
    data->temperature = (float)temperature_int + (float)temperature_dec / 10.0;

    return 0;
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to post data to the server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
                res = CURLE_HTTP_RETURNED_ERROR;
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// Function to retry posting data
int retry_post_data(const char *json_data, int retries) {
    int i;
    for (i = 0; i < retries; i++) {
        if (post_data(json_data) == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Retrying post data (%d/%d)...\n", i + 1, retries);
        sleep(RETRY_DELAY_SEC);
    }
    fprintf(stderr, "Failed to post data after %d retries\n", retries);
    return -1; // Failure
}

// Function to cleanup resources
void cleanup() {
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    DHT22Data dht22_data;
    char *json_data;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    atexit(cleanup);

    while (!terminate) {
        // Read DHT22 data
        ret = read_dht22(&dht22_data);
        if (ret == 0) {
            // Format data as JSON
            json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
                // Post data to server with retries
