// Function to read a 16-bit value from the BMP180
static int16_t read_16(int reg)
{
    int16_t msb = wiringPiI2CReadReg8(bmp180_fd, reg);
    int16_t lsb = wiringPiI2CReadReg8(bmp180_fd, reg + 1);
    return (msb << 8) | lsb;
}

// Function to read an unsigned 16-bit value from the BMP180
static uint16_t read_u16(int reg)
{
    uint16_t msb = wiringPiI2CReadReg8(bmp180_fd, reg);
    uint16_t lsb = wiringPiI2CReadReg8(bmp180_fd, reg + 1);
    return (msb << 8) | lsb;
}

// Function to read a signed 16-bit value from the BMP180
static int16_t read_s16(int reg)
{
