// Function to initialize the BMP180 sensor
int init_bmp180()
{
    bmp180_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (bmp180_fd == -1) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_s16(BMP180_REG_CAL_AC1);
    ac2 = read_s16(BMP180_REG_CAL_AC2);
    ac3 = read_s16(BMP180_REG_CAL_AC3);
    ac4 = read_u16(BMP180_REG_CAL_AC4);
    ac5 = read_u16(BMP180_REG_CAL_AC5);
    ac6 = read_u16(BMP180_REG_CAL_AC6);
    b1 = read_s16(BMP180_REG_CAL_B1);
    b2 = read_s16(BMP180_REG_CAL_B2);
    mb = read_s16(BMP180_REG_CAL_MB);
    mc = read_s16(BMP180_REG_CAL_MC);
    md = read_s16(BMP180_REG_CAL_MD);

    // Check for invalid calibration data (e.g., if any of the read values are zero)
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        b1 == 0 || b2 == 0 || mb == 0 || mc == 0 || md == 0) {
        fprintf(stderr, "Invalid calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temp)
{
    if (write_byte(BMP180_REG_CONTROL, 0x2E) != 0) {
        return -1;
    }
    delay(5); // Wait 4.5ms

    *raw_temp = read_s16(BMP180_REG_MSB);
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    if (write_byte(BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        return -1;
    }
    delay(26); // Wait 25.5ms

    int msb = read_byte(BMP180_REG_MSB);
    int lsb = read_byte(BMP180_REG_LSB);
    int xlsb = read_byte(BMP180_REG_XLSB);

    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate the temperature in degrees Celsius
double calculate_temperature(int raw_temp)
{
    long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate the pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temp)
{
    long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long x1_u = ((unsigned long)ac3 * b6) >> 13;
    unsigned long x2_u = ((unsigned long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long b4 = x1_u + x2_u + 32768;

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to log the pressure value to a file
void log_pressure(double pressure)
{
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler for the button
void button_interrupt_handler()
{
    unsigned long current_time = micros();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;

        if (logging_enabled) {
            printf("Logging enabled\n");
        } else {
            printf("Logging disabled\n");
        }
    }
}

// Signal handler for SIGINT
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    if (bmp180_fd != -1) {
        close(bmp180_fd);
    }
    wiringPiSetup(); // Reinitialize wiringPi to avoid issues
    pinMode(BUTTON_PIN, INPUT); // Set button pin to input to avoid issues
    exit(0);
}

int main()
{
    // Setup signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set button pin as input with pull-up resistor
    pinMode(BUTTON_PIN, INPUT);
    pullUpDnControl(BUTTON_PIN, PUD_UP);

    // Set up interrupt handler for falling edge
    if (wiringPiISR(BUTTON_PIN, INT_EDGE_FALLING, button_interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Initialize BMP180 sensor
    if (init_bmp180() != 0) {
        fprintf(stderr, "Error initializing BMP180 sensor\n");
        return 1;
    }

    printf("BMP180 sensor initialized. Press the button to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;

            if (read_raw_temperature(&raw_temp) != 0) {
                fprintf(stderr, "Error reading raw temperature\n");
            } else if (read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading raw pressure\n");
            } else {
                double temperature = calculate_temperature(raw_temp);
                double pressure = calculate_pressure(raw_pressure, raw_temp);
                log_pressure(pressure);
                printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            }
        } else {
            printf("Logging disabled. Press the button to enable.\n");
        }

        delay(2000); // Wait 2 seconds
    }

    return 0;
}

