    if (bmp180_fd != -1) {
        close(bmp180_fd);
    }
    wiringPiSetup(); // Reinitialize wiringPi to avoid issues
    pinMode(BUTTON_PIN, INPUT); // Set button pin to input to avoid issues
    exit(0);
}

