    signal(SIGINT, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set button pin as input with pull-up resistor
    pinMode(BUTTON_PIN, INPUT);
    pullUpDnControl(BUTTON_PIN, PUD_UP);

    // Set up interrupt handler for falling edge
    if (wiringPiISR(BUTTON_PIN, INT_EDGE_FALLING, button_interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Initialize BMP180 sensor
    if (init_bmp180() != 0) {
        fprintf(stderr, "Error initializing BMP180 sensor\n");
        return 1;
    }

    printf("BMP180 sensor initialized. Press the button to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;

            if (read_raw_temperature(&raw_temp) != 0) {
                fprintf(stderr, "Error reading raw temperature\n");
            } else if (read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading raw pressure\n");
            } else {
                double temperature = calculate_temperature(raw_temp);
                double pressure = calculate_pressure(raw_pressure, raw_temp);
                log_pressure(pressure);
                printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            }
        } else {
            printf("Logging disabled. Press the button to enable.\n");
        }

        delay(2000); // Wait 2 seconds
    }

    return 0;
}

