#include <time.h>
#include <stdbool.h>

#define DHT22_GPIO 4
#define API_URL "http://your-library-api-url.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define READ_INTERVAL 10 // seconds

// Global variables for graceful shutdown
static volatile int running = 1;
static char *api_url = NULL;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    unsigned int pulse_lengths[80];
    int pulse_index = 0;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) {
            syslog(LOG_ERR, "DHT22 timeout waiting for start signal");
            return data; // Indicate failure
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) {
            syslog(LOG_ERR, "DHT22 timeout waiting for end of start signal");
            return data; // Indicate failure
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) {
            syslog(LOG_ERR, "DHT22 timeout waiting for end of data signal");
            return data; // Indicate failure
        }
    }

    // Capture pulse lengths
    for (i = 0; i < 80; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 timeout waiting for low pulse");
                return data; // Indicate failure
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 timeout waiting for high pulse");
                return data; // Indicate failure
            }
        }
        long end = gpioTick();
        pulse_lengths[i] = end - start;
    }

    // Decode data
    for (i = 0; i < 40; i++) {
        int index = i * 2 + 1; // Skip the start bit
        if (pulse_lengths[index] > 40) {
            raw_data[byte_index] |= (1 << (7 - bit_count));
        }
        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Validate checksum
    if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF != raw_data[4]) {
        syslog(LOG_ERR, "DHT22 checksum failure");
        return data; // Indicate failure
    }

    // Convert data
    data.humidity = (float)(((raw_data[0] << 8) | raw_data[1])) / 10.0;
    data.temperature = (float)(((raw_data[2] << 8) | raw_data[3])) / 10.0;
    if (data.temperature > 125) {
        data.temperature = data.temperature - 256;
    }
    data.temperature = data.temperature * 9 / 5 + 32;
    data.valid = 1;

    return data;
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to POST data to API
CURLcode post_data(const char *json_data, const char *url) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return res;
}

// Function to retry POST
CURLcode retry_post(const char *json_data, const char *url, int retries) {
    CURLcode res;
    for (int i = 0; i < retries; i++) {
        res = post_data(json_data, url);
        if (res == CURLE_OK) {
            return CURLE_OK;
        }
        syslog(LOG_WARNING, "POST failed, retrying (%d/%d)...", i + 1, retries);
        sleep(BACKOFF_DELAY);
    }
    syslog(LOG_ERR, "POST failed after %d retries", retries);
    return res;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_logger", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Override API URL if provided
    if (api_url != NULL) {
        syslog(LOG_INFO, "Overriding API URL to: %s", api_url);
    }

    // Main loop
    while (running) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.valid) {
            char *json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
                CURLcode res = retry_post(json_data, api_url != NULL ? api_url : API_URL, MAX_RETRIES);
                if (res != CURLE_OK) {
                    syslog(LOG_ERR, "Failed to post data");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 data");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup
    gpioTerminate();
    closelog();

    return 0;
}

