#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables for graceful shutdown
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
float read_cpu_temp();
int read_fan_state();
int set_fan_state(int state);
int log_fan_state(int state);
void signal_handler(int signum);
int validate_cooling_device();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        program_running = 0;
        printf("Received signal %d, shutting down...\n", signum);
    }
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(TEMP_FILE, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        fclose(fp);
        return atoi(buffer) / 1000.0; // Convert to Celsius
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1.0; // Indicate error
}

// Function to read fan state from file
int read_fan_state() {
    FILE *fp;
    char buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_FILE, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening fan file: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            fprintf(stderr, "Error reading fan file: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        fclose(fp);
        return atoi(buffer);
    }

    fprintf(stderr, "Failed to read fan state after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate error
}

// Function to set fan state to a given value
int set_fan_state(int state) {
    FILE *fp;
    char buffer[2];
    int retries = 0;

    snprintf(buffer, sizeof(buffer), "%d", state);

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening fan file for writing: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        if (fputs(buffer, fp) == EOF) {
            fprintf(stderr, "Error writing to fan file: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            continue;
        }

        fclose(fp);
        return 0; // Success
    }

    fprintf(stderr, "Failed to write fan state after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate error
}

// Function to log fan state to file
int log_fan_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: Fan state set to %d\n", timestamp, state);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to validate the cooling device
int validate_cooling_device() {
    FILE *fp;
    char buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
