#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Configuration
#define TARGET_TEMPERATURE 50.0f
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 100       // %
#define SPI_CHANNEL 0
#define SPI_SPEED 500000     // 500 kHz
#define LOG_FILE "heater_log.txt"

// PID Gains
#define Kp 1.0f
#define Ki 0.1f
#define Kd 0.01f

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function Prototypes
float read_temperature();
void set_pwm_duty_cycle(int duty_cycle);
float calculate_pid(float setpoint, float actual_temperature);
void log_data(float temperature, int duty_cycle, float pid_output);
void signal_handler(int signal);

// PID State
float integral = 0.0f;
float previous_error = 0.0f;

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int i;

    // Read 4 bytes from SPI
    if (wiringPiSPIDataRW(SPI_CHANNEL, data, 4) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -273.15f; // Return absolute zero on error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -273.15f;
    } else if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -273.15f;
    } else if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -273.15f;
    }

    // Extract temperature data (ignoring fault bit)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 3;
    float temperature = (float)raw_temp * 0.25f;

    return temperature;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    pwmWrite(1, duty_cycle); // Assuming GPIO1 is PWM0
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature) {
    float error = setpoint - actual_temperature;

    integral += error;
    float derivative = error - previous_error;

    float output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    return output;
}

// Function to log data to file
void log_data(float temperature, int duty_cycle, float pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Disable heater
    set_pwm_duty_cycle(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Reset PID state
    integral = 0.0f;
    previous_error = 0.0f;

    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure PWM on GPIO1
    pinMode(1, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for 1kHz (adjust as needed)

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature
        float temperature = read_temperature();

        // Check for errors
        if (temperature < -273.0f) {
            fprintf(stderr, "Error reading temperature, disabling heater.\n");
            set_pwm_duty_cycle(0);
            log_data(temperature, 0, 0.0f);
            delay(1000); // Wait before retrying
            continue;
        }

        // Check temperature bounds
        if (temperature > 100.0f || temperature < 0.0f) {
            fprintf(stderr, "Temperature out of range, disabling heater.\n");
            set_pwm_duty_cycle(0);
            log_data(temperature, 0, 0.0f);
            delay(1000); // Wait before retrying
            continue;
        }

        // Calculate PID output
        float pid_output = calculate_pid(TARGET_TEMPERATURE, temperature);

        // Limit PID output to PWM range
        if (pid_output < 0) pid_output = 0;
        if (pid_output > PWM_RANGE) pid_output = PWM_RANGE;

        // Set PWM duty cycle
        int duty_cycle = (int)pid_output;
        set_pwm_duty_cycle(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle, pid_output);

        // Wait for 1 second
        delay(1000);
    }

    return 0;
}

