#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMPERATURE_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

float read_cpu_temperature() {
    FILE *fp;
    int temp_milli_celsius;
    float temp_celsius;

    fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1.0;
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Failed to read temperature from file\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    temp_celsius = (float)temp_milli_celsius / 1000.0;
    return temp_celsius;
}

int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);

    return 0;
}

int main() {
    int duty_cycle;
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
