#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define log file name
#define LOG_FILE "flow_log.txt"

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float flow;
    int status;
} sensor_data_t;

// Function prototypes
int read_sensor(int i2c_handle, float *flow);
int validate_checksum(uint8_t data[], int len);
int log_data(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, float *flow) {
    uint8_t buffer[3];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
        if (result == 3) {
            if (validate_checksum(buffer, 3)) {
                // Convert raw data to flow rate (example conversion, adjust as needed)
                int16_t raw_flow = (buffer[0] << 8) | buffer[1];
                *flow = (float)raw_flow / 100.0; // Example scaling factor
                return 0; // Success
            } else {
                fprintf(stderr, "Checksum validation failed for handle %d\n", i2c_handle);
                return -1; // Checksum failure
            }
        } else {
            fprintf(stderr, "I2C read failed (handle %d, result %d), retries remaining: %d\n", i2c_handle, result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (handle %d)\n", i2c_handle);
    return -1; // Failure after retries
}

// Function to validate CRC checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t crc = data[2];
    uint8_t crc_calculated = 0xFF;
    uint8_t data_to_crc[2] = {data[0], data[1]};

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_to_crc[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31; // Polynomial 0x31
            } else {
                crc_calculated = (crc_calculated << 1);
            }
        }
    }

    return (crc_calculated == crc);
}

// Function to log data to a file
int log_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (program_running) {
        // Read data from sensor 1
        if (read_sensor(i2c_handle1, &flow1) == 0) {
            // Read data from sensor 2
            if (read_sensor(i2c_handle2, &flow2) == 0) {
                // Log the data
                if (log_data(flow1, flow2) == 0) {
                    printf("Data logged: Flow1=%.2f, Flow2=%.2f\n", flow1, flow2);
                } else {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor 2\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor 1\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Close I2C handles and terminate pigpio library
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

