#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Quadrature state machine states
enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
};

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_position(float position);
void signal_handler(int signal);

// Structure to hold encoder state
typedef struct {
    int state;
    float position;
} EncoderState;

EncoderState encoder_state = {STATE_00, 0.0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

// Callback function for encoder changes
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int a_val = gpioRead(ENCODER_A_PIN);
    int b_val = gpioRead(ENCODER_B_PIN);

    // Determine the new state based on the current state and encoder values
    switch (encoder_state.state) {
        case STATE_00:
            if (a_val && b_val) encoder_state.state = STATE_01;
            else if (a_val && !b_val) encoder_state.state = STATE_10;
            else if (!a_val && b_val) encoder_state.state = STATE_11;
            break;
        case STATE_01:
            if (a_val && b_val) encoder_state.state = STATE_00;
            else if (a_val && !b_val) encoder_state.state = STATE_11;
            else if (!a_val && b_val) encoder_state.state = STATE_10;
            break;
        case STATE_11:
            if (a_val && b_val) encoder_state.state = STATE_00;
            else if (a_val && !b_val) encoder_state.state = STATE_01;
            else if (!a_val && b_val) encoder_state.state = STATE_10;
            break;
        case STATE_10:
            if (a_val && b_val) encoder_state.state = STATE_00;
            else if (a_val && !b_val) encoder_state.state = STATE_01;
            else if (!a_val && b_val) encoder_state.state = STATE_11;
            break;
    }

    // Update the position based on the state
    switch (encoder_state.state) {
        case STATE_00:
            encoder_state.position += 90.0;
            break;
        case STATE_01:
            encoder_state.position += 180.0;
            break;
        case STATE_11:
            encoder_state.position += 270.0;
            break;
        case STATE_10:
            encoder_state.position += 0.0;
            break;
    }

    // Normalize the position to be between 0 and 360
    while (encoder_state.position >= 360.0) {
        encoder_state.position -= 360.0;
    }

    // Log the position
    log_position(encoder_state.position);
}

// Function to log the current position to a file
void log_position(float position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    // Set up the callback function for encoder changes
    gpioSetAlertFuncEx(ENCODER_A_PIN, encoder_callback, NULL);
    gpioSetAlertFuncEx(ENCODER_B_PIN, encoder_callback, NULL);

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

