#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define DEBOUNCE_DELAY_US 500

volatile unsigned long pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

// Function prototypes
void *calculate_rpm(void *arg);
void pulse_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to pass arguments to the thread
typedef struct {
    int gpio_pin;
} thread_args_t;

// Interrupt service routine (ISR)
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        gpioDelay(DEBOUNCE_DELAY_US);
        if (gpioRead(gpio) == PI_HIGH) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
    }
}

// Thread function to calculate RPM
void *calculate_rpm(void *arg) {
    thread_args_t *args = (thread_args_t *)arg;
    int gpio_pin = args->gpio_pin;
    unsigned long last_pulse_count = 0;
    double rpm = 0.0;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        sleep(1);

        pthread_mutex_lock(&pulse_mutex);
        unsigned long current_pulse_count = pulse_count;
        pthread_mutex_unlock(&pulse_mutex);

        rpm = (double)(current_pulse_count - last_pulse_count) * 60.0;
        last_pulse_count = current_pulse_count;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (log_file != NULL) {
            fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file not opened.\n");
        }
    }

    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupt
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int result;
    pthread_t rpm_thread;
    thread_args_t thread_args;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin mode to input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-down resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error registering ISR\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Create thread arguments
    thread_args.gpio_pin = GPIO_PIN;

    // Create RPM calculation thread
    result = pthread_create(&rpm_thread, NULL, calculate_rpm, &thread_args);
    if (result != 0) {
        fprintf(stderr, "Error creating RPM thread\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main thread waits for the RPM thread to finish (never happens in this example)
    pthread_join(rpm_thread, NULL);

    return 0;
}

