#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_RATE_SCALE_FACTOR 0.066 // uL/min per raw unit (example value, check datasheet)
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "flow_log.csv"
#define SLEEP_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t raw_flow_rate;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_to_flow_rate(uint16_t raw_flow_rate);
int validate_crc(uint16_t data, uint8_t crc);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data from the SLF3S-4000B
int read_sensor_data(sensor_data_t *data) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    data->raw_flow_rate = (buf[0] << 8) | buf[1];
    data->crc = buf[2];

    return 0;
}

// Convert raw sensor data to flow rate in uL/min
float convert_to_flow_rate(uint16_t raw_flow_rate) {
    return (float)raw_flow_rate * FLOW_RATE_SCALE_FACTOR;
}

// Validate CRC checksum
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t calculated_crc = CRC_INITIAL_VALUE;
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    for (int i = 0; i < 2; i++) {
        calculated_crc ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (calculated_crc & 0x80) {
                calculated_crc = (calculated_crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                calculated_crc <<= 1;
            }
        }
    }

    return (calculated_crc == crc);
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (validate_crc(sensor_data.raw_flow_rate, sensor_data.crc)) {
                float flow_rate = convert_to_flow_rate(sensor_data.raw_flow_rate);
                log_flow_rate(flow_rate);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SLEEP_MS); // Sleep for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

