    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4]; // Buffer to hold the received data
    int result;

    // Read TVOC
    result = i2cReadI2CBlockData(i2c_handle, TVOC_REGISTER, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading TVOC data: %d\n", result);
        return -1;
    }
    data->tvoc = (buf[1] << 8) | buf[0];

    // Read eCO2
    result = i2cReadI2CBlockData(i2c_handle, ECO2_REGISTER, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading eCO2 data: %d\n", result);
        return -1;
    }
    data->eco2 = (buf[1] << 8) | buf[0];

    return 0;
}

// Function to calculate IAQ index (example)
int calculate_iaq(sensor_data_t data) {
    // Simple linear mapping (replace with actual calibration data)
    int iaq_index = (data.tvoc + data.eco2) / 2; // Example calculation
    if (iaq_index < 0) iaq_index = 0;
    if (iaq_index > 100) iaq_index = 100;
    return iaq_index;
}

// Function to log data to CSV file
int log_data(int iaq_index, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, iaq_index, data.tvoc, data.eco2);
    fclose(log_file);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    sensor_data_t sensor_data;
    int iaq_index;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate IAQ index
            iaq_index = calculate_iaq(sensor_data);

            // Log data
            if (log_data(iaq_index, sensor_data) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }

            printf("IAQ: %d, TVOC: %d ppb, eCO2: %d ppm\n", iaq_index, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

