#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pin connected to the TTP223B sensor
#define SENSOR_GPIO 17

// Define the consumer label for the GPIO pin
#define CONSUMER_LABEL "ttp223_tamper"

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME_MS 100

// Define the tamper detection duration in seconds
#define TAMPER_DURATION_SEC 5

// Global variable to store the last touch time
static volatile struct timespec last_touch_time = {0, 0};

// Function prototypes
int initialize_gpio();
int read_sensor();
void handle_tamper_event();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set the GPIO pin as an input
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", SENSOR_GPIO, strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Set the pull-up/down resistor (optional, adjust as needed)
    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d: %s\n", SENSOR_GPIO, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_GPIO);
    if (sensor_value < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n", SENSOR_GPIO, strerror(errno));
        return -1;
    }
    return sensor_value;
}

// Function to handle a tamper event
void handle_tamper_event() {
    printf("Tamper event detected!\n");
}

// Function to cleanup the GPIO resources
void cleanup_gpio() {
    printf("Cleaning up GPIO resources...\n");
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up and exiting...\n", signal);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO library
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Monitoring GPIO %d...\n", SENSOR_GPIO);

    // Main loop
    while (1) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        // Check if the sensor is touched (HIGH)
        if (sensor_value == 1) {
            struct timespec current_time;
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                cleanup_gpio();
                return EXIT_FAILURE;
            }

            // Calculate the time difference in seconds
            double time_diff = (current_time.tv_sec - last_touch_time.tv_sec) + (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000000000.0;

            // Check if the tamper duration has been exceeded
            if (time_diff >= TAMPER_DURATION_SEC) {
                handle_tamper_event();
                last_touch_time = current_time; // Update the last touch time
            }
        } else {
            // Reset the last touch time when the sensor is released
            last_touch_time.tv_sec = 0;
            last_touch_time.tv_nsec = 0;
        }

        // Delay for the debounce time
        gpioDelay(DEBOUNCE_TIME_MS * 1000); // Convert milliseconds to microseconds
    }

    return 0;
}

