#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Constants
#define I2S_DEVICE "default" // ALSA device name
#define GPIO_PIN 17          // GPIO pin for L/R channel select
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 2        // 16-bit samples
#define FILENAME "audio_capture.pcm"

// Global variables
snd_pcm_t *pcm_handle = NULL;
FILE *output_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle, snd_pcm_hw_params_t **hw_params);
int init_gpio(int gpio_pin);
int select_channel(int gpio_pin, int channel);
int capture_audio(snd_pcm_t *pcm_handle, FILE *output_file, int gpio_pin);
int write_to_file(FILE *file, const void *buffer, size_t size);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle, snd_pcm_hw_params_t **hw_params) {
    int rc;
    snd_pcm_hw_params_t *params;

    rc = snd_pcm_open(pcm_handle, I2S_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(rc));
        return -1;
    }

    snd_pcm_hw_params_alloca(&params);

    rc = snd_pcm_hw_params_any(*pcm_handle, params);
    if (rc < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_access(*pcm_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_format(*pcm_handle, params, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_channels(*pcm_handle, params, NUM_CHANNELS);
    if (rc < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    rc = snd_pcm_hw_params_set_rate_near(*pcm_handle, params, &rate, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params(*pcm_handle, params);
    if (rc < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    *hw_params = params;
    return 0;
}

// Initialize GPIO
int init_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    return 0;
}

// Select I2S channel
int select_channel(int gpio_pin, int channel) {
    if (channel != 0 && channel != 1) {
        fprintf(stderr, "Invalid channel selection: %d\n", channel);
        return -1;
    }

    gpioWrite(gpio_pin, channel);
    return 0;
}

// Capture audio
int capture_audio(snd_pcm_t *pcm_handle, FILE *output_file, int gpio_pin) {
    int rc;
    int16_t *buffer = (int16_t *)malloc(SAMPLE_SIZE * NUM_CHANNELS);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate buffer\n");
        return -1;
    }

    while (!terminate) {
        rc = snd_pcm_readi(pcm_handle, buffer, 1); // Read one frame
        if (rc == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (rc < 0) {
            fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(rc));
            break;
        } else if (rc != 1) {
            fprintf(stderr, "Short read, read %d frames\n", rc);
        }

        // Write to file
        if (write_to_file(output_file, buffer, SAMPLE_SIZE * NUM_CHANNELS) != 0) {
            fprintf(stderr, "Error writing to file\n");
            break;
        }

        // Select channel (left or right)
        if (select_channel(gpio_pin, 0) != 0) {
            fprintf(stderr, "Error selecting left channel\n");
            break;
        }
        usleep(1000); // 1ms delay

        if (select_channel(gpio_pin, 1) != 0) {
            fprintf(stderr, "Error selecting right channel\n");
            break;
        }
        usleep(1000); // 1ms delay
    }

    free(buffer);
    return 0;
}

// Write to file
int write_to_file(FILE *file, const void *buffer, size_t size) {
    size_t bytes_written = fwrite(buffer, 1, size, file);
    if (bytes_written != size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, size);
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    if (output_file != NULL) {
        fclose(output_file);
    }

    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize ALSA
    if (init_alsa(&pcm_handle, NULL) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Open output file
    output_file = fopen(FILENAME, "wb");
    if (output_file == NULL) {
        fprintf(stderr, "Error opening output file\n");
        cleanup();
        return 1;
    }

    // Capture audio
    if (capture_audio(pcm_handle, output_file, GPIO_PIN) != 0) {
        fprintf(stderr, "Audio capture failed\n");
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

