#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100 // Hz

// Define debounce time (50ms)
#define DEBOUNCE_TIME 50000 // microseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int pigpio_initialized;
} ProgramState;

ProgramState state = {0};

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    state.pigpio_initialized = 1;

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the flame sensor
int read_flame_sensor() {
    int sensor_value = gpioRead(FLAME_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to control the fan
void control_fan(int flame_detected) {
    if (flame_detected == 0) {
        gpioPWM(FAN_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(FAN_PIN, 0);   // Turn off fan
    }
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop PWM
    gpioPWM(FAN_PIN, 0);

    // Reset GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT);         // Set back to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    if (state.pigpio_initialized) {
        gpioTerminate();
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Log program start
    log_event("Program started");

    // Main loop
    int flame_detected = 0;
    int last_sensor_value = 1; // Initialize to no flame detected
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (sensor_value == 0 && last_sensor_value == 1) {
            // Flame detected
            flame_detected = 1;
            log_event("Flame detected");
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        } else if (sensor_value == 1 && last_sensor_value == 0) {
            // Flame ended
            flame_detected = 0;
            log_event("Flame ended");
        }

        last_sensor_value = sensor_value;

        control_fan(flame_detected);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000;

        if (elapsed_time < DEBOUNCE_TIME) {
            gpioDelay(DEBOUNCE_TIME - elapsed_time); // Debounce
        }

        gpioDelay(50000); // Check every 50ms
    }

    // Log program shutdown
    log_event("Program shutdown");

    // Cleanup and exit
    cleanup();
    return 0;
}

