#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0
#define FRAME_TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define HEATMAP_SIZE 32768
#define MAGIC_NUMBER 4144
#define LOG_FILE_NAME "radar_data.bin"

// Configuration structure
typedef struct {
    double start_frequency;
    double end_frequency;
    int num_chirps;
    int num_samples;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int configure_radar(radar_config_t config);
int capture_frame(uint8_t *heatmap_data);
int log_data(radar_config_t config, uint8_t *heatmap_data);
void signal_handler(int signal);
void data_ready_callback(int gpio, int level, uint32_t tick);

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Data ready callback function
void data_ready_callback(int gpio, int level, uint32_t tick) {
    static uint8_t heatmap_data[HEATMAP_SIZE];
    static int frame_number = 0;
    static struct timespec start_time, end_time;

    if (level == 1) { // Rising edge
        clock_gettime(CLOCK_REALTIME, &start_time);
    } else if (level == 0) { // Falling edge
        clock_gettime(CLOCK_REALTIME, &end_time);

        // Calculate time difference
        double time_diff = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

        // Capture frame
        if (capture_frame(heatmap_data) != 0) {
            fprintf(stderr, "Error capturing frame\n");
            return;
        }

        // Log data
        radar_config_t config = {77.0, 79.0, 64, 256};
        if (log_data(config, heatmap_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Frame %d captured and logged in %.6f seconds\n", frame_number, time_diff);
        frame_number++;
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FRAME_TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_DOWN); // Pull down to avoid floating

    // Set up interrupt on data ready GPIO
    if (gpioSetISRFuncEx(DATA_READY_GPIO, RISING_EDGE, 0, data_ready_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure radar (placeholder)
int configure_radar(radar_config_t config) {
    // In a real implementation, this would send configuration commands to the AWR1642
    printf("Radar configured: Start Freq=%.2f GHz, End Freq=%.2f GHz, Chirps=%d, Samples=%d\n",
           config.start_frequency, config.end_frequency, config.num_chirps, config.num_samples);
    return 0;
}

// Capture frame
int capture_frame(uint8_t *heatmap_data) {
    // Trigger frame capture
    gpioWrite(FRAME_TRIGGER_GPIO, 1);
    gpioDelay(1); // Small delay for trigger to settle
    gpioWrite(FRAME_TRIGGER_GPIO, 0);

    // Read data from SPI
    int bytes_read = spiRead(spi_handle, (char *)heatmap_data, HEATMAP_SIZE);
    if (bytes_read != HEATMAP_SIZE) {
        fprintf(stderr, "SPI read failed: %d bytes read (expected %d)\n", bytes_read, HEATMAP_SIZE);
        return -1;
    }

    return 0;
}

// Log data
int log_data(radar_config_t config, uint8_t *heatmap_data) {
    // Open log file in append binary mode
    log_file = fopen(LOG_FILE_NAME, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Write magic number
    uint32_t magic = MAGIC_NUMBER;
    fwrite(&magic, sizeof(uint32_t), 1, log_file);

    // Write timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fwrite(&ts, sizeof(struct timespec), 1, log_file);

    // Write configuration
    fwrite(&config, sizeof(radar_config_t), 1, log_file);

    // Write frame data
    fwrite(heatmap_data, sizeof(uint8_t), HEATMAP_SIZE, log_file);

    // Close log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure radar
    radar_config_t config = {77.0, 79.0, 64, 256};
    if (configure_radar(config) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Keep the program running until a signal is received
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

