    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = -1; // Initialize to an invalid state

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_flame_sensor();

        if (current_state != previous_state) {
            if (log_flame_state(current_state) != 0) {
                fprintf(stderr, "Error logging flame state\n");
            }
            previous_state = current_state;
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

