int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor(int i2c_handle, sensor_config_t config) {
    int result, retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteWordData(i2c_handle, CONFIG_REG, config.config_value);
        if (result == 0) {
            return 0; // Success
        } else {
            log_error("Failed to write to config register, retrying...");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    log_error("Failed to write to config register after multiple retries.");
    return -1; // Failure
}

