        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for error log.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - ERROR: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        free(timestamp);
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    free(timestamp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
}

