    log_file = fopen("light_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Open data file
    data_file = fopen("light_data.txt", "a");
    if (data_file == NULL) {
        perror("Failed to open data file");
        log_error("Failed to open data file.");
        cleanup();
        return 1;
    }

