volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
    }
}

int main() {
    FILE *log_file = NULL;
    int gpio_status;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    fprintf(stdout, "Flame detection program started. Logging to %s\n", LOG_FILE);

    while (!terminate) {
        // Read GPIO pin value
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status >= 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data to file
            fprintf(log_file, "%s Flame Detected: %s\n", timestamp, (gpio_status == 0) ? "YES" : "NO");
            fflush(log_file); // Ensure data is written to disk immediately

            // Log data to console
            printf("%s Flame Detected: %s\n", timestamp, (gpio_status == 0) ? "YES" : "NO");
        } else {
            fprintf(stderr, "Error reading GPIO pin: %d\n", gpio_status);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function is in milliseconds
    }

    // Cleanup
    fprintf(stdout, "Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Exiting.\n");
    return 0;
}

