#define CHANNEL_5_PIN 6
#define CHANNEL_6_PIN 7
#define CHANNEL_7_PIN 8
#define CHANNEL_8_PIN 9

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to read the state of a single GPIO pin
int read_channel(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the state of all channels to the console
void log_channel_state(int channel1, int channel2, int channel3, int channel4, int channel5, int channel6, int channel7, int channel8) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: %d %d %d %d %d %d %d %d\n", timestamp, channel1, channel2, channel3, channel4, channel5, channel6, channel7, channel8);
}

