#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define the GPIO pins connected to the TTP226 sensors
#define SENSOR_PINS {2, 3, 4, 5, 6, 7, 8, 9}

// Define the number of sensors
#define NUM_SENSORS 8

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nSignal received, terminating program...\n");
    terminate = 1;
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Define the sensor pins as inputs with pull-down resistors
    int sensor_pins[] = SENSOR_PINS;
    for (int i = 0; i < NUM_SENSORS; i++)
    {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    return 0;
}

// Function to read the sensor values
int read_sensors(int *sensor_values)
{
    int sensor_pins[] = SENSOR_PINS;
    for (int i = 0; i < NUM_SENSORS; i++)
    {
        sensor_values[i] = gpioRead(sensor_pins[i]);
        if (sensor_values[i] < 0)
        {
            fprintf(stderr, "Error reading sensor %d\n", i + 1);
            return -1;
        }
    }
    return 0;
}

// Function to format the sensor data into a string
void format_data(int *sensor_values, char *buffer, size_t buffer_size)
{
    snprintf(buffer, buffer_size, "CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3],
             sensor_values[4], sensor_values[5], sensor_values[6], sensor_values[7]);
}

// Function to print the sensor data with a timestamp
void print_data(const char *data)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    printf("[%ldms] %s\n", milliseconds, data);
}

int main()
{
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and configure the GPIO pins
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Allocate memory for the sensor values
    int *sensor_values = (int *)malloc(NUM_SENSORS * sizeof(int));
    if (sensor_values == NULL)
    {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        return 1;
    }

    // Allocate memory for the formatted data string
    char *data_string = (char *)malloc(256 * sizeof(char)); // Adjust size as needed
    if (data_string == NULL)
    {
        fprintf(stderr, "Memory allocation failed\n");
        free(sensor_values);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate)
    {
        // Read the sensor values
        if (read_sensors(sensor_values) == 0)
        {
            // Format the data
            format_data(sensor_values, data_string, 256);

            // Print the data
            print_data(data_string);
        }
        else
        {
            fprintf(stderr, "Error reading sensors, retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Free the allocated memory
    free(sensor_values);
    free(data_string);

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

