#include <string.h>

// Define the GPIO pins connected to the TTP226 sensors
const int sensor_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of all sensors
int read_sensors(int *sensor_values) {
    for (int i = 0; i < num_sensors; i++) {
        int pin = sensor_pins[i];
        int value = gpioRead(pin);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor on pin %d: %d\n", pin, value);
            return -1; // Indicate an error
        }
        sensor_values[i] = value;
    }
    return 0; // Indicate success
}

// Function to format the sensor data into a CSV string
int format_csv(int *sensor_values, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    int offset = snprintf(buffer, buffer_size, "%s", timestamp);
    for (int i = 0; i < num_sensors; i++) {
        offset += snprintf(buffer + offset, buffer_size - offset, ",%d", sensor_values[i]);
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_sensors; i++) {
        int pin = sensor_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", pin);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_OFF) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int sensor_values[num_sensors];

        // Read the sensor values
        if (read_sensors(sensor_values) != 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        // Format the data into a CSV string
        char csv_string[256]; // Adjust size as needed
        if (format_csv(sensor_values, csv_string, sizeof(csv_string)) != 0) {
            fprintf(stderr, "Error formatting CSV, exiting...\n");
            break;
        }

        // Print the CSV string to stdout
        printf("%s\n", csv_string);

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

