#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 7

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int tilt_state;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO7 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO state
        tilt_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate GPIO read
        if (tilt_state != 0 && tilt_state != 1) {
            fprintf(stderr, "Error: Invalid GPIO read: %d\n", tilt_state);
            gpio_status = gpioInitialise(); // Re-initialize pigpio
            if (gpio_status < 0) {
                fprintf(stderr, "pigpio re-initialisation failed: %d\n", gpio_status);
                program_running = 0; // Exit loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Print tilt state
        if (tilt_state == 0) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        // Wait 100 milliseconds
        gpioDelay(100);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

