#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5 // ml/min
#define LOG_FILE "flow_log.txt"
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INITIAL 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_flow_rate(int i2c_handle, float *flow_rate);
int validate_crc(uint8_t data[], int len);
void log_data(float flow_rate1, float flow_rate2, float avg_flow_rate);
void control_alarm(float avg_flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int i2c_handle;
    int address;
} sensor_t;

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read flow rate from the sensor
int read_flow_rate(int i2c_handle, float *flow_rate) {
    uint8_t buffer[3];
    int result;

    // Send start command (0x36 for continuous measurement without averaging)
    result = i2cWriteByte(i2c_handle, 0x36);
    if (result != 0) {
        fprintf(stderr, "Error writing start command: %d\n", result);
        return -1;
    }

    // Wait 100ms
    gpioDelay(100000); // 100ms = 100000 microseconds

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate CRC
    if (!validate_crc(buffer, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to flow rate (ml/min)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 120.0; // Scaling factor from datasheet

    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// Function to log data to file
void log_data(float flow_rate1, float flow_rate2, float avg_flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Avg: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow_rate1, flow_rate2, avg_flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the alarm
void control_alarm(float avg_flow_rate) {
    if (avg_flow_rate < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO HIGH
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO LOW
    }
}

// Signal handler for graceful shutdown
