    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioSetMode(ALARM_GPIO, PI_INPUT); // Set GPIO to input mode
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2, avg_flow_rate;

    // Main loop
    while (!terminate) {
        // Read flow rates from sensors
        if (read_flow_rate(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Error reading from sensor 1\n");
            flow_rate1 = -1.0; // Indicate error
        }
        if (read_flow_rate(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading from sensor 2\n");
            flow_rate2 = -1.0; // Indicate error
        }

        // Calculate average flow rate
        int valid_readings = 0;
        float sum = 0.0;
        if (flow_rate1 >= 0) {
            sum += flow_rate1;
            valid_readings++;
        }
        if (flow_rate2 >= 0) {
            sum += flow_rate2;
            valid_readings++;
        }

        if (valid_readings > 0) {
            avg_flow_rate = sum / valid_readings;
        } else {
            avg_flow_rate = -1.0; // Indicate no valid readings
        }

        // Log data
        log_data(flow_rate1, flow_rate2, avg_flow_rate);

        // Control alarm
        if (avg_flow_rate >= 0) {
            control_alarm(avg_flow_rate);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

