#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 7
#define BUFFER_SIZE 100

// Structure to hold sensor data with timestamp
typedef struct {
    time_t timestamp;
    int sensor_value;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int sensor_value);
void print_buffer();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Add to circular buffer
        add_to_buffer(sensor_value);

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpio's delay function
    }

    // Print the contents of the buffer before exiting
    print_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library and configure GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add sensor data to the circular buffer
void add_to_buffer(int sensor_value) {
    time_t current_time = time(NULL);

    buffer[buffer_index].timestamp = current_time;
    buffer[buffer_index].sensor_value = sensor_value;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate the correct index
        char timestamp_str[30];
        struct tm *tm_info = localtime(&buffer[index].timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("Timestamp: %s, Sensor Value: %d\n", timestamp_str, buffer[index].sensor_value);
    }
    printf("--- End of Buffer ---\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

