#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x4C
#define MODE_REG 0x02
#define MODE_NORMAL 0x00
#define MODE_SLEEP 0x01
#define DATA_REG_X_L 0x08
#define DATA_REG_X_H 0x09
#define DATA_REG_Y_L 0x0A
#define DATA_REG_Y_H 0x0B
#define DATA_REG_Z_L 0x0C
#define DATA_REG_Z_H 0x0D
#define SAMPLE_INTERVAL_MS 500
#define SENSOR_ACTIVE_TIMEOUT_S 1
#define CSV_FILE "fan_health.csv"

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int set_d7s_mode(int fd, uint8_t mode);
int is_sensor_active(int fd);
int read_d7s_data(int fd, int16_t *x, int16_t *y, int16_t *z);
int append_data_to_csv(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading block from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Set D7S mode function
int set_d7s_mode(int fd, uint8_t mode) {
    if (i2c_write_reg(fd, MODE_REG, mode) != 0) {
        fprintf(stderr, "Error setting D7S mode to 0x%02X\n", mode);
        return -1;
    }
    return 0;
}

// Check sensor activity function
int is_sensor_active(int fd) {
