#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2
#define LOG_FILE "stall_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} SensorData;

// Function prototypes
int initialize_gpio();
SensorData read_sensors();
int is_stall_confirmed(SensorData data);
void log_stall_event(time_t timestamp);
void signal_handler(int signal);
void cleanup();

int main() {
    time_t last_stall_time = 0;
    SensorData current_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Stall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_data = read_sensors();

        if (is_stall_confirmed(current_data)) {
            time_t current_time = time(NULL);
            if (current_time - last_stall_time >= STALL_DURATION_SEC) {
                log_stall_event(current_time);
                last_stall_time = current_time;
            }
        } else {
            last_stall_time = 0; // Reset stall timer if stall is not confirmed
        }

        gpioDelay(100); // Delay for 100ms
    }

    cleanup();
    printf("Stall detection stopped.\n");
    return 0;
}

// Initializes the pigpio library and sets the GPIO modes.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0;
}

// Reads the sensor values from the GPIO pins.
SensorData read_sensors() {
    SensorData data;
    data.sensor1_value = gpioRead(SENSOR_1_GPIO);
    data.sensor2_value = gpioRead(SENSOR_2_GPIO);
    return data;
}

// Checks if a stall is confirmed based on the sensor readings.
int is_stall_confirmed(SensorData data) {
    return (data.sensor1_value == 0 && data.sensor2_value == 0);
}

// Logs a stall event to the log file with a timestamp.
void log_stall_event(time_t timestamp) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s\n", timestamp_str) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file); // Ensure data is written to disk
    printf("Stall confirmed at: %s\n", timestamp_str);
}

// Signal handler to catch SIGINT and SIGTERM signals.
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d).  Exiting gracefully.\n", signal);
}

// Cleanup function to release resources.
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

