#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile int running = 1;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an alert to the flood_log.txt file
void log_alert() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening flood_log.txt");
        return;
    }
    fprintf(fp, "%s ALERT: Water detected\n", get_timestamp());
    fclose(fp);
}

// Function to log an error to the error_log.txt file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error_log.txt");
        return;
    }
    fprintf(fp, "%s ERROR: %s\n", get_timestamp(), message);
    fclose(fp);
}

// Function to handle the water level sensor
void handle_water_level() {
    int level = gpioRead(GPIO_PIN);
    if (level == 1) {
        log_alert();
        printf("%s ALERT: Water detected\n", get_timestamp());
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water level monitoring daemon started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        handle_water_level();
        sleep(2);
    }

    // Cleanup
    gpioTerminate();
    printf("Water level monitoring daemon stopped.\n");
    return 0;
}

