#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdatomic.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile atomic_uint pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure it's static to persist outside the function

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to calculate RPM from pulse count
double calculate_rpm(unsigned int pulse_count) {
    return (double)pulse_count * 60.0;
}

// Function to log RPM data to a file
void log_rpm(double rpm) {
    char* timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    printf("%s %.2f\n", timestamp, rpm); // Also print to stdout
}

// Interrupt handler for rising edge detection
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    atomic_fetch_add(&pulse_count, 1);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    terminate = 1;
    printf("Caught signal, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for rising edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Reset pulse count
        atomic_store(&pulse_count, 0);

        // Wait for one second
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // microseconds

        // Calculate RPM
        double rpm = calculate_rpm(atomic_load(&pulse_count));

        // Log RPM data
        log_rpm(rpm);
    }

    // Cleanup
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    fclose(log_file);
    gpioTerminate();

    printf("RPM monitoring stopped.\n");
    return 0;
}

