#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the Hall effect sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the quadrature state machine states
typedef enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
} QuadratureState;

// Define the rotation direction
typedef enum {
    CLOCKWISE,
    COUNTER_CLOCKWISE,
    NONE
} RotationDirection;

// Global variables
static volatile QuadratureState current_state = STATE_00;
static volatile RotationDirection current_direction = NONE;
static volatile int running = 1; // Flag to control the main loop
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
void *logging_thread(void *arg);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize_gpio();
int open_log_file();
void close_log_file();
void log_rotation_event(RotationDirection direction);

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    return 0;
}

// Function to open the log file
int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// Function to close the log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Function to log the rotation event to the file
void log_rotation_event(RotationDirection direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Get milliseconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(log_file, "%s.%03ld: ", timestamp, milliseconds);

    switch (direction) {
