// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
}

int main() {
    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Starting touch-led program");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            syslog(LOG_INFO, "Touch detected");
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return 0;
}

