// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO17 as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    // Set GPIO18 as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    // Initialize LED to LOW
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor and toggle the LED
void read_touch_sensor() {
    int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

    if (touch_detected == 1) {
        // Toggle the LED
        int current_led_state = gpioRead(LED_PIN);
        gpioWrite(LED_PIN, !current_led_state);

        // Debounce delay
        gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        read_touch_sensor();
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

