#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to store log entries
typedef struct {
    int pin;
    time_t timestamp;
    int state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void add_to_buffer(int pin, int state);
void print_buffer();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function to read sensor value with debouncing
int read_sensor(int pin) {
    int i, reading;
    int sum = 0;
    int valid_readings = 0;

    for (i = 0; i < 5; i++) {
        reading = gpioRead(pin);
        if (reading >= 0) {
            sum += reading;
            valid_readings++;
        } else {
            fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        }
        gpioDelay(10000); // 10ms delay
    }

    if (valid_readings > 0) {
        return (sum >= valid_readings / 2) ? 1 : 0; // Return 1 if majority is high, 0 otherwise
    } else {
        return -1; // Indicate error
    }
}

// Function to control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to add entry to circular buffer
void add_to_buffer(int pin, int state) {
    log_buffer[buffer_index].pin = pin;
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        overflow_count++;
