#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode.\n", GPIO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistor on GPIO %d.\n", GPIO_PIN);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the data is written to the file immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    // Initialize GPIO pin
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    int last_state = -1; // Initialize to an invalid state

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_sensor();

        if (current_state != last_state) {
            if (current_state == 0) {
                if (log_event("Rain Detected") != 0) {
                    fprintf(stderr, "Error logging rain event.\n");
                }
            } else {
                if (log_event("No Rain") != 0) {
                    fprintf(stderr, "Error logging no rain event.\n");
                }
            }
            last_state = current_state;
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

