#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensors();
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_difference);
int log_data(SensorStates current_states);
void print_rpm(double rpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Enable pull-up resistors (optional, depending on sensor wiring)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Read sensor states with debouncing
SensorStates read_sensors() {
    SensorStates states;
    int sensor1_value, sensor2_value;
    static int prev_sensor1_state = -1; // Store previous state for debouncing
    static int prev_sensor2_state = -1;
    static unsigned int last_tick1 = 0;
    static unsigned int last_tick2 = 0;

    sensor1_value = gpioRead(SENSOR1_GPIO);
    sensor2_value = gpioRead(SENSOR2_GPIO);

    unsigned int current_tick1 = gpioTick();
    unsigned int current_tick2 = gpioTick();

    // Debounce sensor 1
    if (sensor1_value != prev_sensor1_state) {
        if (current_tick1 - last_tick1 > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
            states.sensor1_state = sensor1_value;
            prev_sensor1_state = sensor1_value;
            last_tick1 = current_tick1;
        } else {
            states.sensor1_state = prev_sensor1_state; // Keep previous state if debounce time not met
        }
    } else {
        states.sensor1_state = prev_sensor1_state;
    }

    // Debounce sensor 2
    if (sensor2_value != prev_sensor2_state) {
        if (current_tick2 - last_tick2 > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
            states.sensor2_state = sensor2_value;
            prev_sensor2_state = sensor2_value;
            last_tick2 = current_tick2;
        } else {
            states.sensor2_state = prev_sensor2_state; // Keep previous state if debounce time not met
        }
    } else {
        states.sensor2_state = prev_sensor2_state;
    }

    return states;
}

// Calculate RPM based on sensor transitions
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_difference) {
    // Check for transition from low to high for both sensors
    if (previous_states.sensor1_state == 0 && current_states.sensor1_state == 1) {
        // Check for transition from high to low for sensor 2
        if (previous_states.sensor2_state == 1 && current_states.sensor2_state == 0) {
            // Both sensors detected a transition, calculate RPM
            return 60.0 / (time_difference / 1000000.0); // Convert seconds to minutes
        }
    }
    return 0.0; // No transition detected, return 0 RPM
}

// Log data to CSV file
int log_data(SensorStates current_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, current_states.sensor1_state, current_states.sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Print RPM to console
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    SensorStates current_states, previous_states;
    double rpm;
    time_t start_time, current_time;
    double time_difference;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize previous states
    previous_states = read_sensors();

    // Get initial timestamp
    time(&start_time);

    printf("Monitoring shaft RPM... Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor states
        current_states = read_sensors();

        // Calculate time difference
        time(&current_time);
        time_difference = difftime(current_time, start_time);

        // Calculate RPM
        rpm = calculate_rpm(current_states, previous_states, time_difference);

        // Log data
        if (log_data(current_states) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Print RPM
        print_rpm(rpm);

        // Update previous states
        previous_states = current_states;

        // Update start time for next iteration
        start_time = current_time;

        // Delay to avoid excessive CPU usage
        gpioDelay(10000); // 10ms delay (10000 microseconds)
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

