#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm duration
#define ALARM_DURATION_MS 2000

// Define tilt duration threshold (in milliseconds)
#define TILT_DURATION_THRESHOLD_MS 2000

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int log_event(const char *event_type);
int activate_alarm(int duration_ms);
int deactivate_alarm();
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log an event to the log file
int log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to activate the alarm
int activate_alarm(int duration_ms) {
    if (gpioWrite(ALARM_PIN, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", ALARM_PIN);
        return -1;
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    return 0;
}

// Function to deactivate the alarm
int deactivate_alarm() {
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", ALARM_PIN);
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Initialize alarm to off
    deactivate_alarm();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int sensor1_state = 0;
    int sensor2_state = 0;
    int alarm_active = 0;
    unsigned int tilt_start_time = 0;

    while (program_running) {
        int new_sensor1_state = read_sensor(SENSOR_1_PIN);
        int new_sensor2_state = read_sensor(SENSOR_2_PIN);

        if (new_sensor1_state < 0 || new_sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (new_sensor1_state != sensor1_state || new_sensor2_state != sensor2_state) {
            if (new_sensor1_state == 1 || new_sensor2_state == 1) {
                if (!alarm_active) {
                    if (!tilt_start_time) {
                        tilt_start_time = gpioTick();
                    }

                    if (gpioTick() - tilt_start_time >= TILT_DURATION_THRESHOLD_MS * 1000) {
                        if (activate_alarm(ALARM_DURATION_MS) == 0) {
                            log_event("threshold_exceeded");
                            alarm_active = 1;
                        } else {
                            fprintf(stderr, "Error activating alarm\n");
                        }
                    }
                }
            } else {
                if (alarm_active) {
                    if (deactivate_alarm() == 0) {
                        log_event("tilt_end");
                        alarm_active = 0;
                    } else {
                        fprintf(stderr, "Error deactivating alarm\n");
                    }
                }
                tilt_start_time = 0; // Reset tilt start time
            }

            sensor1_state = new_sensor1_state;
            sensor2_state = new_sensor2_state;
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

