int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_euclidean_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(double magnitude);
void trigger_alert();
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor() {
    int status;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        // Verify sensor presence by reading the sensor ID
        char buf[1];
        buf[0] = SENSOR_ID;
        status = i2cWriteDevice(i2c_handle, buf, 1);
        if (status != 0) {
            fprintf(stderr, "Error writing sensor ID to I2C: %d\n", status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        char read_buf[1];
        status = i2cReadDevice(i2c_handle, read_buf, 1);
        if (status != 0) {
            fprintf(stderr, "Error reading sensor ID from I2C: %d\n", status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        if (read_buf[0] != SENSOR_ID) {
            fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", read_buf[0], SENSOR_ID);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        // Clear the power-down bit in CTRL1 register
        char ctrl1_data[2];
        ctrl1_data[0] = CTRL1_REG;
        ctrl1_data[1] = 0x00; // Example: Set CTRL1 to 0x00 (power-down disabled)
        status = i2cWriteDevice(i2c_handle, ctrl1_data, 2);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL1 register: %d\n", status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Initialization failed
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    int status;
    char data[6];

    // Read X, Y, and Z axis data
    status = i2cReadI2CBlockData(i2c_handle, DATA_REG_X, data, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate Euclidean magnitude
double calculate_euclidean_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log events
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_LED_PIN, 1); // Turn on LED
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALERT_LED_PIN, 0); // Turn off LED
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    int status;
    int16_t x, y, z;
    double magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, 0x41, 0); // Sensor address 0x41
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alert LED pin as output
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate Euclidean magnitude
            magnitude = calculate_euclidean_magnitude(x, y, z);

            // Check for earthquake-like event
            if (magnitude > EARTHQUAKE_THRESHOLD) {
                printf("Earthquake-like event detected! Magnitude: %.2f\n", magnitude);
                log_event(magnitude);
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Seismic monitoring stopped.\n");

    return 0;
}

