#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
    int last_state;
    int current_state;
} sensor_t;

// Global variables
volatile sig_atomic_t terminate = 0;
sensor_t sensors[NUM_SENSORS];

// Function prototypes
int initialize_sensors(sensor_t *sensors, int num_sensors);
int read_sensor(sensor_t *sensor);
int log_event(int sensor_id, int gpio_pin);
void signal_handler(int signal);
void cleanup(sensor_t *sensors, int num_sensors);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_USER, "Signal received, terminating...");
    terminate = 1;
}

// Initialize sensors
int initialize_sensors(sensor_t *sensors, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        sensors[i].gpio_pin = (i + 2) * 10; // BCM GPIO pins: 3, 5, 7, 11, 13
        sensors[i].sensor_id = i + 1;
        sensors[i].last_state = 1; // Initialize to HIGH (no flame)
        sensors[i].current_state = 1;

        if (gpioSetMode(sensors[i].gpio_pin, PI_INPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as input", sensors[i].gpio_pin);
            return -1;
        }
        gpioSetPullUpDown(sensors[i].gpio_pin, PI_PUD_UP); // Enable pull-up resistor
    }
    return 0;
}

// Read sensor state with debounce
int read_sensor(sensor_t *sensor) {
    int current_state = gpioRead(sensor->gpio_pin);
    if (current_state != sensor->last_state) {
        gpioDelay(DEBOUNCE_MS * 1000); // Debounce
        int debounced_state = gpioRead(sensor->gpio_pin);
        if (debounced_state == current_state) {
            sensor->current_state = debounced_state;
            return 1; // Flame detected
        }
    }
    return 0; // No flame detected
}

// Log event to file
int log_event(int sensor_id, int gpio_pin) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
    fflush(fp);

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", strerror(errno));
    }

    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup(sensor_t *sensors, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensors[i].gpio_pin, PI_INPUT); // Set back to input
    }
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensors(sensors, NUM_SENSORS) != 0) {
        syslog(LOG_ERR, "Sensor initialization failed");
        cleanup(sensors, NUM_SENSORS);
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_USER, "Flame monitor started");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_sensor(&sensors[i])) {
                if (log_event(sensors[i].sensor_id, sensors[i].gpio_pin) != 0) {
                    syslog(LOG_ERR, "Failed to log event for sensor %d", sensors[i].sensor_id);
                }
            }
        }
        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    cleanup(sensors, NUM_SENSORS);
    syslog(LOG_USER, "Flame monitor terminated");
    closelog();
    return 0;
}

