#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and line names
#define GPIOCHIP "gpiochip0"
#define OUT0_LINE "gpio5"
#define OUT1_LINE "gpio6"
#define OUT2_LINE "gpio13"
#define OUT3_LINE "gpio19"
#define OUT4_LINE "gpio26"
#define OUT5_LINE "gpio12"
#define OUT6_LINE "gpio16"
#define OUT7_LINE "gpio20"

// Define the number of sensors
#define NUM_SENSORS 8

// Structure to hold sensor data
typedef struct {
    int index;
    int pin;
    int state;
} sensor_data_t;

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_SENSORS];
static int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor_data(sensor_data_t *sensor_data);
void log_sensor_event(int index, int pin, int state);
void cleanup();
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Initialize GPIO lines
int initialize_gpio() {
    int i;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Configure line request configuration
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    // Open and request each line
    for (i = 0; i < NUM_SENSORS; i++) {
        char *line_name;
        switch (i) {
            case 0: line_name = OUT0_LINE; break;
            case 1: line_name = OUT1_LINE; break;
            case 2: line_name = OUT2_LINE; break;
            case 3: line_name = OUT3_LINE; break;
            case 4: line_name = OUT4_LINE; break;
            case 5: line_name = OUT5_LINE; break;
            case 6: line_name = OUT6_LINE; break;
            case 7: line_name = OUT7_LINE; break;
            default: line_name = NULL; break; // Should not happen
        }

        if (!line_name) {
            fprintf(stderr, "Invalid sensor index: %d\n", i);
            cleanup();
            return -1;
        }

        lines[i] = gpiod_chip_get_line(chip, atoi(line_name));
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %s: %s\n", line_name, strerror(errno));
            cleanup();
            return -1;
        }

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %s: %s\n", line_name, strerror(errno));
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *sensor_data) {
    int i, value;
    for (i = 0; i < NUM_SENSORS; i++) {
        value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", i, strerror(errno));
            return -1;
        }
        sensor_data[i].index = i;
        sensor_data[i].pin = atoi(lines[i]->name);
        sensor_data[i].state = value;
    }
    return 0;
}

// Log sensor event
void log_sensor_event(int index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 1) {
        printf("%s - Sensor %d (BCM %d) - Touch Detected\n", timestamp, index, pin);
    } else {
        printf("%s - Sensor %d (BCM %d) - Touch Released\n", timestamp, index, pin);
    }
}

// Cleanup GPIO resources
void cleanup() {
    int i;
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    sensor_data_t sensor_data[NUM_SENSORS];
    int i, prev_state[NUM_SENSORS] = {0};

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) < 0) {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            break;
        }

        // Log sensor events
        for (i = 0; i < NUM_SENSORS; i++) {
            if (sensor_data[i].state != prev_state[i]) {
