#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_CONF_REG 0x00
#define ALS_DATA_REG 0x04
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_veml7700();
int read_veml7700(unsigned int *lux);
int map_lux_to_duty_cycle(unsigned int lux);
int set_led_brightness(int duty_cycle);
int log_data(unsigned int lux, int duty_cycle, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configure the sensor for continuous mode and integration time (adjust as needed)
    // Example: Set ALS_CONF register to 0x02 for 100ms integration time
    if (i2cWriteByteData(i2c_handle, ALS_CONF_REG, 0x02) < 0) {
        fprintf(stderr, "Error writing to ALS_CONF_REG\n");
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700
int read_veml7700(unsigned int *lux) {
    unsigned int als_data;

    als_data = i2cReadWordData(i2c_handle, ALS_DATA_REG);
    if (als_data == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading ALS_DATA_REG\n");
        return -1;
    }

    *lux = als_data;
    return 0;
}

// Map lux value to duty cycle
int map_lux_to_duty_cycle(unsigned int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set LED brightness using PWM
int set_led_brightness(int duty_cycle) {
    gpioPWM(GPIO_LED, duty_cycle);
    return 0;
}

// Log data to file
int log_data(unsigned int lux, int duty_cycle, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%u,%d,%d\n", timestamp, lux, duty_cycle, error_code);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    unsigned int lux;
    int duty_cycle;
    int error_code;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        error_code = -1;
        log_data(0, 0, error_code);
        cleanup();
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700() != 0) {
        error_code = -2;
        log_data(0, 0, error_code);
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        error_code = read_veml7700(&lux);
        if (error_code != 0) {
            fprintf(stderr, "Error reading lux value\n");
            log_data(0, 0, error_code);
            sleep(1);
            continue;
        }

        // Map lux to duty cycle
        duty_cycle = map_lux_to_duty_cycle(lux);

        // Set LED brightness
        set_led_brightness(duty_cycle);

        // Log data
        log_data(lux, duty_cycle, 0);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

