#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensor channels
#define CHANNEL_1_PIN 2
#define CHANNEL_2_PIN 3
#define CHANNEL_3_PIN 4
#define CHANNEL_4_PIN 5
#define CHANNEL_5_PIN 6
#define CHANNEL_6_PIN 7
#define CHANNEL_7_PIN 8
#define CHANNEL_8_PIN 9

// Define GPIO pin for alert LED
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold the last touch time for each channel
struct {
    int pin;
    unsigned long last_touch_time;
} channel_states[8];

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int channel);
void log_touch_event(int channel);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-down resistors
    gpioSetMode(CHANNEL_1_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_1_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_2_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_2_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_3_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_3_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_4_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_4_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_5_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_5_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_6_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_6_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_7_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_7_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_8_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_8_PIN, PI_PUD_DOWN);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the state of a touch sensor channel
int read_touch_sensor(int channel) {
    int pin;

    switch (channel) {
        case 1: pin = CHANNEL_1_PIN; break;
        case 2: pin = CHANNEL_2_PIN; break;
        case 3: pin = CHANNEL_3_PIN; break;
        case 4: pin = CHANNEL_4_PIN; break;
        case 5: pin = CHANNEL_5_PIN; break;
        case 6: pin = CHANNEL_6_PIN; break;
        case 7: pin = CHANNEL_7_PIN; break;
        case 8: pin = CHANNEL_8_PIN; break;
        default: fprintf(stderr, "Invalid channel number: %d\n", channel); return -1; // Indicate error
    }

    return gpioRead(pin);
}

// Function to log a touch event to the file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure data is written to disk immediately

    if (ferror(log_file)) {
        fprintf(stderr, "Error writing to log file\n");
    }
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Turn off the LED
    control_led(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize channel states
    channel_states[0].pin = CHANNEL_1_PIN; channel_states[0].last_touch_time = 0;
    channel_states[1].pin = CHANNEL_2_PIN; channel_states[1].last_touch_time = 0;
    channel_states[2].pin = CHANNEL_3_PIN; channel_states[2].last_touch_time = 0;
    channel_states[3].pin = CHANNEL_4_PIN; channel_states[3].last_touch_time = 0;
    channel_states[4].pin = CHANNEL_5_PIN; channel_states[4].last_touch_time = 0;
    channel_states[5].pin = CHANNEL_6_PIN; channel_states[5].last_touch_time = 0;
    channel_states[6].pin = CHANNEL_7_PIN; channel_states[6].last_touch_time = 0;
    channel_states[7].pin = CHANNEL_8_PIN; channel_states[7].last_touch_time = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int i = 1; i <= 8; i++) {
            int current_state = read_touch_sensor(i);
            if (current_state == 1) {
                unsigned long now = gpioTick();
                if (now - channel_states[i - 1].last_touch_time > DEBOUNCE_TIME * 1000) {
                    log_touch_event(i);
                    channel_states[i - 1].last_touch_time = now;
                }
            }
        }

        // Check if any channel is still touched
        int any_touched = 0;
        for (int i = 0; i < 8; i++) {
            if (read_touch_sensor(i + 1) == 1) {
                any_touched = 1;
                break;
            }
        }

        control_led(any_touched);

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

