// Function to read the state of a touch sensor channel
int read_touch_sensor(int channel) {
    int pin;

    switch (channel) {
        case 1: pin = CHANNEL_1_PIN; break;
        case 2: pin = CHANNEL_2_PIN; break;
        case 3: pin = CHANNEL_3_PIN; break;
        case 4: pin = CHANNEL_4_PIN; break;
        case 5: pin = CHANNEL_5_PIN; break;
        case 6: pin = CHANNEL_6_PIN; break;
        case 7: pin = CHANNEL_7_PIN; break;
        case 8: pin = CHANNEL_8_PIN; break;
        default: fprintf(stderr, "Invalid channel number: %d\n", channel); return -1; // Indicate error
    }

    return gpioRead(pin);
}

// Function to log a touch event to the file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure data is written to disk immediately

    if (ferror(log_file)) {
        fprintf(stderr, "Error writing to log file\n");
    }
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Turn off the LED
    control_led(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize channel states
    channel_states[0].pin = CHANNEL_1_PIN; channel_states[0].last_touch_time = 0;
    channel_states[1].pin = CHANNEL_2_PIN; channel_states[1].last_touch_time = 0;
    channel_states[2].pin = CHANNEL_3_PIN; channel_states[2].last_touch_time = 0;
    channel_states[3].pin = CHANNEL_4_PIN; channel_states[3].last_touch_time = 0;
    channel_states[4].pin = CHANNEL_5_PIN; channel_states[4].last_touch_time = 0;
    channel_states[5].pin = CHANNEL_6_PIN; channel_states[5].last_touch_time = 0;
    channel_states[6].pin = CHANNEL_7_PIN; channel_states[6].last_touch_time = 0;
    channel_states[7].pin = CHANNEL_8_PIN; channel_states[7].last_touch_time = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int i = 1; i <= 8; i++) {
            int current_state = read_touch_sensor(i);
            if (current_state == 1) {
                unsigned long now = gpioTick();
                if (now - channel_states[i - 1].last_touch_time > DEBOUNCE_TIME * 1000) {
