        for (int i = 0; i < 8; i++) {
            if (read_touch_sensor(i + 1) == 1) {
                any_touched = 1;
                break;
            }
        }

        control_led(any_touched);

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
