#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_opt3001();
int read_opt3001(float *lux);
int write_log(float lux);
void signal_handler(int signal);
void cleanup();
uint16_t swap_bytes(uint16_t value);

// Structure for OPT3001 configuration
typedef struct {
    uint16_t config_value;
} opt3001_config_t;

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize OPT3001 sensor
int init_opt3001() {
    // Configure the OPT3001 for continuous conversion mode and 800ms conversion time
    opt3001_config_t config = {0xCB10}; // Continuous mode, 800ms
    config.config_value = swap_bytes(config.config_value);

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config.config_value >> 8) & 0xFF; // MSB
    buf[2] = config.config_value & 0xFF;       // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001: %d\n", result);
        return -1;
    }

    gpioDelay(100); // Wait for configuration to take effect
    return 0;
}

// Read OPT3001 sensor
int read_opt3001(float *lux) {
    char buf[1];
    buf[0] = RESULT_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to set result register: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read result from OPT3001: %d\n", result);
        return -1;
    }

    uint16_t raw_result = (data[0] << 8) | data[1];
    raw_result = swap_bytes(raw_result);

    // Extract exponent and result
    int exponent = (raw_result >> 12) & 0x0F;
    int result_value = raw_result & 0x0FFF;

    // Calculate lux value
    *lux = 0.01 * pow(2, exponent) * result_value;

    return 0;
}

// Write data to log file
int write_log(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file);

    printf("%s, %.2f\n", timestamp, lux);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Byte swap function
uint16_t swap_bytes(uint16_t value) {
    return (value >> 8) | (value << 8);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize OPT3001
    if (init_opt3001() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    float lux;
    // Main loop
    while (!terminate) {
        if (read_opt3001(&lux) == 0) {
            write_log(lux);
        } else {
            fprintf(stderr, "Failed to read OPT3001 sensor\n");
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

