#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure it's static to persist outside the function

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", get_timestamp(), message);
    fflush(log_file);
    return 0;
}

// Function to handle the touch event
void handle_touch(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick < DEBOUNCE_MS * 1000) {
        return; // Debounce
    }

    last_tick = current_tick;

    if (level == 1) {
        if (log_message("Touch Detected") != 0) {
            fprintf(stderr, "Error logging touch detected message.\n");
        }
    } else if (level == 0) {
        if (log_message("Touch Released") != 0) {
            fprintf(stderr, "Error logging touch released message.\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as an input with pull-down resistor
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for touch pin
    gpioSetAlertFunc(TOUCH_PIN, handle_touch);

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup
    gpioSetAlertFunc(TOUCH_PIN, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    printf("Touch sensor logging stopped.\n");
    return 0;
}

