#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(int16_t *flow_rate, uint8_t *status);
float convert_flow_rate(int16_t raw_flow);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
void log_data(time_t timestamp, float flow_rate, uint8_t status);
void signal_handler(int signal);
void cleanup();

// CRC-8-Dallas/Maxim polynomial 0x31 (x^8 + x^5 + x^4 + 1)
uint8_t crc8(uint8_t data, uint8_t crc)
{
    for (int i = 0; i < 8; i++)
    {
        uint8_t mix = (crc ^ data) & 0x01;
        crc >>= 1;
        if (mix)
            crc ^= 0x31;
        data >>= 1;
    }
    return crc;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0)
    {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0)
    {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    fseek(log_file, 0, SEEK_END);

    int16_t raw_flow;
    uint8_t status;
    float flow_rate;
    time_t timestamp;

    // Main loop
    while (!terminate)
    {
        // Read sensor data
        if (read_sensor(&raw_flow, &status) == 0)
        {
            // Convert flow rate
            flow_rate = convert_flow_rate(raw_flow);

            // Get timestamp
            timestamp = time(NULL);

            // Log data
            log_data(timestamp, flow_rate, status);
        }
        else
        {
            // Get timestamp
            timestamp = time(NULL);

            // Log error
            fprintf(log_file, "%ld,ERROR,I2C read failed\n", timestamp);
            fflush(log_file);

            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() != 0)
            {
                fprintf(stderr, "I2C re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int init_i2c()
{
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int read_sensor(int16_t *flow_rate, uint8_t *status)
{
    uint8_t buffer[3];
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2)
    {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    // Wait at least 2ms
    gpioDelay(2);

    // Read 3 bytes from the sensor
    if (i2cReadDevice(i2c_handle, (char *)buffer, 3) != 3)
    {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // Extract flow rate and status
    *flow_rate = (buffer[0] << 8) | buffer[1];
    *status = buffer[2];

    // Validate CRC
    uint8_t data[2] = {buffer[0], buffer[1]};
    if (!validate_crc(data, 2, *status))
    {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

float convert_flow_rate(int16_t raw_flow)
{
    // Conversion formula from datasheet
    return (float)raw_flow / 120.0;
}

uint8_t calculate_crc(uint8_t data[], int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++)
    {
        crc = crc8(data[i], crc);
    }
    return crc;
}

int validate_crc(uint8_t data[], int len, uint8_t crc)
{
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

void log_data(time_t timestamp, float flow_rate, uint8_t status)
{
    char status_str[20];

    // Check flow rate range
    if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX)
    {
        strcpy(status_str, "INVALID");
    }
    else
    {
        strcpy(status_str, "OK");
    }

    // Log data to file
    fprintf(log_file, "%ld,%.2f,%s\n", timestamp, flow_rate, status_str);
    fflush(log_file);
}

void signal_handler(int signal)
{
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

void cleanup()
{
    if (i2c_handle >= 0)
    {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();
}

