#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the log file name
#define LOG_FILE "path_log.csv"

// Global variables
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
char* get_iso8601_timestamp();
int write_to_log(char *timestamp, int left, int middle, int right);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

// Function to initialize the pigpio library and set GPIO pins as inputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    return 0;
}

// Function to read the digital value from a sensor
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to write the sensor data to the log file
int write_to_log(char *timestamp, int left, int middle, int right) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop to continuously sample the sensors
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue; // Skip to the next iteration
        }

        // Write the data to the log file
        if (write_to_log(timestamp, left_value, middle_value, right_value) != 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

