#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define LOG_FILE "flame_events.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log flame detection events to a file
void log_flame_event() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Flame detected!\n", timestamp);
    fclose(fp);
}

// Function to print an alert message to stdout
void print_alert() {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    printf("%s: Flame detected!\n", timestamp);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_flame_sensor() == 0) {
            log_flame_event();
            print_alert();
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

