#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define constants
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_S 2
#define LOG_FILE "alert_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int activate_buzzer();
int log_alert();
void signal_handler(int sig);
int cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        fprintf(stderr, "Signal received, cleaning up...\n");
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line for input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Activate buzzer for 2 seconds
int activate_buzzer() {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value to 1: %s\n", strerror(errno));
        return -1;
    }
    usleep(BUZZER_DURATION_S * 1000000); // 2 seconds
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value to 0: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Log alert message with timestamp
int log_alert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup resources before exiting
int cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fprintf(log_file, "System stopped\n");
        fclose(log_file);
    }

    return 0;
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }
    fprintf(log_file, "System started\n");
    fflush(log_file);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        fclose(log_file);
        return 1;
    }

    int flame_detected = 0;

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (sensor_value == 0 && !flame_detected) {
            // Flame detected (LOW signal)
            if (log_alert() != 0) {
                fprintf(stderr, "Error logging alert.\n");
            }
            if (activate_buzzer() != 0) {
                fprintf(stderr, "Error activating buzzer.\n");
            }
            flame_detected = 1;
        } else if (sensor_value == 1 && flame_detected) {
            // No flame detected (HIGH signal)
            flame_detected = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000); // 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

