    return 0;
}

// Function to handle the touch event
void handle_touch_event() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        if (write_to_log(timestamp) != 0) {
            fprintf(stderr, "Warning: Failed to write timestamp to log.\n");
        }
        free(timestamp); // Free the allocated memory
    } else {
        fprintf(stderr, "Error: Failed to get timestamp.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(TOUCH_PIN);
    unsigned long last_debounce_time = 0;

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_PIN);

        if (current_state != last_state) {
            unsigned long now = gpioTick();
            if ((now - last_debounce_time) > (DEBOUNCE_MS * 1000)) { // Debounce
                if (current_state == 0) { // Rising edge detected
                    handle_touch_event();
                }
                last_state = current_state;
                last_debounce_time = now;
            }
        }

        gpioDelay(10); // Poll every 10ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Touch sensor logging stopped.\n");
    return 0;
}

