#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define CONFIG_REG 0x01
#define HR_REG 0x24
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define MOVING_AVG_SIZE 5
#define LOG_FILE "heart_rate.csv"

// Expected values
#define EXPECTED_PART_ID 0x82
#define EXPECTED_HW_REV 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t config_reg;
    uint8_t hr_reg;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t reg, uint8_t *data, int len);
int write_sensor_data(int i2c_handle, uint8_t reg, uint8_t data);
int validate_sensor_id(int i2c_handle);
int read_heart_rate(int i2c_handle);
int apply_moving_average(int raw_hr, int *moving_avg_buffer, int buffer_size, int *current_index);
int validate_heart_rate(int filtered_hr);
int log_heart_rate(int bpm);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1182 sensor
int initialize_sensor(int i2c_handle) {
    // Example configuration (adjust as needed for Si1182-A-GM)
    if (write_sensor_data(i2c_handle, CONFIG_REG, 0x01) != 0) { // Example config
        fprintf(stderr, "Error writing to configuration register.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

// Read data from the sensor
int read_sensor_data(int i2c_handle, uint8_t reg, uint8_t *data, int len) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, reg, (char *)data, len);
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retrying...\n", reg, result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1; // Failure
}

// Write data to the sensor
int write_sensor_data(int i2c_handle, uint8_t reg, uint8_t data) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%02X): %d. Retrying...\n", reg, data, result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, data 0x%02X).\n", reg, data);
    return -1; // Failure
}

// Validate sensor ID
int validate_sensor_id(int i2c_handle) {
    uint8_t part_id, hw_rev;

    if (read_sensor_data(i2c_handle, PART_ID_REG, &part_id, 1) != 0) {
        fprintf(stderr, "Error reading PART_ID_REG.\n");
        return -1;
    }

    if (read_sensor_data(i2c_handle, HW_REV_REG, &hw_rev, 1) != 0) {
        fprintf(stderr, "Error reading HW_REV_REG.\n");
        return -1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X. Expected 0x%02X.\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Error: Unexpected HW_REV 0x%02X. Expected 0x%02X.\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    printf("Sensor ID and revision validated.\n");
    return 0;
}

// Read heart rate data
int read_heart_rate(int i2c_handle) {
    uint8_t hr_data[2];
    int raw_hr;

    if (read_sensor_data(i2c_handle, HR_REG, hr_data, 2) != 0) {
        fprintf(stderr, "Error reading heart rate data.\n");
        return -1;
    }

    raw_hr = (hr_data[0] << 8) | hr_data[1];
    return raw_hr;
}

// Apply moving average filter
int apply_moving_average(int raw_hr, int *moving_avg_buffer, int buffer_size, int *current_index) {
    static int sum = 0;
    sum -= moving_avg_buffer[*current_index];
    sum += raw_hr;
    moving_avg_buffer[*current_index] = raw_hr;
    *current_index = (*current_index + 1) % buffer_size;
    return sum / buffer_size;
}

// Validate heart rate
int validate_heart_rate(int filtered_hr) {
    if (filtered_hr < 30 || filtered_hr > 220) {
        fprintf(stderr, "Error: Heart rate out of range (%d BPM).\n", filtered_hr);
        return -1;
    }
    return 0;
}

// Log heart rate to file
int log_heart_rate(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file);

    return 0;
}

int main() {
    int raw_hr, filtered_hr, moving_avg_buffer[MOVING_AVG_SIZE] = {0};
    int current_index = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate sensor ID
    if (validate_sensor_id(i2c_handle) != 0) {
        fprintf(stderr, "Sensor validation failed. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw heart rate
        raw_hr = read_heart_rate(i2c_handle);
        if (raw_hr < 0) {
            fprintf(stderr, "Error reading heart rate. Retrying in 1 second.\n");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        // Apply moving average filter
        filtered_hr = apply_moving_average(raw_hr, moving_avg_buffer, MOVING_AVG_SIZE, &current_index);

        // Validate heart rate
        if (validate_heart_rate(filtered_hr) == 0) {
            // Log heart rate
            if (log_heart_rate(filtered_hr) != 0) {
                fprintf(stderr, "Error logging heart rate.\n");
            }
        } else {
            fprintf(stderr, "Invalid heart rate, not logging.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

