#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN_1 5
#define TOUCH_SENSOR_PIN_2 6
#define TOUCH_SENSOR_PIN_3 7
#define TOUCH_SENSOR_PIN_4 8
#define TOUCH_SENSOR_PIN_5 9
#define TOUCH_SENSOR_PIN_6 10
#define TOUCH_SENSOR_PIN_7 11
#define TOUCH_SENSOR_PIN_8 12

#define OUTPUT_PIN_17 17
#define OUTPUT_PIN_18 18
#define OUTPUT_PIN_19 19
#define OUTPUT_PIN_20 20
#define OUTPUT_PIN_21 21
#define OUTPUT_PIN_22 22
#define OUTPUT_PIN_23 23
#define OUTPUT_PIN_24 24

// Define constants
#define NUM_CHANNELS 8
#define NUM_OUTPUT_PINS 8
#define DEBOUNCE_DELAY_MS 5
#define STABILIZATION_DELAY_MS 200
#define POLLING_INTERVAL_MS 10
#define LOG_FILE_NAME "touch_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *touch_sensor_lines[NUM_CHANNELS];
static struct gpiod_line *output_lines[NUM_OUTPUT_PINS];
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *channel_states);
int update_counter(int *counter, int *channel_states);
int write_outputs(int counter);
int log_event(int channel, int counter);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO lines
int initialize_gpio() {
    int i;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Configure touch sensor lines
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_counter";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    touch_sensor_lines[0] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_1);
    touch_sensor_lines[1] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_2);
    touch_sensor_lines[2] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_3);
    touch_sensor_lines[3] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_4);
    touch_sensor_lines[4] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_5);
    touch_sensor_lines[5] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_6);
    touch_sensor_lines[6] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_7);
    touch_sensor_lines[7] = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN_8);

    for (i = 0; i < NUM_CHANNELS; i++) {
        if (!touch_sensor_lines[i]) {
            fprintf(stderr, "Error getting touch sensor line %d: %s\n", i + 1, strerror(errno));
            cleanup();
            return -1;
        }
        if (gpiod_line_request(touch_sensor_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting touch sensor line %d: %s\n", i + 1, strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Configure output lines
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_counter";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    output_lines[0] = gpiod_chip_get_line(chip, OUTPUT_PIN_17);
    output_lines[1] = gpiod_chip_get_line(chip, OUTPUT_PIN_18);
    output_lines[2] = gpiod_chip_get_line(chip, OUTPUT_PIN_19);
    output_lines[3] = gpiod_chip_get_line(chip, OUTPUT_PIN_20);
    output_lines[4] = gpiod_chip_get_line(chip, OUTPUT_PIN_21);
    output_lines[5] = gpiod_chip_get_line(chip, OUTPUT_PIN_22);
    output_lines[6] = gpiod_chip_get_line(chip, OUTPUT_PIN_23);
    output_lines[7] = gpiod_chip_get_line(chip, OUTPUT_PIN_24);

    for (i = 0; i < NUM_OUTPUT_PINS; i++) {
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting output line %d: %s\n", i + 17, strerror(errno));
            cleanup();
            return -1;
        }
        if (gpiod_line_request(output_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting output line %d: %s\n", i + 17, strerror(errno));
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Read touch sensor values
int read_touch_sensors(int *channel_states) {
    int i;
    int value;

    for (i = 0; i < NUM_CHANNELS; i++) {
        value = gpiod_line_get_value(touch_sensor_lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading touch sensor %d: %s\n", i + 1, strerror(errno));
            return -1;
        }
        channel_states[i] = value;
    }
    return 0;
}

// Update counter based on touch sensor states
int update_counter(int *counter, int *channel_states) {
    int i;
    int increment = 0;

    for (i = 0; i < NUM_CHANNELS; i++) {
        if (channel_states[i] == 1) {
            increment = 1;
            break; // Only increment once per cycle
        }
    }

    if (increment) {
        *counter = (*counter + 1) % 256;
    }
    return 0;
}

// Write counter value to output pins
int write_outputs(int counter) {
    int i;
    int bit;

    for (i = 0; i < NUM_OUTPUT_PINS; i++) {
        bit = (counter >> (NUM_OUTPUT_PINS - 1 - i)) & 1;
        if (gpiod_line_set_value(output_lines[i], bit) < 0) {
            fprintf(stderr, "Error writing to output line %d: %s\n", i + 17, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Log event to file
int log_event(int channel, int counter) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Warning: Log file not opened. Logging to stderr.\n");
        fprintf(stderr, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    int i;

    // Release lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (touch_sensor_lines[i]) {
            gpiod_line_release(touch_sensor_lines[i]);
        }
    }
    for (i = 0; i < NUM_OUTPUT_PINS; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int i;
    int channel_states[NUM_CHANNELS];
    int counter = 0;
    struct timespec delay;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
    }

    // Stabilization delay
    delay.tv_sec = 0;
    delay.tv_nsec = STABILIZATION_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&delay, NULL);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read touch sensor values
        if (read_touch_sensors(channel_states) < 0) {
            fprintf(stderr, "Error reading touch sensors, exiting.\n");
            break;
        }

        // Update counter
        if (update_counter(&counter, channel_states) < 0) {
            fprintf(stderr, "Error updating counter, exiting.\n");
            break;
        }

        // Write counter to output pins
        if (write_outputs(counter) < 0) {
            fprintf(stderr, "Error writing to output pins, exiting.\n");
            break;
        }

        // Log events
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (channel_states[i] == 1) {
                log_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }

        // Polling interval
        delay.tv_sec = 0;
        delay.tv_nsec = POLLING_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Touch sensor monitoring stopped.\n");
    return 0;
}

