#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 27
#define SENSOR4_GPIO 22

// Define the CSV file name
#define CSV_FILE "tracking_log.csv"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor data
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write data to the CSV file
int write_to_csv(const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing\n", CSV_FILE);
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s\n", CSV_FILE);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);
    gpioSetMode(SENSOR4_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor data
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);
        int sensor4_value = read_sensor(SENSOR4_GPIO);

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping write\n");
            gpioDelay(100); // Delay for 100ms
            continue;
        }

        // Write data to the CSV file
        if (write_to_csv(timestamp, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
            fprintf(stderr, "Failed to write to CSV file\n");
        }

        free(timestamp); // Free the allocated memory

        // Delay for 100ms
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

