#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/tilt_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "Signal received, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to log tilt events
void log_tilt_event(int gpio) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, gpio);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to read sensor data with debouncing
int read_sensor(int gpio) {
    int i, readings[5];
    int active_count = 0;

    // Take multiple readings for debouncing
    for (i = 0; i < 5; i++) {
        readings[i] = gpioRead(gpio);
        gpioDelay(DEBOUNCE_MS * 1000 / 5); // Delay for 50ms / 5 readings
    }

    // Check if all readings are active (0)
    for (i = 0; i < 5; i++) {
        if (readings[i] == 0) {
            active_count++;
        }
    }

    // Return 1 if all readings are active, 0 otherwise
    return (active_count == 5) ? 1 : 0;
}

// Function to cleanup GPIO and log file
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    int sensor1_state = 1; // Assume initially no tilt
    int sensor2_state = 1;

    // Main loop
    while (running) {
        int current_sensor1_state = read_sensor(SENSOR_1_GPIO);
        int current_sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Check for tilt event on sensor 1
        if (current_sensor1_state == 0 && sensor1_state == 1) {
            log_tilt_event(SENSOR_1_GPIO);
        }
        sensor1_state = current_sensor1_state;

        // Check for tilt event on sensor 2
        if (current_sensor2_state == 0 && sensor2_state == 1) {
            log_tilt_event(SENSOR_2_GPIO);
        }
        sensor2_state = current_sensor2_state;

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

