#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define MIC_GPIO 7
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_TIME_MS 100

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        fprintf(stderr, "Caught SIGINT, exiting gracefully.\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MIC_GPIO, PI_INPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    struct timespec ts;
    int last_state = 0;

    while (!terminate) {
        int current_state = gpioRead(MIC_GPIO);

        if (current_state != last_state && current_state == 1) {
            // Sound peak detected
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
                printf("%ld.%03ld\n", ts.tv_sec, ts.tv_nsec / 1000000);
            } else {
                fprintf(stderr, "clock_gettime failed\n");
            }

            gpioWrite(LED_GPIO, 1); // Turn LED on
            gpioDelay(LED_ON_TIME_MS * 1000); // Delay for 100ms
            gpioWrite(LED_GPIO, 0); // Turn LED off
        }

        last_state = current_state;
        gpioDelay(SAMPLE_PERIOD_US); // Sample every 125µs
    }

    gpioWrite(LED_GPIO, 0); // Ensure LED is off before exiting
    gpioTerminate();
    return 0;
}

