// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor states
void log_sensor_states(int left_state, int center_state, int right_state) {
    printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Main loop to read and log sensor states
    while (program_running) {
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int center_state = read_sensor(CENTER_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_state != -1 && center_state != -1 && right_state != -1) {
            log_sensor_states(left_state, center_state, right_state);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up and terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}

