#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_PART_ID 0x00
#define SI1175_REG_ALS_VIS_DATA0 0x10
#define SI1175_REG_ALS_VIS_DATA1 0x11

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the Si1175 sensor
int init_si1175() {
    // Reset the sensor (example initialization sequence)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x01) < 0) { // Reset command
        fprintf(stderr, "Error writing reset command to Si1175\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) { // Enable ALS
        fprintf(stderr, "Error writing enable ALS command to Si1175\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) { // Enable ALS force mode
        fprintf(stderr, "Error writing enable ALS force mode command to Si1175\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x0F, 0x03) < 0) { // Set ALS force mode
        fprintf(stderr, "Error writing set ALS force mode command to Si1175\n");
        return -1;
    }

    return 0;
}

// Function to read the ALS data from the Si1175 sensor
int read_als_data(uint16_t *raw_data) {
    int lsb, msb;

    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA0);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB from Si1175\n");
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA1);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB from Si1175\n");
        return -1;
    }

    *raw_data = (msb << 8) | lsb;
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1175 sensor
    if (init_si1175() < 0) {
        fprintf(stderr, "Si1175 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t raw_data;
    while (!terminate) {
        if (read_als_data(&raw_data) == 0) {
            printf("Raw ALS data: %u\n", raw_data);
        } else {
            fprintf(stderr, "Failed to read ALS data\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

