// gcc -o touch_poll touch_poll.c -lrt

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the touch sensor channels
const int touch_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read the state of all touch sensor channels
int read_touch_channels(int *channel_states) {
    for (int i = 0; i < num_channels; i++) {
        int pin = touch_pins[i];
        int state = gpioRead(pin);
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", pin, state);
            return -1; // Indicate an error
        }
        channel_states[i] = state;
    }
    return 0; // Indicate success
}

// Function to format the timestamp and channel states into a string
void format_output(int *channel_states, char *output_buffer, size_t buffer_size) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        fprintf(stderr, "Error getting monotonic clock time\n");
        return;
    }

    double seconds = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    snprintf(output_buffer, buffer_size, "[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
             seconds, channel_states[0], channel_states[1], channel_states[2], channel_states[3],
             channel_states[4], channel_states[5], channel_states[6], channel_states[7]);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        int pin = touch_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as input\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Allocate memory for the channel states
    int *channel_states = (int *)malloc(num_channels * sizeof(int));
    if (channel_states == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the touch sensor channels
        if (read_touch_channels(channel_states) == 0) {
            // Format the output string
            char output_buffer[256];
            format_output(channel_states, output_buffer, sizeof(output_buffer));

            // Print the output string
            printf("%s", output_buffer);
        } else {
            fprintf(stderr, "Error reading touch channels\n");
        }

        // Wait for 200 milliseconds
        gpioDelay(200);
    }

    // Clean up and exit
    free(channel_states);
    gpioTerminate();
    return 0;
}

