#include <pigpio.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Number of steps for the fade
#define FADE_STEPS 50

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to set the RGB LED color using PWM
void set_rgb_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a random hue (0-359)
int generate_random_hue()
{
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        return 0; // Return a default hue in case of error
    }

    unsigned int random_value;
    if (fread(&random_value, sizeof(random_value), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        fclose(urandom);
        return 0; // Return a default hue in case of error
    }

    fclose(urandom);
    return random_value % 360;
}

// Function to convert hue to RGB (common anode)
void hue_to_rgb(int hue, int *red, int *green, int *blue)
{
    float h = (float)hue / 360.0;
    float s = 1.0;
    float v = 1.0;

    float c = s * v;
    float x = c * (1 - fabs(fmod(h * 6.0, 2) - 1));
    float m = v - c;

    float r, g, b;

    if (h < 1.0/6.0) {
        r = c;
        g = x;
        b = 0;
    } else if (h < 2.0/6.0) {
        r = x;
        g = c;
        b = 0;
    } else if (h < 3.0/6.0) {
        r = 0;
        g = c;
        b = x;
    } else if (h < 4.0/6.0) {
        r = 0;
        g = x;
        b = c;
    } else if (h < 5.0/6.0) {
        r = x;
        g = 0;
        b = c;
    } else {
        r = c;
        g = 0;
        b = x;
    }

    *red   = (int)((r + m) * 255);
    *green = (int)((g + m) * 255);
    *blue  = (int)((b + m) * 255);
}

// Function to linearly interpolate between two colors
void interpolate_color(int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue, int step, int total_steps, int *red, int *green, int *blue)
{
    float red_diff   = (float)(end_red   - start_red  ) / total_steps;
    float green_diff = (float)(end_green - start_green) / total_steps;
    float blue_diff  = (float)(end_blue  - start_blue ) / total_steps;

    *red   = start_red   + (int)(red_diff   * step);
    *green = start_green + (int)(green_diff * step);
    *blue  = start_blue  + (int)(blue_diff  * step);
}

int main()
{
    // Initialize syslog
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (8-bit)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Main loop
    while (!terminate) {
        // Generate random hues
        int start_hue = generate_random_hue();
        int end_hue   = generate_random_hue();

        // Convert hues to RGB values
        int start_red, start_green, start_blue;
        int end_red, end_green, end_blue;

        hue_to_rgb(start_hue, &start_red, &start_green, &start_blue);
        hue_to_rgb(end_hue, &end_red, &end_green, &end_blue);

        // Fade between colors
        for (int i = 0; i <= FADE_STEPS; i++) {
            int red, green, blue;
            interpolate_color(start_red, start_green, start_blue, end_red, end_green, end_blue, i, FADE_STEPS, &red, &green, &blue);
            set_rgb_color(red, green, blue);
            gpioDelay(50000); // 50ms delay
        }
    }

    // Turn off the LED
    set_rgb_color(0, 0, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

