#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define PON_REG 0x80
#define AEN_REG 0x80
#define ATIME_REG 0x81
#define CDATA_REG 0x94
#define RDATA_REG 0x96
#define GDATA_REG 0x98
#define BDATA_REG 0x9A
#define LED_GPIO 17
#define RED_THRESHOLD 200
#define INTEGRATION_TIME 154 // ms

// Global variables
int i2c_fd = -1;
int running = 1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t val);
int tcs34725_init(int fd);
int tcs34725_read_rgbc(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c);
void gpio_control(int gpio, int level);
void signal_handler(int signal);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = val;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
    // Power on the sensor
    if (i2c_write_byte(fd, PON_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to power on TCS34725\n");
        return -1;
    }
    gpioDelay(3); // Wait for power-on (at least 2.48ms)

    // Enable RGBC
    if (i2c_write_byte(fd, AEN_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to enable TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME) - 154ms
    uint8_t atime = 0xEB; // 154ms
    if (i2c_write_byte(fd, ATIME_REG, atime) != 0) {
        fprintf(stderr, "Failed to set integration time\n");
        return -1;
    }

    return 0;
}

// TCS34725 read RGBC function
int tcs34725_read_rgbc(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[8];

    if (i2c_read_bytes(fd, CDATA_REG, buf, 8) != 0) {
        fprintf(stderr, "Failed to read RGBC data\n");
        return -1;
    }

    *c = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];
    *r = (uint16_t)buf[3] << 8 | (uint16_t)buf[2];
    *g = (uint16_t)buf[5] << 8 | (uint16_t)buf[4];
    *b = (uint16_t)buf[7] << 8 | (uint16_t)buf[6];

    return 0;
}

// GPIO control function
void gpio_control(int gpio, int level) {
    gpioWrite(gpio, level);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    uint16_t r, g, b, c;

    // Main loop
    while (running) {
        // Read RGBC values
        if (tcs34725_read_rgbc(i2c_fd, &r, &g, &b, &c) == 0) {
            // Print RGBC values
            printf("R: %5d, G: %5d, B: %5d, C: %5d\n", r, g, b, c);

            // Control LED based on red value
            if (r > RED_THRESHOLD) {
                gpio_control(LED_GPIO, 1); // Turn LED on
            } else {
                gpio_control(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, attempting re-initialization...\n");
            // Attempt to re-initialize the sensor
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to re-open I2C bus");
                running = 0; // Exit loop if re-initialization fails
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
                perror("Failed to re-set I2C slave address");
                running = 0;
                continue;
            }
            if (tcs34725_init(i2c_fd) != 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                running = 0;
                continue;
            }
        }

        gpioDelay(200); // Wait 200ms
    }

    // Cleanup
    close(i2c_fd);
    gpio_control(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

