#include <signal.h>
#include <math.h>
#include <unistd.h>

// Constants
#define I2C_ADDR 0x23
#define GPIO_PIN 18
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_RANGE 1000000     // 1 MHz
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for LED data
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} led_data_t;

// Function prototypes
int read_bh1750(int i2c_handle, float *lux);
int map_lux_to_brightness(float lux);
void set_led_brightness(int gpio_pin, int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char buf[2];
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, BH1750_CONTINUOUS_HIGH_RES_MODE);
        if (result != 0) {
            fprintf(stderr, "Error writing to BH1750: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(180000); // Wait 180ms

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from BH1750: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        unsigned int raw_value = (buf[0] << 8) | buf[1];
        *lux = (float)raw_value / 1.2; // Convert to lux
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to map lux value to brightness level
int map_lux_to_brightness(float lux) {
    // Logarithmic mapping
    float log_lux = log10(lux + 1); // Add 1 to avoid log(0)
    float brightness_float = (log_lux / log10(10000)) * 255; // Map to 0-255

    // Clamp to 0-255
    if (brightness_float < 0) {
        brightness_float = 0;
    } else if (brightness_float > 255) {
        brightness_float = 255;
    }

    return (int)brightness_float;
}

// Function to set LED brightness using PWM
void set_led_brightness(int gpio_pin, int brightness) {
    // Calculate duty cycle (0-1000000)
    int duty_cycle = (int)((float)brightness / 255.0 * PWM_RANGE);

    // Set PWM range
    gpioSetPWMrange(gpio_pin, PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(gpio_pin, PWM_FREQUENCY);

    // Set PWM duty cycle
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    float lux;
    int brightness;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_bh1750(i2c_handle, &lux) == 0) {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(GPIO_PIN, brightness);

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

