#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define NUM_LEDS 10
#define SPI_SPEED 1000000 // 1 MHz
#define START_FRAME 0x00000000
#define END_FRAME 0x80000000

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(const char *bus);
int read_bh1750(int fd);
float scale_brightness(int lux);
int construct_apa102_frame(uint8_t *buffer, int lux);
int transmit_apa102_data(int fd, uint8_t *buffer, int num_leds);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

// Initialize I2C
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize SPI
int init_spi(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read BH1750 sensor
int read_bh1750(int fd) {
    uint8_t config[1] = {0x10}; // Continuous high resolution mode
    if (write(fd, config, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }

    usleep(120000); // Wait for conversion (120ms)

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux;
}

// Scale brightness to APA102 range
float scale_brightness(int lux) {
    // Non-linear scaling (logarithmic)
    float brightness = log10(lux + 1) / log10(10000) * 255; // Scale to 0-255
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    return brightness;
}

// Construct APA102 frame
int construct_apa102_frame(uint8_t *buffer, int lux) {
    float brightness = scale_brightness(lux);
    uint32_t led_frame = (0xE0000000 | (brightness << 16) | (brightness << 8) | brightness); // Global brightness

    // Start frame
    memcpy(buffer, &START_FRAME, 4);

    // LED frames
    for (int i = 0; i < NUM_LEDS; i++) {
        memcpy(buffer + 4 + i * 4, &led_frame, 4);
    }

    // End frame
    memcpy(buffer + 4 + NUM_LEDS * 4, &END_FRAME, 4);

    return 0;
}

// Transmit APA102 data
int transmit_apa102_data(int fd, uint8_t *buffer, int num_leds) {
    int total_bytes = 4 + num_leds * 4 + 4; // Start + LED frames + End
    uint8_t *tx_buffer = malloc(total_bytes);
    if (tx_buffer == NULL) {
        perror("Error allocating transmit buffer");
        return -1;
    }

    memcpy(tx_buffer, buffer, total_bytes);

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buffer,
        .len = total_bytes,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error transmitting SPI data");
        free(tx_buffer);
        return -1;
    }

    free(tx_buffer);
    return 0;
}

int main() {
    // Setup signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_BUS);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    uint8_t apa102_buffer[4 + NUM_LEDS * 4 + 4]; // Start + LED frames + End

    while (!terminate) {
        // Read BH1750
        int lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading BH1750. Retrying...\n");
            usleep(100000); // Wait before retrying
            continue;
        }

        // Construct APA102 frame
        if (construct_apa102_frame(apa102_buffer, lux) != 0) {
            fprintf(stderr, "Error constructing APA102 frame.\n");
            continue;
        }

        // Transmit APA102 data
        if (transmit_apa102_data(spi_fd, apa102_buffer, NUM_LEDS) != 0) {
            fprintf(stderr, "Error transmitting APA102 data.\n");
        }

        usleep(10000); // Delay for 10ms
    }

    // Turn off LEDs
    memset(apa102_buffer, 0, sizeof(apa102_buffer));
    transmit_apa102_data(spi_fd, apa102_buffer, NUM_LEDS);

    cleanup();
    return 0;
}

