    if (wiringPiI2CWrite(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) == -1) {
        fprintf(stderr, "Error writing to BH1750 at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    return fd;
}

// Function to initialize SPI
int init_spi() {
    int fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

