    data[4] = 0xE0 | (brightness & 0x1F); // Global brightness (5 bits)
    data[5] = 0x00; // Blue
    data[6] = 0x00; // Green
    data[7] = 0x00; // Red

    // End frame (4 bytes of 0xFF)
    for (i = 0; i < 4; i++) {
