#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define GAMMA 2.2
#define MAX_LUX 10000.0
#define MAX_BRIGHTNESS 255
#define GPIO_PIN 18
#define WS2812B_BITS 24
#define WS2812B_RESET_US 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_veml7700(int i2c_handle, uint16_t *als_data);
float gamma_correct(float lux);
int map_lux_to_brightness(float gamma_corrected_lux);
void set_led_brightness(int gpio_pin, int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read ambient light data from VEML7700
int read_veml7700(int i2c_handle, uint16_t *als_data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, ALS_DATA_REG);
        if (result >= 0) {
            *als_data = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retrying...\n", result);
            gpioDelay(100); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to apply gamma correction
float gamma_correct(float lux) {
    return powf(lux / MAX_LUX, 1.0 / GAMMA);
}

// Function to map lux to brightness
int map_lux_to_brightness(float gamma_corrected_lux) {
    return (int)(gamma_corrected_lux / MAX_LUX * MAX_BRIGHTNESS);
}

// Function to set LED brightness using bit-banging
void set_led_brightness(int gpio_pin, int brightness) {
    // Convert brightness to WS2812B bit stream
    unsigned char bitstream[WS2812B_BITS];
    for (int i = 0; i < WS2812B_BITS; i++) {
        bitstream[i] = (brightness >> (WS2812B_BITS - 1 - i)) & 1;
    }

    // Send reset signal
    gpioWrite(gpio_pin, 0);
    gpioDelay(WS2812B_RESET_US);

    // Send bit stream
    for (int i = 0; i < WS2812B_BITS; i++) {
        gpioWrite(gpio_pin, bitstream[i]);
        gpioDelay(0.8); // 0.8us high for 0, 0.4us low for 1
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als_data;
    float lux, gamma_corrected_lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read ambient light data
        if (read_veml7700(i2c_handle, &als_data) == 0) {
            // Convert raw data to lux (example conversion, adjust as needed)
            lux = (float)als_data * 0.0576; // Example conversion factor

            // Apply gamma correction
            gamma_corrected_lux = gamma_correct(lux);

            // Map lux to brightness
            brightness = map_lux_to_brightness(gamma_corrected_lux);

            // Set LED brightness
            set_led_brightness(GPIO_PIN, brightness);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ambient light data.\n");
        }

        // Pause for 200ms
        gpioDelay(200);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

