#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LED_GPIO 17
#define BUFFER_SIZE 60
#define LUX_MIN 0
#define LUX_MAX 1000
#define FREQ_MIN 0.5
#define FREQ_MAX 5.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_bh1750(int i2c_handle, float *lux);
void update_circular_buffer(float lux);
float calculate_average_lux();
void control_led(float average_lux);
void signal_handler(int signal);

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read two bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to update the circular buffer
void update_circular_buffer(float lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average lux value from the buffer
float calculate_average_lux() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average lux value
void control_led(float average_lux) {
    // Map lux value to frequency
    float frequency = FREQ_MIN + (average_lux / LUX_MAX) * (FREQ_MAX - FREQ_MIN);
    if (frequency < FREQ_MIN) frequency = FREQ_MIN;
    if (frequency > FREQ_MAX) frequency = FREQ_MAX;

    // Calculate duty cycle (50%)
    float duty_cycle = 0.5;

    // Calculate on and off times
    float on_time = 1.0 / (frequency * 2);
    float off_time = on_time;

    // Blink the LED
    gpioWrite(LED_GPIO, 1); // Turn on
    gpioDelay(on_time * 1000000); // Delay in microseconds
    gpioWrite(LED_GPIO, 0); // Turn off
    gpioDelay(off_time * 1000000); // Delay in microseconds
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer with zeros
    for (int i = 0; i < BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0;
