#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Segment patterns for digits 0-9 (common cathode)
const unsigned char segment_patterns[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Function prototypes
void shift_out(unsigned char data);
void display_digit(unsigned char digit);
void blink_digit(unsigned char digit);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    gpioTerminate();
    exit(0);
}

// Shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin
        gpioWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock high
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Small delay

        // Clock low
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
    }
}

// Display a digit on the 7-segment display
void display_digit(unsigned char digit) {
    shift_out(segment_patterns[digit]);

    // Latch the data
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1); // Small delay
}

// Blink a digit on the display
void blink_digit(unsigned char digit) {
    display_digit(digit);
    gpioDelay(500); // On period

    // Turn off the display
    shift_out(0x00);
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(500); // Off period
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (1) {
        blink_digit(5); // Blink the digit '5'
    }

    return 0;
}

