#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *led_line, *button_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for button
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure button line as input with pull-up resistor
    config.consumer = "button_input";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0; // No special flags needed for input

    ret = gpiod_line_request(button_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting button line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure LED line as output
    config.consumer = "led_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0; // No special flags needed for output

    ret = gpiod_line_request(led_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial LED state to off
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Error setting LED value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure button line for falling edge event
    ret = gpiod_line_request_falling_edge_events(button_line, "button_event");
    if (ret < 0) {
        perror("Error requesting falling edge event");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Blinking LED and waiting for button press...\n");

    // Main loop: blink LED and wait for button press
    while (1) {
        // Blink LED
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Error setting LED value (on)");
            break;
        }
        usleep(1000000); // 1 second

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Error setting LED value (off)");
            break;
        }
        usleep(1000000); // 1 second

        // Wait for button press (with timeout)
        ret = gpiod_line_event_wait(button_line, NULL, 1000000); // Timeout of 1 second
        if (ret < 0) {
            perror("Error waiting for button event");
            break;
        } else if (ret > 0) {
            // Button pressed (falling edge detected)
            printf("Button pressed! Stopping blinking and turning off LED.\n");

            // Stop blinking (set LED to off)
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Error setting LED value (off after button press)");
                break;
            }

            // Exit the loop
            break;
        }
    }

    // Cleanup: release GPIO lines and close chip
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

