#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int button_state = gpioRead(BUTTON_PIN);

        if (button_state == 1) {
            // Button is pressed
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(500000);      // Wait 500ms
            gpioWrite(LED_PIN, 0); // Turn off LED
            gpioDelay(500000);      // Wait 500ms
        } else {
            // Button is not pressed
            gpioWrite(LED_PIN, 0); // Ensure LED is off
            gpioDelay(100000);      // Small delay to avoid busy-waiting
        }
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

