#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILENAME "color_log.csv"

// ADPD188BI Registers (Example - adjust based on datasheet)
#define ADPD188BI_REG_ALS_LSB 0x00
#define ADPD188BI_REG_ALS_MSB 0x01
#define ADPD188BI_REG_RED_LSB 0x02
#define ADPD188BI_REG_RED_MSB 0x03
#define ADPD188BI_REG_GREEN_LSB 0x04
#define ADPD188BI_REG_GREEN_MSB 0x05
#define ADPD188BI_REG_BLUE_LSB 0x06
#define ADPD188BI_REG_BLUE_MSB 0x07

// Global variables
static int i2c_handle;
static FILE *csv_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_als(uint16_t *als);
int read_color_channels(uint16_t *red, uint16_t *green, uint16_t *blue);
int set_led_brightness(uint16_t als);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// I2C initialization
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ALS data
int read_als(uint16_t *als) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_REG_ALS_LSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    *als = (buf[1] << 8) | buf[0];
    return 0;
}

// Read color channel data
int read_color_channels(uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_REG_RED_LSB, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading color data: %d\n", result);
        return -1;
    }

    *red = (buf[1] << 8) | buf[0];
    *green = (buf[3] << 8) | buf[2];
    *blue = (buf[5] << 8) | buf[4];

    return 0;
}

// Set LED brightness using PWM
int set_led_brightness(uint16_t als) {
    // Map ALS value to PWM duty cycle (0-255)
    int duty_cycle = als % 256; // Assuming ALS is within 0-65535

    gpioPWM(LED_GPIO, duty_cycle);
    return 0;
}

// Log data to CSV file
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    uint16_t als, red, green, blue;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    fflush(csv_file);

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (read_als(&als) == 0 && read_color_channels(&red, &green, &blue) == 0) {
                set_led_brightness(als);
                log_data(als, red, green, blue);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read error, retrying... (%d/3)\n", retries + 1);
                gpioDelay(100); // Wait 100ms before retrying
                retries++;
            }
        }
        if (retries == 3) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

