#include <string.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ Registers
#define FXOS8700CQ_REG_STATUS 0x00
#define FXOS8700CQ_REG_OUT_X_MSB 0x01
#define FXOS8700CQ_REG_OUT_X_LSB 0x02
#define FXOS8700CQ_REG_OUT_Y_MSB 0x03
#define FXOS8700CQ_REG_OUT_Y_LSB 0x04
#define FXOS8700CQ_REG_OUT_Z_MSB 0x05
#define FXOS8700CQ_REG_OUT_Z_LSB 0x06
#define FXOS8700CQ_REG_WHO_AM_I 0x0D
#define FXOS8700CQ_REG_CTRL_REG1 0x2A
#define FXOS8700CQ_REG_M_CTRL_REG1 0x5B
#define FXOS8700CQ_REG_M_CTRL_REG2 0x5C

// Configuration values
#define FXOS8700CQ_CTRL_REG1_ACTIVE 0x01 // Active mode
#define FXOS8700CQ_CTRL_REG1_DR_200HZ 0x00 // 200Hz data rate
#define FXOS8700CQ_M_CTRL_REG1_ACTIVE 0x1F // Active mode for magnetometer
#define FXOS8700CQ_M_CTRL_REG2_2G 0x00 // +/- 2g range

// Impact threshold
#define IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700cq();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }
    fprintf(stderr, "WHO_AM_I verified successfully: 0x%02X\n", who_am_i);

    // Put the sensor in standby mode
    int status = i2cWriteByteData(i2c_handle, FXOS8700CQ_REG_CTRL_REG1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error putting sensor in standby: %d\n", status);
        return -1;
    }

    // Configure the sensor for +/- 2g range and 200Hz data rate
    status = i2cWriteByteData(i2c_handle, FXOS8700CQ_REG_CTRL_REG1, FXOS8700CQ_CTRL_REG1_ACTIVE | FXOS8700CQ_CTRL_REG1_DR_200HZ);
    if (status < 0) {
        fprintf(stderr, "Error configuring sensor: %d\n", status);
        return -1;
    }

    // Configure magnetometer for +/- 2g range
    status = i2cWriteByteData(i2c_handle, FXOS8700CQ_REG_M_CTRL_REG1, FXOS8700CQ_M_CTRL_REG1_ACTIVE);
    if (status < 0) {
        fprintf(stderr, "Error configuring magnetometer: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, FXOS8700CQ_REG_M_CTRL_REG2, FXOS8700CQ_M_CTRL_REG2_2G);
    if (status < 0) {
        fprintf(stderr, "Error configuring magnetometer range: %d\n", status);
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_REG_OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2; // 14-bit data, right-aligned
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 4096.0; // Assuming +/- 2g range
}

// Log impact data to a file
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Log impact data
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Error logging impact data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

