#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// L3G4200D I2C address
#define L3G4200D_ADDR 0x69

// L3G4200D registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Calibration samples
#define CALIBRATION_SAMPLES 100

// Alert threshold
#define ALERT_THRESHOLD 50.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to hold gyroscope offsets
typedef struct {
    float x;
    float y;
    float z;
} gyro_offsets_t;

// Function prototypes
int init_gyro();
gyro_offsets_t calibrate_gyro();
gyro_data_t read_gyro_data();
void apply_offsets(gyro_data_t raw_data, gyro_offsets_t offsets, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void check_alert(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize the gyroscope
int init_gyro() {
    // Enable gyroscope (100Hz, normal mode)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Calibrate the gyroscope
gyro_offsets_t calibrate_gyro() {
    gyro_offsets_t offsets = {0.0, 0.0, 0.0};
    gyro_data_t raw_data;
    int16_t x, y, z;

    fprintf(stderr, "Calibrating gyroscope...\n");

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        raw_data = read_gyro_data();
        offsets.x += (float)raw_data.x;
        offsets.y += (float)raw_data.y;
        offsets.z += (float)raw_data.z;
        gpioDelay(5000); // 5ms delay
    }

    offsets.x /= CALIBRATION_SAMPLES;
    offsets.y /= CALIBRATION_SAMPLES;
    offsets.z /= CALIBRATION_SAMPLES;

    fprintf(stderr, "Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets.x, offsets.y, offsets.z);

    return offsets;
}

// Read raw gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return 0s to avoid using garbage values
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Apply offsets to raw data
void apply_offsets(gyro_data_t raw_data, gyro_offsets_t offsets, float *x, float *y, float *z) {
    *x = (float)raw_data.x - offsets.x;
    *y = (float)raw_data.y - offsets.y;
    *z = (float)raw_data.z - offsets.z;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file);
}

