    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return 0s to avoid using garbage values
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Apply offsets to raw data
void apply_offsets(gyro_data_t raw_data, gyro_offsets_t offsets, float *x, float *y, float *z) {
    *x = (float)raw_data.x - offsets.x;
    *y = (float)raw_data.y - offsets.y;
    *z = (float)raw_data.z - offsets.z;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Check for alert condition
void check_alert(float x, float y, float z) {
    if (fabs(x) > ALERT_THRESHOLD || fabs(y) > ALERT_THRESHOLD || fabs(z) > ALERT_THRESHOLD) {
        fprintf(stderr, "ALERT: Axis exceeding threshold (%.2f, %.2f, %.2f)!\n", x, y, z);
        fprintf(log_file, "ALERT: Axis exceeding threshold (%.2f, %.2f, %.2f)!\n", x, y, z);
        fflush(log_file);
    }
}

