    terminate = 1;
}

// ADXL345 initialization function
int adxl345_init() {
    // Verify device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set data format: full resolution, +/- 2g range
    int status = i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B);
    if (status < 0) {
        fprintf(stderr, "Error writing data format: %d\n", status);
        return -1;
    }

    // Set power control: measure mode
    status = i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08);
    if (status < 0) {
        fprintf(stderr, "Error writing power control: %d\n", status);
        return -1;
    }

    return 0;
}

