        float heading = calculate_heading(data.accel_x, data.accel_y, data.mag_x, data.mag_y, data.mag_z);

        // Log data
        if (log_data(heading, data.accel_x, data.accel_y, data.accel_z, data.mag_x, data.mag_y, data.mag_z) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(100); // Sample every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open accelerometer I2C device: %d\n", i2c_handle_accel);
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open magnetometer I2C device: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return 1;
    }

    // Configure accelerometer (100Hz, normal mode)
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x57) != 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        return 1;
    }

    // Configure magnetometer (continuous conversion mode)
    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Failed to configure magnetometer\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accel_data(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return 1;
    }

    int16_t raw_x = (buf[1] << 8) | buf[0];
    int16_t raw_y = (buf[3] << 8) | buf[2];
    int16_t raw_z = (buf[5] << 8) | buf[4];

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;

    return 0;
}

// Read magnetometer data
int read_mag_data(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return 1;
    }

    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_z = (buf[2] << 8) | buf[3];
    int16_t raw_y = (buf[4] << 8) | buf[5];

    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle_accel >= 0) {
        i2cClose(i2c_handle_accel);
    }
    if (i2c_handle_mag >= 0) {
        i2cClose(i2c_handle_mag);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

