#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SAMPLE_INTERVAL_NS 10000000 // 10 ms
#define MAX_RETRIES 3
#define CSV_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
} sensor_data_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor(int handle, int16_t *sample);
double calculate_tdoa(int16_t sample1, int16_t sample2);
int log_data(FILE *fp, struct timespec ts, int16_t sensor1, int16_t sensor2, double tdoa);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor(int handle, int16_t *sample) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(handle, buf, 2);
        if (bytes_read == 2) {
            *sample = (int16_t)((buf[0] << 8) | buf[1]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculate TDOA
double calculate_tdoa(int16_t sample1, int16_t sample2) {
    // Simple cross-correlation (replace with a more sophisticated algorithm)
    // This is a placeholder and will not give meaningful TDOA values.
    return (double)(sample1 - sample2);
}

// Log data to CSV file
int log_data(FILE *fp, struct timespec ts, int16_t sensor1, int16_t sensor2, double tdoa) {
    if (fprintf(fp, "%ld,%ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, sensor1, sensor2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    struct timespec ts;
    int16_t sensor1_sample, sensor2_sample;
    double tdoa;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle1, &sensor1_sample) != 0) {
            fprintf(stderr, "Error reading sensor 1, skipping sample.\n");
            continue;
        }

        if (read_sensor(i2c_handle2, &sensor2_sample) != 0) {
            fprintf(stderr, "Error reading sensor 2, skipping sample.\n");
            continue;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            continue;
        }

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor1_sample, sensor2_sample);

        // Log data
        if (log_data(log_file, ts, sensor1_sample, sensor2_sample, tdoa) != 0) {
            fprintf(stderr, "Error logging data, skipping sample.\n");
            continue;
        }

        fflush(log_file); // Flush the buffer to ensure data is written to file

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_NS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

