#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3        // CPOL=1, CPHA=1
#define CS_PIN 8
#define SAMPLE_INTERVAL_MS 100
#define STALL_TIME_US 40
#define GYRO_SENSITIVITY 0.005 // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB
#define DATA_FILE "imu_data.csv"

// ADIS16488A Registers
#define REG_GYRO_XOUT 0x04
#define REG_GYRO_YOUT 0x06
#define REG_GYRO_ZOUT 0x08
#define REG_ACCEL_XOUT 0x0A
#define REG_ACCEL_YOUT 0x0C
#define REG_ACCEL_ZOUT 0x0E

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Structure to hold sensor data
typedef struct {
    double timestamp;
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} sensor_data_t;

// Function prototypes
int spi_read_register(int reg_addr, int16_t *data);
int spi_write_register(int reg_addr, int16_t data);
int read_imu_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Function to read a register from the ADIS16488A
int spi_read_register(int reg_addr, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = 0x80 | (reg_addr << 1); // MSB=1 for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the chip
    gpioDelay(STALL_TIME_US);

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

    gpioWrite(CS_PIN, 1); // Deselect the chip
    gpioDelay(STALL_TIME_US);

    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// Function to write a register in the ADIS16488A
int spi_write_register(int reg_addr, int16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = (reg_addr << 1); // MSB=0 for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF;       // LSB of data

    gpioWrite(CS_PIN, 0); // Select the chip
    gpioDelay(STALL_TIME_US);

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

    gpioWrite(CS_PIN, 1); // Deselect the chip
    gpioDelay(STALL_TIME_US);

    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(sensor_data_t *data) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(REG_GYRO_XOUT, &raw_gyro_x) < 0) return -1;
    if (spi_read_register(REG_GYRO_YOUT, &raw_gyro_y) < 0) return -1;
    if (spi_read_register(REG_GYRO_ZOUT, &raw_gyro_z) < 0) return -1;
    if (spi_read_register(REG_ACCEL_XOUT, &raw_accel_x) < 0) return -1;
    if (spi_read_register(REG_ACCEL_YOUT, &raw_accel_y) < 0) return -1;
