#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define ADIS16448_REG_GYRO_XOUT 0x04
#define ADIS16448_REG_GYRO_YOUT 0x06
#define ADIS16448_REG_GYRO_ZOUT 0x08
#define ADIS16448_REG_ACCEL_XOUT 0x0A
#define ADIS16448_REG_ACCEL_YOUT 0x0C
#define ADIS16448_REG_ACCEL_ZOUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting...\n");
}

// Function to read data from ADIS16448 register
int16_t read_adis16448_register(int handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Set MSB of register address for read operation
    tx_buf[0] = (reg_addr << 1) | 0x01;
    tx_buf[1] = 0x00; // Dummy byte for clocking out data

    status = spiXfer(handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", status);
        return -1; // Indicate error
    }

    return (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
}

int main() {
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    float gyro_x_scaled, gyro_y_scaled, gyro_z_scaled, accel_x_scaled, accel_y_scaled, accel_z_scaled;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_x = read_adis16448_register(spi_handle, ADIS16448_REG_GYRO_XOUT);
        gyro_y = read_adis16448_register(spi_handle, ADIS16448_REG_GYRO_YOUT);
        gyro_z = read_adis16448_register(spi_handle, ADIS16448_REG_GYRO_ZOUT);

        // Read accelerometer data
        accel_x = read_adis16448_register(spi_handle, ADIS16448_REG_ACCEL_XOUT);
        accel_y = read_adis16448_register(spi_handle, ADIS16448_REG_ACCEL_YOUT);
        accel_z = read_adis16448_register(spi_handle, ADIS16448_REG_ACCEL_ZOUT);

        // Check for read errors
        if (gyro_x == -1 || gyro_y == -1 || gyro_z == -1 ||
            accel_x == -1 || accel_y == -1 || accel_z == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Scale the data
        gyro_x_scaled = gyro_x * GYRO_SCALE;
        gyro_y_scaled = gyro_y * GYRO_SCALE;
        gyro_z_scaled = gyro_z * GYRO_SCALE;

        accel_x_scaled = accel_x * ACCEL_SCALE;
        accel_y_scaled = accel_y * ACCEL_SCALE;
        accel_z_scaled = accel_z * ACCEL_SCALE;

        // Print the data
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s, Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gyro_x_scaled, gyro_y_scaled, gyro_z_scaled,
               accel_x_scaled, accel_y_scaled, accel_z_scaled);

        gpioDelay(100); // Wait 100ms
    }

    // Close SPI channel and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

