        if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) == 2) {
            value = (buf[0] << 8) | buf[1];
            return value;
        } else {
            fprintf(stderr, "Error reading register 0x%02X, retrying...\n", reg);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return 0; // Return 0 on failure
}

