    i2c_handle = i2cOpen(1, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6886
    if (i2cWriteByteData(i2c_handle, MPU6886_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer values
        int16_t accel_x = read_mpu6886_value(MPU6886_ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6886_value(MPU6886_ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6886_value(MPU6886_ACCEL_XOUT_H + 4);

        // Read gyroscope values
        int16_t gyro_x = read_mpu6886_value(MPU6886_GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6886_value(MPU6886_GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6886_value(MPU6886_GYRO_XOUT_H + 4);

