#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Sensitivity scales (adjust as needed based on your configuration)
#define ACCEL_SCALE 16384.0f  // +/- 2g range
#define GYRO_SCALE  131.0f    // +/- 250 dps range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the ICM-20602
int init_icm20602() {
    // Wake up the device (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up ICM-20602\n");
        return -1;
    }
    return 0;
}

// Function to read raw sensor data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[12];

    // Read accelerometer and gyroscope data in one go
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 12) != 12) {
        fprintf(stderr, "Error: Could not read sensor data\n");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x  = (int16_t)((buffer[6] << 8) | buffer[7]);
    *gyro_y  = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_z  = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    sensor_data_t data;

    data.accel_x = (float)accel_x / ACCEL_SCALE;
    data.accel_y = (float)accel_y / ACCEL_SCALE;
    data.accel_z = (float)accel_z / ACCEL_SCALE;
    data.gyro_x  = (float)gyro_x  / GYRO_SCALE;
    data.gyro_y  = (float)gyro_y  / GYRO_SCALE;
    data.gyro_z  = (float)gyro_z  / GYRO_SCALE;

    return data;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

