FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMAG5273_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the TMAG5273
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;

    // Read X, Y, and Z axis data in one go
    result = i2cReadI2CBlockData(i2c_handle, X_AXIS_REG, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine the bytes to form 16-bit integers
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Log data to CSV file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file exists and write the header if it doesn't
    FILE *fp = fopen(CSV_FILENAME, "r");
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        csv_file = fopen(CSV_FILENAME, "w");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file for writing: %s\n", CSV_FILENAME);
            return -1;
        }
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    } else {
        fclose(fp);
        csv_file = fopen(CSV_FILENAME, "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file for appending: %s\n", CSV_FILENAME);
            return -1;
        }
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Log data to CSV file
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample period
        usleep(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

