#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_FREE_FALL 0x28

// GPIO pin for interrupt
#define INT_GPIO 17

// Free-fall threshold (g)
#define FREE_FALL_THRESHOLD 0.2

// Free-fall duration (ms)
#define FREE_FALL_DURATION 50

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile int running = 1;
static volatile int freefall_active = 0;

// Function prototypes
int adxl345_init();
int adxl345_read_register(int reg);
int adxl345_write_register(int reg, int value);
int adxl345_read_acceleration(float *x, float *y, float *z);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int adxl345_init() {
    int retries = 3;
    while (retries > 0) {
        // Verify device ID
        int devid = adxl345_read_register(ADXL345_REG_DEVID);
        if (devid != 0xE5) {
            fprintf(stderr, "Error: Invalid device ID: 0x%02X (expected 0xE5)\n", devid);
            retries--;
            sleep(1);
            continue;
        }

        // Put the ADXL345 into standby mode
        if (adxl345_write_register(ADXL345_REG_POWER_CTL, 0x00) != 0) {
            fprintf(stderr, "Error: Failed to put ADXL345 into standby mode\n");
            retries--;
            sleep(1);
            continue;
        }

        // Enable free-fall interrupt
        if (adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x40) != 0) {
            fprintf(stderr, "Error: Failed to enable free-fall interrupt\n");
            retries--;
            sleep(1);
            continue;
        }

        // Enable measurement mode
        if (adxl345_write_register(ADXL345_REG_POWER_CTL, 0x08) != 0) {
            fprintf(stderr, "Error: Failed to enable measurement mode\n");
            retries--;
            sleep(1);
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Error: ADXL345 initialization failed after multiple retries\n");
    return -1; // Initialization failed
}

// Function to read a register from the ADXL345
int adxl345_read_register(int reg) {
    int result = i2cReadByteData(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error: I2C read failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a register to the ADXL345
int adxl345_write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error: I2C write failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(float *x, float *y, float *z) {
    int16_t x0, x1, y0, y1, z0, z1;

    x0 = adxl345_read_register(ADXL345_REG_DATAX0);
    x1 = adxl345_read_register(ADXL345_REG_DATAX1);
    y0 = adxl345_read_register(ADXL345_REG_DATAY0);
    y1 = adxl345_read_register(ADXL345_REG_DATAY1);
    z0 = adxl345_read_register(ADXL345_REG_DATAZ0);
    z1 = adxl345_read_register(ADXL345_REG_DATAZ1);

    if (x0 < 0 || x1 < 0 || y0 < 0 || y1 < 0 || z0 < 0 || z1 < 0) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }

    *x = (float)((int16_t)(x1 << 8 | x0)) * 0.0039; // Convert to g
    *y = (float)((int16_t)(y1 << 8 | y0)) * 0.0039;
    *z = (float)((int16_t)(z1 << 8 | z0)) * 0.0039;

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge (interrupt occurred)
        freefall_active = 1;
        printf("Free-fall detected!\n");
    } else if (level == 0) { // Falling edge (interrupt ended)
        freefall_active = 0;
        printf("Free-fall ended.\n");
    }
}

// Function to log data to a CSV file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    char milliseconds[5];
    snprintf(milliseconds, sizeof(milliseconds), ".%03ld", ts.tv_nsec / 1000000);
    strcat(timestamp, milliseconds);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for interrupt pin
    gpioSetMode(INT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set interrupt handler\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    struct timespec start_time, current_time;
    long elapsed_time;

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (freefall_active) {
            if (adxl345_read_acceleration(&x, &y, &z) == 0) {
                log_data(x, y, z);
            }

            clock_gettime(CLOCK_MONOTONIC, &current_time);
            elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

            if (elapsed_time >= FREE_FALL_DURATION) {
                freefall_active = 0;
                printf("Free-fall duration exceeded. Disabling logging.\n");
            }
        } else {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Disable interrupt
    gpioSetISRFuncEx(INT_GPIO, RISING_EDGE, 0, NULL, NULL);

    // Close I2C bus
    i2cClose(i2c_fd);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Exited cleanly.\n");
    return 0;
}

