#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Sensitivity values (from datasheet)
#define ACCEL_SENSITIVITY 0.061 // mg/LSB, for +/- 2g range
#define GYRO_SENSITIVITY 8.75  // mdps/LSB, for +/- 250 dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define IMPACT_WINDOW 1.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Enum for fall detection state
enum {
    IDLE,
    FREEFALL,
    IMPACT
} fall_state = IDLE;

// Structure to hold sensor data
typedef struct {
    double timestamp;
    double accel_x;
    double accel_y;
    double accel_z;
    double gyro_x;
    double gyro_y;
    double gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
double convert_accel(int16_t raw_accel);
double convert_gyro(int16_t raw_gyro);
int log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);
int check_who_am_i();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

