#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define WHO_AM_I   0x02
#define GYRO_OUT   0x04
#define SMPL_PRD   0x36
#define SMPL_PRD_2 0x37

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    3       // CPOL=1, CPHA=1
#define CS_PIN      8       // GPIO8 (CE0)

// Scale Factor
#define SCALE_FACTOR 0.0305 // deg/sec/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg_addr, int16_t *data);
int spi_write_register(uint8_t reg_addr, uint16_t data);
int verify_adis16266();
int sample_gyro_data(double *angular_rate);
int log_data(double timestamp, double angular_rate);
void signal_handler(int signal);

// Function to read a 16-bit register from the ADIS16266
int spi_read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // OR with 0x80 for read
    tx_buf[1] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a 16-bit register to the ADIS16266
int spi_write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // AND with 0x7F for write
    tx_buf[1] = data & 0xFF; // LSB

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to verify the ADIS16266's WHO_AM_I register
int verify_adis16266() {
    int16_t who_am_i;
    if (spi_read_register(WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x4000) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%X\n", who_am_i);
        return -1;
    }

    printf("ADIS16266 WHO_AM_I check passed: 0x%X\n", who_am_i);
    return 0;
}

// Function to sample gyroscope data and convert to angular rate
int sample_gyro_data(double *angular_rate) {
    int16_t raw_data;

    if (spi_read_register(GYRO_OUT, &raw_data) != 0) {
        fprintf(stderr, "Failed to read GYRO_OUT register\n");
        return -1;
    }

    *angular_rate = (double)raw_data * SCALE_FACTOR;
    return 0;
}

// Function to log data to a CSV file
int log_data(double timestamp, double angular_rate) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%.6f,%.6f\n", timestamp, angular_rate);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify ADIS16266
    if (verify_adis16266() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set sample period (adjust as needed)
    if (spi_write_register(SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (spi_write_register(SMPL_PRD_2, 0x0000) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,AngularRate\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    double angular_rate;
    struct timespec ts;
    double timestamp;

    while (!terminate) {
        if (sample_gyro_data(&angular_rate) == 0) {
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
                if (log_data(timestamp, angular_rate) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to sample gyro data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

