    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify ADIS16266
    if (verify_adis16266() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set sample period (adjust as needed)
    if (spi_write_register(SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (spi_write_register(SMPL_PRD_2, 0x0000) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,AngularRate\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    double angular_rate;
    struct timespec ts;
    double timestamp;

    while (!terminate) {
        if (sample_gyro_data(&angular_rate) == 0) {
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
                if (log_data(timestamp, angular_rate) != 0) {
