#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69 // Or 0x68, check WHO_AM_I
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 0.00875 // 8.75 mdps/LSB
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_NS 10000000 // 10 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_value);
int log_data(struct timespec ts, float x, float y, float z);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int result, retries = 0;
    char buf[2];

    // Check WHO_AM_I register
    buf[0] = WHO_AM_I;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result == 0) break;
        fprintf(stderr, "Error writing WHO_AM_I register (attempt %d): %d\n", retries + 1, result);
        gpioDelay(1000); // Wait 1 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write WHO_AM_I register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 1);
        if (result == 1) break;
        fprintf(stderr, "Error reading WHO_AM_I register (attempt %d): %d\n", retries + 1, result);
        gpioDelay(1000); // Wait 1 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read WHO_AM_I register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    if (buf[0] != 0xD3) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xD3.\n", buf[0]);
        return -1;
    }

    // Configure CTRL_REG1 (0x20)
    buf[0] = CTRL_REG1;
    buf[1] = 0x0F; // Enable all axes, 100 Hz ODR
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, buf, 2);
        if (result == 0) break;
        fprintf(stderr, "Error writing CTRL_REG1 (attempt %d): %d\n", retries + 1, result);
        gpioDelay(1000); // Wait 1 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write CTRL_REG1 after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Configure CTRL_REG4 (0x23)
    buf[0] = CTRL_REG4;
    buf[1] = 0x00; // +/- 250 dps
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, buf, 2);
        if (result == 0) break;
        fprintf(stderr, "Error writing CTRL_REG4 (attempt %d): %d\n", retries + 1, result);
        gpioDelay(1000); // Wait 1 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write CTRL_REG4 after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    return 0;
}

// Read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[1];
    char data[6];
    int result, retries = 0;

    // Set the register to read from (OUT_X_L)
    buf[0] = OUT_X_L | 0x80; // Enable auto-increment

    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result == 0) break;
        fprintf(stderr, "Error writing register address (attempt %d): %d\n", retries + 1, result);
        gpioDelay(1000); // Wait 1 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write register address after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, data, 6);
        if (result == 6) break;
        fprintf(stderr, "Error reading gyro data (attempt %d): %d\n", retries + 1, result);
        gpioDelay(1000); // Wait 1 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read gyro data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Convert raw data to degrees per second
float convert_to_dps(int16_t raw_value) {
    return (float)raw_value * SENSITIVITY;
}

// Log data to CSV file
int log_data(struct timespec ts, float x, float y, float z) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f\n", ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    int result;
    struct timespec ts;
    gyro_data_t gyro_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data.x, &gyro_data.y, &gyro_data.z) == 0) {
            // Convert raw data to DPS
            float x_dps = convert_to_dps(gyro_data.x);
            float y_dps = convert_to_dps(gyro_data.y);
            float z_dps = convert_to_dps(gyro_data.z);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
                break;
            }

            // Log data
            if (log_data(ts, x_dps, y_dps, z_dps) != 0) {
                fprintf(stderr, "Error logging data\n");
                break;
            }
        } else {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }

        // Delay for 10 ms
        gpioDelay(SAMPLE_INTERVAL_NS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

