#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x4C
#define SAMPLE_INTERVAL_MS 100
#define SENSITIVITY_SCALE_FACTOR 0.001 // Example sensitivity, adjust as needed
#define SENSOR_ABSENT_VALUE -1
#define CSV_FILENAME "vibration_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
char *get_iso8601_timestamp();
int write_to_csv(const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(1, D7S_ADDR, 0); // Open I2C bus 1, D7S address 0x4C, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int bytes_read = i2cReadI2CBlockData(i2c_fd, 0x00, buf, 6); // Read 6 bytes starting from register 0x00

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Combine bytes to form 16-bit values
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to get ISO 8601 timestamp
char *get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write data to CSV file
int write_to_csv(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (csv_file == NULL) {
        fprintf(stderr, "CSV file is not open\n");
        return -1;
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file); // Flush the buffer to ensure data is written
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Cleaning up and exiting...\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header to CSV file
    fprintf(csv_file, "Timestamp,X,Y,Z\n");
    fflush(csv_file);

    int16_t x, y, z;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Write data to CSV file
                if (write_to_csv(timestamp, x, y, z) != 0) {
                    fprintf(stderr, "Error writing to CSV file\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping sample.\n");
        }

        // Delay for 100ms
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

