#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the Hall effect sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_data(int sensor1_state, int sensor2_state);
void handle_signal(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorData;

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of a Hall effect sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data to a file
int log_data(int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Get milliseconds
    long milliseconds = ts.tv_nsec / 1000000;

    if (log_file != NULL) {
        fprintf(log_file, "%ld.%03ld,%d,%d\n", ts.tv_sec, milliseconds, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void handle_signal(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0; // Set the running flag to 0 to exit the main loop

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0); // Exit the program
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize the pigpio library and configure GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file for writing
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate(); // Clean up GPIO before exiting
        return 1; // Exit if file opening fails
    }

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Log the data
        if (log_data(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Check if both sensors are active
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Halt message: Conveyor stopped.\n");
        }

        // Wait for 50 milliseconds
        gpioDelay(50); // pigpio's replacement for time_sleep
    }

    // The program will exit gracefully when the running flag is set to 0
    return 0;
}

