#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define DATA_LENGTH 6
#define SAMPLE_RATE_HZ 100
#define SAMPLE_INTERVAL_MS (1000 / SAMPLE_RATE_HZ)
#define FALL_THRESHOLD_DEGREES 45.0
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor();
int configure_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Verify sensor ID
int verify_sensor() {
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    printf("WHO_AM_I verified successfully.\n");
    return 0;
}

// Configure sensor
int configure_sensor() {
    uint8_t ctrl_reg1_value = 0x01 | (0x01 << 3); // Active mode, 100Hz
    if (write(i2c_fd, &ctrl_reg1_value, 1) != 1) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor configured for active mode and 100Hz data rate.\n");
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[DATA_LENGTH];
    if (read(i2c_fd, data, DATA_LENGTH) != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)(((data[0] << 8) | data[1]) >> 4);
    *y = (int16_t)(((data[2] << 8) | data[3]) >> 4);
    *z = (int16_t)(((data[4] << 8) | data[5]) >> 4);

    return 0;
}

// Calculate tilt
double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 2048.0; // Assuming +/- 2g range
    double y_g = (double)y / 2048.0;
    double z_g = (double)z / 2048.0;

    double tilt_x = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;
    double tilt_y = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
