int configure_sensor() {
    uint8_t ctrl_reg1_value = 0x01 | (0x01 << 3); // Active mode, 100Hz
    if (write(i2c_fd, &ctrl_reg1_value, 1) != 1) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor configured for active mode and 100Hz data rate.\n");
    return 0;
}

