int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[DATA_LENGTH];
    if (read(i2c_fd, data, DATA_LENGTH) != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)(((data[0] << 8) | data[1]) >> 4);
    *y = (int16_t)(((data[2] << 8) | data[3]) >> 4);
    *z = (int16_t)(((data[4] << 8) | data[5]) >> 4);

    return 0;
}

