#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants (replace with your actual values)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Magnetic field sensitivity (±4 gauss)
#define MG_PER_LSB 0.146

// Metal detection threshold (800 mG)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration data
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
    float x_scale;
    float y_scale;
    float z_scale;
} calibration_data_t;

calibration_data_t calibration = {X_OFFSET, Y_OFFSET, Z_OFFSET, X_SCALE, Y_SCALE, Z_SCALE};

// Function prototypes
int initialize_sensor();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
float apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z);
void log_data(float x, float y, float z);
void metal_detector_alert(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the LIS3MDL sensor
int initialize_sensor() {
    int retries = 3;
    while (retries > 0) {
        // Configure CTRL_REG1: 10 Hz data rate, continuous conversion
        if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG3: Enable I2C
        if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG4: +/- 4 gauss full scale
        if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG4, 0x00) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Sensor initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read raw magnetic field data from the sensor
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetic data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to apply calibration and convert to milliGauss
float apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    float x = (float)raw_x * MG_PER_LSB * calibration.x_scale - calibration.x_offset;
    float y = (float)raw_y * MG_PER_LSB * calibration.y_scale - calibration.y_offset;
    float z = (float)raw_z * MG_PER_LSB * calibration.z_scale - calibration.z_offset;
    return x * 1000.0; // Convert to milliGauss
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Function to check for metal detection
void metal_detector_alert(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detector Alert: Magnetic field magnitude exceeds threshold (%.3f mG)\n", magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Apply calibration
            x = apply_calibration(raw_x, raw_y, raw_z);
            y = apply_calibration(raw_x, raw_y, raw_z);
            z = apply_calibration(raw_x, raw_y, raw_z);

            // Log data
            log_data(x, y, z);

            // Check for metal detection
            metal_detector_alert(x, y, z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

