#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8 // GPIO8 (BCM)

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adxl354_read_register(uint8_t reg_addr, uint8_t *data, int len);
int adxl354_write_register(uint8_t reg_addr, uint8_t data);
int adxl354_reset();
int adxl354_verify_sensor();
int adxl354_read_acceleration(int32_t *x, int32_t *y, int32_t *z);
void log_data(int32_t x, int32_t y, int32_t z);
void signal_handler(int signal);

// Function to read a register from the ADXL354B
int adxl354_read_register(uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB for read

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to write a register in the ADXL354B
int adxl354_write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = (reg_addr << 1) & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiWrite(spi_handle, tx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to reset the ADXL354B
int adxl354_reset() {
    if (adxl354_write_register(ADXL354_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Reset write failed\n");
        return -1;
    }
    gpioDelay(1); // Wait 1ms
    return 0;
}

// Function to verify sensor presence
int adxl354_verify_sensor() {
    uint8_t partid;
    if (adxl354_read_register(ADXL354_REG_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Part ID read failed\n");
        return -1;
    }

    if (partid != 0x0B) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", partid);
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int adxl354_read_acceleration(int32_t *x, int32_t *y, int32_t *z) {
    uint8_t x_data[3], y_data[3], z_data[3];

    if (adxl354_read_register(ADXL354_REG_XDATA_H, x_data, 3) != 0) {
        fprintf(stderr, "X-axis data read failed\n");
        return -1;
    }
    if (adxl354_read_register(ADXL354_REG_YDATA_H, y_data, 3) != 0) {
        fprintf(stderr, "Y-axis data read failed\n");
        return -1;
    }
    if (adxl354_read_register(ADXL354_REG_ZDATA_H, z_data, 3) != 0) {
        fprintf(stderr, "Z-axis data read failed\n");
        return -1;
    }

    // Combine the bytes to form 20-bit signed integers
    *x = ((int32_t)x_data[0] << 12) | ((int32_t)x_data[1] << 4) | ((int32_t)x_data[2] >> 4);
    if (*x & 0x80000) *x |= 0xFFF00000; // Sign extend

    *y = ((int32_t)y_data[0] << 12) | ((int32_t)y_data[1] << 4) | ((int32_t)y_data[2] >> 4);
    if (*y & 0x80000) *y |= 0xFFF00000; // Sign extend

    *z = ((int32_t)z_data[0] << 12) | ((int32_t)z_data[1] << 4) | ((int32_t)z_data[2] >> 4);
    if (*z & 0x80000) *z |= 0xFFF00000; // Sign extend

    return 0;
}

// Function to log data to a file
void log_data(int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // ADXL354B Initialization Sequence
    if (adxl354_reset() != 0) {
        fprintf(stderr, "Reset failed, exiting\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (adxl354_verify_sensor() != 0) {
        fprintf(stderr, "Sensor verification failed, exiting\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int32_t x, y, z;
    while (!terminate) {
        if (adxl354_read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

