#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define ADIS16362_REG_XGYRO_OUT 0x04
#define ADIS16362_REG_YGYRO_OUT 0x06
#define ADIS16362_REG_ZGYRO_OUT 0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E
#define ADIS16362_REG_TEMP_OUT 0x10
#define ADIS16362_REG_GLOB_CMD 0x68
#define ADIS16362_REG_SMPL_PRD 0x36
#define ADIS16362_REG_DIAG_STS 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0
#define CE0_PIN 8

// Scaling Factors
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int reg_addr, int *data);
int spi_write_register(int reg_addr, int data);
int init_adis16362();
int read_imu_data(float *x_gyro, float *y_gyro, float *z_gyro, float *x_accel, float *y_accel, float *z_accel);
int log_data(long long timestamp, float x_gyro, float y_gyro, float z_gyro, float x_accel, float y_accel, float z_accel);
void signal_handler(int signal);

// Function to read a 16-bit register from the ADIS16362
int spi_read_register(int reg_addr, int *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = (reg_addr << 1) | 0x80; // MSB set for read
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// Function to write a 16-bit register in the ADIS16362
int spi_write_register(int reg_addr, int data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = (reg_addr << 1) & 0x7F; // MSB clear for write
    tx_buf[1] = (data >> 8) & 0xFF;
    tx_buf[2] = data & 0xFF;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Function to initialize the ADIS16362
int init_adis16362() {
    // Reset the device
    if (spi_write_register(ADIS16362_REG_GLOB_CMD, 0x0004) != 0) {
        fprintf(stderr, "Failed to reset ADIS16362\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set sample period (adjust as needed)
    if (spi_write_register(ADIS16362_REG_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }

    // Verify initialization by reading the temperature register
    int temp_data;
    if (spi_read_register(ADIS16362_REG_TEMP_OUT, &temp_data) != 0) {
        fprintf(stderr, "Failed to read temperature register\n");
        return -1;
    }

    // Basic check: if the temperature is within a reasonable range
    if (temp_data < -500 || temp_data > 500) {
        fprintf(stderr, "ADIS16362 initialization failed. Temperature out of range: %d\n", temp_data);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(float *x_gyro, float *y_gyro, float *z_gyro, float *x_accel, float *y_accel, float *z_accel) {
    int x_gyro_raw, y_gyro_raw, z_gyro_raw, x_accel_raw, y_accel_raw, z_accel_raw;

    if (spi_read_register(ADIS16362_REG_XGYRO_OUT, &x_gyro_raw) != 0) return -1;
    if (spi_read_register(ADIS16362_REG_YGYRO_OUT, &y_gyro_raw) != 0) return -1;
    if (spi_read_register(ADIS16362_REG_ZGYRO_OUT, &z_gyro_raw) != 0) return -1;
    if (spi_read_register(ADIS16362_REG_XACCEL_OUT, &x_accel_raw) != 0) return -1;
    if (spi_read_register(ADIS16362_REG_YACCEL_OUT, &y_accel_raw) != 0) return -1;
    if (spi_read_register(ADIS16362_REG_ZACCEL_OUT, &z_gyro_raw) != 0) return -1; // ZGYRO_OUT is actually ZACCEL_OUT

    *x_gyro = (float)x_gyro_raw * GYRO_SCALE;
    *y_gyro = (float)y_gyro_raw * GYRO_SCALE;
    *z_gyro = (float)z_gyro_raw * GYRO_SCALE;
    *x_accel = (float)x_accel_raw * ACCEL_SCALE;
    *y_accel = (float)y_accel_raw * ACCEL_SCALE;
    *z_accel = (float)z_gyro_raw * ACCEL_SCALE; // ZGYRO_OUT is actually ZACCEL_OUT

    return 0;
}

// Function to log data to a CSV file
int log_data(long long timestamp, float x_gyro, float y_gyro, float z_gyro, float x_accel, float y_accel, float z_accel) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16362
    if (init_adis16362() != 0) {
        fprintf(stderr, "ADIS16362 initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;
    struct timespec ts;
    long long timestamp;

    // Main loop
    while (!terminate) {
        // Read IMU data
        if (read_imu_data(&x_gyro, &y_gyro, &z_gyro, &x_accel, &y_accel, &z_accel) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (long long)ts.tv_sec * 1000000000LL + (long long)ts.tv_nsec;

                // Log data
                if (log_data(timestamp, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }

        // Delay for 10ms
        gpioDelay(10000); // 10ms
    }

    // Close SPI handle
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

