#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define GPIO_CHIP 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_handle;
    int result;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    gpio_handle = gpioOpen(GPIO_CHIP, "r");
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to open GPIO chip %d: %d\n", GPIO_CHIP, gpio_handle);
        gpioTerminate();
        return 1;
    }

    // Request GPIO line for reading
    result = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", GPIO_PIN, result);
        gpioClose(gpio_handle);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking sequence started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO value
        result = gpioRead(GPIO_PIN);
        if (result < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %d\n", GPIO_PIN, result);
            break;
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log obstacle detection
        if (result == 0) {
            printf("[%s] Obstacle detected! Self-parking sequence started.\n", timestamp);
            // Simulate self-parking routine
            for (int i = 0; i < 5; i++) {
                printf("[%s] Simulating self-parking step %d...\n", timestamp, i + 1);
                gpioDelay(1000); // Simulate 1 second delay
            }
            printf("[%s] Self-parking sequence completed.\n", timestamp);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Release GPIO line and close chip
    gpioClose(gpio_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

