#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CS_PIN 8

// Scale Factor
#define SCALE_FACTOR 0.02 // deg/sec per LSB

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// SPI Read Register
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Set MSB of register address for read
    tx_buf[0] = (reg_addr << 1) | 0x01; // MSB set for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// SPI Write Register
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Set MSB of register address for write
    tx_buf[0] = (reg_addr << 1) & 0xFE; // MSB clear for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

int main() {
    int status;
    int16_t x_gyro, y_gyro, z_gyro;
    double x_rate, y_rate, z_rate;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);
    gpioWrite(SPI_CS_PIN, 1); // Deactivate CS

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("ADIS16266 Gyroscope Data Acquisition\n");

    while (!terminate) {
        // Read gyroscope data
        status = spi_read_register(spi_handle, ADIS16266_REG_XGYRO_OUT, &x_gyro);
        if (status != 0) {
            fprintf(stderr, "Error reading X gyro data\n");
            continue; // Skip to the next iteration
        }

        status = spi_read_register(spi_handle, ADIS16266_REG_YGYRO_OUT, &y_gyro);
        if (status != 0) {
            fprintf(stderr, "Error reading Y gyro data\n");
            continue; // Skip to the next iteration
        }

        status = spi_read_register(spi_handle, ADIS16266_REG_ZGYRO_OUT, &z_gyro);
        if (status != 0) {
            fprintf(stderr, "Error reading Z gyro data\n");
            continue; // Skip to the next iteration
        }

        // Convert to angular rates
        x_rate = x_gyro * SCALE_FACTOR;
        y_rate = y_gyro * SCALE_FACTOR;
        z_rate = z_gyro * SCALE_FACTOR;

        // Print the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

