    gpioWrite(SPI_CS_PIN, 1); // Deactivate CS

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("ADIS16266 Gyroscope Data Acquisition\n");

    while (!terminate) {
        // Read gyroscope data
        status = spi_read_register(spi_handle, ADIS16266_REG_XGYRO_OUT, &x_gyro);
        if (status != 0) {
            fprintf(stderr, "Error reading X gyro data\n");
            continue; // Skip to the next iteration
        }

        status = spi_read_register(spi_handle, ADIS16266_REG_YGYRO_OUT, &y_gyro);
        if (status != 0) {
            fprintf(stderr, "Error reading Y gyro data\n");
            continue; // Skip to the next iteration
        }

        status = spi_read_register(spi_handle, ADIS16266_REG_ZGYRO_OUT, &z_gyro);
        if (status != 0) {
            fprintf(stderr, "Error reading Z gyro data\n");
            continue; // Skip to the next iteration
        }

        // Convert to angular rates
        x_rate = x_gyro * SCALE_FACTOR;
        y_rate = y_gyro * SCALE_FACTOR;
        z_rate = z_gyro * SCALE_FACTOR;

        // Print the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

