#include <signal.h>
#include <unistd.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from I2C registers
int read_registers(int handle, uint8_t reg, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading block of registers starting at 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int handle) {
    // Check WHO_AM_I register
    int who_am_i = read_register(handle, WHO_AM_I);
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 1.66 kHz, +/- 2g
    if (write_register(handle, CTRL1_XL, 0x80) < 0) return -1; // 1.66 kHz, +/- 2g

    // Configure gyroscope: 1.66 kHz, 250 dps
    if (write_register(handle, CTRL2_G, 0x80) < 0) return -1; // 1.66 kHz, 250 dps

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_imu_data(int handle, float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buf[12];

    if (read_registers(handle, OUTX_L_G, buf, 12) < 0) {
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t raw_accel_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_accel_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_accel_z = (int16_t)((buf[5] << 8) | buf[4]);

    // Combine high and low bytes for gyroscope data
    int16_t raw_gyro_x = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_gyro_y = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_gyro_z = (int16_t)((buf[11] << 8) | buf[10]);

    // Convert raw data to g and dps (assuming +/- 2g and 250 dps)
    *accel_x = (float)raw_accel_x / 16384.0f; // 16384 LSB/g
    *accel_y = (float)raw_accel_y / 16384.0f;
    *accel_z = (float)raw_accel_z / 16384.0f;
    *gyro_x = (float)raw_gyro_x / 131.0f;    // 131 LSB/dps
    *gyro_y = (float)raw_gyro_y / 131.0f;
    *gyro_z = (float)raw_gyro_z / 131.0f;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        if (read_imu_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
