// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_OUT_X_MSB 0x01

// Expected WHO_AM_I value
#define FXOS8700_WHO_AM_I_VALUE 0xC7

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700()
{
    int status;

    // Check WHO_AM_I register
    status = i2cWriteByteData(i2c_handle, FXOS8700_WHO_AM_I, 0); // Dummy write to trigger read
    if (status < 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register: %d\n", status);
        return -1;
    }
    status = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }
    if (status != FXOS8700_WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", FXOS8700_WHO_AM_I_VALUE, status);
        return -1;
    }
    fprintf(stderr, "FXOS8700 WHO_AM_I check passed!\n");

    // Configure the sensor (Hybrid mode, 100 Hz data rate)
    status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x0D); // Active mode, 100 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG2, 0x02); // High resolution
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2 register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read data from the FXOS8700 sensor
int read_fxos8700(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z)
{
    char buffer[12];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (status < 0) {
        fprintf(stderr, "Error reading data: %d\n", status);
        return -1;
    }

    // Extract accelerometer data
    *accel_x = (int16_t)((((uint16_t)buffer[0]) << 6) | (buffer[1] >> 2));
    *accel_y = (int16_t)((((uint16_t)buffer[2]) << 6) | (buffer[3] >> 2));
    *accel_z = (int16_t)((((uint16_t)buffer[4]) << 6) | (buffer[5] >> 2));

    // Extract magnetometer data
    *mag_x = (int16_t)((((uint16_t)buffer[6]) << 8) | buffer[7]);
    *mag_y = (int16_t)((((uint16_t)buffer[8]) << 8) | buffer[9]);
    *mag_z = (int16_t)((((uint16_t)buffer[10]) << 8) | buffer[11]);

    return 0;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;

    // Main loop
    while (!terminate) {
        if (read_fxos8700(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            printf("Accel: X=%d, Y=%d, Z=%d, Mag: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

