double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 256.0; // Assuming +/- 2g range
    double y_g = (double)y / 256.0;
    double z_g = (double)z / 256.0;

    double tilt_angle = atan2(sqrt(x_g * x_g + y_g * y_g), z_g) * 180.0 / M_PI;
    return tilt_angle;
}

