#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_S 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int high_threshold;
    int i;
    int high_count;
    int gpio_status;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <high_threshold>\n", argv[0]);
        return 1;
    }

    high_threshold = atoi(argv[1]);

    if (high_threshold <= 0) {
        fprintf(stderr, "Error: High threshold must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Main loop
    while (program_running) {
        high_count = 0;

        // Sample for 5 seconds
        for (i = 0; i < WINDOW_DURATION_S * 1000 / SAMPLE_INTERVAL_MS; i++) {
            gpio_status = gpioRead(GPIO_PIN);
            if (gpio_status >= 0) {
                if (gpio_status == 1) {
                    high_count++;
                }
            } else {
                fprintf(stderr, "Error reading GPIO pin: %d\n", gpio_status);
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
        }

        // Get timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Check threshold and print status
        if (high_count > high_threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s Status: %d\n", timestamp, high_count);
        }

        // Pause for 1 second
        sleep(1);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

