#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for door locks
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define unlock duration (in seconds)
#define UNLOCK_DURATION 5

// Define security code length
#define CODE_LENGTH 6

// Global variable for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int generate_security_code(int *code);
int read_user_input(int *input_code);
int compare_codes(int *generated_code, int *input_code);
int log_access(int *code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to generate a random security code
int generate_security_code(int *code) {
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < CODE_LENGTH; i++) {
        code[i] = rand() % 10; // Generate a random number between 0 and 9
    }
    return 0;
}

// Function to read user input
int read_user_input(int *input_code) {
    char input[CODE_LENGTH + 1]; // Buffer to hold user input
    int i;

    printf("Enter the security code: ");
    if (fgets(input, sizeof(input), stdin) == NULL) {
        fprintf(stderr, "Error reading input\n");
        return -1;
    }

    // Remove trailing newline character, if present
    size_t len = strlen(input);
    if (len > 0 && input[len - 1] == '\n') {
        input[len - 1] = '\0';
    }

    // Validate input length
    if (strlen(input) != CODE_LENGTH) {
        fprintf(stderr, "Invalid input length. Please enter a %d-digit code.\n", CODE_LENGTH);
        return -1;
    }

    // Convert input to integers
    for (i = 0; i < CODE_LENGTH; i++) {
        if (input[i] < '0' || input[i] > '9') {
            fprintf(stderr, "Invalid input. Please enter a numeric code.\n");
            return -1;
        }
        input_code[i] = input[i] - '0'; // Convert char to int
    }

    return 0;
}

// Function to compare generated and input codes
int compare_codes(int *generated_code, int *input_code) {
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (generated_code[i] != input_code[i]) {
            return -1; // Codes do not match
        }
    }
    return 0; // Codes match
}

// Function to log access to a file
int log_access(int *code) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Convert code to string
    char code_str[CODE_LENGTH + 1];
    for (int i = 0; i < CODE_LENGTH; i++) {
        code_str[i] = '0' + code[i];
    }
    code_str[CODE_LENGTH] = '\0';

    // Create filename
    char filename[50];
    snprintf(filename, sizeof(filename), "access_log_%04d%02d%02d.txt", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday);

    // Open file for appending
    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return -1;
    }

    // Write to file
    fprintf(fp, "%s,%s\n", timestamp, code_str);

    // Close file
    fclose(fp);

    return 0;
}

int main() {
    int door_a_state = PI_LOW; // Initial state for Door A
    int door_b_state = PI_LOW; // Initial state for Door B
    int security_code[CODE_LENGTH];
    int user_input[CODE_LENGTH];
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Set initial output states
    gpioWrite(DOOR_A_GPIO, door_a_state);
    gpioWrite(DOOR_B_GPIO, door_b_state);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door Access Control System\n");

    while (!terminate) {
        // Generate security code
        if (generate_security_code(security_code) != 0) {
            fprintf(stderr, "Error generating security code\n");
            break;
        }

        // Print security code
        printf("Security Code: ");
        for (int i = 0; i < CODE_LENGTH; i++) {
            printf("%d", security_code[i]);
        }
        printf("\n");

        // Read user input
        if (read_user_input(user_input) != 0) {
            fprintf(stderr, "Error reading user input\n");
            continue; // Continue to the next iteration
        }

        // Compare codes
        result = compare_codes(security_code, user_input);

        if (result == 0) {
            // Log access
            if (log_access(security_code) != 0) {
                fprintf(stderr, "Error logging access\n");
            } else {
                printf("Access granted!\n");
            }
        } else {
            // Access denied
            printf("Access denied!\n");
        }

        // Delay before next attempt
        gpioDelay(2000); // 2 seconds
    }

    // Lock doors before exiting
    gpioWrite(DOOR_A_GPIO, PI_LOW);
    gpioWrite(DOOR_B_GPIO, PI_LOW);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

