#define LOG_FILE "frequency_log.txt"
#define SECRET_KEY "MySecretKey"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int init_mpr121();
int read_touch_data(int *touch_status);
void play_tone(int frequency);
void stop_tone();
void log_frequency(int frequency);
void handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        stop_tone();
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (new_socket >= 0) {
            close(new_socket);
        }
        if (server_fd >= 0) {
            close(server_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

