#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x1E
#define MAG_Z_OUT_L 0x04
#define MAG_Z_OUT_H 0x05
#define LED_GPIO 17
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_PERIOD_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_mag_data(int16_t *z_axis);
float calculate_magnitude(int16_t z_axis);
int set_led_brightness(float magnitude);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int lsm303_address;
    int led_gpio;
    int pwm_frequency;
    int sample_period_ms;
} config_t;

config_t config = {
    I2C_BUS,
    LSM303_ADDR,
    LED_GPIO,
    PWM_FREQUENCY,
    SAMPLE_PERIOD_MS
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(config.led_gpio, PI_OUTPUT);
    gpioSetPWMfrequency(config.led_gpio, config.pwm_frequency);
    gpioSetPWMrange(config.led_gpio, 255); // Set PWM range to 0-255

    // Open log file
    log_file = fopen("mag_data.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int16_t z_axis;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_mag_data(&z_axis) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(z_axis);

            // Set LED brightness
            if (set_led_brightness(magnitude) != 0) {
                log_error("Failed to set LED brightness");
            }

            // Log data
            struct timeval tv;
            gettimeofday(&tv, NULL);
            double timestamp = (double)tv.tv_sec + (double)tv.tv_usec / 1000000.0;
            fprintf(log_file, "%.6f, %.2f\n", timestamp, magnitude);
            fflush(log_file);
        } else {
            log_error("Failed to read magnetometer data");
        }

        // Wait for the next sample
        gpioDelay(config.sample_period_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.lsm303_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_mag_data(int16_t *z_axis) {
    char buffer[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, MAG_Z_OUT_L, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", bytes_read);
        return -1;
    }

    // Combine high and low bytes
    *z_axis = (int16_t)((buffer[1] << 8) | buffer[0]);

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t z_axis) {
    return (float)z_axis;
}

// Set LED brightness using PWM
int set_led_brightness(float magnitude) {
    // Map magnitude to PWM duty cycle (0-255)
    int duty_cycle = (int)(fabs(magnitude) / 1000.0 * 255.0); // Assuming max magnitude is 1000
    if (duty_cycle > 255) duty_cycle = 255;
    if (duty_cycle < 0) duty_cycle = 0;

    gpioPWM(config.led_gpio, duty_cycle);
    return 0;
}

// Log error messages
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    if (log_file != NULL) {
        fprintf(log_file, "Error: %s\n", message);
        fflush(log_file);
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop PWM
    gpioPWM(config.led_gpio, 0);

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

