#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define INT1_CFG_A 0x30
#define INT1_SRC_A 0x31
#define INT1_THS_A 0x32

// Accelerometer sensitivity (0.061 mg/LSB)
#define ACCEL_SENSITIVITY 0.061

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int16_t x, y, z;
} sample_t;

sample_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_lsm303d();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
void store_sample(int16_t x, int16_t y, int16_t z);
void dump_buffer();
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Function to initialize the LSM303D accelerometer
int init_lsm303d() {
    // Verify device ID
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x33) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1_A (Enable accelerometer, 100 Hz data rate)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Configure CTRL_REG4_A (Full scale selection: +/- 2g)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    // Configure INT1_CFG_A (Latch interrupt)
    if (i2cWriteByteData(i2c_handle, INT1_CFG_A, 0x40) < 0) {
        fprintf(stderr, "Error writing to INT1_CFG_A\n");
        return -1;
    }

    // Configure INT1_THS_A (Interrupt threshold: 2000 mg)
    if (i2cWriteByteData(i2c_handle, INT1_THS_A, 0xF9) < 0) {
        fprintf(stderr, "Error writing to INT1_THS_A\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to store a sample in the circular buffer
void store_sample(int16_t x, int16_t y, int16_t z) {
    circular_buffer[buffer_index].x = x;
    circular_buffer[buffer_index].y = y;
    circular_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the last 10 samples from the circular buffer
void dump_buffer() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s: ", timestamp);

    int start_index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < 10; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        printf("X: %.3f mg, Y: %.3f mg, Z: %.3f mg ",
               circular_buffer[index].x * ACCEL_SENSITIVITY,
               circular_buffer[index].y * ACCEL_SENSITIVITY,
               circular_buffer[index].z * ACCEL_SENSITIVITY);
    }
    printf("\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() < 0) {
        fprintf(stderr, "LSM303D initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_accelerometer(&x, &y, &z) == 0) {
            store_sample(x, y, z);
        } else {
            fprintf(stderr, "Error reading accelerometer, skipping sample\n");
        }

        // Check for interrupt (optional, for demonstration)
        int int1_src = i2cReadByteData(i2c_handle, INT1_SRC_A);
        if (int1_src < 0) {
            fprintf(stderr, "Error reading INT1_SRC_A: %d\n", int1_src);
        } else {
            if (int1_src & 0x01) {
                dump_buffer();
            }
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Disable accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A during shutdown\n");
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

