#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Function prototypes
int initialize_gpio();
void activate_solenoid(int gpio_pin);
void deactivate_solenoid(int gpio_pin);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track the current active solenoid
int active_solenoid = SOLENOID_1_GPIO;

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to switch between solenoids
    while (1) {
        // Activate the current solenoid
        activate_solenoid(active_solenoid);

        // Deactivate the other solenoid
        deactivate_solenoid((active_solenoid == SOLENOID_1_GPIO) ? SOLENOID_2_GPIO : SOLENOID_1_GPIO);

        // Toggle the active solenoid
        active_solenoid = (active_solenoid == SOLENOID_1_GPIO) ? SOLENOID_2_GPIO : SOLENOID_1_GPIO;

        // Wait for 500 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT);

    // Ensure both solenoids are deactivated initially
    deactivate_solenoid(SOLENOID_1_GPIO);
    deactivate_solenoid(SOLENOID_2_GPIO);

    return 0;
}

// Function to activate a solenoid (set GPIO pin HIGH)
void activate_solenoid(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO pin HIGH
}

// Function to deactivate a solenoid (set GPIO pin LOW)
void deactivate_solenoid(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO pin LOW
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Deactivate both solenoids
    deactivate_solenoid(SOLENOID_1_GPIO);
    deactivate_solenoid(SOLENOID_2_GPIO);

    // Terminate the pigpio library
    gpioTerminate();

    printf("GPIO cleanup complete. Exiting.\n");
    exit(0);
}

// Signal handler function to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up...\n", signal);
    cleanup_gpio();
}

