#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART devices
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout duration (in seconds)
#define TIMEOUT 5

// Global variables
int primary_fd = -1;
int secondary_fd = -1;

// Function prototypes
int read_code(int gpio, char *buffer, int buffer_size, int timeout);
int validate_code(const char *code1, const char *code2, const char *expected_code);
int unlock_locks(int gpio1, int gpio2, int duration_seconds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");

    // Force both locks to be locked
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    // Close UART ports
    if (primary_fd != -1) {
        serClose(primary_fd);
    }
    if (secondary_fd != -1) {
        serClose(secondary_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read a code from a UART port
int read_code(int gpio, char *buffer, int buffer_size, int timeout) {
    int fd;
    if (gpio == LOCK1_GPIO) {
        fd = primary_fd;
    } else if (gpio == LOCK2_GPIO) {
        fd = secondary_fd;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    if (fd == -1) {
        fprintf(stderr, "Error: UART port not opened for GPIO %d\n", gpio);
        return -1;
    }

    int i = 0;
    long start_time = time(NULL);

    while (i < buffer_size - 1) {
        int c = serReadByte(fd);

        if (c >= 0) {
            if (c >= '0' && c <= '9') {
                buffer[i++] = (char)c;
            } else {
                // Reset buffer on non-digit character
                buffer[0] = '\0';
                i = 0;
            }
        } else {
            // Check for timeout
            if (time(NULL) - start_time > timeout) {
                fprintf(stderr, "Error: Timeout reading from GPIO %d\n", gpio);
                return -1;
            }
            gpioDelay(1000); // Small delay to avoid busy-waiting
            continue;
        }

        buffer[i] = '\0'; // Null-terminate the string
    }

    return 0;
}

// Function to validate the received codes
int validate_code(const char *code1, const char *code2, const char *expected_code) {
    if (code1 == NULL || code2 == NULL || expected_code == NULL) {
        fprintf(stderr, "Error: Null pointer passed to validate_code\n");
        return -1;
    }

    if (strcmp(code1, code2) != 0) {
        fprintf(stderr, "Error: Codes do not match\n");
        return -1;
    }

    if (strcmp(code1, expected_code) != 0) {
        fprintf(stderr, "Error: Code does not match expected code\n");
        return -1;
    }

    return 0;
}

// Function to unlock the locks
int unlock_locks(int gpio1, int gpio2, int duration_seconds) {
    if (gpioWrite(gpio1, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d HIGH\n", gpio1);
        return -1;
    }
    if (gpioWrite(gpio2, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d HIGH\n", gpio2);
        return -1;
    }

    gpioDelay(duration_seconds * 1000000); // Delay in microseconds

    if (gpioWrite(gpio1, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d LOW\n", gpio1);
        return -1;
    }
    if (gpioWrite(gpio2, 0) != 0) {
