#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define MOTION_DETECT_TIMEOUT 10 // seconds
#define RELAY_ON_TIME 1 // seconds
#define POLL_INTERVAL 50 // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_relay();
int deactivate_relay();
void log_event(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event(LOG_INFO, "Received shutdown signal. Cleaning up...");
        cleanup();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to LOW
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate the relay
int activate_relay() {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to activate relay");
        return -1;
    }
    log_event(LOG_INFO, "Relay activated");
    return 0;
}

// Deactivate the relay
int deactivate_relay() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to deactivate relay");
        return -1;
    }
    log_event(LOG_INFO, "Relay deactivated");
    return 0;
}

// Log an event to syslog
void log_event(int priority, const char *message) {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

// Cleanup function to release GPIO resources
void cleanup() {
    deactivate_relay();
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event(LOG_INFO, "Motion detector started");

    time_t motion_start_time = 0;
    int motion_detected = 0;

    while (program_running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            if (!motion_detected) {
                motion_detected = 1;
                motion_start_time = time(NULL);
                log_event(LOG_INFO, "Motion detected");
                if (activate_relay() != 0) {
                    program_running = 0; // Exit on relay activation failure
                }
            }

            // Check for timeout
            if (time(NULL) - motion_start_time >= MOTION_DETECT_TIMEOUT) {
                log_event(LOG_WARNING, "Potential malfunction: Motion detected for longer than timeout");
                program_running = 0; // Exit on timeout
            }
        } else {
            if (motion_detected) {
                motion_detected = 0;
                sleep(RELAY_ON_TIME);
                if (deactivate_relay() != 0) {
                    program_running = 0; // Exit on relay deactivation failure
                }
            }
        }

        gpioDelay(POLL_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    log_event(LOG_INFO, "Motion detector stopped");
    cleanup();

    return 0;
}

