#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define irrigation cycle parameters
#define IRRIGATION_DURATION 300 // seconds
#define PAUSE_DURATION 60      // seconds

// Define the timer interval (60 seconds)
#define TIMER_INTERVAL 60

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void irrigation_cycle();
void timer_callback();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Deactivating all relays and exiting.", signal);
    program_running = 0;

    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Release GPIO resources
    gpioTerminate();

    // Close syslog
    closelog();

    exit(0);
}

// Irrigation cycle function
void irrigation_cycle() {
    int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);
    int current_relay = 0;

    // Activate each relay for IRRIGATION_DURATION seconds
    for (int i = 0; i < num_relays; i++) {
        if (program_running == 0) break; // Check for signal during irrigation

        int pin = relay_pins[i];
        syslog(LOG_INFO, "Activating relay on GPIO %d", pin);
        gpioWrite(pin, 0); // Activate relay (LOW)
        time_sleep(IRRIGATION_DURATION);
        gpioWrite(pin, 1); // Deactivate relay (HIGH)
        syslog(LOG_INFO, "Deactivating relay on GPIO %d", pin);

        // Check for signal during pause
        if (program_running == 0) break;

        // Insert a pause between activations
        syslog(LOG_INFO, "Inserting pause for %d seconds", PAUSE_DURATION);
        time_sleep(PAUSE_DURATION);

        // Check for signal during pause
        if (program_running == 0) break;
    }

    // Loop back to the first relay
    if (program_running == 0) return;
    syslog(LOG_INFO, "Looping back to the first relay.");
    gpioWrite(relay_pins[0], 0);
    time_sleep(IRRIGATION_DURATION);
    gpioWrite(relay_pins[0], 1);
}

// Timer callback function
void timer_callback() {
    if (program_running) {
        irrigation_cycle();
    }
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL); // Timer 0, interval in milliseconds

    syslog(LOG_INFO, "Irrigation system started. Running irrigation cycle every %d seconds.", TIMER_INTERVAL);

    // Main loop
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    closelog();
    return 0;
}

