    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t data = 0x00;
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to MPU6050");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from MPU6050
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read all acceleration registers in one go
    if (read(fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Circular buffer add function
void buffer_add(int *buffer, int16_t x, int16_t y, int16_t z, int *head, int *tail, int *count) {
    buffer[*head] = x;
    buffer[*head + 1] = y;
    buffer[*head + 2] = z;

    *head = (*head + 3) % (BUFFER_SIZE * 3);

    if (*count < BUFFER_SIZE) {
        *count += 1;
    } else {
        *tail = (*tail + 3) % (BUFFER_SIZE * 3);
    }
}

// Circular buffer get latest function
int buffer_get_latest(int *buffer, int16_t *x, int16_t *y, int16_t *z, int tail, int count) {
    if (count == 0) {
        return -1; // Buffer is empty
    }

    int latest_index = (tail - 3 + BUFFER_SIZE * 3) % (BUFFER_SIZE * 3);

    *x = buffer[latest_index];
    *y = buffer[latest_index + 1];
    *z = buffer[latest_index + 2];

    return 0;
}

