    struct itimerspec timer_spec;

    timer_spec.it_value.tv_sec = period_ms / 1000;
    timer_spec.it_value.tv_nsec = (period_ms % 1000) * 1000000;
    timer_spec.it_interval.tv_sec = period_ms / 1000;
