#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define the intervals in seconds
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay
int set_relay_state(int gpio, int state) {
    int result = gpioWrite(gpio, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio, result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to toggle the state of a relay
int toggle_relay(int gpio) {
    int current_state = gpioRead(gpio);
    if (current_state == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1; // Indicate failure
    }
    int new_state = (current_state == 0) ? 1 : 0;
    return set_relay_state(gpio, new_state);
}

// Function to delay execution for a specified number of seconds
void delay_seconds(int seconds) {
    struct timespec req;
    req.tv_sec = seconds;
    req.tv_nsec = 0;
    nanosleep(&req, NULL);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Toggle relays 1, 2, and 3
        if (toggle_relay(RELAY1_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 1\n");
        }
        if (toggle_relay(RELAY2_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 2\n");
        }
        if (toggle_relay(RELAY3_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 3\n");
        }

        // Delay for 2 seconds
        delay_seconds(INTERVAL1);

        // Toggle relay 4
        if (toggle_relay(RELAY4_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 4\n");
        }

        // Delay for 3 seconds
        delay_seconds(INTERVAL2);

        // Toggle relays 1 and 2
        if (toggle_relay(RELAY1_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 1\n");
        }
        if (toggle_relay(RELAY2_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 2\n");
        }

        // Delay for 5 seconds
        delay_seconds(INTERVAL3);

        // Toggle relay 3
        if (toggle_relay(RELAY3_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 3\n");
        }

        // Delay for 7 seconds
        delay_seconds(INTERVAL4);

        // Toggle relay 4
        if (toggle_relay(RELAY4_GPIO) != 0) {
            fprintf(stderr, "Error toggling relay 4\n");
        }

        // Delay for 2 seconds
        delay_seconds(INTERVAL1);
    }

    // Turn off all relays before exiting
    set_relay_state(RELAY1_GPIO, 0);
    set_relay_state(RELAY2_GPIO, 0);
    set_relay_state(RELAY3_GPIO, 0);
    set_relay_state(RELAY4_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

