#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mpu6050();
gyro_data_t read_gyro_data();
void store_gyro_data(circular_buffer_t *buffer, gyro_data_t data);
double calculate_angular_velocity(gyro_data_t data);
void check_threshold(double angular_velocity);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data from the MPU-6050
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buf[0] << 8) | buf[1]);
    data.y = (int16_t)((buf[2] << 8) | buf[3]);
    data.z = (int16_t)((buf[4] << 8) | buf[5]);

    return data;
}

// Store gyroscope data in the circular buffer
void store_gyro_data(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the angular velocity magnitude
double calculate_angular_velocity(gyro_data_t data) {
    // Sensitivity scale factor for +/- 250 deg/s range
    double scale_factor = 131.0;

    double x_rate = (double)data.x / scale_factor;
    double y_rate = (double)data.y / scale_factor;
    double z_rate = (double)data.z / scale_factor;

    return sqrt(x_rate * x_rate + y_rate * y_rate + z_rate * z_rate);
}

// Check if the angular velocity exceeds the threshold
void check_threshold(double angular_velocity) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Threshold exceeded! Angular velocity: %.2f deg/s\n", angular_velocity);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MPU-6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data();

        // Store data in circular buffer
        store_gyro_data(&gyro_buffer, gyro_data);

        // Calculate angular velocity
        double angular_velocity = calculate_angular_velocity(gyro_data);

        // Check threshold
        check_threshold(angular_velocity);

        // Delay
        gpioDelay(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

