int init_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 9600 baud, 8N1, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 1; // Wait for 1 decisecond (100ms)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read MH-Z19B sensor
int read_mhz19b(int uart_fd, int *ppm, int *error_flag) {
    unsigned char command[] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char response[9];
    int retries = 0;
    ssize_t bytes_read;
    fd_set readfds;
    struct timeval timeout;

    *error_flag = 0;
    *ppm = -1; // Initialize to an invalid value

    while (retries < MAX_RETRIES) {
        // Send command
        if (write(uart_fd, command, sizeof(command)) != sizeof(command)) {
            log_error("Error writing to UART");
            return -1;
        }

        // Set up select()
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = 0;
        timeout.tv_usec = TIMEOUT_MS * 1000; // Convert ms to us

        // Wait for data or timeout
        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("Error in select");
            log_error("Error in select");
            return -1;
        } else if (select_result == 0) {
            // Timeout
            log_error("Timeout waiting for response");
            retries++;
            continue;
        } else {
            // Read response
            bytes_read = read(uart_fd, response, sizeof(response));
            if (bytes_read == sizeof(response)) {
                // Validate checksum
                if (validate_checksum(response, sizeof(response))) {
                    // Extract CO2 concentration
                    *ppm = (response[2] << 8) | response[3];
                    return 0; // Success
                } else {
                    log_error("Checksum mismatch");
                    *error_flag = 1;
                    return -1; // Checksum error
                }
            } else {
                log_error("Incomplete response");
                retries++;
                continue;
            }
        }
    }

    log_error("Max retries reached");
    return -1; // Max retries reached
}

// Validate checksum
int validate_checksum(const unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 1; i < len - 1; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;
    return (checksum == data[8]);
}

// Write JSON to file
int write_json(FILE *fp, sensor_data_t data) {
    if (fprintf(fp, "{\"timestamp_us\":%ld,\"ppm\":%d,\"error_flag\":%d}\n", data.timestamp_us, data.ppm, data.error_flag) < 0) {
        perror("Error writing to JSON file");
        return -1;
    }
    fflush(fp); // Flush the buffer to ensure data is written
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log files
    log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    error_file = fopen("co2_error.log", "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        fclose(log_file);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int ppm, error_flag;
        sensor_data_t data;

        if (read_mhz19b(uart_fd, &ppm, &error_flag) == 0) {
            data.timestamp_us = time(NULL) * 1000000; // Get microsecond timestamp
            data.ppm = ppm;
            data.error_flag = error_flag;

            // Write JSON to file
            if (write_json(log_file, data) != 0) {
                log_error("Error writing JSON to file");
            }

            // Print JSON to stdout (simulating API call)
            char json_string[JSON_BUFFER_SIZE];
            snprintf(json_string, JSON_BUFFER_SIZE, "{\"timestamp_us\":%ld,\"ppm\":%d,\"error_flag\":%d}\n", data.timestamp_us, data.ppm, data.error_flag);
            printf("%s", json_string);
        } else {
            log_error("Error reading sensor data");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close(uart_fd);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

