#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for LED
#define LED_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Deviation threshold
#define DEVIATION_THRESHOLD 10.0

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float apply_hard_iron_compensation(int16_t x, int16_t y, float x_offset, float y_offset);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float heading);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize the HMC5883L sensor
int init_hmc5883l() {
    // Configure the sensor
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_A, 0x70) < 0) { // 8-average, 15 Hz, normal measurement
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_B, 0xA0) < 0) { // Gain = 5
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_MODE, 0x00) < 0) { // Continuous measurement mode
        fprintf(stderr, "Error writing to HMC5883L_MODE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw magnetometer data
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    int x_msb, x_lsb, z_msb, z_lsb, y_msb, y_lsb;

    x_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_X_MSB);
    x_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_X_LSB);
    z_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Z_MSB);
    z_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Z_LSB);
    y_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Y_MSB);
    y_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Y_LSB);

    if (x_msb < 0 || x_lsb < 0 || z_msb < 0 || z_lsb < 0 || y_msb < 0 || y_lsb < 0) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);

    return 0;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Apply hard-iron compensation
float apply_hard_iron_compensation(int16_t x, int16_t y, float x_offset, float y_offset) {
    return calculate_heading(x - x_offset, y - y_offset);
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the LED based on the deviation from the target heading
void control_led(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 180.0) {
        deviation = 360.0 - deviation;
    }

    if (deviation > DEVIATION_THRESHOLD) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(HMC5883L_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() == -1) {
        fprintf(stderr, "Error initializing HMC5883L.\n");
        close(i2c_fd);
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Initialize circular buffer
    CircularBuffer heading_buffer;
    init_circular_buffer(&heading_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int16_t x, y, z;
        float heading, compensated_heading;

        // Read magnetometer data
        if (read_hmc5883l(&x, &y, &z) == -1) {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(x, y);

        // Apply hard-iron compensation
        compensated_heading = apply_hard_iron_compensation(x, y, 100.0, -50.0);

        // Add to circular buffer
        add_to_buffer(&heading_buffer, compensated_heading);

        // Calculate average heading
        float average_heading = calculate_average(&heading_buffer);

        // Control LED
        control_led(average_heading);

        // Print heading (for debugging)
        printf("Heading: %.2f, Compensated Heading: %.2f, Average Heading: %.2f\n", heading, compensated_heading, average_heading);

        // Delay
        delay(100); // 100ms
    }

    return 0;
}

