#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LOG_FILE "lighting_log.txt"
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
void control_relays(float lux);
int log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Structure for relay states
typedef struct {
    int red;
    int green;
    int blue;
} RelayStates;

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioSetMode(RED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting RED_GPIO mode\n");
        return -1;
    }
    if (gpioSetMode(GREEN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GREEN_GPIO mode\n");
        return -1;
    }
    if (gpioSetMode(BLUE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting BLUE_GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from BH1750 sensor
int read_bh1750(float *lux) {
    char config[1] = {0x10}; // Continuous high resolution mode
    char buffer[2];

    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to control relays based on lux value
void control_relays(float lux) {
    int red_state = 0;
    int green_state = 0;
    int blue_state = 0;

    if (lux < 50) {
        red_state = 1;
    } else if (lux >= 50 && lux < 150) {
        green_state = 1;
    } else if (lux >= 150 && lux < 300) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpioWrite(RED_GPIO, red_state);
    gpioWrite(GREEN_GPIO, green_state);
    gpioWrite(BLUE_GPIO, blue_state);

