#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM Frequency
#define PWM_FREQUENCY 1000

// Proportional gain
#define Kp 10

// Distance thresholds
#define FORWARD_THRESHOLD 50
#define BACKWARD_THRESHOLD 50

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to set motor direction and PWM duty cycle
void set_motor_speed(int motor, int distance) {
    int in1, in3, duty;

    if (motor == 0) { // Motor A
        in1 = MOTOR_A_IN1;
        in3 = MOTOR_B_IN3; // Dummy value, not used
    } else { // Motor B
        in1 = MOTOR_B_IN3;
        in3 = MOTOR_A_IN1; // Dummy value, not used
    }

    if (distance < FORWARD_THRESHOLD) {
        // Forward
        gpioWrite(in1, 1);
        duty = (int)(Kp * (FORWARD_THRESHOLD - distance)); // Proportional control
        if (duty > 255) duty = 255;
        if (duty < 0) duty = 0;
        gpioPWM(in1, duty);
    } else if (distance > BACKWARD_THRESHOLD) {
        // Backward
        gpioWrite(in1, 0);
        duty = (int)(Kp * (distance - BACKWARD_THRESHOLD)); // Proportional control
        if (duty > 255) duty = 255;
        if (duty < 0) duty = 0;
        gpioPWM(in1, duty);
    } else {
        // Stop
        gpioWrite(in1, 0);
        gpioPWM(in1, 0);
    }
}

int main(int argc, char *argv[]) {
    int distance_a, distance_b;

    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    distance_a = atoi(argv[1]);
    distance_b = atoi(argv[2]);

    if (distance_a < 10 || distance_a > 100) {
        fprintf(stderr, "Error: Distance A must be between 10 and 100\n");
        return 1;
    }

    if (distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Error: Distance B must be between 10 and 100\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_A_IN4, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_A_IN4, 255);
    gpioSetPWMrange(MOTOR_B_IN3, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    // Main control loop
    while (program_running) {
        set_motor_speed(0, distance_a); // Motor A
        set_motor_speed(1, distance_b); // Motor B
        gpioDelay(100000); // 100ms
    }

    // Stop motors and terminate pigpio
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioTerminate();

    return 0;
}

