// I2C initialization function
int init_i2c(const char *i2c_device) {
    int fd;
    int retries = 5;
    int delay_ms = 10;

    while (retries > 0) {
        fd = open(i2c_device, O_RDWR);
        if (fd < 0) {
            perror("Error opening I2C device");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error setting I2C slave address");
            close(fd);
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Wake up the MPU6050
        uint8_t data[2] = {PWR_MGMT_1, 0x00};
        if (write(fd, data, 2) != 2) {
            perror("Error writing to I2C device");
            close(fd);
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        // Set sample rate divider
        data[0] = SAMPLE_RATE_DIVIDER;
        data[1] = 1000 / SAMPLE_RATE - 1; // 100Hz sample rate
        if (write(fd, data, 2) != 2) {
            perror("Error writing to I2C device");
            close(fd);
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        return fd;
    }

    fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
    return -1;
}

// Function to read data from MPU6050
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    int retries = 5;
    int delay_ms = 10;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 14) != 14) {
            perror("Error reading from I2C device");
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
        *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
        *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
        *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read MPU6050 data after multiple retries.\n");
    return -1; // Failure
}

// Function to process sensor data and calculate pitch and roll
void process_sensor_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *pitch, float *roll) {
    float accel_x_g = (float)accel_x / 16384.0f; // Assuming +/- 2g range
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    *pitch = atan2f(accel_x_g, sqrtf(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180.0f / M_PI;
    *roll = atan2f(accel_y_g, accel_z_g) * 180.0f / M_PI;
}

// Function to set the servo angle using pigpio
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d. Angle must be between 0 and 180.\n", angle);
        return -1;
    }

    int pulsewidth = (int)(500 + (angle * 2000.0f / 180.0f)); // Map 0-180 to 500-2500
    gpioServo(SERVO_GPIO, pulsewidth);
    return 0;
}

// Function to send data to the API server
int send_data_to_api(float pitch, float roll, int position) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(API_SERVER_PORT);
    if (inet_pton(AF_INET, API_SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "Pitch: %.2f, Roll: %.2f, Position: %d", pitch, roll, position);

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Function to log data to a file
void log_data(float pitch, float roll, int position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating program.\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_fd = init_i2c("/dev/i2c-1");
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int position = 0; // Dummy position value

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process sensor data
            process_sensor_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, &pitch, &roll);

            // Set servo angle
            if (set_servo_angle((int)roll) != 0) {
                fprintf(stderr, "Failed to set servo angle.\n");
            }

            // Send data to API
            if (send_data_to_api(pitch, roll, position) != 0) {
                fprintf(stderr, "Failed to send data to API.\n");
            }

            // Log data
            log_data(pitch, roll, position);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(1000000 / SAMPLE_RATE); // Delay to achieve desired sample rate
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioServo(SERVO_GPIO, 0); // Stop servo
    gpioTerminate();

    return 0;
}

