#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (in seconds)
#define FADE_DURATION 1800

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to hold schedule entry data
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry;

// Global variables
FILE *schedule_file = NULL;
int running = 1;

// Function prototypes
int read_schedule_file(schedule_entry *schedule, int max_entries);
int parse_schedule_line(const char *line, schedule_entry *entry);
int set_relay_state(int relay_number, int on_off);
int fade_relay(int relay_number, int on_off);
void signal_handler(int signal);

// Function to read the schedule file
int read_schedule_file(schedule_entry *schedule, int max_entries) {
    char line[256];
    int i = 0;

    // Open the schedule file
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Read the file line by line
    while (fgets(line, sizeof(line), schedule_file) != NULL && i < max_entries) {
        // Parse the line
        if (parse_schedule_line(line, &schedule[i]) == 0) {
            i++;
        } else {
            fprintf(stderr, "Error parsing line: %s", line);
        }
    }

    // Close the file
    fclose(schedule_file);
    schedule_file = NULL;

    return i; // Return the number of entries read
}

// Function to parse a line from the schedule file
int parse_schedule_line(const char *line, schedule_entry *entry) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok

    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    // Tokenize the line
    token = strtok(line_copy, ",");
    if (token != NULL) {
        entry->hour = atoi(token);
        token = strtok(NULL, ":");
        if (token != NULL) {
            entry->minute = atoi(token);
            token = strtok(NULL, ",");
            if (token != NULL) {
                entry->second = atoi(token);
                token = strtok(NULL, ",");
                if (token != NULL) {
                    entry->relay_number = atoi(token);
                    token = strtok(NULL, ",");
                    if (token != NULL) {
                        if (strcmp(token, "on") == 0) {
                            entry->on_off = 1;
                        } else if (strcmp(token, "off") == 0) {
                            entry->on_off = 0;
                        } else {
                            fprintf(stderr, "Invalid on/off value: %s", token);
                            free(line_copy);
                            return -1;
                        }
                    } else {
                        fprintf(stderr, "Missing on/off value");
                        free(line_copy);
                        return -1;
                    }
                } else {
                    fprintf(stderr, "Missing relay number");
                    free(line_copy);
                    return -1;
                }
            } else {
                fprintf(stderr, "Missing second value");
                free(line_copy);
                return -1;
            }
        } else {
            fprintf(stderr, "Missing minute value");
            free(line_copy);
            return -1;
        }
    } else {
        fprintf(stderr, "Missing hour value");
        free(line_copy);
        return -1;
    }

    free(line_copy);
    return 0;
}

// Function to set the state of a relay
int set_relay_state(int relay_number, int on_off) {
    int gpio_pin;

    // Determine the GPIO pin number
    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_PIN;
            break;
        case 2:
            gpio_pin = RELAY2_PIN;
            break;
        case 3:
            gpio_pin = RELAY3_PIN;
            break;
        case 4:
            gpio_pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    // Set the GPIO pin state
    gpioWrite(gpio_pin, on_off);

    return 0;
}

// Function to perform a fade on a relay
int fade_relay(int relay_number, int on_off) {
    int gpio_pin;
    int i;
    int duty_cycle;

    // Determine the GPIO pin number
    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_PIN;
            break;
        case 2:
            gpio_pin = RELAY2_PIN;
            break;
        case 3:
            gpio_pin = RELAY3_PIN;
            break;
        case 4:
            gpio_pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    // Set the PWM frequency
    gpioSetPWMfrequency(gpio_pin, PWM_FREQUENCY);

    // Determine the start and end duty cycles
    int start_duty_cycle = (on_off == 1) ? 0 : 100;
    int end_duty_cycle = (on_off == 1) ? 100 : 0;

    // Perform the fade
    for (i = 0; i <= FADE_DURATION; i++) {
        // Calculate the current duty cycle
        duty_cycle = start_duty_cycle + (int)(((float)i / FADE_DURATION) * (end_duty_cycle - start_duty_cycle));

        // Set the PWM duty cycle
        gpioPWM(gpio_pin, duty_cycle);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Ensure the final state is set
    gpioPWM(gpio_pin, end_duty_cycle);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    schedule_entry schedule[100]; // Assuming a maximum of 100 schedule entries
    time_t current_time;
    struct tm *time_info;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
