// Structure to hold schedule entry data
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry;

// Global variables
FILE *schedule_file = NULL;
int running = 1;

// Function prototypes
int read_schedule_file(schedule_entry *schedule, int max_entries);
int parse_schedule_line(const char *line, schedule_entry *entry);
int set_relay_state(int relay_number, int on_off);
int fade_relay(int relay_number, int on_off);
