#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200.0   // Minimum buzzer frequency (Hz)
#define MAX_FREQUENCY 2000.0  // Maximum buzzer frequency (Hz)
#define MIN_DISTANCE 2.0      // Minimum measurable distance (cm)
#define MAX_DISTANCE 200.0    // Maximum measurable distance (cm)
#define TIMEOUT_US 50000       // Timeout for echo pulse (microseconds)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
double measureDistance();
double calculateFrequency(double distance);
void setBuzzerFrequency(double frequency);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            echo_start_tick = tick;
            echo_received = 0; // Reset flag
        }
        else if (level == 0) // Falling edge
        {
            echo_end_tick = tick;
            echo_received = 1; // Set flag
        }
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
double measureDistance()
{
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    triggerSensor();

    // Wait for echo to be received or timeout
    int start_time = gpioTick();
    while (!echo_received && (gpioTick() - start_time) < TIMEOUT_US)
    {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (!echo_received)
    {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1.0; // Indicate timeout error
    }

    // Calculate pulse width in microseconds
    int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, then by 2 for one-way distance

    return distance;
}

// Function to calculate the buzzer frequency based on the distance
double calculateFrequency(double distance)
{
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE)
    {
        distance = MIN_DISTANCE;
    }
    else if (distance > MAX_DISTANCE)
    {
        distance = MAX_DISTANCE;
    }

    // Map distance to frequency (inverse relationship)
    double frequency = MAX_FREQUENCY - ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_FREQUENCY - MIN_FREQUENCY);

    return frequency;
}

// Function to set the buzzer frequency using PWM
void setBuzzerFrequency(double frequency)
{
    // Clamp frequency to the defined range
    if (frequency < MIN_FREQUENCY)
    {
        frequency = MIN_FREQUENCY;
    }
    else if (frequency > MAX_FREQUENCY)
    {
        frequency = MAX_FREQUENCY;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);

    // Set PWM duty cycle (50%)
    gpioPWM(BUZZER_PIN, 128); // 128 is half of 255 for 50% duty cycle
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Silence the buzzer
    gpioPWM(BUZZER_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1)
    {
        // Measure distance
        double distance = measureDistance();

        if (distance > 0) // Check for valid distance reading
        {
            // Calculate frequency
            double frequency = calculateFrequency(distance);

            // Set buzzer frequency
            setBuzzerFrequency(frequency);

            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        }
        else
        {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        // Delay to achieve approximately 50 Hz
        gpioDelay(20); // 20 milliseconds = 50 Hz
    }

    return 0;
}

