// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to calculate the PWM duty cycle based on the proximity value
int calculate_duty_cycle(float proximity_value) {
    // Map the proximity value (0.0 to 1.0) to the duty cycle range (0 to 255)
    return (int)(proximity_value * 255.0);
}

// Function to calculate the proximity value based on time
float calculate_proximity(float time) {
    // Simulate a sine-wave proximity value
    return (0.5 * sin(2 * M_PI * time)) + 0.5;
}

// Function to set the RGB LED color using PWM
int set_rgb_color(int red_duty_cycle, int green_duty_cycle, int blue_duty_cycle) {
    if (set_pwm_duty_cycle(RED_PIN, red_duty_cycle) != 0) return -1;
    if (set_pwm_duty_cycle(GREEN_PIN, green_duty_cycle) != 0) return -1;
    if (set_pwm_duty_cycle(BLUE_PIN, blue_duty_cycle) != 0) return -1;
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float time = 0.0;
    while (program_running) {
        // Calculate the proximity value
        float proximity_value = calculate_proximity(time);

        // Calculate the duty cycle for each color component
        int red_duty_cycle = calculate_duty_cycle(proximity_value);
        int green_duty_cycle = calculate_duty_cycle(proximity_value);
        int blue_duty_cycle = calculate_duty_cycle(proximity_value);

        // Set the RGB LED color
        if (set_rgb_color(red_duty_cycle, green_duty_cycle, blue_duty_cycle) != 0) {
            fprintf(stderr, "Error setting RGB color\n");
            break; // Exit loop on error
        }

        // Increment the time
        time += 0.01; // 10ms delay
        if (time > 1.0) time = 0.0;

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Turn off the LED before exiting
    set_rgb_color(0, 0, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

