#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor for +/- 250 degrees/sec range
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps);
int log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// MPU6050 initialization function
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    char buf[2];
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    // Configure gyroscope range to +/- 250 degrees/sec
    buf[0] = GYRO_CONFIG;
    buf[1] = 0x00; // Full scale range = +/- 250 degrees/sec
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to GYRO_CONFIG register");
        return -1;
    }

    return 0;
}

// Data acquisition function
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char reg = GYRO_XOUT_H;
    char buf[6];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, buf, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Data processing function
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *gyro_x_dps = (float)gyro_x / GYRO_SENSITIVITY;
    *gyro_y_dps = (float)gyro_y / GYRO_SENSITIVITY;
    *gyro_z_dps = (float)gyro_z / GYRO_SENSITIVITY;
}

// Data logging function
int log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, gyro_x_dps, gyro_y_dps, gyro_z_dps);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int16_t gyro_x, gyro_y, gyro_z;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process data
            process_data(gyro_x, gyro_y, gyro_z, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data
            log_data(gyro_x_dps, gyro_y_dps, gyro_z_dps);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Sleep for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

