#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequency, duration in ms)
const int melody[][2] = {
    {440, 200},  // A4
    {494, 200},  // B4
    {523, 200},  // C5
    {587, 200},  // D5
    {659, 200},  // E5
    {698, 200},  // F5
    {783, 200},  // G5
    {880, 200}   // A5
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
volatile int melody_playing = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user_data);
void play_melody(int gpio, int level, uint32_t tick, void *user_data);
void stop_melody(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();        // Terminate pigpio
    exit(0);
}

// Interrupt service routine for button press
void button_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) { // Button pressed (active low)
        if (current_tick - last_tick > 50000) { // Debounce: 50ms
            button_pressed = 1;
            last_tick = current_tick;
        }
    }
}

// Interrupt service routine to play melody
void play_melody(int gpio, int level, uint32_t tick, void *user_data) {
    static int note_index = 0;

    if (melody_playing) {
        // Stop melody if button is pressed again
        if (button_pressed) {
            button_pressed = 0;
            gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, stop_melody, NULL);
            gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, stop_melody, NULL);
            gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, button_isr, NULL);
            gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL);
            return;
        }

        // Play next note
        int frequency = melody[note_index][0];
        int duration = melody[note_index][1];

        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_PIN, frequency);
        gpioDelay(duration * 1000); // Delay in microseconds

        note_index = (note_index + 1) % melody_length;

        if (note_index == 0) {
            // End of melody, stop buzzer
            gpioPWM(BUZZER_PIN, 0);
            melody_playing = 0;
            gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, button_isr, NULL);
            gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL);
        }
    }
}

// Interrupt service routine to stop melody
void stop_melody(int gpio, int level, uint32_t tick, void *user_data) {
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    melody_playing = 0;
    gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, button_isr, NULL);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL);
    printf("Melody stopped.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(BUZZER_PIN, melody[0][0]); // Set initial frequency to the first note

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routines
    gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, button_isr, NULL);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL);

    printf("Doorbell system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed && !melody_playing) {
            printf("Button pressed, playing melody...\n");
            button_pressed = 0; // Reset the flag
            melody_playing = 1;
            gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, play_melody, NULL);
            gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, play_melody, NULL);
        }
        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

