#define DEFAULT_TIMEOUT 1000
#define LOG_FILE "vibration_events.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int event_window[WINDOW_SIZE];
static int window_index = 0;

// Function prototypes
int read_sensor(int gpio_pin);
int is_earthquake_alert(int *window, int window_size);
void log_event(FILE *log_file, int value);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "Signal received, exiting gracefully...\n");
}

// Reads the sensor value from the specified GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Checks if the sliding window contains at least three HIGH events
int is_earthquake_alert(int *window, int window_size) {
    int count = 0;
    for (int i = 0; i < window_size; i++) {
        if (window[i] == 1) {
            count++;
        }
    }
    return (count >= 3) ? 1 : 0;
}

// Logs the event to the log file with ISO 8601 timestamp
void log_event(FILE *log_file, int value) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    fprintf(log_file, "%s, %d\n", timestamp, value);
    fflush(log_file);
    free(timestamp);
}

// Gets the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        timeout = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT);
            timeout = DEFAULT_TIMEOUT;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize event window
    for (int i = 0; i < WINDOW_SIZE; i++) {
        event_window[i] = 0;
    }

    fprintf(stderr, "Monitoring vibration sensor on GPIO %d with timeout %d ms...\n", GPIO_PIN, timeout);

    // Main loop
    while (running) {
        int value = read_sensor(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        // Update sliding window
        event_window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;

        // Log the event
        log_event(log_file, value);

        // Check for earthquake alert
        if (is_earthquake_alert(event_window, WINDOW_SIZE)) {
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                fprintf(stderr, "EARTHQUAKE ALERT: %s\n", timestamp);
                free(timestamp);
            }
        }

        // Wait for a short period
        gpioDelay(timeout);
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

