#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x28
#define OUT_X_H_M 0x29
#define OUT_Y_L_M 0x2A
#define OUT_Y_H_M 0x2B
#define OUT_Z_L_M 0x2C
#define OUT_Z_H_M 0x2D

#define X_OFFSET 10.0
#define Y_OFFSET -5.0
#define Z_OFFSET 20.0

#define NUM_DIRECTIONS 8
const char *directions[NUM_DIRECTIONS] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float x, float y);
char *map_heading_to_direction(float heading);
int log_data(float x, float y, float z, float heading, char *direction);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Enable magnetometer (continuous conversion mode)
    uint8_t ctrl_reg1_value = 0x70; // 50 Hz, continuous conversion
    if (write(i2c_fd, &ctrl_reg1_value, 1) != 1) {
        perror("Error writing to CTRL_REG1_M");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read all six registers at once
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(float x, float y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Map heading to compass direction
char *map_heading_to_direction(float heading) {
    int index = (int)(heading / (360.0 / NUM_DIRECTIONS));
    return (char *)directions[index % NUM_DIRECTIONS];
}

// Log data to CSV file
int log_data(float x, float y, float z, float heading, char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, x, y, z, heading, direction);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    char *direction;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate data
            calibrate_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to direction
            direction = map_heading_to_direction(heading);

            // Log data
            if (log_data(calibrated_x, calibrated_y, calibrated_z, heading, direction) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Print data to console
            printf("Calibrated X: %.2f, Calibrated Y: %.2f, Calibrated Z: %.2f, Heading: %.2f, Direction: %s\n",
                   calibrated_x, calibrated_y, calibrated_z, heading, direction);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

