#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "relay_log.json"

static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the relay state to a file
int log_relay_state(int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for log entry.\n");
        return -1;
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    return 0;
}

// Interrupt service routine for the touch sensor
void touch_isr(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();
    if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) { // Convert ms to microseconds
        toggle_relay();
        log_relay_state(relay_state);
        last_touch_time = current_time;
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
