// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define activation time (in seconds)
#define ACTIVATION_TIME 5

// Define delay between relays (in seconds)
#define RELAY_DELAY 1

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_soil_moisture();
void activate_relay(int relay_number, int moisture_level);
void log_data(int relay_number, int moisture_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Release GPIO pins
    gpioSetMode(RELAY1_PIN, PI_INPUT); // Set to input to release
    gpioSetMode(RELAY2_PIN, PI_INPUT);
    gpioSetMode(RELAY3_PIN, PI_INPUT);
    gpioSetMode(RELAY4_PIN, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to inactive state (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Read soil moisture value
int read_soil_moisture() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Activate relay
void activate_relay(int relay_number, int moisture_level) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(pin, 0); // Activate relay (LOW)
    gpioDelay(ACTIVATION_TIME * 1000000); // Delay for activation time (microseconds)
    gpioWrite(pin, 1); // Deactivate relay (HIGH)
    gpioDelay(RELAY_DELAY * 1000000); // Delay between relays (microseconds)
}

// Log data to file
void log_data(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read soil moisture
        int moisture_level = read_soil_moisture();

        // Activate relays if moisture is below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d, activating relays...\n", moisture_level);
            activate_relay(1, moisture_level);
            activate_relay(2, moisture_level);
            activate_relay(3, moisture_level);
            activate_relay(4, moisture_level);

            // Log data
            log_data(1, moisture_level);
            log_data(2, moisture_level);
            log_data(3, moisture_level);
            log_data(4, moisture_level);
        } else {
            printf("Moisture level: %d, no need to irrigate.\n", moisture_level);
        }

        // Wait 10 seconds
        gpioDelay(10 * 1000000); // Delay in microseconds
    }

    return 0;
}

