#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_DURATION 50 // ms
#define SAMPLING_INTERVAL 1 // s
#define LOG_FILE "distance_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
int log_distance(double distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // Wait 1ms

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_time = 0, end_time = 0;

    // Wait for rising edge
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_DURATION * 1000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_DURATION * 1000) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }

    start_time = gpioTick();

    // Wait for falling edge
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_DURATION * 1000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_DURATION * 1000) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Log the distance to a file
int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance sensor logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }
        } else {
            fprintf(log_file, "Timestamp, -1\n");
            fflush(log_file);
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(SAMPLING_INTERVAL * 1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

