// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the duration for each relay activation (in seconds)
#define RELAY_DURATION 5

// Define the cycle duration (in seconds)
#define CYCLE_DURATION 86400 // 24 hours

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_cycle_start();
void cleanup_gpio();
void signal_handler(int signal);

