void activate_relay(int pin) {
    gpioWrite(pin, 0); // Active low
    printf("Activating relay on pin %d\n", pin);
    gpioDelay(RELAY_DURATION * 1000000); // Delay for RELAY_DURATION seconds
}

// Function to deactivate a relay (set GPIO pin HIGH)
void deactivate_relay(int pin) {
    gpioWrite(pin, 1); // Active high
    printf("Deactivating relay on pin %d\n", pin);
}

// Function to log the start time of the watering cycle
void log_cycle_start() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    printf("Cycle start time logged: %s\n", timestamp);
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    gpioTerminate();
    printf("GPIO cleanup complete\n");
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Log the start time of the cycle
        log_cycle_start();

        // Activate relays sequentially
        activate_relay(RELAY1_PIN);
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        deactivate_relay(RELAY4_PIN);

        // Wait for the cycle duration
        gpioDelay(CYCLE_DURATION * 1000000); // Delay for CYCLE_DURATION seconds
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

