#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800 // 30 minutes

// Global variables
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int set_relay_state(int gpio, int state);
int set_pwm_duty_cycle(int gpio, int duty_cycle);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        terminate = 1;
        log_event("Received termination signal. Shutting down...");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY1_GPIO);
        return 1;
    }
    if (gpioSetMode(RELAY2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY2_GPIO);
        return 1;
    }
    if (gpioSetMode(RELAY3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY3_GPIO);
        return 1;
    }
    if (gpioSetMode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY4_GPIO);
        return 1;
    }

    // Set PWM frequency for all GPIO pins
    if (gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY1_GPIO);
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY2_GPIO);
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY3_GPIO);
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", RELAY4_GPIO);
        return 1;
    }

    return 0;
}

// Function to set relay state (0 = off, 1 = on)
int set_relay_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Function to set PWM duty cycle (0-255)
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Invalid duty cycle value: %d\n", duty_cycle);
        return 1;
    }

    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Function to log events with timestamps
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    log_event("Cleaning up resources...");

    // Turn off all relays
    set_relay_state(RELAY1_GPIO, 0);
    set_relay_state(RELAY2_GPIO, 0);
    set_relay_state(RELAY3_GPIO, 0);
    set_relay_state(RELAY4_GPIO, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_event("Cleanup complete. Exiting.");
}

int main() {
    // Open the log file
    log_file = fopen("smart_lighting.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    log_event("Starting smart lighting sunrise effect...");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sunrise effect
    for (int i = 0; i <= SUNRISE_DURATION && !terminate; i++) {
        int duty_cycle = (int)(((float)i / SUNRISE_DURATION) * 255.0);

        if (set_pwm_duty_cycle(RELAY1_GPIO, duty_cycle) != 0) {
            log_event("Failed to set PWM duty cycle for RELAY1_GPIO");
        }
        if (set_pwm_duty_cycle(RELAY2_GPIO, duty_cycle) != 0) {
            log_event("Failed to set PWM duty cycle for RELAY2_GPIO");
        }
        if (set_pwm_duty_cycle(RELAY3_GPIO, duty_cycle) != 0) {
            log_event("Failed to set PWM duty cycle for RELAY3_GPIO");
        }
        if (set_pwm_duty_cycle(RELAY4_GPIO, duty_cycle) != 0) {
            log_event("Failed to set PWM duty cycle for RELAY4_GPIO");
        }

        char message[100];
        snprintf(message, sizeof(message), "Sunrise effect: Duty cycle set to %d", duty_cycle);
        log_event(message);

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

