#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define BUFFER_SIZE 100
#define THRESHOLD_DPS 250.0
#define MAX_RETRIES 3

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
bool running = true;

// Function prototypes
int init_i2c();
int read_gyro_data(gyro_data_t *data);
void process_data(gyro_data_t *data);
void control_led(bool on);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
