#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <sys/time.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define GYRO_X_REG 0x43
#define GYRO_Y_REG 0x45
#define GYRO_Z_REG 0x47
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_NS 10000000 // 10 ms

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_read_register(uint8_t reg, int16_t *value);
int gyro_read_rates(int16_t *x_rate, int16_t *y_rate, int16_t *z_rate);
int log_data(const char *timestamp, int16_t x_rate, int16_t y_rate, int16_t z_rate);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI read register function with retry
int spi_read_register(uint8_t reg, int16_t *value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    struct spi_ioc_transfer transfer[1];

    tx_buf[0] = reg | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;       // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 2;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Error asserting CS low");
            return -1;
        }

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
            perror("Error during SPI transfer");
            gpiod_line_set_value(cs_line, 1);
            return -1;
        }

        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error de-asserting CS high");
            return -1;
        }

        *value = (rx_buf[0] << 8) | rx_buf[1];
        return 0; // Success
    }

    fprintf(stderr, "SPI read failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure after retries
}

// Read gyroscope rates
int gyro_read_rates(int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    if (spi_read_register(GYRO_X_REG, x_rate) != 0) {
        fprintf(stderr, "Error reading gyro X rate\n");
        return -1;
    }
    if (spi_read_register(GYRO_Y_REG, y_rate) != 0) {
        fprintf(stderr, "Error reading gyro Y rate\n");
        return -1;
    }
    if (spi_read_register(GYRO_Z_REG, z_rate) != 0) {
        fprintf(stderr, "Error reading gyro Z rate\n");
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(const char *timestamp, int16_t x_rate, int16_t y_rate, int16_t z_rate) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    fprintf(stderr, "Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO chip
    gpio_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    // Open GPIO line
    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(cs_line, "gyro_logger", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Gyroscope data logging started. Press Ctrl+C to stop.\n");

    struct timespec ts;
    int16_t x_rate, y_rate, z_rate;
    char timestamp[30];

    while (!terminate) {
        // Read gyroscope rates
        if (gyro_read_rates(&x_rate, &y_rate, &z_rate) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Format timestamp
                snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02dT%02d:%02d:%02d.%09ldZ",
                         (int)ts.tv_sec / 31536000 + 1970, // Year
                         (int)((ts.tv_sec % 31536000) / 2592000) + 1, // Month (1-12)
                         (int)(((ts.tv_sec % 31536000) % 2592000) / 86400) + 1, // Day of month (1-31)
                         (int)((ts.tv_sec % 86400) / 3600), // Hour (0-23)
                         (int)((ts.tv_sec % 3600) / 60), // Minute (0-59)
                         (int)(ts.tv_sec % 60), // Second (0-59)
                         ts.tv_nsec); // Nanosecond (0-999999999)

                // Log data
                if (log_data(timestamp, x_rate, y_rate, z_rate) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                perror("Error getting timestamp");
            }
        } else {
            fprintf(stderr, "Error reading gyro rates\n");
        }

        // Wait for the next sample
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_INTERVAL_NS;
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return 0;
}

