#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0

// GPIO Configuration
#define LED_GPIO 17
#define BUFFER_SIZE 64

// Threshold
#define THRESHOLD 200.0f

// Data Structure
typedef struct {
    uint32_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular Buffer
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global Variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_spi();
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
void process_data(gyro_data_t data);
void blink_led(int gpio, int duration_ms);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
void print_buffer(circular_buffer_t *buffer);
void signal_handler(int signal);

// Initialize Circular Buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize MPU6050
int init_mpu6050() {
    char buf[2];
    buf[0] = MPU6050_PWR_MGMT_1;
    buf[1] = 0x00; // Wake up the MPU6050
    if (spiXfer(spi_handle, buf, buf, 2) != 0) {
        fprintf(stderr, "Error writing to MPU6050\n");
        return -1;
    }
    return 0;
}

// Read Gyroscope Data
int read_gyro_data(gyro_data_t *data) {
    char buf[7];
    buf[0] = MPU6050_GYRO_XOUT_H | 0x80; // Read multiple bytes
    if (spiXfer(spi_handle, buf, buf, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    data->x = (int16_t)((buf[1] << 8) | buf[2]);
    data->y = (int16_t)((buf[3] << 8) | buf[4]);
    data->z = (int16_t)((buf[5] << 8) | buf[6]);

    return 0;
}

// Process Gyroscope Data
void process_data(gyro_data_t data) {
    // Convert raw data to degrees per second (dps)
    float x_dps = (float)data.x / 131.0f;
    float y_dps = (float)data.y / 131.0f;
    float z_dps = (float)data.z / 131.0f;

    // Check for threshold exceedance
    if (fabs(x_dps) > THRESHOLD || fabs(y_dps) > THRESHOLD || fabs(z_dps) > THRESHOLD) {
        blink_led(LED_GPIO, 500);
    }

    // Get timestamp
    data.timestamp = gpioTick();

    // Add to circular buffer
    add_to_buffer(&gyro_buffer, data);
}

// Blink LED
void blink_led(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for duration_ms milliseconds
    gpioWrite(gpio, 0); // Turn LED off
}

// Add Data to Circular Buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Print Circular Buffer
void print_buffer(circular_buffer_t *buffer) {
    printf("Timestamp,X,Y,Z\n");
    int start = (buffer->head - buffer->count + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        printf("%u,%d,%d,%d\n", buffer->buffer[index].timestamp, buffer->buffer[index].x, buffer->buffer[index].y, buffer->buffer[index].z);
    }
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize Circular Buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    gyro_data_t data;

    // Main loop
    while (program_running) {
        if (read_gyro_data(&data) == 0) {
            process_data(data);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }
        gpioDelay(10000); // 10ms delay
    }

    // Print buffer before exiting
    print_buffer(&gyro_buffer);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

