#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// LED GPIO pin
#define LED_PIN 21

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch);
void log_data(float roll, float pitch);
void control_led(float roll, float pitch);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (set sleep bit to 0)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate roll and pitch
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    float accel_x_g = (float)accel_x / 16384.0f; // Sensitivity: +/- 2g
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    *roll = atan2(accel_y_g, accel_z_g) * 180.0f / M_PI;
    *pitch = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180.0f / M_PI;
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on tilt
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45.0f || fabs(pitch) > 45.0f) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    int16_t accel_x, accel_y, accel_z;
    float roll, pitch;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accel_data(&accel_x, &accel_y, &accel_z) == 0) {
            // Calculate roll and pitch
            calculate_roll_pitch(accel_x, accel_y, accel_z, &roll, &pitch);

            // Log data
            log_data(roll, pitch);

            // Control LED
            control_led(roll, pitch);

            // Print roll and pitch to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

