#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define PRESENCE_LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char val);
int read_si1145_data(int fd, int *ambient_light, int *proximity);
void log_data(FILE *fp, int ambient_light, int proximity);
void control_led(int gpio, int state);
void signal_handler(int signal);

// I2C read function with retry
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(fd, reg, (char *)buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, unsigned char reg, unsigned char val) {
    int retries = 0;
    int result;

