// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define SAMPLE_DELAY_US 10000 // 10 ms
#define MAX_RETRIES 3

// ADXRS290 Registers
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP 0x04
#define ADXRS290_REG_STATUS 0x06
#define ADXRS290_REG_DIAG 0x08
#define ADXRS290_REG_X_RATE_BW 0x0A
#define ADXRS290_REG_Y_RATE_BW 0x0C
#define ADXRS290_REG_TEMP_BW 0x0E
#define ADXRS290_REG_CTRL 0x10
#define ADXRS290_REG_FIFO_CTRL 0x12
#define ADXRS290_REG_FIFO_DATA 0x14
#define ADXRS290_REG_FIFO_STATUS 0x16
#define ADXRS290_REG_SERIAL_ID 0x18
#define ADXRS290_REG_RESET 0x1A

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_read_register(int reg_addr, int *data);
int spi_write_register(int reg_addr, int data);
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
int log_data(struct timespec ts, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
int initialize_spi();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// SPI read register function
int spi_read_register(int reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 0;

    tx_buf[0] = reg_addr | 0x80; // OR with read bit
    tx_buf[1] = 0x00; // Dummy byte

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 0) {
            *data = (int16_t)rx_buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read failed (attempt %d), retrying...\n", retries + 1);
            gpioDelay(1000); // Wait 1 ms before retry
            retries++;
        }
    }

    fprintf(stderr, "SPI read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// SPI write register function
int spi_write_register(int reg_addr, int data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 0;

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit
    tx_buf[1] = (char)data;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI write failed (attempt %d), retrying...\n", retries + 1);
            gpioDelay(1000); // Wait 1 ms before retry
            retries++;
        }
    }

    fprintf(stderr, "SPI write failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read gyro data function
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    int x_rate_raw, y_rate_raw;

    if (spi_read_register(ADXRS290_REG_X_RATE, &x_rate_raw) != 0) {
        fprintf(stderr, "Failed to read X rate.\n");
        return -1;
    }

    if (spi_read_register(ADXRS290_REG_Y_RATE, &y_rate_raw) != 0) {
        fprintf(stderr, "Failed to read Y rate.\n");
        return -1;
    }

    *x_rate = (int16_t)x_rate_raw;
    *y_rate = (int16_t)y_rate_raw;

    return 0;
}

// Log data function
int log_data(struct timespec ts, int16_t x_rate, int16_t y_rate) {
    fprintf(fp, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000, x_rate, y_rate);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Initialize SPI function
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int main() {
    int16_t x_rate, y_rate;
    struct timespec ts;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate chip select initially

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(fp, "timestamp,x_rate,y_rate\n");

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fclose(fp);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read gyro data
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log data
                log_data(ts, x_rate, y_rate);
            } else {
                fprintf(stderr, "Failed to get timestamp.\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        // Delay
        gpioDelay(SAMPLE_DELAY_US);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

