#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION 2 // seconds
#define SEISMIC_EVENT_DURATION 500 // milliseconds
#define LOG_FILE "seismic_events.txt"

// Global variables
static volatile int alert_active = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int open_log_file();
void log_seismic_event();
void alert_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold sensor state
typedef struct {
    int sensor1_state;
    int sensor2_state;
    uint32_t last_change_time;
} sensor_state_t;

sensor_state_t sensor_state = {0, 0, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, alert_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 1. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, alert_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 2. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic event detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(1000); // Check every 1ms
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Open log file
int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }
    return 0;
}

// Log seismic event to file
void log_seismic_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Alert callback function
void alert_callback(int gpio, int level, uint32_t tick) {
