#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <math.h>

#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GYRO_ADDRESS 0x00
#define GYRO_REGISTER 0x02 // Example register address
#define BUFFER_CAPACITY 100
#define THRESHOLD 20.0 // deg/s
#define LED_PIN 17
#define SAMPLE_RATE_HZ 100

// Data structure for circular buffer
typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

// Circular buffer
typedef struct {
    gyro_data_t data[BUFFER_CAPACITY];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
volatile sig_atomic_t program_running = 1;
circular_buffer_t gyro_buffer;

// Function prototypes
int spi_read_register(uint8_t reg);
float process_gyro_data(int16_t raw_data);
void buffer_init(circular_buffer_t *buffer);
bool buffer_add(circular_buffer_t *buffer, struct timespec timestamp, float rate);
bool buffer_get_latest(circular_buffer_t *buffer, gyro_data_t *data);
void signal_handler(int signal);
void *monitor_thread(void *arg);

// SPI read register function
int spi_read_register(uint8_t reg) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = (reg << 1) | 0x01; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte

    wiringPiSPIDataRW(SPI_CHANNEL, tx_buf, 2);

    rx_buf[0] = tx_buf[0];
    rx_buf[1] = tx_buf[1];

    return (rx_buf[1] << 8) | rx_buf[0];
}

// Data processing function
float process_gyro_data(int16_t raw_data) {
    // Convert raw data to degrees per second (adjust scale as needed)
    return (float)raw_data * 0.02; // Example conversion
}

// Circular buffer initialization function
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Circular buffer add function
bool buffer_add(circular_buffer_t *buffer, struct timespec timestamp, float rate) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].rate = rate;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count < BUFFER_CAPACITY) {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return true;
}

// Circular buffer get latest function
bool buffer_get_latest(circular_buffer_t *buffer, gyro_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return false;
    }
    int index = (buffer->head - 1 + BUFFER_CAPACITY) % BUFFER_CAPACITY;
    *data = buffer->data[index];
    pthread_mutex_unlock(&buffer->mutex);
    return true;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Monitoring thread function
void *monitor_thread(void *arg) {
    while (program_running) {
        gyro_data_t latest_data;
        if (buffer_get_latest(&gyro_buffer, &latest_data)) {
            if (fabs(latest_data.rate) > THRESHOLD) {
                digitalWrite(LED_PIN, HIGH); // Turn LED on
            } else {
                digitalWrite(LED_PIN, LOW);  // Turn LED off
            }
        }
        delay(100); // Check every 100ms
    }
    return NULL;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LED pin
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially off

    // Initialize circular buffer
    buffer_init(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create monitoring thread
    pthread_t monitor_thread_id;
    if (pthread_create(&monitor_thread_id, NULL, monitor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create monitoring thread: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    struct timespec ts;
    while (program_running) {
        // Read gyro data
        int raw_data = spi_read_register(GYRO_REGISTER);
        if (raw_data == -1) {
            fprintf(stderr, "SPI read failed\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Process gyro data
        float rate = process_gyro_data((int16_t)raw_data);

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            delay(100); // Wait before retrying
            continue;
        }

        // Add data to buffer
        if (!buffer_add(&gyro_buffer, ts, rate)) {
            fprintf(stderr, "Failed to add data to buffer\n");
        }

        // Delay for 10ms (100Hz sample rate)
        delay(10);
    }

    // Clean up
    pthread_join(monitor_thread_id, NULL);
    digitalWrite(LED_PIN, LOW); // Turn off LED
    pthread_mutex_destroy(&gyro_buffer.mutex);

    return 0;
}

