#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define the PWM frequency
#define PWM_FREQUENCY 100

// Define the PWM range
#define PWM_RANGE 255

// Global variable to store the total duration
int total_duration = 0;

// Function prototypes
int validate_duration(int duration);
int initialize_gpio();
int set_lamp_brightness(int gpio, int brightness);
int fade_lamp(int gpio, int start_brightness, int end_brightness, int duration);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to validate the duration input
int validate_duration(int duration) {
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds.\n");
        return 0;
    }
    return 1;
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 0;
    }

    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    return 1;
}

// Function to set the brightness of a lamp
int set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
    return 1;
}

// Function to fade a lamp from one brightness to another over a given duration
int fade_lamp(int gpio, int start_brightness, int end_brightness, int duration) {
    int steps = duration * PWM_FREQUENCY; // Number of steps to reach the end brightness
    float increment = (float)(end_brightness - start_brightness) / steps;
    float current_brightness = start_brightness;

    for (int i = 0; i < steps; i++) {
        current_brightness += increment;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > PWM_RANGE) current_brightness = PWM_RANGE;

        set_lamp_brightness(gpio, (int)current_brightness);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1/PWM_FREQUENCY seconds
    }

    set_lamp_brightness(gpio, end_brightness); // Ensure the lamp is at the end brightness
    return 1;
}

// Function to cleanup GPIO resources
void cleanup() {
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Validate the duration input
    total_duration = atoi(argv[1]);
    if (!validate_duration(total_duration)) {
        return 1;
    }

    // Initialize GPIO
    if (!initialize_gpio()) {
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade the lamps sequentially
    int lamp1_duration = total_duration / 3;
    int lamp2_duration = total_duration / 3;
    int lamp3_duration = total_duration - lamp1_duration - lamp2_duration;

    printf("Starting sunset simulation for %d seconds...\n", total_duration);

    fade_lamp(LAMP1_GPIO, PWM_RANGE, 0, lamp1_duration);
    printf("Lamp 1 faded to off in %d seconds.\n", lamp1_duration);

    fade_lamp(LAMP2_GPIO, PWM_RANGE, 0, lamp2_duration);
    printf("Lamp 2 faded to off in %d seconds.\n", lamp2_duration);

    fade_lamp(LAMP3_GPIO, PWM_RANGE, 0, lamp3_duration);
    printf("Lamp 3 faded to off in %d seconds.\n", lamp3_duration);

    printf("Sunset simulation complete.\n");

    // Cleanup and exit
    cleanup();
    return 0;
}

