#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define SAMPLE_DELAY_MS 10
#define LOG_FILE "touch_relay.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
void debounce_touch_event(uint16_t touch_status);
void toggle_relay();
void log_error(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121
int init_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        log_error("Failed to set MPR121 to stop mode");
        return -1;
    }
    gpioDelay(1); // Small delay

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode 0 to be a touchable electrode
        log_error("Failed to set electrode configuration");
        return -1;
    }

    // Touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 40) < 0) { // Touch threshold
            log_error("Failed to set touch threshold");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 20) < 0) { // Release threshold
            log_error("Failed to set release threshold");
            return -1;
        }
    }

    // Start mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        log_error("Failed to set MPR121 to start mode");
        return -1;
    }
    gpioDelay(1); // Small delay

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_error("Failed to read touch status");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to debounce the touch event
void debounce_touch_event(uint16_t touch_status) {
    gpioDelay(DEBOUNCE_DELAY_MS);
    uint16_t current_touch_status;
    if (read_touch_status(&current_touch_status) == 0) {
        if (touch_status != current_touch_status) {
            log_error("Debounce failed: Touch status changed during debounce period");
        }
    } else {
        log_error("Debounce failed: Could not read touch status during debounce period");
    }
}

// Function to toggle the relay
void toggle_relay() {
    int current_gpio_level = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_gpio_level);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: ERROR: %s\n", timestamp, message);
    fflush(log_file);
    perror(message); // Also print to stderr
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C connection");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        log_error("MPR121 initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize to LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t previous_touch_status = 0;

    // Main loop
    while (!terminate) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x01) { // Electrode 0 is touched
                if (!(previous_touch_status & 0x01)) {
                    toggle_relay();
                    debounce_touch_event(touch_status);
                }
            }
            previous_touch_status = touch_status;
        } else {
            log_error("Failed to read touch status in main loop");
        }

        gpioDelay(SAMPLE_DELAY_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

