#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_1 17
#define FLAME_SENSOR_2 22
#define FLAME_SENSOR_3 23
#define BUZZER 18
#define LED 24

// Define constants
#define LOG_FILE "flame_log.txt"
#define BUZZER_DURATION 2 // seconds
#define LED_DURATION 2    // seconds
#define DEBOUNCE_DELAY 50 // milliseconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_flame_sensor(int gpio_pin);
int check_flame_condition(int sensor1, int sensor2, int sensor3);
void log_flame_detection(void);
void activate_buzzer(void);
void activate_led(void);
void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
    return value;
}

// Function to check if all flame sensors indicate a LOW level
int check_flame_condition(int sensor1, int sensor2, int sensor3) {
    return (sensor1 == 0 && sensor2 == 0 && sensor3 == 0);
}

// Function to log flame detection with timestamp
void log_flame_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Flame Detected\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the buzzer
void activate_buzzer(void) {
    gpioWrite(BUZZER, 1); // Turn buzzer on
    gpioDelay(BUZZER_DURATION * 1000000); // Wait for 2 seconds
    gpioWrite(BUZZER, 0); // Turn buzzer off
}

// Function to activate the LED
void activate_led(void) {
    gpioWrite(LED, 1); // Turn LED on
    gpioDelay(LED_DURATION * 1000000); // Wait for 2 seconds
    gpioWrite(LED, 0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_flame_sensor(FLAME_SENSOR_1);
        int sensor2_value = read_flame_sensor(FLAME_SENSOR_2);
        int sensor3_value = read_flame_sensor(FLAME_SENSOR_3);

        if (check_flame_condition(sensor1_value, sensor2_value, sensor3_value)) {
            log_flame_detection();
            activate_buzzer();
            activate_led();
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioWrite(BUZZER, 0);
    gpioWrite(LED, 0);
    gpioTerminate();

    return 0;
}

