    gpioWrite(BUZZER, 1); // Turn buzzer on
    gpioDelay(BUZZER_DURATION * 1000000); // Wait for 2 seconds
    gpioWrite(BUZZER, 0); // Turn buzzer off
}

// Function to activate the LED
void activate_led(void) {
    gpioWrite(LED, 1); // Turn LED on
    gpioDelay(LED_DURATION * 1000000); // Wait for 2 seconds
    gpioWrite(LED, 0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
