// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

// Ultrasonic Sensor
#define TRIGGER_PIN 20
#define ECHO_PIN 21

// PID Constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Global Variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
float read_ultrasonic_sensor();
float calculate_tilt_error();
int set_motor_speed(int motor, int speed);
int stop_motors();
int log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// PID Controller
float integral = 0.0;
float previous_error = 0.0;

// Function to read the ultrasonic sensor
float read_ultrasonic_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high
    int count = 10000; // Timeout after 10ms
    while (gpioRead(ECHO_PIN) == 0 && count > 0) {
        count--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count == 0) return 9999.0; // Timeout
    start_tick = gpioTick();

    // Wait for echo to go low
    count = 10000; // Timeout after 10ms
    while (gpioRead(ECHO_PIN) == 1 && count > 0) {
        count--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count == 0) return 9999.0; // Timeout
    end_tick = gpioTick();

    double diff = (double)(end_tick - start_tick);
    double distance = diff / 2.0 / 29.1; // Speed of sound: 29.1 us/cm

    return (float)distance;
}

// Function to calculate the tilt error
float calculate_tilt_error() {
    // Simulate tilt error (replace with actual sensor reading)
    float tilt_error = ((float)rand() / RAND_MAX) * 20.0 - 10.0;
    return tilt_error;
}

// Function to set the motor speed
int set_motor_speed(int motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    int forward_pin, backward_pin, enable_pin;

    if (motor == 0) { // Motor A
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin = ENA;
    } else if (motor == 1) { // Motor B
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin = ENB;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return -1;
    }

    gpioWrite(enable_pin, 1); // Enable PWM

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(enable_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, 0);
    }

    return 0;
}

// Function to stop both motors
int stop_motors() {
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
    return 0;
}

// Function to log data to a file
int log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Stopping motors and exiting.\n");
        program_running = 0;
        stop_motors();
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize random seed
    srand(time(NULL));

    // Open log file
    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor data
        float distance = read_ultrasonic_sensor();
        float tilt_error = calculate_tilt_error();

        // PID control
        float error = tilt_error;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        // Motor control
        int motor_a_speed = (int)(output * 50.0); // Adjust gain as needed
        int motor_b_speed = (int)(output * 50.0); // Adjust gain as needed

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            printf("Obstacle detected! Reverse both motors.\n");
            set_motor_speed(0, -255);
            set_motor_speed(1, -255);
            gpioDelay(500); // Reverse for 500ms
            set_motor_speed(0, 0);
            set_motor_speed(1, 0);
            gpioDelay(50); // Stop for 50ms
        } else {
            set_motor_speed(0, motor_a_speed);
            set_motor_speed(1, motor_b_speed);
        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50); // 50ms delay

        previous_error = error;
    }

    // Cleanup
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

