#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Configuration
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 2 // bytes
#define PERIOD_SIZE 1024
#define DEVICE_NAME "default"
#define RMS_BUFFER_SIZE 100 // milliseconds
#define PWM_FREQUENCY 1000  // Hz
#define PWM_RANGE 255
#define SCALE_FACTOR_DEFAULT 1.0
#define SCALE_FACTOR_MIN 0.1
#define SCALE_FACTOR_MAX 5.0
#define SCALE_FACTOR_ARG_NAME "--scale"
#define SCALE_FACTOR_ARG_NAME_SHORT "-s"

// GPIO pins
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

// ALSA availability macro
#ifdef ALSA_PCM_NEW
#define ALSA_AVAILABLE 1
#else
#define ALSA_AVAILABLE 0
#endif

// Global variables
snd_pcm_t *pcm_handle = NULL;
double scale_factor = SCALE_FACTOR_DEFAULT;
int running = 1;

// Function prototypes
int initialize_alsa(snd_pcm_t **pcm_handle, snd_pcm_hw_params_t **hw_params);
double calculate_rms(const short *buffer, int num_frames);
void map_rms_to_color(double rms, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);
void cleanup();

// Function to initialize ALSA
int initialize_alsa(snd_pcm_t **pcm_handle, snd_pcm_hw_params_t **hw_params) {
    int rc;
    snd_pcm_hw_params_t *params;
    unsigned int val;

    rc = snd_pcm_open(pcm_handle, DEVICE_NAME, SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", DEVICE_NAME, snd_strerror(rc));
        return -1;
    }

    snd_pcm_hw_params_alloca(&params);

    rc = snd_pcm_hw_params_any(*pcm_handle, params);
    if (rc < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_access(*pcm_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_format(*pcm_handle, params, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_channels(*pcm_handle, params, NUM_CHANNELS);
    if (rc < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    val = SAMPLE_RATE;
    rc = snd_pcm_hw_params_set_rate_near(*pcm_handle, params, &val, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    val = PERIOD_SIZE;
    rc = snd_pcm_hw_params_set_period_size_near(*pcm_handle, params, &val, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params(*pcm_handle, params);
    if (rc < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    *hw_params = params;

    return 0;
}

// Function to calculate RMS amplitude
double calculate_rms(const short *buffer, int num_frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_frames; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / num_frames);
}

// Function to map RMS amplitude to color
void map_rms_to_color(double rms, int *red, int *green, int *blue) {
    // Non-linear mapping (e.g., logarithmic)
    double normalized_rms = rms / 32767.0; // Normalize to a reasonable range
    double mapped_rms = log10(1.0 + normalized_rms * scale_factor) / log10(1.0 + scale_factor);

    // Map to RGB (example: red to green)
    *red = (int)(mapped_rms * 255.0);
    *green = 255 - (int)(mapped_rms * 255.0);
    *blue = 0;

    // Clamp values to 0-255
    if (*red > 255) *red = 255;
    if (*green > 255) *green = 255;
    if (*blue > 255) *blue = 255;
    if (*red < 0) *red = 0;
    if (*green < 0) *green = 0;
    if (*blue < 0) *blue = 0;
}

// Function to set LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int rc;
    snd_pcm_hw_params_t *hw_params = NULL;
    short *buffer = NULL;
    int buffer_size = PERIOD_SIZE * SAMPLE_SIZE;
    int red, green, blue;
    double rms;
    struct timeval start_time, current_time;
    long elapsed_time;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], SCALE_FACTOR_ARG_NAME) == 0 && i + 1 < argc) {
            scale_factor = atof(argv[i + 1]);
            if (scale_factor < SCALE_FACTOR_MIN || scale_factor > SCALE_FACTOR_MAX) {
                fprintf(stderr, "Scale factor out of range. Using default: %f\n", SCALE_FACTOR_DEFAULT);
                scale_factor = SCALE_FACTOR_DEFAULT;
            }
            i++; // Skip the argument value
        } else if (strcmp(argv[i], SCALE_FACTOR_ARG_NAME_SHORT) == 0 && i + 1 < argc) {
            scale_factor = atof(argv[i + 1]);
            if (scale_factor < SCALE_FACTOR_MIN || scale_factor > SCALE_FACTOR_MAX) {
                fprintf(stderr, "Scale factor out of range. Using default: %f\n", SCALE_FACTOR_DEFAULT);
                scale_factor = SCALE_FACTOR_DEFAULT;
            }
            i++; // Skip the argument value
        }
    }

    printf("Scale factor: %f\n", scale_factor);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Allocate buffer
    buffer = (short *)malloc(buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate buffer\n");
        cleanup();
        return 1;
    }

    // Initialize ALSA
    if (ALSA_AVAILABLE) {
        if (initialize_alsa(&pcm_handle, &hw_params) != 0) {
            fprintf(stderr, "ALSA initialization failed\n");
            cleanup();
            return 1;
        }
    } else {
        printf("ALSA not available, using simulated audio input.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    gettimeofday(&start_time, NULL);
    while (running) {
        if (ALSA_AVAILABLE) {
            rc = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
            if (rc == -EPIPE) {
                fprintf(stderr, "Overrun occurred\n");
                snd_pcm_prepare(pcm_handle);
            } else if (rc == -ESTRPIPE) {
                fprintf(stderr, "Suspended\n");
                snd_pcm_resume(pcm_handle);
            } else if (rc < 0) {
                fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(rc));
            } else if (rc != PERIOD_SIZE) {
                fprintf(stderr, "Short read, read %d frames\n", rc);
            } else {
                rms = calculate_rms(buffer, PERIOD_SIZE);
                map_rms_to_color(rms, &red, &green, &blue);
                set_led_color(red, green, blue);
            }
        } else {
            // Simulate audio input with a sine wave
            double time = (double)(gettimeofday().tv_sec % 10000) / 10000.0; // 0-10 seconds
            double amplitude = 127.0 * (1.0 + sin(2.0 * M_PI * 440.0 * time)); // 440 Hz sine wave
            rms = amplitude;
            map_rms_to_color(rms, &red, &green, &blue);
            set_led_color(red, green, blue);
        }

        // Print status every 100ms
        gettimeofday(&current_time, NULL);
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;
        if (elapsed_time >= 100) {
            printf("RMS: %f, Red: %d, Green: %d, Blue: %d\n", rms, red, green, blue);
            gettimeofday(&start_time, NULL);
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    free(buffer);
    return 0;
}

