#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_data(int i2c_handle, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b);
int log_data(FILE *fp, uint32_t timestamp, uint16_t c, uint16_t r, uint16_t g, uint16_t b);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize TCS34725 sensor
int tcs34725_init(int i2c_handle) {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable TCS34725 sensor.\n");
        return -1;
    }

    // Set integration time (154ms)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xEB) < 0) {
        fprintf(stderr, "Error: Could not set integration time.\n");
        return -1;
    }

    return 0;
}

// Read color data from TCS34725 sensor
int tcs34725_read_data(int i2c_handle, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    char buf[8];

    // Read all color data in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buf, 8) < 0) {
        fprintf(stderr, "Error: Could not read color data.\n");
        *c = 0; *r = 0; *g = 0; *b = 0;
        return -1;
    }

    *c = (buf[1] << 8) | buf[0];
    *r = (buf[3] << 8) | buf[2];
    *g = (buf[5] << 8) | buf[4];
    *b = (buf[7] << 8) | buf[6];

    return 0;
}

// Log data to CSV file
int log_data(FILE *fp, uint32_t timestamp, uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    if (fprintf(fp, "%u,%u,%u,%u,%u\n", timestamp, c, r, g, b) < 0) {
        fprintf(stderr, "Error: Could not write data to file.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open color_data.csv for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,C,R,G,B\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t c, r, g, b;
    uint32_t timestamp;

    // Main loop
    while (!terminate) {
        // Read color data
        if (tcs34725_read_data(i2c_handle, &c, &r, &g, &b) == 0) {
            // Get Unix epoch timestamp
            timestamp = time(NULL);

            // Log data to file
            if (log_data(fp, timestamp, c, r, g, b) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read color data.\n");
        }

        // Wait 500ms
        gpioDelay(500000); // pigpio uses microseconds
    }

    // Cleanup
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

