#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define sunrise and sunset durations (in seconds)
#define SUNRISE_DURATION 3600  // 1 hour
#define DAYTIME_DURATION 21600 // 6 hours
#define SUNSET_DURATION 3600  // 1 hour
#define NIGHTTIME_DURATION 50400 // 14.4 hours

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay (active-low)
void set_relay_state(int gpio_pin, int state) {
    gpioWrite(gpio_pin, !state); // Active-low
}

// Function to calculate the PWM duty cycle based on time and duration
int calculate_duty_cycle(int current_time, int total_duration) {
    if (current_time < 0 || current_time > total_duration) {
        fprintf(stderr, "Error: Invalid current time (%d) for duration (%d)\n", current_time, total_duration);
        return -1; // Indicate an error
    }

    if (total_duration == 0) {
        return 0; // Avoid division by zero
    }

    return (int)(((float)current_time / (float)total_duration) * PWM_RANGE);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range for all pins
    gpioSetPWMrange(RELAY1_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY2_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY3_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY4_PIN, PWM_RANGE);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sunrise, daytime, sunset, and nighttime lighting simulation started.\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Sunrise phase
        for (int i = 0; i <= SUNRISE_DURATION && program_running; i++) {
            int duty_cycle = calculate_duty_cycle(i, SUNRISE_DURATION);
            if (duty_cycle == -1) {
                program_running = 0; // Exit on error
                break;
            }

            set_pwm_duty_cycle(RELAY1_PIN, duty_cycle);
            set_pwm_duty_cycle(RELAY2_PIN, duty_cycle);
            set_pwm_duty_cycle(RELAY3_PIN, duty_cycle);
            set_pwm_duty_cycle(RELAY4_PIN, duty_cycle);
            gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1/PWM_FREQUENCY seconds
        }

        // Daytime phase
        for (int i = 0; i <= DAYTIME_DURATION && program_running; i++) {
            set_relay_state(RELAY1_PIN, 1); // Turn on all relays
            set_relay_state(RELAY2_PIN, 1);
            set_relay_state(RELAY3_PIN, 1);
            set_relay_state(RELAY4_PIN, 1);
            gpioDelay(1000000); // Delay for 1 second
        }

        // Sunset phase
        for (int i = 0; i <= SUNSET_DURATION && program_running; i++) {
            int duty_cycle = calculate_duty_cycle(i, SUNSET_DURATION);
            if (duty_cycle == -1) {
                program_running = 0; // Exit on error
                break;
            }

            set_pwm_duty_cycle(RELAY1_PIN, duty_cycle);
            set_pwm_duty_cycle(RELAY2_PIN, duty_cycle);
            set_pwm_duty_cycle(RELAY3_PIN, duty_cycle);
            set_pwm_duty_cycle(RELAY4_PIN, duty_cycle);
            gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1/PWM_FREQUENCY seconds
        }

        // Nighttime phase
        for (int i = 0; i <= NIGHTTIME_DURATION && program_running; i++) {
            set_relay_state(RELAY1_PIN, 0); // Turn off all relays
            set_relay_state(RELAY2_PIN, 0);
            set_relay_state(RELAY3_PIN, 0);
            set_relay_state(RELAY4_PIN, 0);
            gpioDelay(1000000); // Delay for 1 second
        }
    }

    // Cleanup and exit
    printf("Turning off all relays...\n");
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

