#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR_PATH "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a motion event to a file
int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to capture a video using raspivid
int capture_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s%s -t %d", VIDEO_DIR_PATH, filename, VIDEO_DURATION_SEC * 1000); // raspivid uses milliseconds

    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to generate a filename based on the current timestamp
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(25 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(filename, 25, "%Y%m%d_%H%M%S.h264", timeinfo);
    return filename;
}

// Function to handle the SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_trigger_time = 0;

    while (running) {
        // Read the GPIO pin level
        int level = gpioRead(GPIO_PIN);

        // Check for motion event (LOW signal)
        if (level == 0) {
            // Debounce the input
            int current_time = gpioTick();
            if (current_time - last_trigger_time > DEBOUNCE_INTERVAL_MS * 1000) { // Convert ms to microseconds
                // Generate filename
                char *filename = generate_filename();
                if (filename == NULL) {
                    fprintf(stderr, "Failed to generate filename\n");
                    continue; // Skip to the next iteration
                }

                // Get timestamp
                char *timestamp = get_iso8601_timestamp();
                if (timestamp == NULL) {
                    fprintf(stderr, "Failed to get timestamp\n");
                    free(filename);
                    continue;
                }

                // Log the motion event
                if (log_motion_event(timestamp) != 0) {
                    fprintf(stderr, "Failed to log motion event\n");
                }
                free(timestamp);

