#include <string.h>

// Define GPIO pins for the relays
#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int gpio_pin, int moisture_level);
void log_data(int moisture_level, int relay_1_state, int relay_2_state, int relay_3_state, int relay_4_state);
void signal_handler(int signal);

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY_1, PI_OUTPUT);
    gpioSetMode(RELAY_2, PI_OUTPUT);
    gpioSetMode(RELAY_3, PI_OUTPUT);
    gpioSetMode(RELAY_4, PI_OUTPUT);

    // Initialize relays to OFF (HIGH)
    gpioWrite(RELAY_1, 1);
    gpioWrite(RELAY_2, 1);
    gpioWrite(RELAY_3, 1);
    gpioWrite(RELAY_4, 1);

    return 0; // Indicate success
}

// Function to simulate reading the moisture sensor
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random moisture level between 0 and 100
    int moisture_level = rand() % 101;

    return moisture_level;
}

// Function to control the relay based on the moisture level
void control_relay(int gpio_pin, int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        // Dry soil, activate the relay (LOW)
        gpioWrite(gpio_pin, 0);
    } else {
        // Wet soil, deactivate the relay (HIGH)
        gpioWrite(gpio_pin, 1);
    }
}

// Function to log the data to a file
void log_data(int moisture_level, int relay_1_state, int relay_2_state, int relay_3_state, int relay_4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Relay 1: %s, Relay 2: %s, Relay 3: %s, Relay 4: %s\n",
            timestamp, moisture_level,
            relay_1_state == 0 ? "ON" : "OFF",
            relay_2_state == 0 ? "ON" : "OFF",
            relay_3_state == 0 ? "ON" : "OFF",
            relay_4_state == 0 ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Deactivate all relays
    gpioWrite(RELAY_1, 1);
    gpioWrite(RELAY_2, 1);
    gpioWrite(RELAY_3, 1);
    gpioWrite(RELAY_4, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file for appending
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read the moisture sensor
        int moisture_level = read_moisture_sensor();

        // Control the relays
        control_relay(RELAY_1, moisture_level);
        control_relay(RELAY_2, moisture_level);
        control_relay(RELAY_3, moisture_level);
        control_relay(RELAY_4, moisture_level);

        // Log the data
        log_data(moisture_level, gpioRead(RELAY_1), gpioRead(RELAY_2), gpioRead(RELAY_3), gpioRead(RELAY_4));

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

