#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_WIDTH 10  // microseconds
#define MAX_DISTANCE 23200      // microseconds (4 meters)
#define TIMEOUT_US 100          // microseconds
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int pigpio_initialized = 0;
static int mutex_initialized = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
void timeout_callback();
void signal_handler(int signal);

// Mutex (simulated using pigpio's callback mechanism)
void mutex_lock() {
    // No explicit locking needed in this simple example
    // pigpio's callbacks are atomic, so we don't need to worry about race conditions
}

void mutex_unlock() {
    // No explicit unlocking needed in this simple example
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    mutex_lock();
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Indicate falling edge received

        uint32_t pulse_width = end_tick - start_tick;

        if (pulse_width > MAX_DISTANCE) {
            fprintf(stderr, "Error: Invalid pulse width (%u us) - discarding\n", pulse_width);
        } else {
            // Get timestamp with nanosecond precision
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            uint32_t timestamp_ns = (uint32_t)(ts.tv_sec % 71552000) * 1000000000 + ts.tv_nsec; // Wrap around roughly every 71.6 minutes

            // Log the data to file
            fprintf(log_file, "%u,%u\n", timestamp_ns, pulse_width);
            fflush(log_file); // Ensure data is written to disk immediately
        }
    }
    mutex_unlock();
}

// Callback function for timeout
void timeout_callback() {
    mutex_lock();
    fprintf(stderr, "Error: Timeout occurred\n");
    mutex_unlock();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    if (pigpio_initialized) {
        gpioTerminate();
    }

    // Destroy mutex (simulated)
    if (mutex_initialized) {
        // No explicit destruction needed in this simple example
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up callbacks
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        trigger_sensor();
        gpioSetTimerFuncEx(0, 200, timeout_callback, NULL); // Set timeout
        gpioDelay(200); // Wait 200ms before next trigger
    }

    return 0;
}

