#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR_1 0x18
#define LIS3DH_ADDR_2 0x19
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define BUZZER_DURATION_MS 1000

// Global variables
static int i2c_handle = -1;
static volatile bool running = true;
static float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
static float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

// Function prototypes
int init_i2c(int bus, int addr);
int init_lis3dh(int handle);
int read_acceleration(int handle, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
bool detect_freefall(float magnitude, float threshold);
bool detect_impact(float magnitude, float threshold);
void activate_buzzer(int gpio, int duration_ms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = false;
    }
}

// Initialize I2C interface
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Initialize LIS3DH sensor
int init_lis3dh(int handle) {
    // Enable all axes and set data rate to 100 Hz
    if (i2cWriteByteData(handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes, convert to g-force units
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)x_raw / 16384.0f; // +/- 2g range
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Detect free-fall
bool detect_freefall(float magnitude, float threshold) {
    return magnitude < threshold;
}

// Detect impact
bool detect_impact(float magnitude, float threshold) {
    return magnitude > threshold;
}

// Activate buzzer
void activate_buzzer(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn buzzer on
    gpioDelay(duration_ms);
    gpioWrite(gpio, 0); // Turn buzzer off
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    printf("Free-fall threshold: %.2f g\n", freefall_threshold);
    printf("Impact threshold: %.2f g\n", impact_threshold);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Attempt to initialize I2C with both addresses
    i2c_handle = init_i2c(I2C_BUS, LIS3DH_ADDR_1);
    if (i2c_handle < 0) {
        i2c_handle = init_i2c(I2C_BUS, LIS3DH_ADDR_2);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to initialize I2C with both addresses.\n");
            gpioTerminate();
            return 1;
        }
        printf("LIS3DH found at address 0x%02x\n", LIS3DH_ADDR_2);
    } else {
        printf("LIS3DH found at address 0x%02x\n", LIS3DH_ADDR_1);
    }

    // Initialize LIS3DH sensor
