        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR1_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_IN3);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR1_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_IN4);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_IN1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_IN3);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_IN4);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Trace the square
    if (trace_square(50, 2048, 1) < 0) {
        fprintf(stderr, "Error: Failed to trace the square\n");
