#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// LIS3DH Registers
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L   0x28
#define LIS3DH_OUT_X_H   0x29
#define LIS3DH_OUT_Y_L   0x2A
#define LIS3DH_OUT_Y_H   0x2B
#define LIS3DH_OUT_Z_L   0x2C
#define LIS3DH_OUT_Z_H   0x2D

// Configuration
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define SAMPLE_RATE_MS 100
#define SAMPLE_RATE_HZ (1000 / SAMPLE_RATE_MS)
#define LOG_FILE "/var/log/high_acceleration.log"

// Global variables
static int i2c_handle;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
int log_data(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the LIS3DH sensor
int initialize_sensor(int i2c_handle) {
    // Configure CTRL_REG1: 100Hz, Normal mode, Enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: High resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x88) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = *y = *z = 0.0; // Return 0s on error
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g units (assuming +/- 2g range and 12-bit resolution)
    *x = (float)raw_x / 3276.8f;
    *y = (float)raw_y / 3276.8f;
    *z = (float)raw_z / 3276.8f;

    return 0;
}

// Function to log acceleration data to a file
int log_data(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.3f, %.3f, %.3f\n", timestamp, x, y, z);
    fclose(fp);
    return 0;
}

// Function to shutdown the system
void shutdown_system() {
    printf("Shutting down...\n");
    if (i2c_handle >= 0) {
