    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the LIS3DH sensor
int initialize_sensor(int i2c_handle) {
    // Configure CTRL_REG1: 100Hz, Normal mode, Enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: High resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x88) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

