        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g units (assuming +/- 2g range and 12-bit resolution)
    *x = (float)raw_x / 3276.8f;
    *y = (float)raw_y / 3276.8f;
