#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Define alert duration
#define ALERT_DURATION 2 // seconds

// Define no line threshold
#define NO_LINE_THRESHOLD 5

// Define motor control functions (placeholders)
void move_forward() { printf("Moving forward\n"); }
void turn_left() { printf("Turning left\n"); }
void turn_right() { printf("Turning right\n"); }
void stop_moving() { printf("Stopping\n"); }

// Global variables
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int read_sensor(int gpio_pin);
void update_buffer(CircularBuffer *cb, int value);
int check_line(CircularBuffer *cb);
void handle_alert();
void signal_handler(int signal);
void initialize_circular_buffer(CircularBuffer *cb);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Initialize circular buffer
void initialize_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 1; // Initialize with a default value (no line)
    }
}

// Read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Update circular buffer
void update_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Check for line presence
int check_line(CircularBuffer *cb) {
    int no_line_count = 0;
    for (int i = 0; i < cb->count; i++) {
        if (cb->buffer[i] == 1) {
            no_line_count++;
        }
    }
    return (no_line_count >= NO_LINE_THRESHOLD) ? 1 : 0;
}

// Handle alert
void handle_alert() {
    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
    gpioDelay(ALERT_DURATION * 1000000); // Wait for alert duration
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer line_buffer;
    initialize_circular_buffer(&line_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int center_value = read_sensor(CENTER_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        // Update circular buffer
        update_buffer(&line_buffer, center_value);

        // Check for errors
        if (left_value == -1 || center_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            gpioTerminate();
            return 1;
        }

        // Check for line presence
        int line_present = check_line(&line_buffer);

        // Control robot based on sensor readings
        if (line_present) {
            if (left_value == 0) {
                turn_left();
            } else if (right_value == 0) {
                turn_right();
            } else {
                move_forward();
            }
        } else {
            stop_moving();
            handle_alert();
        }

        gpioDelay(10000); // Delay for 10ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

