#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define MAGNETIC_FIELD_THRESHOLD 5.0 // mT
#define SAMPLE_INTERVAL_MS 100
#define TIMEOUT_COUNT 50
#define LOG_FILE "magnetic_events.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(float *magnetic_field);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);

// Structure for sensor data (example)
typedef struct {
    float magnetic_field;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read magnetic field data
int read_magnetic_field(float *magnetic_field) {
    char buf[2];
    int result;
    int timeout_count = 0;

    while (timeout_count < TIMEOUT_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert raw data to magnetic field (example conversion)
            int16_t raw_data = (buf[0] << 8) | buf[1];
            *magnetic_field = (float)raw_data / 100.0; // Example scaling
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d\n", result);
            log_event("I2C read error");
            gpioDelay(1000); // Wait 1ms before retrying
            timeout_count++;
        }
    }

    fprintf(stderr, "Timeout reading magnetic field after %d attempts\n", TIMEOUT_COUNT);
    log_event("Timeout reading magnetic field");
    return -1; // Timeout
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Function to log events
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float magnetic_field;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read magnetic field
        if (read_magnetic_field(&magnetic_field) == 0) {
            // Check threshold and control relay
            if (magnetic_field > MAGNETIC_FIELD_THRESHOLD) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }

            // Log magnetic field reading
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Magnetic field: %.2f mT", magnetic_field);
            log_event(log_message);
        } else {
            fprintf(stderr, "Failed to read magnetic field. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is off
    gpioTerminate();
    log_event("Program terminated");

    return 0;
}

