#include <netinet/in.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

int server_fd, new_socket;
FILE *log_file;

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    char message[100];
    sprintf(message, "Received signal %d, shutting down...", signum);
    log_event(message);

    // Turn off the relay
    gpioWrite(GPIO_PIN, 0);

    // Close the socket
    if (new_socket > 0) {
        close(new_socket);
    }
    if (server_fd > 0) {
        close(server_fd);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    int addrlen = sizeof(struct sockaddr_in);
    char buffer[BUFFER_SIZE] = {0};
    int valread;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_event("setsockopt failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure server address
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to the address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Socket bind failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_event("Socket listen failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_event("Server listening on port 5000");

    // Accept incoming connections
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            log_event("Socket accept failed");
            close(server_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Read data from the socket
        valread = recv(new_socket, buffer, BUFFER_SIZE - 1, 0);
        if (valread < 0) {
            perror("recv failed");
            log_event("Socket recv failed");
            close(new_socket);
            close(server_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
        buffer[valread] = '\0';

        // Process the command
        char command[BUFFER_SIZE];
        strncpy(command, buffer, BUFFER_SIZE - 1);
        command[BUFFER_SIZE - 1] = '\0'; // Ensure null termination

        // Remove trailing whitespace
        char *end = command + strlen(command) - 1;
        while (end > command && isspace((unsigned char)*end)) end--;
        end[1] = '\0';

        if (strcasecmp(command, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            log_event("Relay turned ON");
        } else if (strcasecmp(command, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
            log_event("Relay turned OFF");
        } else {
            char message[100];
            sprintf(message, "Invalid command: %s", command);
            log_event(message);
        }

        // Close the socket
        close(new_socket);
        new_socket = 0; // Reset new_socket to 0 after closing
    }

    return 0;
}

