#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0 // ml/min
#define POLLING_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int i2c_bus, int i2c_address);
int read_sensor_data(int i2c_handle, float *flow_rate);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int control_relay(int gpio_pin, int state);
int log_flow_data(FILE *log_file, float flow_rate1, float flow_rate2);
void signal_handler(int signal);
void cleanup();

// CRC-8-Maxim polynomial 0x31 (x^8 + x^5 + x^4 + 1)
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc = crc8_table[crc ^ data[i]];
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        cleanup();
        return 1;
    }

    // Initialize relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    float flow_rate1, flow_rate2;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
        }
        if (read_sensor_data(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
        }

        // Control relay based on flow rates
        if ((flow_rate1 < FLOW_THRESHOLD) && (flow_rate2 < FLOW_THRESHOLD)) {
            control_relay(RELAY_GPIO, 1); // Energize relay
        } else {
            control_relay(RELAY_GPIO, 0); // De-energize relay
        }

        // Log flow data
        log_flow_data(log_file, flow_rate1, flow_rate2);

        // Wait for the next poll interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int initialize_i2c(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", i2c_address, handle);
        return -1;
    }

    // Start measurement command (0x36, 0x2F)
    char start_cmd[2] = {0x36, 0x2F};
    int result = i2cWriteDevice(handle, start_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write start measurement command to sensor at address 0x%02x: %d\n", i2c_address, result);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

int read_sensor_data(int i2c_handle, float *flow_rate) {
    char buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Failed to read 3 bytes from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Validate CRC
    if (!validate_crc((uint8_t *)buffer, 2, buffer[2])) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data to flow rate (ml/min)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 120.0; // Sensitivity of 120 LSB/ml/min

    return 0;
}

int validate_crc(uint8_t data[], int len, uint8_t crc) {
    return crc8(data, len) == crc;
}

int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

int log_flow_data(FILE *log_file, float flow_rate1, float flow_rate2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n", timestamp, flow_rate1, flow_rate2);
    fflush(log_file);

    return 0;
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup() {
    // De-energize relay
    control_relay(RELAY_GPIO, 0);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

