void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event(LOG_INFO, "Received shutdown signal. Stopping motor and exiting.");
        program_running = 0;
        stop_motor();
        gpioTerminate();
        closelog();
        exit(0);
    }
}

