        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) {
            log_event(LOG_ERR, "Error reading sensor, exiting");
            break;
        }

        if (sensor_value == 0 && last_sensor_value == 1) { // Rising edge (dry to wet)
            log_event(LOG_INFO, "Rain detected!");
            if (control_motor(1) != 0) {
                log_event(LOG_ERR, "Failed to start motor");
            }
            sleep(MOTOR_DURATION);
            if (control_motor(0) != 0) {
                log_event(LOG_ERR, "Failed to stop motor");
            }
            consecutive_rain_count = 0; // Reset rain count after successful close
        } else if (sensor_value == 1) {
            consecutive_rain_count++;
            if (consecutive_rain_count >= RAIN_DETECT_THRESHOLD) {
                log_event(LOG_INFO, "Rain persists for threshold duration. Stopping motor.");
                stop_motor();
                consecutive_rain_count = 0; // Reset rain count after stopping
            }
        } else {
            consecutive_rain_count = 0; // Reset rain count if no rain
        }

        last_sensor_value = sensor_value;
        usleep(200000); // 200ms
    }

    // Cleanup
    log_event(LOG_INFO, "Cleaning up and exiting.");
    stop_motor();
    gpioTerminate();
    closelog();

    return 0;
}

