#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define pulse widths (in microseconds)
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to track the current state of the servo
int servo_state = 0; // 0: stopped, 1: locked, 2: unlocked

// Function prototypes
int initialize_gpio();
int read_button(int pin);
int set_servo_pulse_width(int pin, int pulse_width);
void handle_lock_button();
void handle_unlock_button();
void handle_shutdown_signal(int signal);

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, shutting down...\n", signal);
    handle_shutdown_signal(signal);
    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read button states
        int lock_button_pressed = read_button(LOCK_BUTTON_PIN);
        int unlock_button_pressed = read_button(UNLOCK_BUTTON_PIN);

        // Handle button presses
        if (lock_button_pressed) {
            handle_lock_button();
        } else if (unlock_button_pressed) {
            handle_unlock_button();
        }

        // Small delay to reduce CPU usage
        usleep(1000); // 1 millisecond
    }

    return 0;
}

// Function to initialize GPIO
int initialize_gpio()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Enable pull-up resistors on the button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the state of a button
int read_button(int pin)
{
    return !gpioRead(pin); // Button is active low
}

// Function to set the pulse width of the servo
int set_servo_pulse_width(int pin, int pulse_width)
{
    int result = gpioServo(pin, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to handle the lock button press
void handle_lock_button()
{
    // Debounce
    usleep(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

    // Check if the button is still pressed after the debounce delay
    if (read_button(LOCK_BUTTON_PIN)) {
        printf("Lock button pressed. Locking the door.\n");
        if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Failed to set lock pulse width.\n");
        } else {
            servo_state = 1; // Update servo state
        }
    }
}

// Function to handle the unlock button press
void handle_unlock_button()
{
    // Debounce
    usleep(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

    // Check if the button is still pressed after the debounce delay
    if (read_button(UNLOCK_BUTTON_PIN)) {
        printf("Unlock button pressed. Unlocking the door.\n");
        if (set_servo_pulse_width(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Failed to set unlock pulse width.\n");
        } else {
            servo_state = 2; // Update servo state
        }
    }
}

// Function to handle shutdown signals
void handle_shutdown_signal(int signal)
{
    // Stop the servo
    printf("Stopping servo...\n");
    if (set_servo_pulse_width(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to stop servo.\n");
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
}

