#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_TIME 60  // seconds
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_led();
int deactivate_led();
int log_event(const char *event_type, int duration);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int pir_pin;
    int led_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Activate LED
int activate_led() {
    gpioWrite(LED_PIN, 1);
    return 0;
}

// Deactivate LED
int deactivate_led() {
    gpioWrite(LED_PIN, 0);
    return 0;
}

// Log event to file
int log_event(const char *event_type, int duration) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (strcmp(event_type, "activate") == 0) {
        fprintf(log_file, "%s - LED activated for %d seconds\n", timestamp, duration);
    } else if (strcmp(event_type, "deactivate") == 0) {
        fprintf(log_file, "%s - LED deactivated\n", timestamp);
    } else {
        fprintf(stderr, "Invalid event type: %s\n", event_type);
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    deactivate_led();

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_pir_sensor() == 1) {
            printf("Motion detected!\n");
            if (activate_led() == 0) {
                log_event("activate", LED_ON_TIME);
                gpioDelay(LED_ON_TIME * 1000); // Delay for LED_ON_TIME seconds
                deactivate_led();
                log_event("deactivate", 0);
            } else {
                fprintf(stderr, "Failed to activate LED\n");
            }
        }
        gpioDelay(100); // Polling interval of 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_led();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

