int log_event(const char *event_type, int duration) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (strcmp(event_type, "activate") == 0) {
        fprintf(log_file, "%s - LED activated for %d seconds\n", timestamp, duration);
    } else if (strcmp(event_type, "deactivate") == 0) {
        fprintf(log_file, "%s - LED deactivated\n", timestamp);
    } else {
        fprintf(stderr, "Invalid event type: %s\n", event_type);
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    deactivate_led();

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

