    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_pir_sensor() == 1) {
            printf("Motion detected!\n");
            if (activate_led() == 0) {
                log_event("activate", LED_ON_TIME);
                gpioDelay(LED_ON_TIME * 1000); // Delay for LED_ON_TIME seconds
