                log_event("deactivate", 0);
            } else {
                fprintf(stderr, "Failed to activate LED\n");
            }
        }
        gpioDelay(100); // Polling interval of 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_led();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

