#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_ECR 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
int debounce_touch(int i2c_handle, int electrode);
int control_relay(int gpio_pin, int state);
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121 sensor
int mpr121_init(int i2c_handle) {
    // Soft Reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        log_message("Error: Soft Reset failed");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure Baseline Filtering
    if (i2cWriteByteData(i2c_handle, MPR121_MHD_R, 0x01) < 0) {
        log_message("Error: MHD_R write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHD_R, 0x01) < 0) {
        log_message("Error: NHD_R write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCL_R, 0x00) < 0) {
        log_message("Error: NCL_R write failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDL_R, 0x00) < 0) {
        log_message("Error: FDL_R write failed");
        return -1;
    }

    // Configure Electrode Configuration
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        log_message("Error: Electrode Configuration failed");
        return -1;
    }

    // Configure ECR
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        log_message("Error: ECR write failed");
        return -1;
    }

    // Configure Config1
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x10) < 0) {
        log_message("Error: Config1 write failed");
        return -1;
    }

    // Configure Config2
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x20) < 0) {
        log_message("Error: Config2 write failed");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(int i2c_handle) {
    int touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    int touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        log_message("Error: Failed to read touch status");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to debounce the touch of a specific electrode
int debounce_touch(int i2c_handle, int electrode) {
    int touch_status;
    int i;

    for (i = 0; i < 5; i++) {
        touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) return -1;
        if ((touch_status & (1 << electrode)) != 0) {
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay
            touch_status = read_touch_status(i2c_handle);
            if (touch_status < 0) return -1;
            if ((touch_status & (1 << electrode)) != 0) {
                return 1; // Valid touch
            }
        }
        gpioDelay(10000); // 10ms delay
    }
    return 0; // Invalid touch
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Function to log messages to a file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, shutting down...");
    control_relay(GPIO_RELAY, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        log_message("Error: I2C bus open failed");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        log_message("Error: MPR121 initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    control_relay(GPIO_RELAY, 0); // Initialize relay to OFF state

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("MPR121 relay control started");

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            log_message("Error reading touch status, retrying...");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        if (debounce_touch(i2c_handle, 0) == 1) {
            log_message("Electrode 0 touched, toggling relay");
            int current_state = gpioRead(GPIO_RELAY);
            control_relay(GPIO_RELAY, !current_state); // Toggle relay state
        }

        gpioDelay(50000); // Delay 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

