#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <stdarg.h>

#define PORT 5000
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PWM_FREQUENCY 50
#define LOG_FILE "security.log"

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int server_fd = 0;
FILE *log_file = NULL;

// Function prototypes
void log_message(int priority, const char *format, ...);
void signal_handler(int signal);
int setup_gpio();
int setup_socket();
void handle_client(int client_fd);
int read_pir_sensor();
int set_servo_angle(int angle);
int parse_command(const char *command, int *angle);

// Function to log messages with timestamp
void log_message(int priority, const char *format, ...) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    va_list args;
    va_start(args, format);
    char message[256];
    vsnprintf(message, sizeof(message), format, args);
    va_end(args);

    // Log to syslog
    syslog(priority, "%s: %s", timestamp, message);

    // Log to file
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received: %d. Terminating...", signal);
    terminate = 1;
}

// Function to setup GPIO
int setup_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_GPIO, 2000); // 2000 us range for 50 Hz

    return 0;
}

// Function to setup the socket
int setup_socket() {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }

    return server_fd;
}

// Function to handle a client connection
void handle_client(int client_fd) {
    char buffer[1024] = {0};
    int valread;
    int angle;
    char response[256];

    valread = read(client_fd, buffer, sizeof(buffer) - 1);
    if (valread < 0) {
        log_message(LOG_ERR, "Read failed");
        close(client_fd);
        return;
    }

    buffer[valread] = '\0';
    log_message(LOG_INFO, "Received command: %s", buffer);

    if (strncmp(buffer, "PIR", 3) == 0) {
        int pir_value = read_pir_sensor();
        snprintf(response, sizeof(response), "PIR:%d", pir_value);
        send(client_fd, response, strlen(response), 0);
        log_message(LOG_INFO, "Sent PIR sensor value: %s", response);
    } else if (parse_command(buffer, &angle) == 0) {
        if (set_servo_angle(angle) == 0) {
            snprintf(response, sizeof(response), "OK");
            send(client_fd, response, strlen(response), 0);
            log_message(LOG_INFO, "Set servo angle to: %d", angle);
        } else {
            snprintf(response, sizeof(response), "ERROR: Invalid angle");
            send(client_fd, response, strlen(response), 0);
            log_message(LOG_ERR, "Invalid angle: %d", angle);
        }
    } else {
        snprintf(response, sizeof(response), "ERROR: Invalid command");
        send(client_fd, response, strlen(response), 0);
        log_message(LOG_ERR, "Invalid command: %s", buffer);
    }

    close(client_fd);
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        return -1;
    }

    // Calculate pulse width (1000us - 2000us for 0-180 degrees)
    int pulse_width = (int)(((float)angle / 180.0) * 1000.0 + 1000.0);
    gpioPWM(SERVO_GPIO, pulse_width);
    return 0;
}

// Function to parse the command
int parse_command(const char *command, int *angle) {
    char cmd[5];
    if (sscanf(command, "%4s %d", cmd, angle) == 2) {
        return 0;
    } else {
        return -1;
    }
}

int main() {
    // Open syslog
    openlog("security_system", LOG_PID | LOG_USER, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        syslog(LOG_ERR, "Error opening log file");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        log_message(LOG_ERR, "GPIO setup failed. Exiting.");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Setup socket
    server_fd = setup_socket();
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket setup failed. Exiting.");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Server listening on port %d", PORT);

    // Main loop
    while (!terminate) {
        struct sockaddr_in address;
        int addrlen = sizeof(address);
        int new_socket;

        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            if (terminate) break; // Exit loop if signal received
            log_message(LOG_ERR, "Accept failed");
            continue; // Continue listening
        }

        log_message(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(address.sin_addr), ntohs(address.sin_port));

        handle_client(new_socket);
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    close(server_fd);
    gpioTerminate();
    fclose(log_file);
    closelog();

    return 0;
}

