#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150
#define SAMPLE_INTERVAL 2 // seconds
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char config[1] = {0x10}; // Continuous high-resolution mode
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(120); // Wait for measurement

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relay
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fclose(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Deactivate relay
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_RELAY as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    printf("Relay activated\n");
                }
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    printf("Relay deactivated\n");
                }
            }

            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Sleep for SAMPLE_INTERVAL seconds
    }

    cleanup();
    return 0;
}

