#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0  // grams
#define DEFAULT_SCALE_FACTOR 1.0   // grams/raw
#define DEFAULT_DURATION 500       // milliseconds
#define NUM_READINGS 5
#define TARE_READINGS 10
#define TIMEOUT_US 1000000 // 1 second timeout

// Global variables
volatile sig_atomic_t terminate = 0;
double threshold = DEFAULT_THRESHOLD;
double scale_factor = DEFAULT_SCALE_FACTOR;
int duration = DEFAULT_DURATION;
double tare_offset = 0.0;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double scale_factor, double tare_offset);
void activate_solenoid(int duration_ms);
void tare();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Log message to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DOUT to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DOUT) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Delay 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        syslog(LOG_ERR, "Timeout waiting for HX711 DOUT to go low");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply channel A gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Two's complement conversion
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calculate weight in grams
double calculate_weight(int raw_value, double scale_factor, double tare_offset) {
    return (double)(raw_value - tare_offset) * scale_factor;
}

// Activate solenoid lock
void activate_solenoid(int duration_ms) {
    gpioWrite(SOLENOID_PIN, 1); // Set HIGH
    gpioDelay(duration_ms);      // Wait
    gpioWrite(SOLENOID_PIN, 0); // Set LOW
}

// Tare the load cell
void tare() {
    double sum = 0.0;
    int i;

    log_message(LOG_INFO, "Starting tare...");
    for (i = 0; i < TARE_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading during tare, skipping...");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    tare_offset = sum / TARE_READINGS;
    log_message(LOG_INFO, "Tare complete.");
    printf("Tare offset: %.2f\n", tare_offset);
}

int main(int argc, char *argv[]) {
    int opt;
    int i;
    double sum;
    int raw_value;
    double weight;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale_factor] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare();

    // Main loop
    while (!terminate) {
        sum = 0.0;
        for (i = 0; i < NUM_READINGS; i++) {
            raw_value = read_hx711();
            if (raw_value == -1) {
                log_message(LOG_ERR, "Error reading HX711, retrying...");
                gpioDelay(100); // Wait before retrying
                i--;             // Retry the same reading
                continue;
            }
            sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }

        weight = calculate_weight((int)(sum / NUM_READINGS), scale_factor, tare_offset);
        printf("Weight: %.2f grams\n", weight);

        if (weight > threshold) {
            log_message(LOG_INFO, "Weight threshold exceeded, activating solenoid...");
            activate_solenoid(duration);
            log_message(LOG_INFO, "Solenoid deactivated.");
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
    closelog();

    return 0;
}

