#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define KEEPALIVE 60

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Function to set the relay state
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        log_message(LOG_ERR, "Failed to write to GPIO pin.");
        return -1;
    }
    return 0;
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT client connected to broker.");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to subscribe to topic.");
        }
    } else {
        log_message(LOG_ERR, "MQTT client connection failed.");
    }
}

// Callback function for when the MQTT client disconnects from the broker
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message(LOG_ERR, "MQTT client disconnected unexpectedly.");
    } else {
        log_message(LOG_INFO, "MQTT client disconnected.");
    }
}

// Callback function for when the MQTT client receives a message
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            log_message(LOG_INFO, "Received ON command, setting relay to ON.");
            set_relay_state(1);
        } else if (strcmp(payload, "OFF") == 0) {
            log_message(LOG_INFO, "Received OFF command, setting relay to OFF.");
            set_relay_state(0);
        } else {
            log_message(LOG_ERR, "Invalid payload received.");
        }
    } else {
        log_message(LOG_ERR, "Empty payload received.");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received, stopping MQTT client and cleaning up.");
    running = 0;
}

int main() {
    // Initialize syslog
    openlog("mqtt_relay", LOG_PID, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    set_relay_state(0);

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create MQTT client instance.");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker.");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1);
        if (loop_result != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "MQTT loop error, retrying in 5 seconds.");
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

