// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (in microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define target pulse widths for each servo (in microseconds)
#define SERVO1_TARGET 1000
#define SERVO2_TARGET 1500
#define SERVO3_TARGET 2000
#define SERVO4_TARGET 500
#define SERVO5_TARGET 2500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Stopping servos and exiting...\n");
}

// Function to set the pulse width of a servo
int set_servo_pulse(int gpio_pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d us). Must be between %d and %d us.\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1; // Indicate an error
    }

    gpioPWM(gpio_pin, pulse_width); // Set the PWM duty cycle
    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set PWM frequency for all servos
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);

    // Set PWM range (resolution) - optional, but recommended
    gpioSetPWMrange(SERVO1_PIN, 1000); // Example range
    gpioSetPWMrange(SERVO2_PIN, 1000);
    gpioSetPWMrange(SERVO3_PIN, 1000);
    gpioSetPWMrange(SERVO4_PIN, 1000);
    gpioSetPWMrange(SERVO5_PIN, 1000);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Move servos to target positions
    if (set_servo_pulse(SERVO1_PIN, SERVO1_TARGET) != 0) return 1;
    if (set_servo_pulse(SERVO2_PIN, SERVO2_TARGET) != 0) return 1;
    if (set_servo_pulse(SERVO3_PIN, SERVO3_TARGET) != 0) return 1;
    if (set_servo_pulse(SERVO4_PIN, SERVO4_TARGET) != 0) return 1;
    if (set_servo_pulse(SERVO5_PIN, SERVO5_TARGET) != 0) return 1;

    // Wait for 3 seconds
    gpioDelay(3000000); // 3 seconds in microseconds

    // Stop servos (set duty cycle to 0)
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program finished.\n");
    return 0; // Exit successfully
}

