#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoders
#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PI Controller Gains
#define KP 1.0
#define KI 0.1

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Encoder Ticks Per Revolution
#define TICKS_PER_REV 64

// Target RPM
#define TARGET_RPM 50.0

// Stall Detection Timeout (seconds)
#define STALL_TIMEOUT 2

// Global Variables
volatile int32_t encoder_a_count = 0;
volatile int32_t encoder_b_count = 0;
volatile int stall_detected = 0;

// Function Prototypes
void motor_a_isr(int gpio, int level, uint32_t tick, void *user);
void motor_b_isr(int gpio, int level, uint32_t tick, void *user);
void pi_control_loop(void *user);
void signal_handler(int signal);

// Structure to hold encoder counts
typedef struct {
    int32_t encoder_a;
    int32_t encoder_b;
} encoder_data_t;

// Function to read encoder counts
encoder_data_t read_encoders(void) {
    encoder_data_t data;
    data.encoder_a = __sync_fetch_and_and(&encoder_a_count, 0); // Atomic read and reset
    data.encoder_b = __sync_fetch_and_and(&encoder_b_count, 0); // Atomic read and reset
    return data;
}

// Function to calculate RPM
double calculate_rpm(int32_t count, double time_elapsed) {
    return (double)count * (60.0 / TICKS_PER_REV) / time_elapsed;
}

// Function to set motor direction and PWM
void set_motor_pwm(int motor_pwm, int motor_dir, int pwm_value) {
    gpioWrite(motor_dir, 0); // Forward
    gpioPWM(motor_pwm, pwm_value);
}

// Function to stop motors
void stop_motors(void) {
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
}

// Interrupt Service Routines
void motor_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    uint32_t diff = current_tick - last_tick;

    if (diff > 1000) { // Debounce and filter
        if (gpio == ENCODER_A_A) {
            if (gpioRead(ENCODER_A_B) == 0) {
                __sync_fetch_and_add(&encoder_a_count, 1);
            } else {
                __sync_fetch_and_sub(&encoder_a_count, 1);
            }
        } else if (gpio == ENCODER_A_B) {
            if (gpioRead(ENCODER_A_A) == 0) {
                __sync_fetch_and_sub(&encoder_a_count, 1);
            } else {
                __sync_fetch_and_add(&encoder_a_count, 1);
            }
        }
        last_tick = current_tick;
    }
}

void motor_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    uint32_t diff = current_tick - last_tick;

    if (diff > 1000) { // Debounce and filter
        if (gpio == ENCODER_B_A) {
            if (gpioRead(ENCODER_B_B) == 0) {
                __sync_fetch_and_add(&encoder_b_count, 1);
            } else {
                __sync_fetch_and_sub(&encoder_b_count, 1);
            }
        } else if (gpio == ENCODER_B_B) {
            if (gpioRead(ENCODER_B_A) == 0) {
                __sync_fetch_and_sub(&encoder_b_count, 1);
            } else {
                __sync_fetch_and_add(&encoder_b_count, 1);
            }
        }
        last_tick = current_tick;
    }
}

// PI Control Loop
void pi_control_loop(void *user) {
    static double integral = 0.0;
    double error, output;
    encoder_data_t encoder_data;
    double time_elapsed;
    double rpm_a, rpm_b;

    // Read encoder data
    encoder_data = read_encoders();

    // Calculate time elapsed
    time_elapsed = (double)gpioTick() / 1000000.0; // in seconds

    // Calculate RPM
    rpm_a = calculate_rpm(encoder_data.encoder_a, time_elapsed);
    rpm_b = calculate_rpm(encoder_data.encoder_b, time_elapsed);

    // Calculate error
    error = TARGET_RPM - (rpm_a + rpm_b) / 2.0; // Average RPM

    // Calculate integral
    integral += error * time_elapsed;

    // Calculate output
    output = KP * error + KI * integral;

    // Anti-windup clamping
    if (output > 255.0) {
        output = 255.0;
    } else if (output < 0.0) {
        output = 0.0;
    }

    // Set motor PWM
    set_motor_pwm(MOTOR_A_PWM, MOTOR_A_DIR, (int)output);
    set_motor_pwm(MOTOR_B_PWM, MOTOR_B_DIR, (int)output);

    // Stall detection
    if (encoder_data.encoder_a == 0 && encoder_data.encoder_b == 0) {
        static time_t stall_start_time = 0;
        if (stall_start_time == 0) {
            stall_start_time = time(NULL);
        } else {
            if (time(NULL) - stall_start_time > STALL_TIMEOUT) {
                if (!stall_detected) {
                    fprintf(stderr, "Warning: Encoder stall detected!\n");
                    stall_detected = 1;
                }
            }
        }
    } else {
        stall_start_time = 0; // Reset stall timer
        stall_detected = 0;
    }

    // Print RPM and PWM
    printf("RPM A: %.2f, RPM B: %.2f, PWM: %.2f\n", rpm_a, rpm_b, output);
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();
    gpioTerminate();
    exit(0);
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

