    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, motor_a_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, motor_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, motor_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B B\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

