#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS_DELAY 5 // seconds
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// GPIO initialization
int initialize_gpio() {
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(180000); // Wait 180ms

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relay
int control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) != 0) {
        fprintf(stderr, "Error writing to GPIO\n");
        return -1;
    }
    return 0;
}

// Log data
int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Turn off relay on exit
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    time_t last_relay_change = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Chicken coop monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Control relay based on lux value with hysteresis
            time_t now = time(NULL);
            if (lux < LUX_THRESHOLD_DUSK && (now - last_relay_change) > HYSTERESIS_DELAY) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_data(lux, relay_state);
                    last_relay_change = now;
                }
            } else if (lux > LUX_THRESHOLD_DAWN && (now - last_relay_change) > HYSTERESIS_DELAY) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_data(lux, relay_state);
                    last_relay_change = now;
                }
            }

            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor\n");
            log_data(-1.0, relay_state); // Log error
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

