#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
int debounce_touch_sensor();
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        control_relay(0); // Turn off the relay
        gpioTerminate();   // Terminate pigpio
        exit(0);
    }
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch_sensor() {
    int stable_count = 0;
    int current_state = read_touch_sensor();

    while (stable_count < 5) {
        if (read_touch_sensor() == current_state) {
            stable_count++;
        } else {
            stable_count = 0;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }

    return current_state;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    relay_state = state;
}

// Function to log the relay state
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    control_relay(0);
    log_relay_state(0);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (debounce_touch_sensor() == 1) {
            // Toggle relay state
            control_relay(!relay_state);
            log_relay_state(relay_state);

            // Wait for touch release
            while (debounce_touch_sensor() == 1) {
                gpioDelay(DEBOUNCE_DELAY * 1000);
            }
        }

        gpioDelay(10000); // Sleep for 10 milliseconds
    }

    return 0;
}

