#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define VALVE_GPIO 27
#define PULSES_PER_LITER 450.0
#define SAMPLE_INTERVAL_SEC 1
#define DEBOUNCE_TIMEOUT_MS 100
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define LOG_FILE "water_flow.log"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulses);
void control_valve(double lpm);
void log_data(double lpm, int valve_state);
void signal_handler(int signal);

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIMEOUT_MS * 1000) { // Convert ms to microseconds
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = current_tick;
    }
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_valve(double lpm) {
    int valve_state = gpioRead(VALVE_GPIO);
    if (lpm > LPM_THRESHOLD_HIGH && valve_state == PI_HIGH) {
        gpioWrite(VALVE_GPIO, PI_LOW); // Close the valve
        log_data(lpm, PI_LOW);
    } else if (lpm < LPM_THRESHOLD_LOW && valve_state == PI_LOW) {
        gpioWrite(VALVE_GPIO, PI_HIGH); // Open the valve
        log_data(lpm, PI_HIGH);
    }
}

// Function to log data to a file
void log_data(double lpm, int valve_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Valve: %s\n", timestamp, lpm, valve_state == PI_HIGH ? "Open" : "Closed");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Close the valve
    gpioWrite(VALVE_GPIO, PI_HIGH);

    // Log the event
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, System shutdown.\n", timestamp);
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(current_pulse_count);
        control_valve(lpm);

        printf("LPM: %.2f\n", lpm);
    }

    return 0;
}

