#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <cjson/cJSON.h>
#include <errno.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_TARGET_WEIGHT 0.0
#define DEFAULT_ACTUAL_WEIGHT 0.0
#define DEFAULT_ERROR_MESSAGE "NONE"
#define DEFAULT_PULSE_WIDTH 1500
#define DEFAULT_SERVO_GPIO 18
#define DEFAULT_HX711_DATA_GPIO 23
#define DEFAULT_HX711_SCK_GPIO 24
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define TIMEOUT_ATTEMPTS 1000
#define TIMEOUT_US 10000 // 10ms

// Global variables
static volatile int running = 1;
static int servo_gpio = DEFAULT_SERVO_GPIO;
static int hx711_data_gpio = DEFAULT_HX711_DATA_GPIO;
static int hx711_sck_gpio = DEFAULT_HX711_SCK_GPIO;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int socket_fd = -1;

// Function prototypes
void signal_handler(int signal);
int load_config();
int read_hx711();
void set_servo_pulse_width(int pulse_width);
cJSON *create_json_log(double target_weight, double actual_weight, const char *error_message);
int write_log(cJSON *json_log);
int send_data(int client_socket, const char *data);
int receive_data(int client_socket, char *buffer, size_t buffer_size);
int handle_client(int client_socket);
int start_server();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Load configuration from file
int load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "servo_gpio") == 0) {
                servo_gpio = atoi(value);
            } else if (strcmp(key, "hx711_data_gpio") == 0) {
                hx711_data_gpio = atoi(value);
            } else if (strcmp(key, "hx711_sck_gpio") == 0) {
                hx711_sck_gpio = atoi(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            }
        }
    }

    fclose(fp);
    printf("Configuration loaded: calibration_factor=%.2f, servo_gpio=%d, hx711_data_gpio=%d, hx711_sck_gpio=%d, server_ip=%s, server_port=%d\n",
           calibration_factor, servo_gpio, hx711_data_gpio, hx711_sck_gpio, server_ip, server_port);
    return 0;
}

// Read from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(hx711_data_gpio, PI_INPUT);
    gpioSetMode(hx711_sck_gpio, PI_OUTPUT);

    // Wait for DATA pin to go low
    int timeout = 0;
    while (gpioRead(hx711_data_gpio) == 1 && timeout < TIMEOUT_ATTEMPTS) {
        gpioDelay(1); // 1 us delay
        timeout++;
    }

    if (timeout >= TIMEOUT_ATTEMPTS) {
        fprintf(stderr, "HX711 timeout waiting for data\n");
        return -1; // Timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(hx711_sck_gpio, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(hx711_data_gpio)) {
            data++;
        }
        gpioWrite(hx711_sck_gpio, 0);
        gpioDelay(1); // 1 us delay
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(hx711_sck_gpio, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(hx711_sck_gpio, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(servo_gpio, pulse_width);
}

// Create JSON log
cJSON *create_json_log(double target_weight, double actual_weight, const char *error_message) {
    cJSON *json_log = cJSON_CreateObject();
    cJSON_AddNumberToObject(json_log, "target_weight", target_weight);
    cJSON_AddNumberToObject(json_log, "actual_weight", actual_weight);
    cJSON_AddStringToObject(json_log, "error_message", error_message);
    return json_log;
}

// Write log to file
int write_log(cJSON *json_log) {
    FILE *fp = fopen("dispensing_log.json", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    char *json_str = cJSON_Print(json_log);
    if (json_str == NULL) {
        fprintf(stderr, "Error printing JSON\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s\n", json_str);
    free(json_str);
    fclose(fp);
    return 0;
}

// Send data to client
int send_data(int client_socket, const char *data) {
    ssize_t bytes_sent = send(client_socket, data, strlen(data), 0);
    if (bytes_sent == -1) {
        perror("Error sending data");
        return -1;
    }
    return 0;
}

// Receive data from client
int receive_data(int client_socket, char *buffer, size_t buffer_size) {
    ssize_t bytes_received = recv(client_socket, buffer, buffer_size - 1, 0);
    if (bytes_received == -1) {
        perror("Error receiving data");
        return -1;
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
        return 0;
    }
    buffer[bytes_received] = '\0';
    return bytes_received;
}

// Handle client connection
int handle_client(int client_socket) {
    char buffer[1024];
    int bytes_received;
    double target_weight;
    int pulse_width;
    int raw_weight;
    double actual_weight;
    cJSON *json_log;

    while (running) {
        memset(buffer, 0, sizeof(buffer));
        bytes_received = receive_data(client_socket, buffer, sizeof(buffer));
        if (bytes_received <= 0) {
            break;
        }

        // Parse target weight
        if (sscanf(buffer, "%lf", &target_weight) != 1) {
            fprintf(stderr, "Invalid target weight received: %s\n", buffer);
            send_data(client_socket, "Invalid target weight\n");
            continue;
        }

        // Calculate pulse width
        pulse_width = (int)(((target_weight / calibration_factor) - 1000) / (2000 - 1000) * (2000 - 1000) + 1000);
        if (pulse_width < 1000) pulse_width = 1000;
        if (pulse_width > 2000) pulse_width = 2000;

        // Set servo pulse width
        set_servo_pulse_width(pulse_width);

        // Wait for load cell to stabilize
        gpioDelay(1000); // 1 second

        // Read actual weight
        raw_weight = read_hx711();
        if (raw_weight == -1) {
            actual_weight = DEFAULT_ACTUAL_WEIGHT;
            json_log = create_json_log(target_weight, actual_weight, "HX711 timeout");
            write_log(json_log);
            cJSON_Delete(json_log);
            send_data(client_socket, "HX711 timeout\n");
            continue;
        }

        actual_weight = (double)raw_weight / calibration_factor;

        // Create JSON log
        json_log = create_json_log(target_weight, actual_weight, DEFAULT_ERROR_MESSAGE);

        // Write log to file
        if (write_log(json_log) != 0) {
            fprintf(stderr, "Error writing log\n");
        }
        cJSON_Delete(json_log);

        // Send actual weight back to client
        char response[50];
        snprintf(response, sizeof(response), "%.2f\n", actual_weight);
        send_data(client_socket, response);
    }

    close(client_socket);
    return 0;
}

// Start server
int start_server() {
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);
    int client_socket;

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error creating socket");
        return -1;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(server_ip);
    server_address.sin_port = htons(server_port);

    // Bind socket to address
    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) == -1) {
        perror("Error binding socket");
        close(socket_fd);
        return -1;
    }

    // Listen for connections
    if (listen(socket_fd, 5) == -1) {
        perror("Error listening on socket");
        close(socket_fd);
        return -1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    while (running) {
        // Accept connection
        client_socket = accept(socket_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket == -1) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Client connected\n");

        // Handle client connection
        handle_client(client_socket);

        printf("Client disconnected\n");
    }

    close(socket_fd);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Load configuration
    if (load_config() != 0) {
        fprintf(stderr, "Failed to load configuration, using defaults\n");
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start server
    if (start_server() != 0) {
        fprintf(stderr, "Server failed to start\n");
        gpioTerminate();
        return 1;
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting\n");
    return 0;
}

