#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

static volatile int running = 1;
static int debounce_interval_ms = 50;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor()
{
    return gpioRead(TOUCH_SENSOR_GPIO);
}

// Function to toggle the relay state
void toggle_relay()
{
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
}

// Function to log the relay state to the console
void log_relay_state(int state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1)
    {
        printf("%s Relay: ON\n", timestamp);
    }
    else
    {
        printf("%s Relay: OFF\n", timestamp);
    }
}

// Function to handle the touch event
void handle_touch_event()
{
    toggle_relay();
    int current_relay_state = gpioRead(RELAY_GPIO);
    log_relay_state(current_relay_state);
}

// Function to debounce the touch sensor
void debounce_touch_sensor()
{
    gpioDelay(debounce_interval_ms * 1000); // Convert ms to microseconds
}

int main(int argc, char *argv[])
{
    // Parse command-line arguments
    if (argc > 1 && strcmp(argv[1], "-d") == 0)
    {
        if (argc > 2)
        {
            debounce_interval_ms = atoi(argv[2]);
            if (debounce_interval_ms <= 0)
            {
                fprintf(stderr, "Invalid debounce interval. Using default value of 50ms.\n");
                debounce_interval_ms = 50;
            }
        }
        else
        {
            fprintf(stderr, "Usage: %s -d <debounce_interval_ms>\n", argv[0]);
            return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    printf("Touch sensor monitoring started. Debounce interval: %dms\n", debounce_interval_ms);

    // Main loop
    while (running)
    {
        if (read_touch_sensor() == 0) // Rising edge detected (LOW to HIGH)
        {
            handle_touch_event();
            debounce_touch_sensor();
        }
        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Turn off relay before exiting
    gpioTerminate();

    printf("Touch sensor monitoring stopped.\n");

    return 0;
}

