#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define INCREMENT_ANGLE 10
#define INCREMENT_PULSE_WIDTH 100

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d-%d)\n", MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d-%d)\n", MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }

    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width\n");
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int angle = 90;
    struct termios term;
    tcgetattr(STDIN_FILENO, &term);
    term.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &term);

    printf("Servo control. Angle: %d. Press +/- to adjust, 'q' to quit.\n", angle);

    while (!terminate) {
        char c = getchar();

        if (c == '+') {
            angle += INCREMENT_ANGLE;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
        } else if (c == '-') {
            angle -= INCREMENT_ANGLE;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
        } else if (c == 'q') {
            break;
        }

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
            break;
        }

        printf("Servo angle: %d\n", angle);
    }

    gpioServo(SERVO_PIN, 0); // Stop servo pulses
    gpioTerminate();

    tcsetattr(STDIN_FILENO, TCSANOW, &term);

    printf("Program terminated.\n");
    return 0;
}

