#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define RPM_INTERVAL_SEC 5

static volatile int running = 1;
static FILE *log_file = NULL;
static struct timespec last_pulse_time;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to open the log file
int open_log_file() {
    log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }
    return 0;
}

// Function to close the log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Function to terminate GPIO
void terminate_gpio() {
    gpioTerminate();
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", &tm_info);
    char milliseconds[5];
    snprintf(milliseconds, 5, ".%03ldZ", ts.tv_nsec / 1000000);
    strcat(timestamp, milliseconds);
}

// Function to calculate RPM
double calculate_rpm(struct timespec start_time, struct timespec end_time) {
    double time_diff_sec = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
    if (time_diff_sec == 0) return 0.0; // Avoid division by zero
    return 60.0 / time_diff_sec;
}

// Function to write RPM data to log file
void write_rpm_to_log(const char *timestamp, double rpm) {
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
        fflush(log_file);
    }
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Callback function for GPIO interrupt
void pulse_callback(int gpio, int level, uint32_t tick) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Debounce
    if (current_time.tv_sec - last_pulse_time.tv_sec < DEBOUNCE_MS / 1000) {
        if (current_time.tv_nsec - last_pulse_time.tv_nsec < 1000000 * DEBOUNCE_MS) {
            return; // Ignore the pulse
        }
    }

    last_pulse_time = current_time;

    // Calculate RPM
    static struct timespec start_time = {0, 0};
    static int pulse_count = 0;
    static double rpm = 0.0;

    pulse_count++;

    if (pulse_count == 1) {
        start_time = current_time;
    } else if (pulse_count == 2) {
        rpm = calculate_rpm(start_time, current_time);
        start_time = current_time;
        pulse_count = 0;

        // Get timestamp
        char timestamp[30];
        get_iso8601_timestamp(timestamp);

        // Write to log file
        write_rpm_to_log(timestamp, rpm);

        // Print to stdout
        print_rpm(rpm);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        terminate_gpio();
        return 1;
    }

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        close_log_file();
        terminate_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        gpioDelay(RPM_INTERVAL_SEC * 1000000); // Sleep for RPM_INTERVAL_SEC seconds
    }

    // Cleanup
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    close_log_file();
    terminate_gpio();

    return 0;
}

