#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int relay_state = 0; // 0 = OFF, 1 = ON
    int touch_state = 0;
    int last_touch_state = 0;
    unsigned int last_touch_time = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_GPIO, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (touch_state == 1) {
            if (last_touch_state == 0) {
                // Rising edge detected
                relay_state = !relay_state; // Toggle relay state
                gpioWrite(RELAY_GPIO, relay_state);
                last_touch_time = gpioTick();
                fprintf(stderr, "Rising edge detected, toggling relay to %d\n", relay_state);
            }
            last_touch_state = 1;
        } else {
            last_touch_state = 0;
        }

        if (touch_state == 1 && (gpioTick() - last_touch_time) > 10000000) {
            // Touch sensor held HIGH for more than 10 seconds
            fprintf(stderr, "Touch sensor held HIGH for more than 10 seconds, forcing relay OFF\n");
            relay_state = 0;
            gpioWrite(RELAY_GPIO, relay_state);
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up and exiting...\n");
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    gpioTerminate();

    return 0;
}

