#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18  // BCM GPIO 18
#define VALVE_DIR_PIN 23  // BCM GPIO 23
#define FLOW_SENSOR_PIN 24 // BCM GPIO 24

// Define PWM frequency and range
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255       // 0-255

// Define target flow rate command-line argument
#define TARGET_FLOW_ARG "-t"

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void valve_control(double flow_rate);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Structure to hold program state
typedef struct {
    int running;
} ProgramState;

ProgramState state = {1}; // Initialize running to 1

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        fprintf(stderr, "Error: Invalid target flow rate. Usage: %s -t <flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (state.running) {
        // Read flow rate (simulated)
        double flow_rate = (double)pulse_count * 0.01; // L/min per pulse
        pulse_count = 0; // Reset pulse count for the next interval

        // Valve control
        valve_control(flow_rate);

        // Log data
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f,%d\n", now, flow_rate, gpioGetPWMdutycycle(VALVE_PWM_PIN));
        fflush(log_file);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioPWM(VALVE_PWM_PIN, 0); // Stop PWM
    gpioWrite(VALVE_DIR_PIN, 0); // Disable valve
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_DIR_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE);

    // Enable valve
    gpioWrite(VALVE_DIR_PIN, 1);

    // Register interrupt handler
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Valve control function
void valve_control(double flow_rate) {
    // Proportional control
    double error = target_flow_rate - flow_rate;
    double duty_cycle = error * 1.0; // Kp = 1.0

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    // Set PWM duty cycle
    gpioPWM(VALVE_PWM_PIN, (int)duty_cycle);
}

// Flow sensor interrupt service routine
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    state.running = 0; // Set running to 0 to exit the main loop
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    if (argc != 3) {
        return 1; // Invalid number of arguments
    }

    if (strcmp(argv[1], TARGET_FLOW_ARG) != 0) {
        return 1; // Invalid argument
    }

    char *endptr;
    target_flow_rate = strtod(argv[2], &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0) {
        return 1; // Invalid flow rate
    }

    return 0; // Success
}

