#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_BAUD 100000
#define VALID_TAG_VALUE 0x123456789ABC
#define DEBOUNCE_DELAY_MS 50
#define LOCK_DELAY_SEC 5
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid_tag();
int validate_tag(int tag);
int control_locks(int lock1_state, int lock2_state);
int log_event(const char *event_type);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid_tag() {
    char tx_buf[10] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    char rx_buf[10];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 10);

    if (result != 0) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        log_event("RFID Read Failure");
        return -1; // Indicate failure
    }

    // Convert received bytes to an integer
    int tag = 0;
    for (int i = 0; i < 10; i++) {
        tag = (tag << 8) | rx_buf[i];
    }

    return tag;
}

// Function to validate the RFID tag
int validate_tag(int tag) {
    if (tag == VALID_TAG_VALUE) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Function to control the door locks
int control_locks(int lock1_state, int lock2_state) {
    gpioWrite(LOCK1_GPIO, lock1_state);
    gpioWrite(LOCK2_GPIO, lock2_state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize locks to engaged state
    control_locks(1, 1);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int button_pressed = 0;
    int button_state;

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read RFID tag
        int tag = read_rfid_tag();

        // Validate tag
        int valid = (tag != -1) && validate_tag(tag);

        // Read button state
        button_state = gpioRead(BUTTON_GPIO);

        if (button_state == 0) { // Button is pressed (active low)
            if (!button_pressed) {
                button_pressed = 1;
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
            }
        } else {
            button_pressed = 0;
        }

        if (valid && button_pressed) {
            // Disengage locks
            control_locks(0, 0);
            log_event("Lock Disengaged");
            gpioDelay(LOCK_DELAY_SEC * 1000000); // 5 seconds

            // Re-engage locks
            control_locks(1, 1);
            log_event("Lock Re-engaged");
            button_pressed = 0; // Reset button press flag
        } else if (valid) {
            log_event("Valid Tag Read");
        } else if (button_pressed) {
            log_event("Button Pressed Without Valid Tag");
        } else if (tag == -1) {
            log_event("RFID Read Failure");
        } else {
            log_event("Invalid Tag Read");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_locks(1, 1); // Ensure locks are engaged on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

