#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoders
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPM
#define TARGET_RPM 60.0

// PWM Frequency
#define PWM_FREQUENCY 100

// PID Sample Time (ms)
#define PID_SAMPLE_TIME 100

// Global Variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

FILE *log_file = NULL;

// Function Prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
double calculate_rpm(int encoder_count, double time_interval);
double pid_control(double setpoint, double actual_rpm, double *integral, double *previous_error);
void set_motor_speed(int motor, double duty_cycle);
void log_data(double motor1_rpm, double motor2_rpm, double p, double i, double d, double pid_output);
void signal_handler(int signal);

// Encoder 1 Thread
void *encoder1_thread(void *arg) {
    int last_state = 0;
    int current_state = 0;

    while (1) {
        current_state = gpioRead(ENCODER1_B);

        if (current_state != last_state) {
            if (gpioRead(ENCODER1_A) == current_state) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count++;
                pthread_mutex_unlock(&encoder1_mutex);
            } else {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count--;
                pthread_mutex_unlock(&encoder1_mutex);
            }
            last_state = current_state;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

// Encoder 2 Thread
void *encoder2_thread(void *arg) {
    int last_state = 0;
    int current_state = 0;

    while (1) {
        current_state = gpioRead(ENCODER2_B);

        if (current_state != last_state) {
            if (gpioRead(ENCODER2_A) == current_state) {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count++;
                pthread_mutex_unlock(&encoder2_mutex);
            } else {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count--;
                pthread_mutex_unlock(&encoder2_mutex);
            }
            last_state = current_state;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

// Calculate RPM
double calculate_rpm(int encoder_count, double time_interval) {
    return (double)encoder_count / (time_interval / 60.0);
}

// PID Control
double pid_control(double setpoint, double actual_rpm, double *integral, double *previous_error) {
    double error = setpoint - actual_rpm;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Set Motor Speed
void set_motor_speed(int motor, double duty_cycle) {
    int ena_pin, in1_pin, in2_pin;

    if (motor == 1) {
        ena_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else {
        ena_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    }

    if (duty_cycle > 0) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
    } else if (duty_cycle < 0) {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
        duty_cycle = -duty_cycle; // Make duty cycle positive for PWM
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
    }

    gpioPWM(ena_pin, (int)(duty_cycle * 255.0)); // pigpio PWM range is 0-255
}

// Log Data
void log_data(double motor1_rpm, double motor2_rpm, double p, double i, double d, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, motor1_rpm, motor2_rpm, p, i, d, pid_output);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);

    // Stop Motors
    set_motor_speed(1, 0.0);
    set_motor_speed(2, 0.0);

    // Close Log File
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO Lines
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENA, 255);
    gpioSetPWMrange(MOTOR2_ENB, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(MOTOR1_ENA, 0);
    gpioPWM(MOTOR2_ENB, 0);

    // Open Log File
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P,I,D,PID_Output\n");
    }

    // Create threads
    pthread_t encoder1_thread_id, encoder2_thread_id;
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID Variables
    double integral1 = 0.0, previous_error1 = 0.0;
    double integral2 = 0.0, previous_error2 = 0.0;
    double motor1_rpm, motor2_rpm, p1, i1, d1, pid_output1;
    double p2, i2, d2, pid_output2;

    // Main Loop
    while (1) {
        // Read Encoder Counts
        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_count_local = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_count_local = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        motor1_rpm = calculate_rpm(encoder1_count_local, (double)PID_SAMPLE_TIME / 1000.0);
        motor2_rpm = calculate_rpm(encoder2_count_local, (double)PID_SAMPLE_TIME / 1000.0);

        // PID Control
        p1 = KP * (TARGET_RPM - motor1_rpm);
        i1 = KI * (TARGET_RPM - motor1_rpm);
        d1 = KD * (TARGET_RPM - motor1_rpm);
        pid_output1 = pid_control(TARGET_RPM, motor1_rpm, &integral1, &previous_error1);

        p2 = KP * (TARGET_RPM - motor2_rpm);
        i2 = KI * (TARGET_RPM - motor2_rpm);
        d2 = KD * (TARGET_RPM - motor2_rpm);
        pid_output2 = pid_control(TARGET_RPM, motor2_rpm, &integral2, &previous_error2);

        // Set Motor Speeds
        set_motor_speed(1, pid_output1);
        set_motor_speed(2, pid_output2);

        // Log Data
        log_data(motor1_rpm, motor2_rpm, p1, i1, d1, pid_output1);

        // Delay
        gpioDelay(PID_SAMPLE_TIME);
    }

    return 0;
}

