#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

// Function to initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) { // Enable all 12 electrodes
        fprintf(stderr, "Error: Electrode config failed\n");
        return -1;
    }

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTERING, 0x01) < 0) {
        fprintf(stderr, "Error: Baseline filtering config failed\n");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Touch threshold config failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Release threshold config failed for electrode %d\n", i);
            return -1;
        }
