            if (touch_status > 0) {
                if (!relay_state) {
                    gpio_control(1); // Turn relay ON
                    log_relay_state(1);
                    relay_state = 1;
                }
            } else {
                if (relay_state) {
                    gpio_control(0); // Turn relay OFF
                    log_relay_state(0);
                    relay_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50); // Delay 50ms
    }

    // Cleanup
    gpio_control(0); // Turn relay OFF
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

