// Define GPIO pins for the solenoid valves
#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int open_valve(int gpio_pin);
int close_valve(int gpio_pin);
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(VALVE_1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE_2_GPIO, PI_OUTPUT);

    // Ensure valves are initially closed
    close_valve(VALVE_1_GPIO);
    close_valve(VALVE_2_GPIO);

    return 0;
}

// Function to open a solenoid valve
int open_valve(int gpio_pin) {
    if (gpio_pin != VALVE_1_GPIO && gpio_pin != VALVE_2_GPIO) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to open valve on GPIO %d\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to close a solenoid valve
int close_valve(int gpio_pin) {
    if (gpio_pin != VALVE_1_GPIO && gpio_pin != VALVE_2_GPIO) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to close valve on GPIO %d\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Close valves
    close_valve(VALVE_1_GPIO);
    close_valve(VALVE_2_GPIO);

    // Terminate pigpio
    gpioTerminate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Valve 1: Open for 500ms
        if (open_valve(VALVE_1_GPIO) == 0) {
            log_event("Valve 1 opened");
            gpioDelay(500); // Delay for 500ms
            close_valve(VALVE_1_GPIO);
            log_event("Valve 1 closed");
        } else {
            log_event("Error opening Valve 1");
        }

        // Pause for 5 seconds
        gpioDelay(5000); // Delay for 5000ms (5 seconds)

        // Valve 2: Open for 1000ms
        if (open_valve(VALVE_2_GPIO) == 0) {
            log_event("Valve 2 opened");
            gpioDelay(1000); // Delay for 1000ms
            close_valve(VALVE_2_GPIO);
            log_event("Valve 2 closed");
        } else {
            log_event("Error opening Valve 2");
        }

        // Pause for 10 seconds
        gpioDelay(10000); // Delay for 10000ms (10 seconds)
    }

    return 0;
}

