#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// GPIO pin for relay control
#define RELAY_GPIO 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
int mpr121_write_register(uint8_t reg, uint8_t value);
int mpr121_read_register(uint8_t reg, uint8_t *value);
void relay_on();
void relay_off();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (mpr121_write_register(MPR121_ECR, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode.\n");
        return -1;
    }

    // Configure touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(0x41 + 2 * i, 0x30) != 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (mpr121_write_register(0x42 + 2 * i, 0x10) != 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (mpr121_write_register(MPR121_CONFIG1, 0x10) != 0) { // Filter config
        fprintf(stderr, "Error: Failed to set filter config.\n");
        return -1;
    }
    if (mpr121_write_register(MPR121_CONFIG2, 0x20) != 0) { // Charge time config
        fprintf(stderr, "Error: Failed to set charge time config.\n");
        return -1;
    }

    // Set electrode current
    if (mpr121_write_register(MPR121_ECR, 0x10) != 0) { // Enable electrode 0
        fprintf(stderr, "Error: Failed to set electrode current.\n");
        return -1;
    }

    // Start mode
    if (mpr121_write_register(MPR121_ECR, 0x1F) != 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to set MPR121 to run mode.\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    uint8_t data[2];

    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    *touch_status = ((uint16_t)data[1] << 8) | data[0];
    return 0;
}

// Function to write a register in the MPR121
int mpr121_write_register(uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (i2cWriteI2CBlockData(i2c_handle, reg, buf + 1, 1) != 1) {
        fprintf(stderr, "Error: Failed to write to register 0x%02X.\n", reg);
        return -1;
    }

    return 0;
}

// Function to read a register from the MPR121
int mpr121_read_register(uint8_t reg, uint8_t *value) {
    if (i2cReadI2CBlockData(i2c_handle, reg, (char *)value, 1) != 1) {
        fprintf(stderr, "Error: Failed to read from register 0x%02X.\n", reg);
        return -1;
    }

    return 0;
}

// Function to turn the relay on
void relay_on() {
    gpioWrite(RELAY_GPIO, 1); // Set GPIO HIGH
    printf("Relay ON\n");
}

// Function to turn the relay off
void relay_off() {
    gpioWrite(RELAY_GPIO, 0); // Set GPIO LOW
    printf("Relay OFF\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
