#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define DOOR_RELAY 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_SECONDS 2
#define POLLING_INTERVAL_MS 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor(int gpio_pin);
int control_relay(int gpio_pin, int state);
int log_event(const char *event_type, int gpio_pin);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    time_t last_motion_time;
} sensor_data_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);

    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);

    gpioSetMode(DOOR_RELAY, PI_OUTPUT);
    gpioWrite(DOOR_RELAY, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value
int read_pir_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Control the relay
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Log events to file
int log_event(const char *event_type, int gpio_pin) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - GPIO %d - %s\n", buf, gpio_pin, event_type);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize sensor data
    sensor_data_t sensor1_data = {PIR_SENSOR_1, 0};
    sensor_data_t sensor2_data = {PIR_SENSOR_2, 0};

    // Main loop
    while (program_running) {
        // Read PIR sensors
        int sensor1_value = read_pir_sensor(PIR_SENSOR_1);
        int sensor2_value = read_pir_sensor(PIR_SENSOR_2);

        // Check for motion and rate limit
        time_t now = time(NULL);

        if (sensor1_value == 1 && difftime(now, sensor1_data.last_motion_time) >= RATE_LIMIT_SECONDS) {
            printf("Motion detected by sensor 1\n");
            log_event("Motion Detected", PIR_SENSOR_1);
            control_relay(DOOR_RELAY, 1); // Activate relay
            gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
            control_relay(DOOR_RELAY, 0); // Deactivate relay
            log_event("Door Unlocked", PIR_SENSOR_1);
            sensor1_data.last_motion_time = now;
        }

        if (sensor2_value == 1 && difftime(now, sensor2_data.last_motion_time) >= RATE_LIMIT_SECONDS) {
            printf("Motion detected by sensor 2\n");
            log_event("Motion Detected", PIR_SENSOR_2);
            control_relay(DOOR_RELAY, 1); // Activate relay
            gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
            control_relay(DOOR_RELAY, 0); // Deactivate relay
            log_event("Door Unlocked", PIR_SENSOR_2);
            sensor2_data.last_motion_time = now;
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioWrite(DOOR_RELAY, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

