#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_READINGS 100
#define TIMEOUT_MS 500

// Global variables
static volatile int running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double scale_factor, double offset);
void control_solenoid(double weight, double threshold);
void log_weight(int raw_value, double weight);
void calibrate_offset();
void load_calibration();
void save_calibration();
void signal_handler(int signal);

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_MS) {
        gpioDelay(1); // Wait 1ms
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout reading HX711\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Short delay
    }

    // Pulse the clock pin 25th time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Weight calculation function
double calculate_weight(int raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Solenoid control function
void control_solenoid(double weight, double threshold) {
    if (weight > threshold) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // De-activate solenoid
    }
}

// Logging function
void log_weight(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, raw_value, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Offset calibration function
void calibrate_offset() {
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading during offset calibration, skipping.\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    offset = sum / CALIBRATION_READINGS;
    printf("Calibrated offset: %.2f\n", offset);
}

// Load calibration data from file
void load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found, using default values.\n");
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Invalid calibration file format, using default values.\n");
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Loaded calibration: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
}

// Save calibration data to file
void save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return;
    }

    fprintf(fp, "%.2f %.2f", scale_factor, offset);
    fclose(fp);
    printf("Saved calibration: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Load calibration data
    load_calibration();

    // Calibrate offset
    calibrate_offset();

    // Save calibration data
    save_calibration();

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value, scale_factor, offset);
            control_solenoid(weight, WEIGHT_THRESHOLD);
            log_weight(raw_value, weight);
        }
        gpioDelay(500); // Delay 500ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // De-activate solenoid
    fclose(log_file);
    gpioTerminate();

    return 0;
}

