#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Define check interval (seconds)
#define CHECK_INTERVAL 60

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, stopping motor and exiting...");
        control_motor(0); // Stop the motor
        gpioTerminate();   // Terminate pigpio
        closelog();        // Close syslog
        exit(0);
    }
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[5];
    int i;

    for (i = 0; i < 5; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }

    // Check if at least three readings are LOW
    int low_count = 0;
    for (i = 0; i < 5; i++) {
        if (readings[i] == 0) {
            low_count++;
        }
    }

    if (low_count >= 3) {
        return 0; // Rain detected
    } else {
        return 1; // No rain detected
    }
}

// Function to control the motor
void control_motor(int state) {
    if (state == 1) {
        // Close the window
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
        log_event("Motor started to close window");
    } else {
        // Stop the motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Motor stopped");
    }
}

