#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define DT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 17

// Define constants
#define WEIGHT_THRESHOLD 100.0  // g
#define SOLENOID_DURATION 5      // seconds
#define LOG_FILE "stock_events.txt"
#define SCALE_FACTOR 100.0      // Adjust this value based on your load cell
#define OFFSET 0.0              // Adjust this value based on your load cell

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_hx711();
float convert_to_weight(int raw_value);
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    // Wait for DT to go low
    while (gpioRead(DT_PIN) == 1 && timeout_counter < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= 1000) {
        log_event("HX711 read timeout");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(DT_PIN)) {
            data++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK 25th time to set the HX711 for the next reading
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert 24-bit two's complement to signed integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw HX711 value to weight in grams
float convert_to_weight(int raw_value) {
    return (float)(raw_value - OFFSET) / SCALE_FACTOR;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    log_event("Solenoid activated");
    gpioDelay(SOLENOID_DURATION * 1000); // Wait for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    log_event("Solenoid deactivated");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (!terminate) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            float weight = convert_to_weight(raw_value);
            char weight_str[50];
            snprintf(weight_str, sizeof(weight_str), "Weight: %.2f g", weight);
            log_event(weight_str);

            if (weight < WEIGHT_THRESHOLD) {
                activate_solenoid();
            }
        } else {
            log_event("Error reading HX711");
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup
    log_event("Program terminated");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

