#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define log file name
#define LOG_FILE "security.log"

// Define timeout threshold (in milliseconds)
#define TIMEOUT_THRESHOLD 100

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 5.0

// Define solenoid activation time (in seconds)
#define SOLENOID_ACTIVATION_TIME 5

// Global variables
static volatile int running = 1;
static double calibration_factor = 0.0;
static FILE *calibration_file = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double calibrate_weight(int raw_value);
void activate_solenoid();
void log_event(double weight);
void signal_handler(int signal);
int load_calibration_factor();
int save_calibration_factor();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, unlocking solenoid and exiting...\n");
        running = 0;
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        gpioTerminate(); // Terminate pigpio
        if (calibration_file != NULL) fclose(calibration_file);
        if (log_file != NULL) fclose(log_file);
        exit(0);
    }
}

// Function to read raw data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Wait 1 ms
        timeout_counter++;
        if (timeout_counter > TIMEOUT_THRESHOLD) {
            fprintf(stderr, "HX711 timeout error!\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Delay 1 us
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Delay 1 us
    }

    // Pulse the clock pin 25th time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Delay 1 us
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Delay 1 us

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

