double calibrate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to activate the solenoid
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set GPIO high
    gpioDelay(SOLENOID_ACTIVATION_TIME * 1000); // Delay for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Set GPIO low
}

// Function to log events
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Function to load the calibration factor from file
int load_calibration_factor() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file!\n");
        return -1;
    }

    if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from file!\n");
        fclose(calibration_file);
        return -1;
    }

    fclose(calibration_file);
    return 0;
}

// Function to save the calibration factor to file
int save_calibration_factor() {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file for writing!\n");
        return -1;
    }

    fprintf(calibration_file, "%lf", calibration_factor);
    fclose(calibration_file);
    return 0;
}

int main() {
    int raw_value;
    double weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed!\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Load calibration factor
    if (load_calibration_factor() != 0) {
        printf("Calibration factor not found. Please calibrate the system.\n");

        // Prompt user for calibration
        printf("Place a known weight on the load cell and enter the weight in kg: ");
        if (scanf("%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Invalid input for calibration factor!\n");
            gpioTerminate();
            return 1;
        }

        // Save calibration factor to file
        if (save_calibration_factor() != 0) {
            fprintf(stderr, "Error saving calibration factor!\n");
            gpioTerminate();
            return 1;
        }

        printf("Calibration factor saved to %s\n", CALIBRATION_FILE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("System initialized. Monitoring weight...\n");

    // Main loop
    while (running) {
        raw_value = read_hx711();
        if (raw_value != -1) {
            weight = calibrate_weight(raw_value);
            printf("Raw: %d, Weight: %.2f kg\n", raw_value, weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded! Activating solenoid.\n");
                activate_solenoid();
                log_event(weight);
            }
        } else {
            fprintf(stderr, "Error reading from HX711!\n");
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    gpioTerminate(); // Terminate pigpio
    fclose(log_file);

    return 0;
}

