#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define VALVE_GPIO 18
#define CONFIG_FILE "watering.conf"
#define LOG_FILE "watering.log"

volatile sig_atomic_t terminate = 0;

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from configuration file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid format in configuration file %s\n", filename);
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid format in configuration file %s\n", filename);
        return -1;
    }

    char *endptr;
    long val = strtol(token, &endptr, 10);

    if (*endptr != '\0' || val < 1 || val > 3600) {
        fprintf(stderr, "Error: Invalid duration value in configuration file %s\n", filename);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    log_event("Received shutdown signal");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO18 as an output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set initial valve state to off
    gpioWrite(VALVE_GPIO, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int duration;

    // Read watering duration from configuration file
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Error: Failed to read watering duration\n");
        log_event("Failed to read watering duration");
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);
    log_event("Watering duration read successfully");

    // Main loop
    while (!terminate) {
        // Activate the valve
        gpioWrite(VALVE_GPIO, 1);
        printf("Valve ON\n");
        log_event("Valve ON");

        // Wait for the specified duration
        gpioDelay(duration * 1000); // pigpioDelay takes milliseconds

        // Deactivate the valve
        gpioWrite(VALVE_GPIO, 0);
        printf("Valve OFF\n");
        log_event("Valve OFF");

        // Wait for a short period before the next cycle
        gpioDelay(1000); // 1 second
    }

    // Clean up and exit
    gpioWrite(VALVE_GPIO, 0); // Ensure valve is off
    gpioTerminate();
    printf("Exiting cleanly\n");
    log_event("Exiting cleanly");
    return 0;
}

