#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150.0
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    float lux;
    int relay_state;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to read illuminance from BH1750
int read_bh1750(float *lux) {
    char config_mode = 0x10; // Continuous high resolution mode
    char buffer[2];

    if (i2cWriteByte(i2c_handle, config_mode) != 0) {
        fprintf(stderr, "Error writing to I2C\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C\n");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) != 0) {
        fprintf(stderr, "Error writing to GPIO\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float lux;
    int relay_state = 0; // Initially off

    printf("Starting sensor monitoring...\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && !relay_state) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_data(lux, relay_state);
                    printf("Relay ON\n");
                } else {
                    fprintf(stderr, "Error controlling relay (ON)\n");
                }
            } else if (lux >= LUX_THRESHOLD && relay_state) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_data(lux, relay_state);
                    printf("Relay OFF\n");
                } else {
                    fprintf(stderr, "Error controlling relay (OFF)\n");
                }
            }

            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            log_data(-1.0, -1); // Log error
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    fclose(log_file);
    gpioTerminate();

    return 0;
}

