#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR_1_GPIO 17
#define MOTOR_2_GPIO 27

// Define pulse durations in milliseconds
#define MOTOR_1_DURATION 200
#define MOTOR_2_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, stopping motors and exiting...\n", signal);
        program_running = 0;
    }
}

// Function to pulse a motor for a given duration
int pulse_motor(int gpio_pin, int duration_ms) {
    if (gpioWrite(gpio_pin, 1) != 0) { // Turn motor on
        fprintf(stderr, "Error: Failed to write 1 to GPIO %d\n", gpio_pin);
        return -1;
    }
    gpioDelay(duration_ms * 1000); // Delay for the specified duration
    if (gpioWrite(gpio_pin, 0) != 0) { // Turn motor off
        fprintf(stderr, "Error: Failed to write 0 to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Pulse Motor 1
        if (pulse_motor(MOTOR_1_GPIO, MOTOR_1_DURATION) != 0) {
            fprintf(stderr, "Error: Failed to pulse Motor 1\n");
            program_running = 0; // Stop the loop on error
        }

        // Pulse Motor 2
        if (pulse_motor(MOTOR_2_GPIO, MOTOR_2_DURATION) != 0) {
            fprintf(stderr, "Error: Failed to pulse Motor 2\n");
            program_running = 0; // Stop the loop on error
        }
    }

    // Stop motors before exiting
    gpioWrite(MOTOR_1_GPIO, 0);
    gpioWrite(MOTOR_2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

