#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <zmq.h>

#define SOUND_SENSOR_MODE "sound_sensor"
#define ALARM_NODE_MODE "alarm_node"
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define ALARM_LED_GPIO 27
#define ZMQ_ENDPOINT "tcp://*:5555"

// Global variables for cleanup
static int running = 1;
static void *zmq_context = NULL;
static void *zmq_publisher = NULL;
static void *zmq_subscriber = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_LED_GPIO, 0); // Ensure LED is off initially
    return 0;
}

// Function to initialize ZeroMQ
int initialize_zmq(const char *mode) {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    if (strcmp(mode, SOUND_SENSOR_MODE) == 0) {
        zmq_publisher = zmq_socket(zmq_context, ZMQ_PUB);
        if (!zmq_publisher) {
            perror("zmq_socket (pub) failed");
            return -1;
        }

        int bind_result = zmq_bind(zmq_publisher, ZMQ_ENDPOINT);
        if (bind_result != 0) {
            perror("zmq_bind failed");
            return -1;
        }
    } else if (strcmp(mode, ALARM_NODE_MODE) == 0) {
        zmq_subscriber = zmq_socket(zmq_context, ZMQ_SUB);
        if (!zmq_subscriber) {
            perror("zmq_socket (sub) failed");
            return -1;
        }

        int connect_result = zmq_connect(zmq_subscriber, ZMQ_ENDPOINT);
        if (connect_result != 0) {
            perror("zmq_connect failed");
            return -1;
        }

        int subscribe_result = zmq_setsockopt(zmq_subscriber, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC));
        if (subscribe_result != 0) {
            perror("zmq_setsockopt (subscribe) failed");
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return -1;
    }

    return 0;
}

// Function to read sound sensor
int read_sound_sensor() {
    return gpioRead(17); // Assuming GPIO17 is connected to the sound sensor
}

// Function to publish sound alert
int publish_sound_alert() {
    char message[50];
    time_t now = time(NULL);
    snprintf(message, sizeof(message), "%s:%ld", SOUND_ALERTS_TOPIC, now);

    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    int send_result = zmq_msg_send(&zmq_message, zmq_publisher, 0);
    zmq_msg_close(&zmq_message);

    if (send_result == -1) {
        perror("zmq_msg_send failed");
        return -1;
    }

    return 0;
}

// Function to receive sound alert
int receive_sound_alert() {
    zmq_msg_t zmq_message;
    zmq_msg_init(&zmq_message);

    int recv_result = zmq_msg_recv(&zmq_message, zmq_subscriber, 0);
    if (recv_result == -1) {
        perror("zmq_msg_recv failed");
        zmq_msg_close(&zmq_message);
        return -1;
    }

    char *message = (char *)zmq_msg_data(&zmq_message);
    size_t message_size = zmq_msg_size(&zmq_message);

    printf("Received message: %s\n", message);

    zmq_msg_close(&zmq_message);
    return 0;
}

// Function to activate alarm
void activate_alarm() {
    gpioWrite(ALARM_LED_GPIO, 1); // Turn on the LED
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALARM_LED_GPIO, 0); // Turn off the LED
}

// Function to cleanup GPIO and ZeroMQ
void cleanup() {
    printf("Cleaning up...\n");

    if (zmq_publisher) {
        zmq_close(zmq_publisher);
    }
    if (zmq_subscriber) {
        zmq_close(zmq_subscriber);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    gpioWrite(ALARM_LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: %s or %s\n", SOUND_SENSOR_MODE, ALARM_NODE_MODE);
        return 1;
    }

    const char *mode = argv[1];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (initialize_zmq(mode) != 0) {
        cleanup();
        return 1;
    }

    if (strcmp(mode, SOUND_SENSOR_MODE) == 0) {
        printf("Running in sound sensor mode\n");
        while (running) {
            if (read_sound_sensor() == 0) {
                printf("Sound detected!\n");
                if (publish_sound_alert() != 0) {
                    fprintf(stderr, "Failed to publish sound alert\n");
                }
            }
            gpioDelay(10); // Check every 10ms
        }
    } else if (strcmp(mode, ALARM_NODE_MODE) == 0) {
        printf("Running in alarm node mode\n");
        while (running) {
            if (receive_sound_alert() == 0) {
                printf("Received sound alert!\n");
                activate_alarm();
            }
            gpioDelay(10); // Check every 10ms
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        cleanup();
        return 1;
    }

    cleanup();
    return 0;
}

