#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x23
#define SENSOR2_ADDR 0x24
#define SENSOR3_ADDR 0x25
#define SENSOR4_ADDR 0x26

// Define I2C device
#define I2C_DEVICE "/dev/i2c-1"

// Define multicast address and port
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

// Define start-measurement command
#define START_MEASUREMENT 0x10

// Define NaN value
#define NAN_VALUE NAN

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
int udp_socket = -1;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

// Function to read lux value from a sensor
float read_sensor(int i2c_fd, int sensor_id, int addr) {
    uint8_t write_buf[1];
    uint8_t read_buf[2];
    int ret;

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address for sensor %d (0x%02x): %s\n", sensor_id, addr, strerror(errno));
        return NAN_VALUE;
    }

    // Send start-measurement command
    write_buf[0] = START_MEASUREMENT;
    ret = write(i2c_fd, write_buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device for sensor %d (0x%02x): %s\n", sensor_id, addr, strerror(errno));
        return NAN_VALUE;
    }

    // Wait for measurement to complete (180ms)
    usleep(180000);

    // Read two bytes of data
    ret = read(i2c_fd, read_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C device for sensor %d (0x%02x): %s\n", sensor_id, addr, strerror(errno));
        return NAN_VALUE;
    }

    // Convert data to lux value
    uint16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to format data into a string
char* format_data(float lux1, float lux2, float lux3, float lux4) {
    static char buffer[256]; // Static buffer to avoid memory allocation issues
    snprintf(buffer, sizeof(buffer), "1,%.2f;2,%.2f;3,%.2f;4,%.2f", lux1, lux2, lux3, lux4);
    return buffer;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char* data) {
    struct sockaddr_in addr;
    int ttl = 1;

    // Create socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s\n", strerror(errno));
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    return 0;
}

int main() {
    float lux1, lux2, lux3, lux4;
    char* data;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        lux1 = read_sensor(i2c_fd, 1, SENSOR1_ADDR);
        lux2 = read_sensor(i2c_fd, 2, SENSOR2_ADDR);
        lux3 = read_sensor(i2c_fd, 3, SENSOR3_ADDR);
        lux4 = read_sensor(i2c_fd, 4, SENSOR4_ADDR);

        // Format data
        data = format_data(lux1, lux2, lux3, lux4);

        // Send data via UDP multicast
        if (send_udp_multicast(data) != 0) {
            fprintf(stderr, "Error sending UDP multicast data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device and UDP socket
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

