#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 register addresses
#define AS7341_ID 0x00
#define AS7341_STATUS 0x73
#define AS7341_F1DATAH 0x96
#define AS7341_F1DATAL 0x97
#define AS7341_F2DATAH 0x98
#define AS7341_F2DATAL 0x99
#define AS7341_F3DATAH 0x9A
#define AS7341_F3DATAL 0x9B
#define AS7341_F4DATAH 0x9C
#define AS7341_F4DATAL 0x9D
#define AS7341_F5DATAH 0x9E
#define AS7341_F5DATAL 0x9F
#define AS7341_F6DATAH 0xA0
#define AS7341_F6DATAL 0xA1
#define AS7341_F7DATAH 0xA2
#define AS7341_F7DATAL 0xA3
#define AS7341_F8DATAH 0xA4
#define AS7341_F8DATAL 0xA5
#define AS7341_CDATAH 0xA6
#define AS7341_CDATAL 0xA7
#define AS7341_NDATAH 0xA8
#define AS7341_NDATAL 0xA9
#define AS7341_ENABLE 0x80
#define AS7341_CFG0 0x81
#define AS7341_CFG1 0x82
#define AS7341_CFG2 0x83
#define AS7341_CFG3 0x84
#define AS7341_CFG4 0x85
#define AS7341_CFG5 0x86
#define AS7341_CFG6 0x87
#define AS7341_CFG7 0x88
#define AS7341_CFG8 0x89
#define AS7341_CFG9 0x8A
#define AS7341_CFG10 0x8B
#define AS7341_CFG11 0x8C
#define AS7341_CFG12 0x8D
#define AS7341_CFG13 0x8E
#define AS7341_CFG14 0x8F
#define AS7341_CFG15 0x90
#define AS7341_CFG16 0x91
#define AS7341_CFG17 0x92
#define AS7341_CFG18 0x93
#define AS7341_CFG19 0x94
#define AS7341_CFG20 0x95

// Expected AS7341 ID
#define AS7341_EXPECTED_ID 0xAB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_as7341();
int read_spectral_data(uint16_t *spectral_data);
float calculate_lux(uint16_t *spectral_data);
int log_data(uint16_t *spectral_data, float lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize AS7341 sensor
int init_as7341() {
    int status;
    uint8_t id;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, AS7341_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading AS7341 ID: %d\n", status);
        return -1;
    }
    id = (uint8_t)status;

    if (id != AS7341_EXPECTED_ID) {
        fprintf(stderr, "Error: Incorrect AS7341 ID (0x%02X, expected 0x%02X)\n", id, AS7341_EXPECTED_ID);
        return -1;
    }

    // Power on the sensor
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); // PON = 1, SP_EN = 1
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    // Configure SMUX (example configuration)
    status = i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x03); // SMUX = 00000011
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG6 register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read spectral data from AS7341
int read_spectral_data(uint16_t *spectral_data) {
    int status;
    uint8_t buffer[2];

    // Read F1-F8 data
    status = i2cReadI2CBlockData(i2c_handle, AS7341_F1DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F1 data: %d\n", status);
        return -1;
    }
    spectral_data[0] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F2DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F2 data: %d\n", status);
        return -1;
    }
    spectral_data[1] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F3DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F3 data: %d\n", status);
        return -1;
    }
    spectral_data[2] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F4DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F4 data: %d\n", status);
        return -1;
    }
    spectral_data[3] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F5DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F5 data: %d\n", status);
        return -1;
    }
    spectral_data[4] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F6DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F6 data: %d\n", status);
        return -1;
    }
    spectral_data[5] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F7DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F7 data: %d\n", status);
        return -1;
    }
    spectral_data[6] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F8DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F8 data: %d\n", status);
        return -1;
    }
    spectral_data[7] = (uint16_t)buffer[1] << 8 | buffer[0];

    // Read Clear and NIR data
    status = i2cReadI2CBlockData(i2c_handle, AS7341_CDATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading Clear data: %d\n", status);
        return -1;
    }
    spectral_data[8] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_NDATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading NIR data: %d\n", status);
        return -1;
    }
    spectral_data[9] = (uint16_t)buffer[1] << 8 | buffer[0];

    return 0;
}

// Calculate lux approximation
float calculate_lux(uint16_t *spectral_data) {
    // Simple approximation based on F1-F8
    float lux = 0.0;
    for (int i = 0; i < 8; i++) {
        lux += spectral_data[i];
    }
    return lux / 8.0;
}

// Log data to CSV file
int log_data(uint16_t *spectral_data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp,
            spectral_data[0],
            spectral_data[1],
            spectral_data[2],
            spectral_data[3],
            spectral_data[4],
            spectral_data[5],
            spectral_data[6],
            spectral_data[7],
            spectral_data[8],
            lux);

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    int status;
    uint16_t spectral_data[10];
    float lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AS7341 sensor
    if (init_as7341() < 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    fflush(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(spectral_data) == 0) {
            // Calculate lux
            lux = calculate_lux(spectral_data);

            // Log data
            log_data(spectral_data, lux);

            printf("F1: %u, F2: %u, F3: %u, F4: %u, F5: %u, F6: %u, F7: %u, F8: %u, Clear: %u, NIR: %u, Lux: %.2f\n",
                   spectral_data[0],
                   spectral_data[1],
                   spectral_data[2],
                   spectral_data[3],
                   spectral_data[4],
                   spectral_data[5],
                   spectral_data[6],
                   spectral_data[7],
                   spectral_data[8],
                   spectral_data[9],
                   lux);
        } else {
            fprintf(stderr, "Error reading spectral data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

