    // Read F1-F8 data
    status = i2cReadI2CBlockData(i2c_handle, AS7341_F1DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F1 data: %d\n", status);
        return -1;
    }
    spectral_data[0] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F2DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F2 data: %d\n", status);
        return -1;
    }
    spectral_data[1] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F3DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F3 data: %d\n", status);
        return -1;
