    spectral_data[2] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F4DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F4 data: %d\n", status);
        return -1;
    }
    spectral_data[3] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F5DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F5 data: %d\n", status);
        return -1;
    }
    spectral_data[4] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F6DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F6 data: %d\n", status);
        return -1;
    }
    spectral_data[5] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F7DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F7 data: %d\n", status);
        return -1;
    }
    spectral_data[6] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_F8DATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading F8 data: %d\n", status);
        return -1;
    }
    spectral_data[7] = (uint16_t)buffer[1] << 8 | buffer[0];

    // Read Clear and NIR data
    status = i2cReadI2CBlockData(i2c_handle, AS7341_CDATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading Clear data: %d\n", status);
        return -1;
    }
    spectral_data[8] = (uint16_t)buffer[1] << 8 | buffer[0];

    status = i2cReadI2CBlockData(i2c_handle, AS7341_NDATAH, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading NIR data: %d\n", status);
        return -1;
    }
    spectral_data[9] = (uint16_t)buffer[1] << 8 | buffer[0];

    return 0;
}

