#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x4C
#define DEFAULT_SAMPLING_INTERVAL 1.0
#define DEFAULT_FILENAME "seismic_data.csv"

// D7S Register Addresses
#define D7S_REG_X_LSB 0x02
#define D7S_REG_X_MSB 0x03
#define D7S_REG_Y_LSB 0x04
#define D7S_REG_Y_MSB 0x05
#define D7S_REG_Z_LSB 0x06
#define D7S_REG_Z_MSB 0x07
#define D7S_REG_WHO_AM_I 0x00
#define D7S_WHO_AM_I_VALUE 0x41

// Global variables
static int i2c_handle;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static double sampling_interval = DEFAULT_SAMPLING_INTERVAL;
static char *filename = DEFAULT_FILENAME;
static FILE *csv_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int read_d7s_data(float *x, float *y, float *z);
int log_data(float x, float y, float z);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function to initialize the I2C bus
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Open I2C bus 1
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    // Verify sensor presence by reading WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, D7S_REG_WHO_AM_I);
    if (who_am_i < 0) {
        log_error("Failed to read WHO_AM_I register");
        i2cClose(i2c_handle);
        return -1;
    }

    if (who_am_i != D7S_WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Sensor not found (WHO_AM_I = 0x%02X, expected 0x%02X)\n", who_am_i, D7S_WHO_AM_I_VALUE);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read data from the D7S sensor
int read_d7s_data(float *x, float *y, float *z) {
    char buffer[6];
    int result;

    // Read X, Y, and Z values
    result = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_LSB, buffer, 6);
    if (result != 6) {
        log_error("Failed to read data from sensor");
        return -1;
    }

    // Combine LSB and MSB, convert to g
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)x_raw / 1000.0; // Example scaling factor, adjust as needed
    *y = (float)y_raw / 1000.0;
    *z = (float)z_raw / 1000.0;

    return 0;
}

// Function to log data to a CSV file
int log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file == NULL) {
        log_error("CSV file is not open");
        return -1;
    }

    fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to log errors to a file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (error_file == NULL) {
        fprintf(stderr, "Error: Error file is not open\n");
        return -1;
    }

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and files
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtod(optarg, NULL);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(filename, "a");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        cleanup();
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t data;
    while (!terminate) {
        if (read_d7s_data(&data.x, &data.y, &data.z) == 0) {
            if (log_data(data.x, data.y, data.z) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(sampling_interval * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

