// Configuration
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD_VALUE 0x0201040306050807
#define MAX_TLV_SIZE 1024 // Adjust as needed
#define CSV_FILE "radar_data.csv"
#define MAX_OBJECTS 10 // Maximum number of objects to store

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *csv_file = NULL;

// Structure for radar data
typedef struct {
    time_t timestamp;
    int object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Function prototypes
int setup_uart(const char *device, int baud_rate);
int read_uart_data(int fd, char *buffer, int max_size);
int validate_magic_word(const char *buffer, int size);
int parse_tlv_data(const char *buffer, int size, RadarData *data, int max_objects);
int write_to_csv(FILE *file, const RadarData *data, int num_objects);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Exiting gracefully.\n", signal);
    program_running = 0;
}

// UART setup function
int setup_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, no hardware flow control
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// UART data reading function with timeout
int read_uart_data(int fd, char *buffer, int max_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 1; // Timeout after 1 second
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error from select: %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        int bytes_read = read(fd, buffer, max_size);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        return bytes_read;
    }
}

// Magic word validation function
int validate_magic_word(const char *buffer, int size) {
    if (size < MAGIC_WORD_SIZE) {
        fprintf(stderr, "Magic word size is too small: %d\n", size);
        return 0;
    }

    unsigned long magic_word = *((unsigned long *)buffer);
    if (magic_word != MAGIC_WORD_VALUE) {
        fprintf(stderr, "Invalid magic word: 0x%lx\n", magic_word);
        return 0;
    }

    return 1;
}

// TLV parsing function
int parse_tlv_data(const char *buffer, int size, RadarData *data, int max_objects) {
    int num_objects = 0;
    int offset = 0;

    while (offset < size && num_objects < max_objects) {
        unsigned short tlv_type = *((unsigned short *)(buffer + offset));
        unsigned short tlv_length = *((unsigned short *)(buffer + offset + 2));

        if (offset + tlv_length > size) {
            fprintf(stderr, "TLV length exceeds buffer size\n");
            return -1; // Indicate parsing error
        }

        // Example TLV type and data handling (replace with actual parsing logic)
        if (tlv_type == 1) { // Example TLV type for range
            if (tlv_length == 4) {
                data[num_objects].range_m = *((float *)(buffer + offset + 4));
            } else {
                fprintf(stderr, "Invalid range TLV length: %d\n", tlv_length);
                return -1;
            }
        } else if (tlv_type == 2) { // Example TLV type for velocity
            if (tlv_length == 4) {
                data[num_objects].velocity_mps = *((float *)(buffer + offset + 4));
            } else {
                fprintf(stderr, "Invalid velocity TLV length: %d\n", tlv_length);
                return -1;
            }
        } else {
            fprintf(stderr, "Unknown TLV type: %d\n", tlv_type);
        }

        offset += tlv_length;
        num_objects++;
    }

    return num_objects;
}

// CSV writing function
int write_to_csv(FILE *file, const RadarData *data, int num_objects) {
    for (int i = 0; i < num_objects; i++) {
        fprintf(file, "%ld,%d,%.2f,%.2f\n", data[i].timestamp, data[i].object_index, data[i].range_m, data[i].velocity_mps);
    }
    fflush(file); // Ensure data is written to disk
    return 0;
}

// Cleanup function
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
        fprintf(stderr, "UART closed.\n");
    }

    if (csv_file != NULL) {
        fclose(csv_file);
        fprintf(stderr, "CSV file closed.\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART setup failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    char buffer[MAX_TLV_SIZE];
    RadarData radar_data[MAX_OBJECTS];
    int object_index = 0;

    fprintf(stderr, "Starting data acquisition...\n");

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, MAX_TLV_SIZE);
        if (bytes_read > 0) {
            if (validate_magic_word(buffer, bytes_read)) {
                int num_objects = parse_tlv_data(buffer, bytes_read, radar_data, MAX_OBJECTS);
                if (num_objects > 0) {
                    time(&radar_data[0].timestamp);
                    radar_data[0].object_index = object_index;
                    write_to_csv(csv_file, radar_data, num_objects);
                    object_index++;
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            usleep(100000); // Wait before retrying
        }
    }

    fprintf(stderr, "Exiting program.\n");
    cleanup();
    return 0;
}

