#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <stdbool.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define LINE_BUFFER_SIZE 256
#define MAX_RANGE 10.0

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Structure to hold program state
typedef struct {
    char line_buffer[LINE_BUFFER_SIZE];
    int line_buffer_len;
} ProgramState;

// Function prototypes
int setup_uart(const char *device, int baud_rate);
int read_uart_data(int fd, char *buffer, int max_len, int timeout_sec);
int parse_line(const char *line, long *timestamp, float *range);
void log_detection(long timestamp, float range);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        fprintf(stderr, "Signal received, exiting gracefully.\n");
        program_running = 0;
    }
}

// Setup UART function
int setup_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD; // 8N1, no parity, no hardware flow control
    tty.c_iflag = IGNBRK; // Ignore break condition
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read UART data function
int read_uart_data(int fd, char *buffer, int max_len, int timeout_sec) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = timeout_sec;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        int bytes_read = read(fd, buffer, max_len - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

// Parse line function
int parse_line(const char *line, long *timestamp, float *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok
    if (line_copy == NULL) {
        fprintf(stderr, "Error duplicating line: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        free(line_copy);
        return -1;
    }
    char *endptr;
    *timestamp = strtol(token, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n') {
        free(line_copy);
        return -1; // Invalid timestamp
    }

    token = strtok(NULL, ",");
    if (token == NULL) {
        free(line_copy);
        return -1;
    }

    *range = strtof(token, &endptr);
    if (*endptr != '\0' && *endptr != '\n') {
        free(line_copy);
        return -1; // Invalid range
    }

    free(line_copy);
    return 0;
}

// Log detection function
void log_detection(long timestamp, float range) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Setup UART
    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    ProgramState state = {{0}, 0};

    // Main loop
    while (program_running) {
        char buffer[LINE_BUFFER_SIZE];
